import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Enums
export enum UserRole {
  ADMIN = 'ADMIN',
  PLANNER = 'PLANNER',
  TECHNICIAN = 'TECHNICIAN'
}

export enum WorkOrderStatus {
  PENDING = 'PENDING',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
  BLOCKED = 'BLOCKED'
}

export enum WorkOrderType {
  CORRECTIVE = 'CORRECTIVE',
  PREVENTIVE = 'PREVENTIVE'
}

export enum Priority {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL'
}

export enum PurchaseRequestStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED',
  RECEIVED = 'RECEIVED'
}

// Interfaces
export interface User {
  id: string;
  name: string;
  role: UserRole;
  specialty?: string; // For technicians e.g., 'Electricidad', 'Mecánica'
  avatar: string;
}

export interface Asset {
  id: string;
  name: string;
  location: string;
  status: 'OPERATIONAL' | 'DOWN';
}

export interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  quantity: number;
  minStock: number;
  cost: number;
  category: string;
}

export interface PurchaseRequest {
  id: string;
  itemId: string;
  itemName: string;
  quantity: number;
  requestedBy: string;
  date: string;
  status: PurchaseRequestStatus;
  totalCost: number;
}

export interface WorkOrder {
  id: string;
  title: string;
  description: string;
  assetId: string;
  assetName: string;
  assignedTechnicianId?: string;
  technicianName?: string;
  type: WorkOrderType;
  priority: Priority;
  status: WorkOrderStatus;
  dueDate: string;
  specialtyRequired: string;

  // Execution Data
  startTime?: string;
  endTime?: string;
  completionComment?: string;
  evidenceImageUrl?: string;
}

