import React from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Wrench, 
  Package, 
  ShoppingCart, 
  LogOut, 
  Menu,
  ShieldAlert,
  HardHat
} from 'lucide-react';

interface LayoutProps {
  currentUser: User;
  currentView: string;
  onNavigate: (view: string) => void;
  onLogout: () => void;
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ currentUser, currentView, onNavigate, onLogout, children }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

  const NavItem = ({ view, label, icon: Icon, restrictedTo }: any) => {
    if (restrictedTo && !restrictedTo.includes(currentUser.role)) return null;

    const isActive = currentView === view;
    return (
      <button
        onClick={() => {
          onNavigate(view);
          setIsMobileMenuOpen(false);
        }}
        className={`w-full flex items-center gap-3 px-4 py-3 text-sm font-medium transition-colors rounded-lg mb-1
          ${isActive 
            ? 'bg-blue-600 text-white' 
            : 'text-slate-400 hover:bg-slate-800 hover:text-white'
          }`}
      >
        <Icon size={20} />
        {label}
      </button>
    );
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-slate-900 text-white h-full shadow-xl">
        <div className="p-6 border-b border-slate-800 flex items-center gap-2">
          <div className="bg-blue-600 p-2 rounded-lg">
            <Wrench className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-lg font-bold tracking-tight">Nexus GMAO</h1>
            <p className="text-xs text-slate-400">v2.4.0 Enterprise</p>
          </div>
        </div>

        <nav className="flex-1 p-4 overflow-y-auto">
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-4 px-4">
            Módulos
          </div>

          <NavItem 
            view="dashboard" 
            label="Dashboard KPI" 
            icon={LayoutDashboard} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="work-orders" 
            label="Órdenes de Trabajo" 
            icon={Wrench} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="technician" 
            label="Mi Agenda" 
            icon={HardHat} 
            restrictedTo={[UserRole.TECHNICIAN]} 
          />
          <NavItem 
            view="inventory" 
            label="Almacén & Stock" 
            icon={Package} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="purchasing" 
            label="Compras" 
            icon={ShoppingCart} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
        </nav>

        <div className="p-4 border-t border-slate-800">
          <div className="flex items-center gap-3 mb-4 px-2">
            <img src={currentUser.avatar} alt="User" className="w-8 h-8 rounded-full ring-2 ring-blue-500" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">{currentUser.name}</p>
              <p className="text-xs text-slate-500 truncate capitalize">{currentUser.role.toLowerCase()}</p>
            </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center gap-2 px-4 py-2 text-sm text-red-400 hover:bg-slate-800 rounded-lg transition-colors"
          >
            <LogOut size={16} />
            Cerrar Sesión
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden bg-slate-900 text-white p-4 flex justify-between items-center shadow-md z-20">
          <div className="flex items-center gap-2">
             <Wrench className="text-blue-500" size={24} />
             <span className="font-bold">Nexus GMAO</span>
          </div>
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
            <Menu size={24} />
          </button>
        </header>

        {/* Mobile Menu Overlay */}
        {isMobileMenuOpen && (
          <div className="md:hidden absolute inset-0 bg-slate-900 z-10 p-4 pt-20">
            <nav className="flex flex-col gap-2">
              <NavItem view="dashboard" label="Dashboard" icon={LayoutDashboard} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="work-orders" label="Órdenes de Trabajo" icon={Wrench} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="technician" label="Mi Agenda" icon={HardHat} restrictedTo={[UserRole.TECHNICIAN]} />
              <NavItem view="inventory" label="Inventario" icon={Package} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="purchasing" label="Compras" icon={ShoppingCart} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <hr className="border-slate-800 my-2" />
              <button onClick={onLogout} className="flex items-center gap-3 px-4 py-3 text-red-400">
                <LogOut size={20} /> Cerrar Sesión
              </button>
            </nav>
          </div>
        )}

        <main className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50 relative">
          {children}
        </main>
      </div>
    </div>
  );
};

import React from 'react';
import { WorkOrder, InventoryItem, PurchaseRequest, WorkOrderType } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { AlertCircle, CheckCircle2, DollarSign, PackageAlert } from 'lucide-react';

interface DashboardProps {
  workOrders: WorkOrder[];
  inventory: InventoryItem[];
  purchaseRequests: PurchaseRequest[];
}

export const Dashboard: React.FC<DashboardProps> = ({ workOrders, inventory, purchaseRequests }) => {
  // Calculations
  const totalWorkOrders = workOrders.length;
  const completedOrders = workOrders.filter(wo => wo.status === 'COMPLETED').length;
  const complianceRate = totalWorkOrders ? Math.round((completedOrders / totalWorkOrders) * 100) : 0;

  const lowStockItems = inventory.filter(item => item.quantity <= item.minStock);
  const totalInventoryValue = inventory.reduce((acc, item) => acc + (item.quantity * item.cost), 0);
  const approvedPurchases = purchaseRequests.filter(pr => pr.status === 'APPROVED').reduce((acc, pr) => acc + pr.totalCost, 0);

  // Chart Data
  const typeData = [
    { name: 'Preventivo', value: workOrders.filter(wo => wo.type === WorkOrderType.PREVENTIVE).length },
    { name: 'Correctivo', value: workOrders.filter(wo => wo.type === WorkOrderType.CORRECTIVE).length },
  ];
  const COLORS = ['#3b82f6', '#ef4444'];

  const monthlySpendData = [
    { name: 'Ago', amount: 1200 },
    { name: 'Sep', amount: 950 },
    { name: 'Oct', amount: approvedPurchases + 450 }, // Mock historical + current
  ];

  const StatCard = ({ title, value, subtext, icon: Icon, color }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <h3 className="text-2xl font-bold text-slate-900">{value}</h3>
        {subtext && <p className={`text-xs mt-2 ${color ? `text-${color}-600` : 'text-slate-400'}`}>{subtext}</p>}
      </div>
      <div className={`p-3 rounded-lg bg-${color}-50 text-${color}-600`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-900">Dashboard General</h2>
        <p className="text-slate-500">Vista general de operaciones y recursos.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Cumplimiento Plan" 
          value={`${complianceRate}%`} 
          subtext={`${completedOrders}/${totalWorkOrders} Órdenes completadas`}
          icon={CheckCircle2}
          color="green"
        />
        <StatCard 
          title="Stock Crítico" 
          value={lowStockItems.length} 
          subtext="Artículos bajo mínimo"
          icon={PackageAlert}
          color="amber"
        />
        <StatCard 
          title="Valor Inventario" 
          value={`$${totalInventoryValue.toLocaleString()}`} 
          subtext="Capital inmovilizado"
          icon={DollarSign}
          color="blue"
        />
        <StatCard 
          title="Gasto Mensual" 
          value={`$${approvedPurchases.toLocaleString()}`} 
          subtext="Compras aprobadas (Oct)"
          icon={AlertCircle}
          color="indigo"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold mb-4 text-slate-800">Mix de Mantenimiento (Preventivo vs Correctivo)</h3>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={typeData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                fill="#8884d8"
                paddingAngle={5}
                dataKey="value"
              >
                {typeData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend verticalAlign="bottom" height={36}/>
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold mb-4 text-slate-800">Gasto en Repuestos (Último Trimestre)</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={monthlySpendData}>
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
              <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(value) => `$${value}`} />
              <Tooltip 
                cursor={{fill: '#f1f5f9'}}
                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
              />
              <Bar dataKey="amount" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, User, UserRole } from '../types';
import { Calendar, User as UserIcon, AlertTriangle, Clock, Filter, Plus } from 'lucide-react';

interface WorkOrderListProps {
  orders: WorkOrder[];
  users: User[];
  onAssign: (orderId: string, technicianId: string) => void;
  onCreate: () => void; // Placeholder for creating new OT
}

export const WorkOrderList: React.FC<WorkOrderListProps> = ({ orders, users, onAssign, onCreate }) => {
  const [filterSpecialty, setFilterSpecialty] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);
  const specialties = Array.from(new Set(technicians.map(t => t.specialty).filter(Boolean)));

  const filteredOrders = orders.filter(order => {
    const matchesSpecialty = filterSpecialty === 'ALL' || order.specialtyRequired === filterSpecialty;
    const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
    return matchesSpecialty && matchesStatus;
  });

  const getPriorityColor = (p: Priority) => {
    switch (p) {
      case Priority.CRITICAL: return 'bg-red-100 text-red-700 border-red-200';
      case Priority.HIGH: return 'bg-orange-100 text-orange-700 border-orange-200';
      case Priority.MEDIUM: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      default: return 'bg-blue-100 text-blue-700 border-blue-200';
    }
  };

  const getStatusColor = (s: WorkOrderStatus) => {
    switch (s) {
      case WorkOrderStatus.COMPLETED: return 'bg-green-100 text-green-800';
      case WorkOrderStatus.IN_PROGRESS: return 'bg-blue-100 text-blue-800';
      default: return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Órdenes (OT)</h2>
          <p className="text-slate-500">Planificación y asignación de tareas.</p>
        </div>
        <button 
          onClick={onCreate}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-sm"
        >
          <Plus size={18} />
          Nueva OT
        </button>
      </div>

      {/* Filters */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex flex-wrap gap-4 items-center">
        <div className="flex items-center gap-2 text-slate-500">
          <Filter size={18} />
          <span className="text-sm font-medium">Filtros:</span>
        </div>

        <select 
          className="bg-slate-50 border border-slate-200 rounded-lg text-sm px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
          value={filterSpecialty}
          onChange={(e) => setFilterSpecialty(e.target.value)}
        >
          <option value="ALL">Todas las Especialidades</option>
          {specialties.map(s => <option key={s} value={s as string}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border border-slate-200 rounded-lg text-sm px-3 py-2 focus:ring-2 focus:ring-blue-500 outline-none"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="ALL">Todos los Estados</option>
          <option value={WorkOrderStatus.PENDING}>Pendientes</option>
          <option value={WorkOrderStatus.IN_PROGRESS}>En Progreso</option>
          <option value={WorkOrderStatus.COMPLETED}>Completadas</option>
        </select>
      </div>

      {/* List */}
      <div className="grid grid-cols-1 gap-4">
        {filteredOrders.map(ot => (
          <div key={ot.id} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
            <div className="flex flex-col lg:flex-row justify-between lg:items-center gap-4">
              <div className="space-y-2 flex-1">
                <div className="flex items-center gap-3">
                  <span className={`text-xs font-bold px-2 py-1 rounded border ${getPriorityColor(ot.priority)}`}>
                    {ot.priority}
                  </span>
                  <span className={`text-xs font-medium px-2 py-1 rounded ${getStatusColor(ot.status)}`}>
                    {ot.status.replace('_', ' ')}
                  </span>
                  <span className="text-xs text-slate-400 font-mono">#{ot.id}</span>
                </div>
                <h3 className="text-lg font-bold text-slate-900">{ot.title}</h3>
                <p className="text-sm text-slate-600">{ot.description}</p>
                <div className="flex items-center gap-4 text-xs text-slate-500 mt-2">
                  <span className="flex items-center gap-1"><AlertTriangle size={14} /> {ot.assetName}</span>
                  <span className="flex items-center gap-1"><Calendar size={14} /> Vence: {ot.dueDate}</span>
                  <span className="flex items-center gap-1 px-2 py-0.5 bg-slate-100 rounded-full">{ot.specialtyRequired}</span>
                </div>
              </div>

              <div className="flex flex-col gap-2 min-w-[200px]">
                <div className="flex items-center gap-2 text-sm text-slate-600">
                  <UserIcon size={16} />
                  <span>Asignado a:</span>
                </div>
                <select 
                  className="w-full bg-slate-50 border border-slate-200 rounded-lg text-sm px-3 py-2"
                  value={ot.assignedTechnicianId || ''}
                  onChange={(e) => onAssign(ot.id, e.target.value)}
                  disabled={ot.status === WorkOrderStatus.COMPLETED}
                >
                  <option value="">-- Sin Asignar --</option>
                  {technicians
                    .filter(t => t.specialty === ot.specialtyRequired) // Filter by specialty
                    .map(t => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                  <option disabled>--- Otros Especialistas ---</option>
                  {technicians
                    .filter(t => t.specialty !== ot.specialtyRequired)
                    .map(t => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
                {ot.assignedTechnicianId && (
                   <p className="text-xs text-green-600 flex items-center gap-1">
                     <Clock size={12} /> Técnico notificado
                   </p>
                )}
              </div>
            </div>
          </div>
        ))}

        {filteredOrders.length === 0 && (
          <div className="text-center py-12 bg-white rounded-xl border border-dashed border-slate-300">
            <p className="text-slate-400">No se encontraron órdenes con estos filtros.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { InventoryItem, PurchaseRequest, PurchaseRequestStatus, User, UserRole } from '../types';
import { Package, AlertTriangle, ShoppingCart, Plus, Check, X } from 'lucide-react';

interface InventoryProps {
  inventory: InventoryItem[];
  purchaseRequests: PurchaseRequest[];
  user: User;
  onRequestPurchase: (itemId: string, qty: number) => void;
  onApprovePurchase: (reqId: string) => void;
  onReceivePurchase: (reqId: string) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ 
  inventory, 
  purchaseRequests, 
  user, 
  onRequestPurchase, 
  onApprovePurchase,
  onReceivePurchase
}) => {
  const [activeTab, setActiveTab] = useState<'STOCK' | 'PURCHASES'>('STOCK');
  const [qtyInputs, setQtyInputs] = useState<Record<string, number>>({});

  const handleQtyChange = (id: string, val: string) => {
    setQtyInputs(prev => ({ ...prev, [id]: parseInt(val) || 0 }));
  };

  const pendingRequests = purchaseRequests.filter(pr => pr.status === PurchaseRequestStatus.PENDING);
  const approvedRequests = purchaseRequests.filter(pr => pr.status === PurchaseRequestStatus.APPROVED);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Almacén y Compras</h2>
          <p className="text-slate-500">Gestión de repuestos y solicitudes de compra.</p>
        </div>
        <div className="flex gap-2 p-1 bg-slate-200 rounded-lg">
          <button 
            onClick={() => setActiveTab('STOCK')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-all ${activeTab === 'STOCK' ? 'bg-white text-slate-900 shadow' : 'text-slate-600 hover:text-slate-900'}`}
          >
            Inventario
          </button>
          <button 
            onClick={() => setActiveTab('PURCHASES')}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-all ${activeTab === 'PURCHASES' ? 'bg-white text-slate-900 shadow' : 'text-slate-600 hover:text-slate-900'}`}
          >
            Compras
            {pendingRequests.length > 0 && user.role !== UserRole.TECHNICIAN && (
              <span className="ml-2 bg-red-500 text-white text-xs px-2 py-0.5 rounded-full">{pendingRequests.length}</span>
            )}
          </button>
        </div>
      </div>

      {activeTab === 'STOCK' && (
        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
              <tr>
                <th className="px-6 py-4 font-semibold">SKU / Ítem</th>
                <th className="px-6 py-4 font-semibold">Categoría</th>
                <th className="px-6 py-4 font-semibold">Stock Actual</th>
                <th className="px-6 py-4 font-semibold text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {inventory.map(item => {
                const isLowStock = item.quantity <= item.minStock;
                return (
                  <tr key={item.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4">
                      <div className="flex items-start gap-3">
                        <div className={`p-2 rounded-lg ${isLowStock ? 'bg-red-50 text-red-500' : 'bg-slate-100 text-slate-500'}`}>
                          <Package size={20} />
                        </div>
                        <div>
                          <p className="font-medium text-slate-900">{item.name}</p>
                          <p className="text-xs text-slate-500">{item.sku}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-slate-600">
                      <span className="px-2 py-1 bg-slate-100 rounded text-xs">{item.category}</span>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <span className={`font-bold ${isLowStock ? 'text-red-600' : 'text-slate-700'}`}>
                          {item.quantity} un.
                        </span>
                        {isLowStock && (
                          <div className="flex items-center gap-1 text-xs text-red-500 bg-red-50 px-2 py-1 rounded">
                            <AlertTriangle size={12} /> Min: {item.minStock}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                       <div className="flex items-center justify-end gap-2">
                         <input 
                           type="number" 
                           min="1"
                           placeholder="Cant."
                           className="w-20 border border-slate-200 rounded px-2 py-1 text-sm"
                           onChange={(e) => handleQtyChange(item.id, e.target.value)}
                         />
                         <button 
                           onClick={() => onRequestPurchase(item.id, qtyInputs[item.id] || 10)}
                           className="text-blue-600 hover:bg-blue-50 p-2 rounded-lg transition-colors flex items-center gap-1 text-xs font-medium"
                         >
                           <ShoppingCart size={16} /> Solicitar
                         </button>
                       </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'PURCHASES' && (
        <div className="grid grid-cols-1 gap-8">
          {/* Admin Approval Section */}
          <div className="space-y-4">
            <h3 className="font-bold text-slate-800 flex items-center gap-2">
              <Clock size={20} className="text-amber-500"/> Pendientes de Aprobación
            </h3>
            {pendingRequests.length === 0 ? (
              <p className="text-sm text-slate-400 italic">No hay solicitudes pendientes.</p>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                 {pendingRequests.map(pr => (
                   <div key={pr.id} className="bg-white p-4 rounded-xl border border-amber-200 shadow-sm relative overflow-hidden">
                      <div className="absolute top-0 right-0 w-2 h-full bg-amber-400 opacity-20"></div>
                      <div className="mb-3">
                        <span className="text-xs font-bold text-amber-600 bg-amber-50 px-2 py-1 rounded mb-2 inline-block">PENDIENTE</span>
                        <h4 className="font-bold text-slate-900">{pr.itemName}</h4>
                        <p className="text-sm text-slate-600">Cant: {pr.quantity} | Total: ${pr.totalCost}</p>
                        <p className="text-xs text-slate-400 mt-1">Solicitado por: {pr.requestedBy}</p>
                      </div>

                      {user.role === UserRole.ADMIN && (
                        <div className="flex gap-2 mt-4 pt-4 border-t border-slate-100">
                          <button 
                            onClick={() => onApprovePurchase(pr.id)}
                            className="flex-1 bg-green-600 text-white py-2 rounded-lg text-sm font-medium hover:bg-green-700 flex justify-center items-center gap-1"
                          >
                            <Check size={16} /> Aprobar
                          </button>
                          <button className="flex-1 bg-red-100 text-red-600 py-2 rounded-lg text-sm font-medium hover:bg-red-200 flex justify-center items-center gap-1">
                            <X size={16} /> Rechazar
                          </button>
                        </div>
                      )}
                   </div>
                 ))}
              </div>
            )}
          </div>

          {/* Receiving Section */}
          <div className="space-y-4">
            <h3 className="font-bold text-slate-800 flex items-center gap-2">
              <Check size={20} className="text-green-500"/> Aprobadas / Por Ingresar
            </h3>
            {approvedRequests.length === 0 ? (
              <p className="text-sm text-slate-400 italic">No hay pedidos esperando ingreso.</p>
            ) : (
              <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
                <table className="w-full text-left text-sm">
                   <thead className="bg-slate-50 text-slate-500">
                     <tr>
                       <th className="px-6 py-3">Ítem</th>
                       <th className="px-6 py-3">Cantidad</th>
                       <th className="px-6 py-3">Costo</th>
                       <th className="px-6 py-3 text-right">Acción</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                     {approvedRequests.map(pr => (
                       <tr key={pr.id}>
                         <td className="px-6 py-3 font-medium">{pr.itemName}</td>
                         <td className="px-6 py-3">{pr.quantity}</td>
                         <td className="px-6 py-3">${pr.totalCost}</td>
                         <td className="px-6 py-3 text-right">
                           <button 
                             onClick={() => onReceivePurchase(pr.id)}
                             className="text-blue-600 hover:underline text-xs font-bold uppercase tracking-wide"
                           >
                             Ingresar Stock
                           </button>
                         </td>
                       </tr>
                     ))}
                   </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { WorkOrder, WorkOrderStatus, Priority } from '../types';
import { Calendar, MapPin, Play, CheckCircle, Camera, AlertCircle, X } from 'lucide-react';

interface TechnicianViewProps {
  orders: WorkOrder[];
  technicianId: string;
  onStatusChange: (id: string, status: WorkOrderStatus, data?: { comment?: string; evidence?: string }) => void;
}

export const TechnicianView: React.FC<TechnicianViewProps> = ({ orders, technicianId, onStatusChange }) => {
  const [selectedOrder, setSelectedOrder] = useState<WorkOrder | null>(null);
  const [completeModalOpen, setCompleteModalOpen] = useState(false);

  // Form State for Completion
  const [comment, setComment] = useState('');
  const [evidenceFile, setEvidenceFile] = useState<string | null>(null);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const myOrders = orders.filter(o => o.assignedTechnicianId === technicianId);
  const todayOrders = myOrders.filter(o => o.status !== WorkOrderStatus.COMPLETED);

  const handleStart = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onStatusChange(id, WorkOrderStatus.IN_PROGRESS);
  };

  const openCompleteModal = (e: React.MouseEvent, order: WorkOrder) => {
    e.stopPropagation();
    setSelectedOrder(order);
    setCompleteModalOpen(true);
    setComment('');
    setEvidenceFile(null);
    setError('');
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      // Create a fake local URL for preview
      const url = URL.createObjectURL(e.target.files[0]);
      setEvidenceFile(url);
    }
  };

  const submitCompletion = () => {
    if (!comment.trim()) {
      setError('Debes ingresar un comentario técnico.');
      return;
    }
    if (!evidenceFile) {
      setError('Es obligatorio adjuntar una foto de evidencia.');
      return;
    }
    if (selectedOrder) {
      onStatusChange(selectedOrder.id, WorkOrderStatus.COMPLETED, { comment, evidence: evidenceFile });
      setCompleteModalOpen(false);
      setSelectedOrder(null);
    }
  };

  return (
    <div className="space-y-4 max-w-2xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-xl font-bold text-slate-900">Mi Agenda</h2>
          <p className="text-sm text-slate-500">Tareas asignadas para hoy.</p>
        </div>
        <div className="bg-blue-50 text-blue-700 px-3 py-1 rounded-full text-sm font-bold">
          {todayOrders.length} Pendientes
        </div>
      </div>

      {todayOrders.length === 0 ? (
         <div className="text-center py-12 bg-white rounded-xl shadow-sm">
           <div className="inline-flex p-4 rounded-full bg-green-50 text-green-500 mb-4">
             <CheckCircle size={32} />
           </div>
           <p className="text-slate-600 font-medium">¡Todo al día!</p>
           <p className="text-slate-400 text-sm">No tienes órdenes pendientes.</p>
         </div>
      ) : (
        <div className="space-y-4">
          {todayOrders.map(ot => (
            <div 
              key={ot.id} 
              className={`bg-white rounded-xl shadow-sm border-l-4 p-5 transition-all ${
                ot.priority === Priority.CRITICAL ? 'border-l-red-500' : 
                ot.priority === Priority.HIGH ? 'border-l-orange-500' : 'border-l-blue-500'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className="text-xs font-mono text-slate-400">#{ot.id}</span>
                <span className={`text-xs font-bold px-2 py-1 rounded uppercase ${
                  ot.status === WorkOrderStatus.IN_PROGRESS ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                }`}>
                  {ot.status.replace('_', ' ')}
                </span>
              </div>

              <h3 className="text-lg font-bold text-slate-900 mb-1">{ot.title}</h3>
              <div className="flex items-center gap-2 text-sm text-slate-600 mb-4">
                <MapPin size={14} className="text-slate-400"/>
                {ot.assetName}
              </div>

              <p className="text-sm text-slate-500 mb-6 bg-slate-50 p-3 rounded-lg border border-slate-100">
                {ot.description}
              </p>

              <div className="flex gap-3">
                {ot.status === WorkOrderStatus.PENDING && (
                  <button 
                    onClick={(e) => handleStart(e, ot.id)}
                    className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-medium flex justify-center items-center gap-2 active:bg-blue-700"
                  >
                    <Play size={18} /> Iniciar
                  </button>
                )}

                {ot.status === WorkOrderStatus.IN_PROGRESS && (
                  <button 
                    onClick={(e) => openCompleteModal(e, ot)}
                    className="flex-1 bg-green-600 text-white py-3 rounded-lg font-medium flex justify-center items-center gap-2 active:bg-green-700"
                  >
                    <CheckCircle size={18} /> Finalizar
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Completion Modal */}
      {completeModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <h3 className="font-bold text-slate-800">Finalizar Orden</h3>
              <button onClick={() => setCompleteModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <div className="p-6 space-y-4">
              {error && (
                <div className="bg-red-50 text-red-600 text-sm p-3 rounded-lg flex items-center gap-2">
                  <AlertCircle size={16} /> {error}
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Comentario Técnico</label>
                <textarea 
                  className="w-full border border-slate-300 rounded-lg p-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none h-24 resize-none"
                  placeholder="Describe el trabajo realizado y solución aplicada..."
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Evidencia Fotográfica</label>
                <div 
                  className="border-2 border-dashed border-slate-300 rounded-lg p-6 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-50 transition-colors"
                  onClick={() => fileInputRef.current?.click()}
                >
                  {evidenceFile ? (
                    <div className="relative w-full h-32 bg-slate-100 rounded overflow-hidden">
                       <img src={evidenceFile} className="w-full h-full object-cover" alt="Preview" />
                       <div className="absolute inset-0 flex items-center justify-center bg-black/30 text-white text-xs font-bold opacity-0 hover:opacity-100 transition-opacity">Cambiar Foto</div>
                    </div>
                  ) : (
                    <>
                      <Camera className="text-slate-400 mb-2" size={32} />
                      <p className="text-xs text-slate-500">Toca para tomar foto o subir archivo</p>
                    </>
                  )}
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
                </div>
              </div>
            </div>

            <div className="p-4 border-t border-slate-100 bg-slate-50 flex gap-3">
              <button 
                onClick={() => setCompleteModalOpen(false)}
                className="flex-1 py-3 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={submitCompletion}
                className="flex-1 bg-blue-600 text-white py-3 rounded-lg font-medium hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
              >
                Completar OT
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { TechnicianView } from './features/TechnicianView';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS 
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus 
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string }) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));
  };

  const handleCreateWorkOrder = () => {
    alert("Funcionalidad de Crear OT: En una app real, esto abriría un formulario completo.");
  };

  // Handlers for Inventory & Purchases
  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      quantity: qty,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING,
      totalCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada correctamente.");
  };

  const handleApprovePurchase = (reqId: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.APPROVED } : pr
    ));
  };

  const handleReceivePurchase = (reqId: string) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // Update Stock
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + request.quantity } 
        : item
    ));

    // Update Request Status
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.RECEIVED } : pr
    ));
  };

  // Role Simulation Handler
  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      // Redirect to appropriate landing view
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      {/* Simulation Banner - FOR DEMO PURPOSES */}
      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-slate-800 text-white text-xs p-2 rounded shadow-lg border border-slate-700 opacity-90 hover:opacity-100 transition-opacity cursor-pointer"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN}>Simular: Admin</option>
          <option value={UserRole.PLANNER}>Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN}>Simular: Técnico</option>
        </select>
      </div>

      {/* Render Views based on route */}
      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS} 
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

    </Layout>
  );
}

export default App;

import React, { useState } from 'react';
import { InventoryItem, PurchaseRequest, PurchaseRequestStatus, User, UserRole } from '../types';
import { Package, AlertTriangle, ShoppingCart, Plus, Check, X, Clock } from 'lucide-react';

interface InventoryProps {
  inventory: InventoryItem[];
  purchaseRequests: PurchaseRequest[];
  user: User;
  onRequestPurchase: (itemId: string, qty: number) => void;
  onApprovePurchase: (reqId: string) => void;
  onReceivePurchase: (reqId: string) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ 
  inventory, 
  purchaseRequests, 
  user, 
  onRequestPurchase, 
  onApprovePurchase,
  onReceivePurchase
}) => {
  const [activeTab, setActiveTab] = useState<'STOCK' | 'PURCHASES'>('STOCK');
  const [qtyInputs, setQtyInputs] = useState<Record<string, number>>({});

  const handleQtyChange = (id: string, val: string) => {
    setQtyInputs(prev => ({ ...prev, [id]: parseInt(val) || 0 }));
  };

  const pendingRequests = purchaseRequests.filter(pr => pr.status === PurchaseRequestStatus.PENDING);
  const approvedRequests = purchaseRequests.filter(pr => pr.status === PurchaseRequestStatus.APPROVED);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
