import React from 'react';
import { WorkOrder, InventoryItem, PurchaseRequest, WorkOrderType } from '../types';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { AlertCircle, CheckCircle2, DollarSign, AlertTriangle } from 'lucide-react';

interface DashboardProps {
  workOrders: WorkOrder[];
  inventory: InventoryItem[];
  purchaseRequests: PurchaseRequest[];
}

export const Dashboard: React.FC<DashboardProps> = ({ workOrders, inventory, purchaseRequests }) => {
  // Calculations
  const totalWorkOrders = workOrders.length;
  const completedOrders = workOrders.filter(wo => wo.status === 'COMPLETED').length;
  const complianceRate = totalWorkOrders ? Math.round((completedOrders / totalWorkOrders) * 100) : 0;

  const lowStockItems = inventory.filter(item => item.quantity <= item.minStock);
  const totalInventoryValue = inventory.reduce((acc, item) => acc + (item.quantity * item.cost), 0);
  const approvedPurchases = purchaseRequests.filter(pr => pr.status === 'APPROVED').reduce((acc, pr) => acc + pr.totalCost, 0);

  // Chart Data
  const typeData = [
    { name: 'Preventivo', value: workOrders.filter(wo => wo.type === WorkOrderType.PREVENTIVE).length },
    { name: 'Correctivo', value: workOrders.filter(wo => wo.type === WorkOrderType.CORRECTIVE).length },
  ];
  const COLORS = ['#3b82f6', '#ef4444'];

  const monthlySpendData = [
    { name: 'Ago', amount: 1200 },
    { name: 'Sep', amount: 950 },
    { name: 'Oct', amount: approvedPurchases + 450 }, // Mock historical + current
  ];

  const StatCard = ({ title, value, subtext, icon: Icon, color }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-start justify-between">
      <div>
        <p className="text-sm font-medium text-slate-500 mb-1">{title}</p>
        <h3 className="text-2xl font-bold text-slate-900">{value}</h3>
        {subtext && <p className={`text-xs mt-2 ${color ? `text-${color}-600` : 'text-slate-400'}`}>{subtext}</p>}
      </div>
      <div className={`p-3 rounded-lg bg-${color}-50 text-${color}-600`}>
        <Icon size={24} />
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold text-slate-900">Dashboard General</h2>
        <p className="text-slate-500">Vista general de operaciones y recursos.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Cumplimiento Plan" 
          value={`${complianceRate}%`} 
          subtext={`${completedOrders}/${totalWorkOrders} Órdenes completadas`}
          icon={CheckCircle2}
          color="green"
        />
        <StatCard 
          title="Stock Crítico" 
          value={lowStockItems.length} 
          subtext="Artículos bajo mínimo"
          icon={AlertTriangle}
          color="amber"
        />
        <StatCard 
          title="Valor Inventario" 
          value={`$${totalInventoryValue.toLocaleString()}`} 
          subtext="Capital inmovilizado"
          icon={DollarSign}
          color="blue"
        />
        <StatCard 
          title="Gasto Mensual" 
          value={`$${approvedPurchases.toLocaleString()}`} 
          subtext="Compras aprobadas (Oct)"
          icon={AlertCircle}
          color="indigo"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold mb-4 text-slate-800">Mix de Mantenimiento (Preventivo vs Correctivo)</h3>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie
                data={typeData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                fill="#8884d8"
                paddingAngle={5}
                dataKey="value"
              >
                {typeData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend verticalAlign="bottom" height={36}/>
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 h-80">
          <h3 className="text-lg font-semibold mb-4 text-slate-800">Gasto en Repuestos (Último Trimestre)</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={monthlySpendData}>
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} />
              <YAxis stroke="#94a3b8" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(value) => `$${value}`} />
              <Tooltip 
                cursor={{fill: '#f1f5f9'}}
                contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
              />
              <Bar dataKey="amount" fill="#6366f1" radius={[4, 4, 0, 0]} barSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

