import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { TechnicianView } from './features/TechnicianView';
import { PreventiveMaintenance } from './features/PreventiveMaintenance';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    // If a Preventive OT is COMPLETED, we must update the Plan's nextDueDate
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          // Calculate new date
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          // Update Plan
          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[], assigneeId: string) => {
    const technician = MOCK_USERS.find(u => u.id === assigneeId);
    if (!technician) return;

    const newOrders: WorkOrder[] = [];

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado automáticamente.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          assignedTechnicianId: assigneeId,
          technicianName: technician.name,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, // Default priority for preventive
          status: WorkOrderStatus.PENDING,
          dueDate: plan.nextDueDate,
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`Se han generado ${newOrders.length} Órdenes de Trabajo para ${technician.name}.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleCreateWorkOrder = () => {
    alert("Funcionalidad de Crear OT: En una app real, esto abriría un formulario completo.");
  };

  // Handlers for Inventory & Purchases
  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      quantity: qty,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING,
      totalCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada correctamente.");
  };

  const handleApprovePurchase = (reqId: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.APPROVED } : pr
    ));
  };

  const handleReceivePurchase = (reqId: string) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // Update Stock
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + request.quantity } 
        : item
    ));

    // Update Request Status
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.RECEIVED } : pr
    ));
  };

  // Role Simulation Handler
  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      // Redirect to appropriate landing view
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      {/* Simulation Banner - FOR DEMO PURPOSES */}
      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-slate-800 text-white text-xs p-2 rounded shadow-lg border border-slate-700 opacity-90 hover:opacity-100 transition-opacity cursor-pointer"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN}>Simular: Admin</option>
          <option value={UserRole.PLANNER}>Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN}>Simular: Técnico</option>
        </select>
      </div>

      {/* Render Views based on route */}
      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS} 
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          users={MOCK_USERS}
          assets={MOCK_ASSETS}
          onGenerateOrders={handleGenerateOrders}
          onCreatePlan={handleCreatePlan}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

    </Layout>
  );
}

export default App;

import React, { useState } from 'react';
import { MaintenancePlan, User, UserRole, Asset } from '../types';
import { CalendarClock, AlertCircle, CheckSquare, Clock, User as UserIcon, Filter, Play, Plus, X, Trash2, Save } from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  users: User[];
  assets: Asset[];
  onGenerateOrders: (planIds: string[], assigneeId: string) => void;
  onCreatePlan: (plan: MaintenancePlan) => void;
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ plans, users, assets, onGenerateOrders, onCreatePlan }) => {
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [selectedTechnician, setSelectedTechnician] = useState<string>('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  // New Plan Form State
  const [newPlanTitle, setNewPlanTitle] = useState('');
  const [newPlanAssetId, setNewPlanAssetId] = useState('');
  const [newPlanFreq, setNewPlanFreq] = useState(30);
  const [newPlanDate, setNewPlanDate] = useState('');
  const [newPlanHours, setNewPlanHours] = useState(1);
  const [newPlanSpecialty, setNewPlanSpecialty] = useState('Mecánica');
  const [newPlanChecklist, setNewPlanChecklist] = useState<string[]>([]);
  const [tempTask, setTempTask] = useState('');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // Logic for dates
  const today = new Date();
  const getDaysDiff = (dateStr: string) => {
    const due = new Date(dateStr);
    const diffTime = due.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // KPIs
  const totalHours = plans.reduce((acc, plan) => acc + plan.estimatedHours, 0);
  const overduePlans = plans.filter(p => getDaysDiff(p.nextDueDate) < 0).length;
  const criticalPlans = plans.filter(p => getDaysDiff(p.nextDueDate) >= 0 && getDaysDiff(p.nextDueDate) <= 5).length;
  const technicianCapacity = technicians.length * 40; // 40h week

  const togglePlanSelection = (id: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedPlanIds(newSet);
  };

  const selectAll = () => {
    if (selectedPlanIds.size === plans.length) setSelectedPlanIds(new Set());
    else setSelectedPlanIds(new Set(plans.map(p => p.id)));
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un plan.');
    if (!selectedTechnician) return alert('Debes seleccionar un técnico responsable.');

    onGenerateOrders(Array.from(selectedPlanIds), selectedTechnician);
    setSelectedPlanIds(new Set());
  };

  // Form Handlers
  const addTask = () => {
    if (tempTask.trim()) {
      setNewPlanChecklist([...newPlanChecklist, tempTask.trim()]);
      setTempTask('');
    }
  };

  const removeTask = (index: number) => {
    setNewPlanChecklist(newPlanChecklist.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlanTitle || !newPlanAssetId || !newPlanDate) {
      return alert('Por favor completa los campos obligatorios.');
    }

    const selectedAsset = assets.find(a => a.id === newPlanAssetId);

    const newPlan: MaintenancePlan = {
      id: `mp-${Date.now()}`,
      title: newPlanTitle,
      assetId: newPlanAssetId,
      assetName: selectedAsset?.name || 'Desconocido',
      frequencyDays: Number(newPlanFreq),
      nextDueDate: newPlanDate,
      estimatedHours: Number(newPlanHours),
      specialtyRequired: newPlanSpecialty,
      checklistTemplate: newPlanChecklist
    };

    onCreatePlan(newPlan);
    setIsModalOpen(false);
    // Reset form
    setNewPlanTitle('');
    setNewPlanAssetId('');
    setNewPlanChecklist([]);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Planificador de Preventivos</h2>
          <p className="text-slate-500">Gestión de recurrencias y generación de órdenes.</p>
        </div>

        <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg font-medium shadow-sm hover:bg-blue-700 transition-colors"
            >
              <Plus size={18} />
              Nuevo Plan
            </button>

            {/* Bulk Action Widget */}
            <div className="bg-white p-2 pr-4 rounded-lg shadow-sm border border-slate-200 flex items-center gap-3">
            <div className="flex items-center gap-2 pl-2 border-r border-slate-200 pr-3">
                <span className="text-xs font-bold text-slate-500 uppercase hidden md:inline">Asignación</span>
                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-0.5 rounded-full">
                {selectedPlanIds.size}
                </span>
            </div>

            <select 
                className="text-sm border-none focus:ring-0 text-slate-700 bg-transparent outline-none w-40"
                value={selectedTechnician}
                onChange={(e) => setSelectedTechnician(e.target.value)}
            >
                <option value="">- Asignar a -</option>
                {technicians.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>

            <button 
                onClick={handleBulkGenerate}
                disabled={selectedPlanIds.size === 0}
                className={`p-1.5 rounded text-sm font-medium transition-colors ${selectedPlanIds.size > 0 ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                title="Generar Órdenes"
            >
                <Play size={16} fill="currentColor" />
            </button>
            </div>
        </div>
      </div>

      {/* KPIs Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 text-red-600 rounded-lg"><AlertCircle size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Vencidos</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{overduePlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Clock size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Próx. 5 días</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{criticalPlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><CheckSquare size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Horas Planificadas</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{totalHours}h</span>
          <span className="text-xs text-slate-400 ml-2">/ {technicianCapacity}h Disp.</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
           <div className="w-full bg-slate-100 rounded-full h-2.5 mt-4 mb-2">
              <div 
                className="bg-blue-600 h-2.5 rounded-full" 
                style={{ width: `${Math.min((totalHours / technicianCapacity) * 100, 100)}%` }}
              ></div>
           </div>
           <p className="text-xs text-slate-500">Ocupación del Staff Semanal</p>
        </div>
      </div>

      {/* Main Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 w-12">
                <input type="checkbox" onChange={selectAll} checked={selectedPlanIds.size === plans.length && plans.length > 0} className="rounded border-slate-300"/>
              </th>
              <th className="px-6 py-4 font-semibold">Plan Maestro</th>
              <th className="px-6 py-4 font-semibold">Activo</th>
              <th className="px-6 py-4 font-semibold">Frecuencia</th>
              <th className="px-6 py-4 font-semibold">Próx. Vencimiento</th>
              <th className="px-6 py-4 font-semibold">Especialidad</th>
              <th className="px-6 py-4 font-semibold text-right">Horas Est.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {plans.map(plan => {
              const daysDiff = getDaysDiff(plan.nextDueDate);
              let statusClass = "bg-green-50 border-green-200";
              let textClass = "text-green-700";

              if (daysDiff < 0) {
                statusClass = "bg-red-50 border-red-200";
                textClass = "text-red-700";
              } else if (daysDiff <= 5) {
                statusClass = "bg-orange-50 border-orange-200";
                textClass = "text-orange-700";
              }

              return (
                <tr key={plan.id} className={`hover:bg-slate-50 transition-colors ${selectedPlanIds.has(plan.id) ? 'bg-blue-50/50' : ''}`}>
                  <td className="px-6 py-4">
                    <input 
                      type="checkbox" 
                      checked={selectedPlanIds.has(plan.id)}
                      onChange={() => togglePlanSelection(plan.id)}
                      className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{plan.title}</div>
                    <div className="text-xs text-slate-500">{plan.checklistTemplate.length} tareas definidas</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">{plan.assetName}</td>
                  <td className="px-6 py-4 text-slate-600">Cada {plan.frequencyDays} días</td>
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center px-2.5 py-1 rounded border ${statusClass} ${textClass} text-xs font-bold`}>
                      <CalendarClock size={14} className="mr-1.5" />
                      {plan.nextDueDate} 
                      <span className="ml-1 opacity-75">({daysDiff}d)</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                     <span className="px-2 py-1 bg-slate-100 rounded text-xs text-slate-600">{plan.specialtyRequired}</span>
                  </td>
                  <td className="px-6 py-4 text-right font-medium text-slate-700">{plan.estimatedHours}h</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* CREATE PLAN MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white rounded-2xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[90vh]">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl">
              <h3 className="text-lg font-bold text-slate-800">Nuevo Plan Maestro</h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <div className="p-6 overflow-y-auto">
              <form id="planForm" onSubmit={handleSubmit} className="space-y-6">

                {/* Basic Info */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="col-span-1 md:col-span-2">
                        <label className="block text-sm font-medium text-slate-700 mb-1">Título del Plan</label>
                        <input 
                            required
                            type="text" 
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            placeholder="Ej. Revisión mensual de aire acondicionado"
                            value={newPlanTitle}
                            onChange={e => setNewPlanTitle(e.target.value)}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Asignar a Equipo (Activo)</label>
                        <select 
                            required
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                            value={newPlanAssetId}
                            onChange={e => setNewPlanAssetId(e.target.value)}
                        >
                            <option value="">-- Seleccionar Equipo --</option>
                            {assets.map(asset => (
                                <option key={asset.id} value={asset.id}>{asset.name} ({asset.location})</option>
                            ))}
                        </select>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Frecuencia (Días)</label>
                        <input 
                            required
                            type="number" 
                            min="1"
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            value={newPlanFreq}
                            onChange={e => setNewPlanFreq(Number(e.target.value))}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Próximo Vencimiento</label>
                        <input 
                            required
                            type="date" 
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            value={newPlanDate}
                            onChange={e => setNewPlanDate(e.target.value)}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Horas Estimadas</label>
                        <input 
                            required
                            type="number" 
                            min="0.5" step="0.5"
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            value={newPlanHours}
                            onChange={e => setNewPlanHours(Number(e.target.value))}
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Especialidad Requerida</label>
                        <select 
                            className="w-full border border-slate-300 rounded-lg p-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                            value={newPlanSpecialty}
                            onChange={e => setNewPlanSpecialty(e.target.value)}
                        >
                            <option value="Mecánica">Mecánica</option>
                            <option value="Electricidad">Electricidad</option>
                            <option value="Hidráulica">Hidráulica</option>
                            <option value="General">General</option>
                        </select>
                    </div>
                </div>

                {/* Checklist Builder */}
                <div className="border-t border-slate-100 pt-4">
                    <label className="block text-sm font-bold text-slate-800 mb-2">Check-list de Tareas</label>
                    <div className="flex gap-2 mb-3">
                        <input 
                            type="text" 
                            className="flex-1 border border-slate-300 rounded-lg p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                            placeholder="Describir tarea (ej. Verificar presión)"
                            value={tempTask}
                            onChange={e => setTempTask(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addTask())}
                        />
                        <button 
                            type="button"
                            onClick={addTask}
                            className="bg-slate-100 text-slate-700 hover:bg-slate-200 px-3 py-2 rounded-lg font-medium text-sm transition-colors"
                        >
                            <Plus size={18} />
                        </button>
                    </div>

                    <div className="bg-slate-50 rounded-lg p-2 space-y-1 max-h-40 overflow-y-auto border border-slate-200">
                        {newPlanChecklist.length === 0 && (
                            <p className="text-xs text-slate-400 text-center py-2">No hay tareas definidas.</p>
                        )}
                        {newPlanChecklist.map((task, idx) => (
                            <div key={idx} className="flex justify-between items-center bg-white p-2 rounded shadow-sm border border-slate-100 text-sm">
                                <span className="text-slate-700">{idx + 1}. {task}</span>
                                <button type="button" onClick={() => removeTask(idx)} className="text-red-400 hover:text-red-600">
                                    <Trash2 size={14} />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>

              </form>
            </div>

            <div className="p-5 border-t border-slate-100 bg-slate-50 flex gap-3 rounded-b-2xl">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="flex-1 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSubmit}
                className="flex-1 bg-blue-600 text-white py-2.5 rounded-lg font-medium hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 flex justify-center items-center gap-2"
              >
                <Save size={18} /> Guardar Plan
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { MaintenancePlan, User, UserRole, Asset } from '../types';
import { CalendarClock, AlertCircle, CheckSquare, Clock, User as UserIcon, Filter, Play, Plus, X, Trash2, Save, LayoutGrid } from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  users: User[];
  assets: Asset[];
  onGenerateOrders: (planIds: string[], assigneeId: string) => void;
  onCreatePlan: (plan: MaintenancePlan) => void;
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ plans, users, assets, onGenerateOrders, onCreatePlan }) => {
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [selectedTechnician, setSelectedTechnician] = useState<string>('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  // New Plan Form State
  const [newPlanTitle, setNewPlanTitle] = useState('');
  const [newPlanAssetId, setNewPlanAssetId] = useState('');
  const [newPlanFreq, setNewPlanFreq] = useState(30);
  const [newPlanDate, setNewPlanDate] = useState('');
  const [newPlanHours, setNewPlanHours] = useState(1);
  const [newPlanSpecialty, setNewPlanSpecialty] = useState('Mecánica');
  const [newPlanChecklist, setNewPlanChecklist] = useState<string[]>([]);
  const [tempTask, setTempTask] = useState('');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // Logic for dates
  const today = new Date();
  const getDaysDiff = (dateStr: string) => {
    const due = new Date(dateStr);
    const diffTime = due.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // KPIs
  const totalHours = plans.reduce((acc, plan) => acc + plan.estimatedHours, 0);
  const overduePlans = plans.filter(p => getDaysDiff(p.nextDueDate) < 0).length;
  const criticalPlans = plans.filter(p => getDaysDiff(p.nextDueDate) >= 0 && getDaysDiff(p.nextDueDate) <= 5).length;
  const technicianCapacity = technicians.length * 40; // 40h week

  const togglePlanSelection = (id: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedPlanIds(newSet);
  };

  const selectAll = () => {
    if (selectedPlanIds.size === plans.length) setSelectedPlanIds(new Set());
    else setSelectedPlanIds(new Set(plans.map(p => p.id)));
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un plan.');
    if (!selectedTechnician) return alert('Debes seleccionar un técnico responsable.');

    onGenerateOrders(Array.from(selectedPlanIds), selectedTechnician);
    setSelectedPlanIds(new Set());
  };

  // Form Handlers
  const addTask = () => {
    if (tempTask.trim()) {
      setNewPlanChecklist([...newPlanChecklist, tempTask.trim()]);
      setTempTask('');
    }
  };

  const removeTask = (index: number) => {
    setNewPlanChecklist(newPlanChecklist.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlanTitle || !newPlanAssetId || !newPlanDate) {
      return alert('Por favor completa los campos obligatorios.');
    }

    const selectedAsset = assets.find(a => a.id === newPlanAssetId);

    const newPlan: MaintenancePlan = {
      id: `mp-${Date.now()}`,
      title: newPlanTitle,
      assetId: newPlanAssetId,
      assetName: selectedAsset?.name || 'Desconocido',
      frequencyDays: Number(newPlanFreq),
      nextDueDate: newPlanDate,
      estimatedHours: Number(newPlanHours),
      specialtyRequired: newPlanSpecialty,
      checklistTemplate: newPlanChecklist
    };

    onCreatePlan(newPlan);
    setIsModalOpen(false);
    // Reset form
    setNewPlanTitle('');
    setNewPlanAssetId('');
    setNewPlanChecklist([]);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Planificador de Preventivos</h2>
          <p className="text-slate-500">Gestión de recurrencias y generación de órdenes.</p>
        </div>

        <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg font-medium shadow-sm hover:bg-blue-700 transition-colors"
            >
              <Plus size={18} />
              Nuevo Plan
            </button>

            {/* Bulk Action Widget */}
            <div className="bg-white p-2 pr-4 rounded-lg shadow-sm border border-slate-200 flex items-center gap-3">
            <div className="flex items-center gap-2 pl-2 border-r border-slate-200 pr-3">
                <span className="text-xs font-bold text-slate-500 uppercase hidden md:inline">Asignación</span>
                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-0.5 rounded-full">
                {selectedPlanIds.size}
                </span>
            </div>

            <select 
                className="text-sm border-none focus:ring-0 text-slate-700 bg-transparent outline-none w-40"
                value={selectedTechnician}
                onChange={(e) => setSelectedTechnician(e.target.value)}
            >
                <option value="">- Asignar a -</option>
                {technicians.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>

            <button 
                onClick={handleBulkGenerate}
                disabled={selectedPlanIds.size === 0}
                className={`p-1.5 rounded text-sm font-medium transition-colors ${selectedPlanIds.size > 0 ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                title="Generar Órdenes"
            >
                <Play size={16} fill="currentColor" />
            </button>
            </div>
        </div>
      </div>

      {/* KPIs Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 text-red-600 rounded-lg"><AlertCircle size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Vencidos</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{overduePlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Clock size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Próx. 5 días</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{criticalPlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><CheckSquare size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Horas Planificadas</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{totalHours}h</span>
          <span className="text-xs text-slate-400 ml-2">/ {technicianCapacity}h Disp.</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
           <div className="w-full bg-slate-100 rounded-full h-2.5 mt-4 mb-2">
              <div 
                className="bg-blue-600 h-2.5 rounded-full" 
                style={{ width: `${Math.min((totalHours / technicianCapacity) * 100, 100)}%` }}
              ></div>
           </div>
           <p className="text-xs text-slate-500">Ocupación del Staff Semanal</p>
        </div>
      </div>

      {/* Main Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 w-12">
                <input type="checkbox" onChange={selectAll} checked={selectedPlanIds.size === plans.length && plans.length > 0} className="rounded border-slate-300"/>
              </th>
              <th className="px-6 py-4 font-semibold">Plan Maestro</th>
              <th className="px-6 py-4 font-semibold">Activo</th>
              <th className="px-6 py-4 font-semibold">Frecuencia</th>
              <th className="px-6 py-4 font-semibold">Próx. Vencimiento</th>
              <th className="px-6 py-4 font-semibold">Especialidad</th>
              <th className="px-6 py-4 font-semibold text-right">Horas Est.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {plans.map(plan => {
              const daysDiff = getDaysDiff(plan.nextDueDate);
              let statusClass = "bg-green-50 border-green-200";
              let textClass = "text-green-700";

              if (daysDiff < 0) {
                statusClass = "bg-red-50 border-red-200";
                textClass = "text-red-700";
              } else if (daysDiff <= 5) {
                statusClass = "bg-orange-50 border-orange-200";
                textClass = "text-orange-700";
              }

              return (
                <tr key={plan.id} className={`hover:bg-slate-50 transition-colors ${selectedPlanIds.has(plan.id) ? 'bg-blue-50/50' : ''}`}>
                  <td className="px-6 py-4">
                    <input 
                      type="checkbox" 
                      checked={selectedPlanIds.has(plan.id)}
                      onChange={() => togglePlanSelection(plan.id)}
                      className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{plan.title}</div>
                    <div className="text-xs text-slate-500">{plan.checklistTemplate.length} tareas definidas</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">{plan.assetName}</td>
                  <td className="px-6 py-4 text-slate-600">Cada {plan.frequencyDays} días</td>
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center px-2.5 py-1 rounded border ${statusClass} ${textClass} text-xs font-bold`}>
                      <CalendarClock size={14} className="mr-1.5" />
                      {plan.nextDueDate} 
                      <span className="ml-1 opacity-75">({daysDiff}d)</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                     <span className="px-2 py-1 bg-slate-100 rounded text-xs text-slate-600">{plan.specialtyRequired}</span>
                  </td>
                  <td className="px-6 py-4 text-right font-medium text-slate-700">{plan.estimatedHours}h</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* CREATE PLAN MODAL - REDESIGNED */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-4xl shadow-2xl flex flex-col max-h-[95vh] animate-in fade-in zoom-in-95 duration-200">
            {/* Header */}
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white rounded-t-2xl shrink-0">
              <div className="flex items-center gap-3">
                <div className="bg-blue-50 p-2 rounded-lg text-blue-600">
                    <LayoutGrid size={24} />
                </div>
                <div>
                    <h3 className="text-xl font-bold text-slate-900">Nuevo Plan Maestro</h3>
                    <p className="text-sm text-slate-500">Configuración de mantenimiento recurrente</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-50 p-2 rounded-full text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 overflow-y-auto">
              <form id="planForm" onSubmit={handleSubmit} className="space-y-8">

                {/* Main Grid Layout */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

                    {/* Left Column: Core Data */}
                    <div className="lg:col-span-7 space-y-6">
                        <div>
                            <label className="block text-sm font-semibold text-slate-800 mb-2">Título del Plan</label>
                            <input 
                                required
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 placeholder:text-slate-400 shadow-sm"
                                placeholder="Ej. Mantenimiento Preventivo de Compresor A"
                                value={newPlanTitle}
                                onChange={e => setNewPlanTitle(e.target.value)}
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <div>
                                <label className="block text-sm font-semibold text-slate-800 mb-2">Asignar a Equipo</label>
                                <select 
                                    required
                                    className="w-full border border-slate-300 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 shadow-sm"
                                    value={newPlanAssetId}
                                    onChange={e => setNewPlanAssetId(e.target.value)}
                                >
                                    <option value="">-- Seleccionar --</option>
                                    {assets.map(asset => (
                                        <option key={asset.id} value={asset.id}>{asset.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-semibold text-slate-800 mb-2">Especialidad</label>
                                <select 
                                    className="w-full border border-slate-300 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 shadow-sm"
                                    value={newPlanSpecialty}
                                    onChange={e => setNewPlanSpecialty(e.target.value)}
                                >
                                    <option value="Mecánica">Mecánica</option>
                                    <option value="Electricidad">Electricidad</option>
                                    <option value="Hidráulica">Hidráulica</option>
                                    <option value="Instrumentación">Instrumentación</option>
                                    <option value="General">General</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Right Column: Planning Details (Card) */}
                    <div className="lg:col-span-5 bg-slate-50 p-6 rounded-xl border border-slate-200 space-y-5">
                        <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2 pb-2 border-b border-slate-200">
                            <Clock size={16} className="text-blue-600"/> Programación
                        </h4>

                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Frecuencia</label>
                            <div className="flex items-center gap-2">
                                <input 
                                    required
                                    type="number" 
                                    min="1"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                    value={newPlanFreq}
                                    onChange={e => setNewPlanFreq(Number(e.target.value))}
                                />
                                <span className="text-sm font-medium text-slate-600">días</span>
                            </div>
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Próximo Vencimiento</label>
                            <input 
                                required
                                type="date" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                value={newPlanDate}
                                onChange={e => setNewPlanDate(e.target.value)}
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Carga Estimada</label>
                            <div className="flex items-center gap-2">
                                <input 
                                    required
                                    type="number" 
                                    min="0.5" step="0.5"
                                    className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                    value={newPlanHours}
                                    onChange={e => setNewPlanHours(Number(e.target.value))}
                                />
                                <span className="text-sm font-medium text-slate-600">horas</span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Checklist Section */}
                <div className="border-t border-slate-100 pt-8">
                    <div className="flex justify-between items-end mb-4">
                        <div>
                            <h4 className="text-base font-bold text-slate-900">Protocolo de Tareas (Check-list)</h4>
                            <p className="text-sm text-slate-500 mt-1">Define paso a paso las instrucciones técnicas.</p>
                        </div>
                        <span className="bg-blue-100 text-blue-800 text-xs font-bold px-3 py-1 rounded-full">
                            {newPlanChecklist.length} Pasos definidos
                        </span>
                    </div>

                    <div className="flex gap-3 mb-6">
                        <input 
                            type="text" 
                            className="flex-1 border border-slate-300 rounded-lg px-4 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 placeholder:text-slate-400 shadow-sm"
                            placeholder="Escribe una tarea y presiona Enter..."
                            value={tempTask}
                            onChange={e => setTempTask(e.target.value)}
                            onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addTask())}
                        />
                        <button 
                            type="button"
                            onClick={addTask}
                            className="bg-slate-800 text-white hover:bg-slate-900 px-6 py-3 rounded-lg font-bold text-sm transition-colors flex items-center gap-2 shadow-lg shadow-slate-200"
                        >
                            <Plus size={18} /> Agregar
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-60 overflow-y-auto pr-1">
                        {newPlanChecklist.length === 0 && (
                            <div className="col-span-full py-10 text-center border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50">
                                <CheckSquare className="mx-auto text-slate-300 mb-2" size={32} />
                                <p className="text-slate-500 font-medium">No hay tareas definidas</p>
                                <p className="text-slate-400 text-sm">Agrega pasos para guiar al técnico.</p>
                            </div>
                        )}
                        {newPlanChecklist.map((task, idx) => (
                            <div key={idx} className="flex items-center gap-3 bg-white p-3 rounded-lg shadow-sm border border-slate-200 group hover:border-blue-400 transition-colors">
                                <span className="flex-shrink-0 w-6 h-6 rounded-full bg-slate-100 text-slate-600 flex items-center justify-center text-xs font-bold border border-slate-200">
                                    {idx + 1}
                                </span>
                                <span className="flex-1 text-sm text-slate-700 font-medium">{task}</span>
                                <button 
                                    type="button" 
                                    onClick={() => removeTask(idx)} 
                                    className="text-slate-300 hover:text-red-500 hover:bg-red-50 p-1.5 rounded-md transition-all"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>
              </form>
            </div>

            <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 rounded-b-2xl shrink-0">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSubmit}
                className="bg-blue-600 text-white px-8 py-2.5 rounded-lg font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 flex items-center gap-2"
              >
                <Save size={18} /> Guardar Plan Maestro
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { MaintenancePlan, User, UserRole, Asset } from '../types';
import { CalendarClock, AlertCircle, CheckSquare, Clock, User as UserIcon, Filter, Play, Plus, X, Trash2, Save, LayoutGrid, ClipboardList, Calendar } from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  users: User[];
  assets: Asset[];
  onGenerateOrders: (planIds: string[], assigneeId: string) => void;
  onCreatePlan: (plan: MaintenancePlan) => void;
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ plans, users, assets, onGenerateOrders, onCreatePlan }) => {
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [selectedTechnician, setSelectedTechnician] = useState<string>('');
  const [isModalOpen, setIsModalOpen] = useState(false);

  // New Plan Form State
  const [newPlanTitle, setNewPlanTitle] = useState('');
  const [newPlanAssetId, setNewPlanAssetId] = useState('');
  const [newPlanFreq, setNewPlanFreq] = useState(30);
  const [newPlanDate, setNewPlanDate] = useState('');
  const [newPlanHours, setNewPlanHours] = useState(1);
  const [newPlanSpecialty, setNewPlanSpecialty] = useState('Mecánica');
  const [newPlanChecklist, setNewPlanChecklist] = useState<string[]>([]);
  const [tempTask, setTempTask] = useState('');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // Logic for dates
  const today = new Date();
  const getDaysDiff = (dateStr: string) => {
    const due = new Date(dateStr);
    const diffTime = due.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // KPIs
  const totalHours = plans.reduce((acc, plan) => acc + plan.estimatedHours, 0);
  const overduePlans = plans.filter(p => getDaysDiff(p.nextDueDate) < 0).length;
  const criticalPlans = plans.filter(p => getDaysDiff(p.nextDueDate) >= 0 && getDaysDiff(p.nextDueDate) <= 5).length;
  const technicianCapacity = technicians.length * 40; // 40h week

  const togglePlanSelection = (id: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedPlanIds(newSet);
  };

  const selectAll = () => {
    if (selectedPlanIds.size === plans.length) setSelectedPlanIds(new Set());
    else setSelectedPlanIds(new Set(plans.map(p => p.id)));
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un plan.');
    if (!selectedTechnician) return alert('Debes seleccionar un técnico responsable.');

    onGenerateOrders(Array.from(selectedPlanIds), selectedTechnician);
    setSelectedPlanIds(new Set());
  };

  // Form Handlers
  const addTask = () => {
    if (tempTask.trim()) {
      setNewPlanChecklist([...newPlanChecklist, tempTask.trim()]);
      setTempTask('');
    }
  };

  const removeTask = (index: number) => {
    setNewPlanChecklist(newPlanChecklist.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlanTitle || !newPlanAssetId || !newPlanDate) {
      return alert('Por favor completa los campos obligatorios.');
    }

    const selectedAsset = assets.find(a => a.id === newPlanAssetId);

    const newPlan: MaintenancePlan = {
      id: `mp-${Date.now()}`,
      title: newPlanTitle,
      assetId: newPlanAssetId,
      assetName: selectedAsset?.name || 'Desconocido',
      frequencyDays: Number(newPlanFreq),
      nextDueDate: newPlanDate,
      estimatedHours: Number(newPlanHours),
      specialtyRequired: newPlanSpecialty,
      checklistTemplate: newPlanChecklist
    };

    onCreatePlan(newPlan);
    setIsModalOpen(false);
    // Reset form
    setNewPlanTitle('');
    setNewPlanAssetId('');
    setNewPlanChecklist([]);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Planificador de Preventivos</h2>
          <p className="text-slate-500">Gestión de recurrencias y generación de órdenes.</p>
        </div>

        <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg font-medium shadow-sm hover:bg-blue-700 transition-colors"
            >
              <Plus size={18} />
              Nuevo Plan
            </button>

            {/* Bulk Action Widget */}
            <div className="bg-white p-2 pr-4 rounded-lg shadow-sm border border-slate-200 flex items-center gap-3">
            <div className="flex items-center gap-2 pl-2 border-r border-slate-200 pr-3">
                <span className="text-xs font-bold text-slate-500 uppercase hidden md:inline">Asignación</span>
                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-0.5 rounded-full">
                {selectedPlanIds.size}
                </span>
            </div>

            <select 
                className="text-sm border-none focus:ring-0 text-slate-700 bg-transparent outline-none w-40"
                value={selectedTechnician}
                onChange={(e) => setSelectedTechnician(e.target.value)}
            >
                <option value="">- Asignar a -</option>
                {technicians.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>

            <button 
                onClick={handleBulkGenerate}
                disabled={selectedPlanIds.size === 0}
                className={`p-1.5 rounded text-sm font-medium transition-colors ${selectedPlanIds.size > 0 ? 'bg-blue-600 text-white hover:bg-blue-700' : 'bg-slate-100 text-slate-400 cursor-not-allowed'}`}
                title="Generar Órdenes"
            >
                <Play size={16} fill="currentColor" />
            </button>
            </div>
        </div>
      </div>

      {/* KPIs Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 text-red-600 rounded-lg"><AlertCircle size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Vencidos</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{overduePlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Clock size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Próx. 5 días</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{criticalPlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><CheckSquare size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Horas Planificadas</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{totalHours}h</span>
          <span className="text-xs text-slate-400 ml-2">/ {technicianCapacity}h Disp.</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
           <div className="w-full bg-slate-100 rounded-full h-2.5 mt-4 mb-2">
              <div 
                className="bg-blue-600 h-2.5 rounded-full" 
                style={{ width: `${Math.min((totalHours / technicianCapacity) * 100, 100)}%` }}
              ></div>
           </div>
           <p className="text-xs text-slate-500">Ocupación del Staff Semanal</p>
        </div>
      </div>

      {/* Main Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 w-12">
                <input type="checkbox" onChange={selectAll} checked={selectedPlanIds.size === plans.length && plans.length > 0} className="rounded border-slate-300"/>
              </th>
              <th className="px-6 py-4 font-semibold">Plan Maestro</th>
              <th className="px-6 py-4 font-semibold">Activo</th>
              <th className="px-6 py-4 font-semibold">Frecuencia</th>
              <th className="px-6 py-4 font-semibold">Próx. Vencimiento</th>
              <th className="px-6 py-4 font-semibold">Especialidad</th>
              <th className="px-6 py-4 font-semibold text-right">Horas Est.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {plans.map(plan => {
              const daysDiff = getDaysDiff(plan.nextDueDate);
              let statusClass = "bg-green-50 border-green-200";
              let textClass = "text-green-700";

              if (daysDiff < 0) {
                statusClass = "bg-red-50 border-red-200";
                textClass = "text-red-700";
              } else if (daysDiff <= 5) {
                statusClass = "bg-orange-50 border-orange-200";
                textClass = "text-orange-700";
              }

              return (
                <tr key={plan.id} className={`hover:bg-slate-50 transition-colors ${selectedPlanIds.has(plan.id) ? 'bg-blue-50/50' : ''}`}>
                  <td className="px-6 py-4">
                    <input 
                      type="checkbox" 
                      checked={selectedPlanIds.has(plan.id)}
                      onChange={() => togglePlanSelection(plan.id)}
                      className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{plan.title}</div>
                    <div className="text-xs text-slate-500">{plan.checklistTemplate.length} tareas definidas</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">{plan.assetName}</td>
                  <td className="px-6 py-4 text-slate-600">Cada {plan.frequencyDays} días</td>
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center px-2.5 py-1 rounded border ${statusClass} ${textClass} text-xs font-bold`}>
                      <CalendarClock size={14} className="mr-1.5" />
                      {plan.nextDueDate} 
                      <span className="ml-1 opacity-75">({daysDiff}d)</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                     <span className="px-2 py-1 bg-slate-100 rounded text-xs text-slate-600">{plan.specialtyRequired}</span>
                  </td>
                  <td className="px-6 py-4 text-right font-medium text-slate-700">{plan.estimatedHours}h</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* CREATE PLAN MODAL - REDESIGNED */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-5xl shadow-2xl flex flex-col max-h-[95vh] animate-in fade-in zoom-in-95 duration-200">
            {/* Header */}
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white rounded-t-2xl shrink-0">
              <div className="flex items-center gap-3">
                <div className="bg-blue-50 p-2 rounded-lg text-blue-600">
                    <LayoutGrid size={24} />
                </div>
                <div>
                    <h3 className="text-xl font-bold text-slate-900">Nuevo Plan Maestro</h3>
                    <p className="text-sm text-slate-500">Configuración de mantenimiento recurrente</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-50 p-2 rounded-full text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 overflow-y-auto">
              <form id="planForm" onSubmit={handleSubmit} className="h-full">

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">

                    {/* COLUMNA IZQUIERDA: DATOS DEL PLAN */}
                    <div className="space-y-6">
                        <div className="pb-2 border-b border-slate-100 mb-4">
                            <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                                <LayoutGrid size={18} className="text-slate-400"/> Información General
                            </h4>
                        </div>

                        <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-2">Título del Plan</label>
                            <input 
                                required
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 placeholder:text-slate-400 shadow-sm transition-all"
                                placeholder="Ej. Mantenimiento Mensual Compresor"
                                value={newPlanTitle}
                                onChange={e => setNewPlanTitle(e.target.value)}
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <div>
                                <label className="block text-sm font-semibold text-slate-700 mb-2">Asignar a Equipo</label>
                                <select 
                                    required
                                    className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 shadow-sm"
                                    value={newPlanAssetId}
                                    onChange={e => setNewPlanAssetId(e.target.value)}
                                >
                                    <option value="">-- Seleccionar --</option>
                                    {assets.map(asset => (
                                        <option key={asset.id} value={asset.id}>{asset.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-semibold text-slate-700 mb-2">Especialidad</label>
                                <select 
                                    className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 shadow-sm"
                                    value={newPlanSpecialty}
                                    onChange={e => setNewPlanSpecialty(e.target.value)}
                                >
                                    <option value="Mecánica">Mecánica</option>
                                    <option value="Electricidad">Electricidad</option>
                                    <option value="Hidráulica">Hidráulica</option>
                                    <option value="Instrumentación">Instrumentación</option>
                                    <option value="General">General</option>
                                </select>
                            </div>
                        </div>

                        <div className="pt-4 pb-2 border-b border-slate-100 mb-4 mt-2">
                            <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                                <Calendar size={18} className="text-slate-400"/> Planificación
                            </h4>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Frecuencia (Días)</label>
                                <div className="relative">
                                    <input 
                                        required
                                        type="number" 
                                        min="1"
                                        className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                        value={newPlanFreq}
                                        onChange={e => setNewPlanFreq(Number(e.target.value))}
                                    />
                                    <span className="absolute right-3 top-2.5 text-slate-400 text-xs font-medium">días</span>
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Carga Estimada</label>
                                <div className="relative">
                                    <input 
                                        required
                                        type="number" 
                                        min="0.5" step="0.5"
                                        className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                        value={newPlanHours}
                                        onChange={e => setNewPlanHours(Number(e.target.value))}
                                    />
                                    <span className="absolute right-3 top-2.5 text-slate-400 text-xs font-medium">horas</span>
                                </div>
                            </div>

                            <div className="md:col-span-2">
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Próximo Vencimiento</label>
                                <input 
                                    required
                                    type="date" 
                                    className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 cursor-pointer"
                                    value={newPlanDate}
                                    onChange={e => setNewPlanDate(e.target.value)}
                                />
                            </div>
                        </div>
                    </div>

                    {/* COLUMNA DERECHA: CHECKLIST */}
                    <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 flex flex-col h-full">
                         <div className="flex justify-between items-end mb-4 shrink-0">
                            <div>
                                <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                                    <ClipboardList size={18} className="text-blue-600"/> Protocolo de Tareas
                                </h4>
                                <p className="text-xs text-slate-500 mt-1">Pasos técnicos para el operario.</p>
                            </div>
                            <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2.5 py-1 rounded-full border border-blue-200">
                                {newPlanChecklist.length} Pasos
                            </span>
                        </div>

                        <div className="flex gap-2 mb-4 shrink-0">
                            <input 
                                type="text" 
                                className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 placeholder:text-slate-400 shadow-sm"
                                placeholder="Nueva tarea..."
                                value={tempTask}
                                onChange={e => setTempTask(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addTask())}
                            />
                            <button 
                                type="button"
                                onClick={addTask}
                                className="bg-slate-800 text-white hover:bg-slate-900 px-4 py-2 rounded-lg font-bold text-sm transition-colors shadow-sm"
                            >
                                <Plus size={18} />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto pr-1 space-y-2 min-h-[200px]">
                            {newPlanChecklist.length === 0 && (
                                <div className="h-full flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50 p-6">
                                    <CheckSquare className="mx-auto text-slate-300 mb-3" size={40} />
                                    <p className="text-slate-500 font-medium text-sm">Lista vacía</p>
                                    <p className="text-slate-400 text-xs">Agrega las tareas de mantenimiento.</p>
                                </div>
                            )}
                            {newPlanChecklist.map((task, idx) => (
                                <div key={idx} className="flex items-start gap-3 bg-white p-3 rounded-lg shadow-sm border border-slate-200 group hover:border-blue-400 transition-colors animate-in slide-in-from-bottom-2 duration-200">
                                    <span className="flex-shrink-0 mt-0.5 w-5 h-5 rounded bg-slate-100 text-slate-500 flex items-center justify-center text-[10px] font-bold border border-slate-200">
                                        {idx + 1}
                                    </span>
                                    <span className="flex-1 text-sm text-slate-700 leading-snug break-words">{task}</span>
                                    <button 
                                        type="button" 
                                        onClick={() => removeTask(idx)} 
                                        className="text-slate-300 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

              </form>
            </div>

            <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 rounded-b-2xl shrink-0">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSubmit}
                className="bg-blue-600 text-white px-8 py-2.5 rounded-lg font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 flex items-center gap-2"
              >
                <Save size={18} /> Guardar Plan Maestro
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { TechnicianView } from './features/TechnicianView';
import { PreventiveMaintenance } from './features/PreventiveMaintenance';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    // If a Preventive OT is COMPLETED, we must update the Plan's nextDueDate
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          // Calculate new date
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          // Update Plan
          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[]) => {
    const newOrders: WorkOrder[] = [];

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado desde Plan Maestro.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          // Created without assignment
          assignedTechnicianId: undefined,
          technicianName: undefined,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, 
          status: WorkOrderStatus.PENDING,
          dueDate: plan.nextDueDate,
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`✅ Se han generado ${newOrders.length} Órdenes de Trabajo. Ahora puedes asignarlas desde el listado.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleCreateWorkOrder = () => {
    alert("Funcionalidad de Crear OT: En una app real, esto abriría un formulario completo.");
  };

  // Handlers for Inventory & Purchases
  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      quantity: qty,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING,
      totalCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada correctamente.");
  };

  const handleApprovePurchase = (reqId: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.APPROVED } : pr
    ));
  };

  const handleReceivePurchase = (reqId: string) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // Update Stock
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + request.quantity } 
        : item
    ));

    // Update Request Status
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.RECEIVED } : pr
    ));
  };

  // Role Simulation Handler
  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      // Redirect to appropriate landing view
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      {/* Simulation Banner - FOR DEMO PURPOSES */}
      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-slate-800 text-white text-xs p-2 rounded shadow-lg border border-slate-700 opacity-90 hover:opacity-100 transition-opacity cursor-pointer"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN}>Simular: Admin</option>
          <option value={UserRole.PLANNER}>Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN}>Simular: Técnico</option>
        </select>
      </div>

      {/* Render Views based on route */}
      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS} 
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          assets={MOCK_ASSETS}
          onGenerateOrders={handleGenerateOrders}
          onCreatePlan={handleCreatePlan}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

    </Layout>
  );
}

export default App;

import React, { useState } from 'react';
import { MaintenancePlan, Asset } from '../types';
import { CalendarClock, AlertCircle, CheckSquare, Clock, Play, Plus, X, Trash2, Save, LayoutGrid, ClipboardList, Calendar, CheckCircle2 } from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  assets: Asset[];
  onGenerateOrders: (planIds: string[]) => void;
  onCreatePlan: (plan: MaintenancePlan) => void;
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ plans, assets, onGenerateOrders, onCreatePlan }) => {
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [isModalOpen, setIsModalOpen] = useState(false);

  // New Plan Form State
  const [newPlanTitle, setNewPlanTitle] = useState('');
  const [newPlanAssetId, setNewPlanAssetId] = useState('');
  const [newPlanFreq, setNewPlanFreq] = useState(30);
  const [newPlanDate, setNewPlanDate] = useState('');
  const [newPlanHours, setNewPlanHours] = useState(1);
  const [newPlanSpecialty, setNewPlanSpecialty] = useState('Mecánica');
  const [newPlanChecklist, setNewPlanChecklist] = useState<string[]>([]);
  const [tempTask, setTempTask] = useState('');

  // Logic for dates
  const today = new Date();
  const getDaysDiff = (dateStr: string) => {
    const due = new Date(dateStr);
    const diffTime = due.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // KPIs
  const totalHours = plans.reduce((acc, plan) => acc + plan.estimatedHours, 0);
  const overduePlans = plans.filter(p => getDaysDiff(p.nextDueDate) < 0).length;
  const criticalPlans = plans.filter(p => getDaysDiff(p.nextDueDate) >= 0 && getDaysDiff(p.nextDueDate) <= 5).length;

  const togglePlanSelection = (id: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedPlanIds(newSet);
  };

  const selectAll = () => {
    if (selectedPlanIds.size === plans.length) setSelectedPlanIds(new Set());
    else setSelectedPlanIds(new Set(plans.map(p => p.id)));
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un plan.');
    onGenerateOrders(Array.from(selectedPlanIds));
    setSelectedPlanIds(new Set());
  };

  // Form Handlers
  const addTask = () => {
    if (tempTask.trim()) {
      setNewPlanChecklist([...newPlanChecklist, tempTask.trim()]);
      setTempTask('');
    }
  };

  const removeTask = (index: number) => {
    setNewPlanChecklist(newPlanChecklist.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPlanTitle || !newPlanAssetId || !newPlanDate) {
      return alert('Por favor completa los campos obligatorios.');
    }

    const selectedAsset = assets.find(a => a.id === newPlanAssetId);

    const newPlan: MaintenancePlan = {
      id: `mp-${Date.now()}`,
      title: newPlanTitle,
      assetId: newPlanAssetId,
      assetName: selectedAsset?.name || 'Desconocido',
      frequencyDays: Number(newPlanFreq),
      nextDueDate: newPlanDate,
      estimatedHours: Number(newPlanHours),
      specialtyRequired: newPlanSpecialty,
      checklistTemplate: newPlanChecklist
    };

    onCreatePlan(newPlan);
    setIsModalOpen(false);
    // Reset form
    setNewPlanTitle('');
    setNewPlanAssetId('');
    setNewPlanChecklist([]);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Planificador de Preventivos</h2>
          <p className="text-slate-500">Gestión de recurrencias y generación de órdenes.</p>
        </div>

        <div className="flex items-center gap-3">
             {selectedPlanIds.size > 0 && (
                <button 
                    onClick={handleBulkGenerate}
                    className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-lg font-medium shadow-sm hover:bg-slate-900 transition-all animate-in fade-in"
                >
                    <Play size={16} fill="currentColor" />
                    Generar {selectedPlanIds.size} OTs
                </button>
            )}

            <button 
              onClick={() => setIsModalOpen(true)}
              className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg font-medium shadow-sm hover:bg-blue-700 transition-colors"
            >
              <Plus size={18} />
              Nuevo Plan
            </button>
        </div>
      </div>

      {/* KPIs Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-red-100 text-red-600 rounded-lg"><AlertCircle size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Vencidos</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{overduePlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-orange-100 text-orange-600 rounded-lg"><Clock size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Próx. 5 días</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{criticalPlans}</span>
        </div>
        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100">
          <div className="flex items-center gap-3 mb-2">
            <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><CheckSquare size={20}/></div>
            <span className="text-sm font-medium text-slate-500">Horas Planificadas</span>
          </div>
          <span className="text-2xl font-bold text-slate-900">{totalHours}h</span>
          <span className="text-xs text-slate-400 ml-2">Totales</span>
        </div>
         <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-100 flex flex-col justify-center">
             <div className="flex items-center gap-3">
                 <div className="p-2 bg-green-100 text-green-600 rounded-lg"><CheckCircle2 size={20}/></div>
                 <div>
                    <span className="text-sm font-medium text-slate-500 block">Total Planes</span>
                    <span className="text-2xl font-bold text-slate-900">{plans.length}</span>
                 </div>
             </div>
        </div>
      </div>

      {/* Main Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-slate-50 text-slate-500 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 w-12">
                <input type="checkbox" onChange={selectAll} checked={selectedPlanIds.size === plans.length && plans.length > 0} className="rounded border-slate-300"/>
              </th>
              <th className="px-6 py-4 font-semibold">Plan Maestro</th>
              <th className="px-6 py-4 font-semibold">Activo</th>
              <th className="px-6 py-4 font-semibold">Frecuencia</th>
              <th className="px-6 py-4 font-semibold">Próx. Vencimiento</th>
              <th className="px-6 py-4 font-semibold">Especialidad</th>
              <th className="px-6 py-4 font-semibold text-right">Horas Est.</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {plans.map(plan => {
              const daysDiff = getDaysDiff(plan.nextDueDate);
              let statusClass = "bg-green-50 border-green-200";
              let textClass = "text-green-700";

              if (daysDiff < 0) {
                statusClass = "bg-red-50 border-red-200";
                textClass = "text-red-700";
              } else if (daysDiff <= 5) {
                statusClass = "bg-orange-50 border-orange-200";
                textClass = "text-orange-700";
              }

              return (
                <tr key={plan.id} className={`hover:bg-slate-50 transition-colors ${selectedPlanIds.has(plan.id) ? 'bg-blue-50/50' : ''}`}>
                  <td className="px-6 py-4">
                    <input 
                      type="checkbox" 
                      checked={selectedPlanIds.has(plan.id)}
                      onChange={() => togglePlanSelection(plan.id)}
                      className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                    />
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-900">{plan.title}</div>
                    <div className="text-xs text-slate-500">{plan.checklistTemplate.length} tareas definidas</div>
                  </td>
                  <td className="px-6 py-4 text-slate-600">{plan.assetName}</td>
                  <td className="px-6 py-4 text-slate-600">Cada {plan.frequencyDays} días</td>
                  <td className="px-6 py-4">
                    <div className={`inline-flex items-center px-2.5 py-1 rounded border ${statusClass} ${textClass} text-xs font-bold`}>
                      <CalendarClock size={14} className="mr-1.5" />
                      {plan.nextDueDate} 
                      <span className="ml-1 opacity-75">({daysDiff}d)</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                     <span className="px-2 py-1 bg-slate-100 rounded text-xs text-slate-600">{plan.specialtyRequired}</span>
                  </td>
                  <td className="px-6 py-4 text-right font-medium text-slate-700">{plan.estimatedHours}h</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* CREATE PLAN MODAL - REDESIGNED */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-5xl shadow-2xl flex flex-col max-h-[95vh] animate-in fade-in zoom-in-95 duration-200">
            {/* Header */}
            <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white rounded-t-2xl shrink-0">
              <div className="flex items-center gap-3">
                <div className="bg-blue-50 p-2 rounded-lg text-blue-600">
                    <LayoutGrid size={24} />
                </div>
                <div>
                    <h3 className="text-xl font-bold text-slate-900">Nuevo Plan Maestro</h3>
                    <p className="text-sm text-slate-500">Configuración de mantenimiento recurrente</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="bg-slate-50 p-2 rounded-full text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors">
                <X size={24} />
              </button>
            </div>

            <div className="p-8 overflow-y-auto">
              <form id="planForm" onSubmit={handleSubmit} className="h-full">

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">

                    {/* COLUMNA IZQUIERDA: DATOS DEL PLAN */}
                    <div className="space-y-6">
                        <div className="pb-2 border-b border-slate-100 mb-4">
                            <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                                <LayoutGrid size={18} className="text-slate-400"/> Información General
                            </h4>
                        </div>

                        <div>
                            <label className="block text-sm font-semibold text-slate-700 mb-2">Título del Plan</label>
                            <input 
                                required
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 placeholder:text-slate-400 shadow-sm transition-all"
                                placeholder="Ej. Mantenimiento Mensual Compresor"
                                value={newPlanTitle}
                                onChange={e => setNewPlanTitle(e.target.value)}
                            />
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                            <div>
                                <label className="block text-sm font-semibold text-slate-700 mb-2">Asignar a Equipo</label>
                                <select 
                                    required
                                    className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 shadow-sm"
                                    value={newPlanAssetId}
                                    onChange={e => setNewPlanAssetId(e.target.value)}
                                >
                                    <option value="">-- Seleccionar --</option>
                                    {assets.map(asset => (
                                        <option key={asset.id} value={asset.id}>{asset.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-semibold text-slate-700 mb-2">Especialidad</label>
                                <select 
                                    className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 shadow-sm"
                                    value={newPlanSpecialty}
                                    onChange={e => setNewPlanSpecialty(e.target.value)}
                                >
                                    <option value="Mecánica">Mecánica</option>
                                    <option value="Electricidad">Electricidad</option>
                                    <option value="Hidráulica">Hidráulica</option>
                                    <option value="Instrumentación">Instrumentación</option>
                                    <option value="General">General</option>
                                </select>
                            </div>
                        </div>

                        <div className="pt-4 pb-2 border-b border-slate-100 mb-4 mt-2">
                            <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                                <Calendar size={18} className="text-slate-400"/> Planificación
                            </h4>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                             <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Frecuencia (Días)</label>
                                <div className="relative">
                                    <input 
                                        required
                                        type="number" 
                                        min="1"
                                        className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                        value={newPlanFreq}
                                        onChange={e => setNewPlanFreq(Number(e.target.value))}
                                    />
                                    <span className="absolute right-3 top-2.5 text-slate-400 text-xs font-medium">días</span>
                                </div>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Carga Estimada</label>
                                <div className="relative">
                                    <input 
                                        required
                                        type="number" 
                                        min="0.5" step="0.5"
                                        className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900"
                                        value={newPlanHours}
                                        onChange={e => setNewPlanHours(Number(e.target.value))}
                                    />
                                    <span className="absolute right-3 top-2.5 text-slate-400 text-xs font-medium">horas</span>
                                </div>
                            </div>

                            <div className="md:col-span-2">
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1.5">Próximo Vencimiento</label>
                                <input 
                                    required
                                    type="date" 
                                    className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 cursor-pointer"
                                    value={newPlanDate}
                                    onChange={e => setNewPlanDate(e.target.value)}
                                />
                            </div>
                        </div>
                    </div>

                    {/* COLUMNA DERECHA: CHECKLIST */}
                    <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 flex flex-col h-full">
                         <div className="flex justify-between items-end mb-4 shrink-0">
                            <div>
                                <h4 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                                    <ClipboardList size={18} className="text-blue-600"/> Protocolo de Tareas
                                </h4>
                                <p className="text-xs text-slate-500 mt-1">Pasos técnicos para el operario.</p>
                            </div>
                            <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2.5 py-1 rounded-full border border-blue-200">
                                {newPlanChecklist.length} Pasos
                            </span>
                        </div>

                        <div className="flex gap-2 mb-4 shrink-0">
                            <input 
                                type="text" 
                                className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white text-slate-900 placeholder:text-slate-400 shadow-sm"
                                placeholder="Nueva tarea..."
                                value={tempTask}
                                onChange={e => setTempTask(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addTask())}
                            />
                            <button 
                                type="button"
                                onClick={addTask}
                                className="bg-slate-800 text-white hover:bg-slate-900 px-4 py-2 rounded-lg font-bold text-sm transition-colors shadow-sm"
                            >
                                <Plus size={18} />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto pr-1 space-y-2 min-h-[200px]">
                            {newPlanChecklist.length === 0 && (
                                <div className="h-full flex flex-col items-center justify-center text-center border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50 p-6">
                                    <CheckSquare className="mx-auto text-slate-300 mb-3" size={40} />
                                    <p className="text-slate-500 font-medium text-sm">Lista vacía</p>
                                    <p className="text-slate-400 text-xs">Agrega las tareas de mantenimiento.</p>
                                </div>
                            )}
                            {newPlanChecklist.map((task, idx) => (
                                <div key={idx} className="flex items-start gap-3 bg-white p-3 rounded-lg shadow-sm border border-slate-200 group hover:border-blue-400 transition-colors animate-in slide-in-from-bottom-2 duration-200">
                                    <span className="flex-shrink-0 mt-0.5 w-5 h-5 rounded bg-slate-100 text-slate-500 flex items-center justify-center text-[10px] font-bold border border-slate-200">
                                        {idx + 1}
                                    </span>
                                    <span className="flex-1 text-sm text-slate-700 leading-snug break-words">{task}</span>
                                    <button 
                                        type="button" 
                                        onClick={() => removeTask(idx)} 
                                        className="text-slate-300 hover:text-red-500 hover:bg-red-50 p-1 rounded transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"
                                    >
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

              </form>
            </div>

            <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 rounded-b-2xl shrink-0">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-6 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSubmit}
                className="bg-blue-600 text-white px-8 py-2.5 rounded-lg font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200 flex items-center gap-2"
              >
                <Save size={18} /> Guardar Plan Maestro
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, User, UserRole, WorkOrderType } from '../types';
import { Calendar, User as UserIcon, AlertTriangle, Clock, Filter, Plus, CalendarClock, Wrench, MoreHorizontal, ArrowRight, Activity } from 'lucide-react';

interface WorkOrderListProps {
  orders: WorkOrder[];
  users: User[];
  onAssign: (orderId: string, technicianId: string) => void;
  onCreate: () => void;
}

export const WorkOrderList: React.FC<WorkOrderListProps> = ({ orders, users, onAssign, onCreate }) => {
  const [filterSpecialty, setFilterSpecialty] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);
  const specialties = Array.from(new Set(technicians.map(t => t.specialty).filter(Boolean)));

  const filteredOrders = orders.filter(order => {
    const matchesSpecialty = filterSpecialty === 'ALL' || order.specialtyRequired === filterSpecialty;
    const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
    return matchesSpecialty && matchesStatus;
  });

  const getPriorityConfig = (p: Priority) => {
    switch (p) {
      case Priority.CRITICAL: return { color: 'text-red-700 bg-red-50 border-red-100', label: 'Crítica', dot: 'bg-red-500' };
      case Priority.HIGH: return { color: 'text-orange-700 bg-orange-50 border-orange-100', label: 'Alta', dot: 'bg-orange-500' };
      case Priority.MEDIUM: return { color: 'text-yellow-700 bg-yellow-50 border-yellow-100', label: 'Media', dot: 'bg-yellow-500' };
      default: return { color: 'text-blue-700 bg-blue-50 border-blue-100', label: 'Baja', dot: 'bg-blue-500' };
    }
  };

  const getStatusConfig = (s: WorkOrderStatus) => {
    switch (s) {
      case WorkOrderStatus.COMPLETED: return { color: 'bg-emerald-100 text-emerald-800', label: 'Completada' };
      case WorkOrderStatus.IN_PROGRESS: return { color: 'bg-blue-100 text-blue-800', label: 'En Progreso' };
      default: return { color: 'bg-slate-100 text-slate-600', label: 'Pendiente' };
    }
  };

  const getTypeConfig = (type: WorkOrderType) => {
    if (type === WorkOrderType.PREVENTIVE) {
      return { 
        icon: CalendarClock, 
        text: 'Preventivo', 
        style: 'text-indigo-600 bg-indigo-50 border-indigo-100' 
      };
    }
    return { 
      icon: Activity, 
      text: 'Correctivo', 
      style: 'text-amber-600 bg-amber-50 border-amber-100' 
    };
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Órdenes (OT)</h2>
          <p className="text-slate-500">Supervisión y asignación de tareas de mantenimiento.</p>
        </div>
        <button 
          onClick={onCreate}
          className="flex items-center gap-2 bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg font-medium transition-all shadow-lg shadow-slate-200 active:scale-95"
        >
          <Plus size={18} />
          Nueva OT
        </button>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-3 items-center sticky top-0 z-10 backdrop-blur-xl bg-white/90">
        <div className="flex items-center gap-2 text-slate-500 px-2">
          <Filter size={18} />
          <span className="text-sm font-bold uppercase tracking-wide">Filtros</span>
        </div>

        <div className="h-6 w-px bg-slate-200 hidden md:block"></div>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterSpecialty}
          onChange={(e) => setFilterSpecialty(e.target.value)}
        >
          <option value="ALL">Todas las Especialidades</option>
          {specialties.map(s => <option key={s} value={s as string}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="ALL">Todos los Estados</option>
          <option value={WorkOrderStatus.PENDING}>Pendientes</option>
          <option value={WorkOrderStatus.IN_PROGRESS}>En Progreso</option>
          <option value={WorkOrderStatus.COMPLETED}>Completadas</option>
        </select>

        <div className="ml-auto text-xs text-slate-400 font-medium hidden md:block">
            Mostrando {filteredOrders.length} órdenes
        </div>
      </div>

      {/* Grid Layout */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredOrders.map(ot => {
          const typeConfig = getTypeConfig(ot.type);
          const priorityConfig = getPriorityConfig(ot.priority);
          const statusConfig = getStatusConfig(ot.status);
          const TypeIcon = typeConfig.icon;

          return (
            <div key={ot.id} className="group bg-white rounded-xl shadow-sm border border-slate-200 hover:shadow-lg hover:border-indigo-200 transition-all duration-300 flex flex-col">

              {/* Card Header */}
              <div className="p-5 pb-3">
                <div className="flex justify-between items-start mb-3">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-bold border ${typeConfig.style}`}>
                        <TypeIcon size={14} />
                        {typeConfig.text}
                    </div>
                    <div className="flex items-center gap-2">
                         {ot.planId && (
                            <span className="text-[10px] font-mono text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100" title="Plan Maestro Vinculado">
                                PLAN
                            </span>
                        )}
                        <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                            {priorityConfig.label}
                        </span>
                    </div>
                </div>

                <h3 className="text-base font-bold text-slate-900 leading-tight mb-1 group-hover:text-indigo-600 transition-colors line-clamp-1" title={ot.title}>
                    {ot.title}
                </h3>

                <div className="flex items-center gap-1.5 text-slate-500 text-xs mb-3 font-medium">
                    <Wrench size={12} />
                    {ot.assetName}
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 h-10 leading-relaxed">
                    {ot.description}
                </p>
              </div>

              {/* Card Meta & Status */}
              <div className="px-5 py-3 border-t border-slate-50 bg-slate-50/50 flex items-center justify-between mt-auto">
                 <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                    <Calendar size={14} className="text-slate-400"/>
                    <span className={new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600 font-bold" : ""}>
                        {ot.dueDate}
                    </span>
                 </div>
                 <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${statusConfig.color}`}>
                    {statusConfig.label}
                 </span>
              </div>

              {/* Assignment Footer */}
              <div className="px-5 py-3 border-t border-slate-100 flex items-center gap-3">
                 <div className={`p-1.5 rounded-full ${ot.assignedTechnicianId ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                    <UserIcon size={16} />
                 </div>

                 <div className="flex-1 min-w-0">
                    {ot.status === WorkOrderStatus.COMPLETED ? (
                         <div className="text-xs font-bold text-slate-700 truncate">
                            {ot.technicianName}
                         </div>
                    ) : (
                        <select 
                            className="w-full bg-transparent text-sm font-medium text-slate-700 focus:outline-none cursor-pointer truncate"
                            value={ot.assignedTechnicianId || ''}
                            onChange={(e) => onAssign(ot.id, e.target.value)}
                        >
                            <option value="">Asignar Técnico...</option>
                            {technicians
                                .filter(t => t.specialty === ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name}</option>
                            ))}
                            <option disabled className="bg-slate-100 text-xs">--- Otros ---</option>
                            {technicians
                                .filter(t => t.specialty !== ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name} (Otr)</option>
                            ))}
                        </select>
                    )}
                    {ot.assignedTechnicianId && ot.status !== WorkOrderStatus.COMPLETED && (
                        <p className="text-[10px] text-indigo-600 font-medium truncate">Asignado</p>
                    )}
                 </div>
              </div>
            </div>
          );
        })}

        {filteredOrders.length === 0 && (
          <div className="col-span-full py-16 flex flex-col items-center justify-center text-center bg-white rounded-xl border border-dashed border-slate-300">
            <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                <Filter size={32} />
            </div>
            <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
            <p className="text-slate-400 text-sm">Prueba ajustando los filtros de búsqueda.</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, User, UserRole, WorkOrderType } from '../types';
import { Calendar, User as UserIcon, AlertTriangle, Clock, Filter, Plus, CalendarClock, Wrench, MoreHorizontal, ArrowRight, Activity, LayoutList, LayoutGrid } from 'lucide-react';

interface WorkOrderListProps {
  orders: WorkOrder[];
  users: User[];
  onAssign: (orderId: string, technicianId: string) => void;
  onCreate: () => void;
}

export const WorkOrderList: React.FC<WorkOrderListProps> = ({ orders, users, onAssign, onCreate }) => {
  const [filterSpecialty, setFilterSpecialty] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('table'); // Default to Table for high density

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);
  const specialties = Array.from(new Set(technicians.map(t => t.specialty).filter(Boolean)));

  const filteredOrders = orders.filter(order => {
    const matchesSpecialty = filterSpecialty === 'ALL' || order.specialtyRequired === filterSpecialty;
    const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
    return matchesSpecialty && matchesStatus;
  });

  const getPriorityConfig = (p: Priority) => {
    switch (p) {
      case Priority.CRITICAL: return { color: 'text-red-700 bg-red-50 border-red-100', label: 'Crítica', dot: 'bg-red-500' };
      case Priority.HIGH: return { color: 'text-orange-700 bg-orange-50 border-orange-100', label: 'Alta', dot: 'bg-orange-500' };
      case Priority.MEDIUM: return { color: 'text-yellow-700 bg-yellow-50 border-yellow-100', label: 'Media', dot: 'bg-yellow-500' };
      default: return { color: 'text-blue-700 bg-blue-50 border-blue-100', label: 'Baja', dot: 'bg-blue-500' };
    }
  };

  const getStatusConfig = (s: WorkOrderStatus) => {
    switch (s) {
      case WorkOrderStatus.COMPLETED: return { color: 'bg-emerald-100 text-emerald-800', label: 'Completada' };
      case WorkOrderStatus.IN_PROGRESS: return { color: 'bg-blue-100 text-blue-800', label: 'En Progreso' };
      default: return { color: 'bg-slate-100 text-slate-600', label: 'Pendiente' };
    }
  };

  const getTypeConfig = (type: WorkOrderType) => {
    if (type === WorkOrderType.PREVENTIVE) {
      return { 
        icon: CalendarClock, 
        text: 'Preventivo', 
        style: 'text-indigo-600 bg-indigo-50 border-indigo-100' 
      };
    }
    return { 
      icon: Activity, 
      text: 'Correctivo', 
      style: 'text-amber-600 bg-amber-50 border-amber-100' 
    };
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Órdenes (OT)</h2>
          <p className="text-slate-500">Supervisión y asignación de tareas de mantenimiento.</p>
        </div>
        <div className="flex items-center gap-3">
            {/* View Toggle (Desktop Only) */}
            <div className="hidden md:flex bg-white rounded-lg border border-slate-200 p-1 shadow-sm">
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2 rounded transition-colors ${viewMode === 'table' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tabla"
                >
                    <LayoutList size={18} />
                </button>
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2 rounded transition-colors ${viewMode === 'grid' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tarjetas"
                >
                    <LayoutGrid size={18} />
                </button>
            </div>

            <button 
            onClick={onCreate}
            className="flex items-center gap-2 bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg font-medium transition-all shadow-lg shadow-slate-200 active:scale-95"
            >
            <Plus size={18} />
            Nueva OT
            </button>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-3 items-center sticky top-0 z-10 backdrop-blur-xl bg-white/90">
        <div className="flex items-center gap-2 text-slate-500 px-2">
          <Filter size={18} />
          <span className="text-sm font-bold uppercase tracking-wide">Filtros</span>
        </div>

        <div className="h-6 w-px bg-slate-200 hidden md:block"></div>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterSpecialty}
          onChange={(e) => setFilterSpecialty(e.target.value)}
        >
          <option value="ALL">Todas las Especialidades</option>
          {specialties.map(s => <option key={s} value={s as string}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="ALL">Todos los Estados</option>
          <option value={WorkOrderStatus.PENDING}>Pendientes</option>
          <option value={WorkOrderStatus.IN_PROGRESS}>En Progreso</option>
          <option value={WorkOrderStatus.COMPLETED}>Completadas</option>
        </select>

        <div className="ml-auto text-xs text-slate-400 font-medium hidden md:block">
            Mostrando {filteredOrders.length} órdenes
        </div>
      </div>

      {/* TABLE VIEW (Desktop Default) */}
      <div className={`hidden md:block ${viewMode === 'grid' ? '!hidden' : ''}`}>
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider font-semibold">
                    <tr>
                        <th className="px-6 py-4 w-16">Tipo</th>
                        <th className="px-6 py-4">ID / Asunto</th>
                        <th className="px-6 py-4">Activo</th>
                        <th className="px-6 py-4">Prioridad</th>
                        <th className="px-6 py-4">Estado</th>
                        <th className="px-6 py-4">Asignación</th>
                        <th className="px-6 py-4 text-right">Vencimiento</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredOrders.map(ot => {
                        const typeConfig = getTypeConfig(ot.type);
                        const priorityConfig = getPriorityConfig(ot.priority);
                        const statusConfig = getStatusConfig(ot.status);
                        const TypeIcon = typeConfig.icon;

                        return (
                            <tr key={ot.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4">
                                     <div className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${typeConfig.style}`} title={typeConfig.text}>
                                        <TypeIcon size={16} />
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="text-xs font-mono text-slate-400 mb-0.5">{ot.id}</span>
                                        <span className="font-bold text-slate-900 group-hover:text-indigo-600 transition-colors truncate max-w-[200px]" title={ot.title}>{ot.title}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">
                                    <div className="flex items-center gap-2">
                                        <Wrench size={14} className="text-slate-400"/>
                                        <span className="truncate max-w-[150px]" title={ot.assetName}>{ot.assetName}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                                        <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                                        {priorityConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${statusConfig.color}`}>
                                        {statusConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    {ot.status === WorkOrderStatus.COMPLETED ? (
                                        <div className="flex items-center gap-2 text-xs font-medium text-slate-700">
                                            <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-slate-500"><UserIcon size={12}/></div>
                                            {ot.technicianName}
                                        </div>
                                    ) : (
                                        <div className="relative group/select">
                                            <select 
                                                className="w-full bg-slate-50 border border-slate-200 text-xs font-medium text-slate-700 rounded-md py-1.5 pl-2 pr-6 focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer appearance-none hover:bg-slate-100 transition-colors"
                                                value={ot.assignedTechnicianId || ''}
                                                onChange={(e) => onAssign(ot.id, e.target.value)}
                                            >
                                                <option value="">-- Sin Asignar --</option>
                                                {technicians
                                                    .filter(t => t.specialty === ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                                <option disabled>--- Otros ---</option>
                                                {technicians
                                                    .filter(t => t.specialty !== ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                            </select>
                                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-400">
                                                <UserIcon size={12} />
                                            </div>
                                        </div>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <span className={`text-xs font-medium ${new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600" : "text-slate-500"}`}>
                                        {ot.dueDate}
                                    </span>
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
             {filteredOrders.length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-center">
                    <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                        <Filter size={32} />
                    </div>
                    <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
                </div>
            )}
        </div>
      </div>

      {/* GRID VIEW (Mobile Default, Desktop Optional) */}
      <div className={`grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 ${viewMode === 'table' ? 'md:hidden' : ''}`}>
        {filteredOrders.map(ot => {
          const typeConfig = getTypeConfig(ot.type);
          const priorityConfig = getPriorityConfig(ot.priority);
          const statusConfig = getStatusConfig(ot.status);
          const TypeIcon = typeConfig.icon;

          return (
            <div key={ot.id} className="group bg-white rounded-xl shadow-sm border border-slate-200 hover:shadow-lg hover:border-indigo-200 transition-all duration-300 flex flex-col">

              {/* Card Header */}
              <div className="p-5 pb-3">
                <div className="flex justify-between items-start mb-3">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-bold border ${typeConfig.style}`}>
                        <TypeIcon size={14} />
                        {typeConfig.text}
                    </div>
                    <div className="flex items-center gap-2">
                         {ot.planId && (
                            <span className="text-[10px] font-mono text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100" title="Plan Maestro Vinculado">
                                PLAN
                            </span>
                        )}
                        <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                            {priorityConfig.label}
                        </span>
                    </div>
                </div>

                <h3 className="text-base font-bold text-slate-900 leading-tight mb-1 group-hover:text-indigo-600 transition-colors line-clamp-1" title={ot.title}>
                    {ot.title}
                </h3>

                <div className="flex items-center gap-1.5 text-slate-500 text-xs mb-3 font-medium">
                    <Wrench size={12} />
                    {ot.assetName}
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 h-10 leading-relaxed">
                    {ot.description}
                </p>
              </div>

              {/* Card Meta & Status */}
              <div className="px-5 py-3 border-t border-slate-50 bg-slate-50/50 flex items-center justify-between mt-auto">
                 <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                    <Calendar size={14} className="text-slate-400"/>
                    <span className={new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600 font-bold" : ""}>
                        {ot.dueDate}
                    </span>
                 </div>
                 <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${statusConfig.color}`}>
                    {statusConfig.label}
                 </span>
              </div>

              {/* Assignment Footer */}
              <div className="px-5 py-3 border-t border-slate-100 flex items-center gap-3">
                 <div className={`p-1.5 rounded-full ${ot.assignedTechnicianId ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                    <UserIcon size={16} />
                 </div>

                 <div className="flex-1 min-w-0">
                    {ot.status === WorkOrderStatus.COMPLETED ? (
                         <div className="text-xs font-bold text-slate-700 truncate">
                            {ot.technicianName}
                         </div>
                    ) : (
                        <select 
                            className="w-full bg-transparent text-sm font-medium text-slate-700 focus:outline-none cursor-pointer truncate"
                            value={ot.assignedTechnicianId || ''}
                            onChange={(e) => onAssign(ot.id, e.target.value)}
                        >
                            <option value="">Asignar Técnico...</option>
                            {technicians
                                .filter(t => t.specialty === ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name}</option>
                            ))}
                            <option disabled className="bg-slate-100 text-xs">--- Otros ---</option>
                            {technicians
                                .filter(t => t.specialty !== ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name} (Otr)</option>
                            ))}
                        </select>
                    )}
                    {ot.assignedTechnicianId && ot.status !== WorkOrderStatus.COMPLETED && (
                        <p className="text-[10px] text-indigo-600 font-medium truncate">Asignado</p>
                    )}
                 </div>
              </div>
            </div>
          );
        })}

        {filteredOrders.length === 0 && viewMode === 'grid' && (
             <div className="col-span-full py-16 flex flex-col items-center justify-center text-center bg-white rounded-xl border border-dashed border-slate-300">
                <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                    <Filter size={32} />
                </div>
                <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
             </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { TechnicianView } from './features/TechnicianView';
import { PreventiveMaintenance } from './features/PreventiveMaintenance';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    // If a Preventive OT is COMPLETED, we must update the Plan's nextDueDate
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          // Calculate new date
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          // Update Plan
          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[]) => {
    const newOrders: WorkOrder[] = [];

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado desde Plan Maestro.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          // Created without assignment
          assignedTechnicianId: undefined,
          technicianName: undefined,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, 
          status: WorkOrderStatus.PENDING,
          dueDate: plan.nextDueDate,
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`✅ Se han generado ${newOrders.length} Órdenes de Trabajo. Ahora puedes asignarlas desde el listado.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleCreateWorkOrder = (newOrder: WorkOrder) => {
    setWorkOrders(prev => [newOrder, ...prev]);
    // No alert needed, UI update is immediate
  };

  // Handlers for Inventory & Purchases
  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      quantity: qty,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING,
      totalCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada correctamente.");
  };

  const handleApprovePurchase = (reqId: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.APPROVED } : pr
    ));
  };

  const handleReceivePurchase = (reqId: string) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // Update Stock
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + request.quantity } 
        : item
    ));

    // Update Request Status
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.RECEIVED } : pr
    ));
  };

  // Role Simulation Handler
  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      // Redirect to appropriate landing view
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      {/* Simulation Banner - FOR DEMO PURPOSES */}
      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-slate-800 text-white text-xs p-2 rounded shadow-lg border border-slate-700 opacity-90 hover:opacity-100 transition-opacity cursor-pointer"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN}>Simular: Admin</option>
          <option value={UserRole.PLANNER}>Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN}>Simular: Técnico</option>
        </select>
      </div>

      {/* Render Views based on route */}
      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS}
          assets={MOCK_ASSETS}
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          assets={MOCK_ASSETS}
          onGenerateOrders={handleGenerateOrders}
          onCreatePlan={handleCreatePlan}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Inventory 
          inventory={inventory}
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onRequestPurchase={handleRequestPurchase}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

    </Layout>
  );
}

export default App;

import React, { useState } from 'react';
