                    </div>
                </div>

                <h3 className="text-base font-bold text-slate-900 leading-tight mb-1 group-hover:text-indigo-600 transition-colors line-clamp-1" title={ot.title}>
                    {ot.title}
                </h3>

                <div className="flex items-center gap-1.5 text-slate-500 text-xs mb-3 font-medium">
                    <Wrench size={12} />
                    {ot.assetName}
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 h-10 leading-relaxed">
                    {ot.description}
                </p>
              </div>

              {/* Card Meta & Status */}
              <div className="px-5 py-3 border-t border-slate-50 bg-slate-50/50 flex items-center justify-between mt-auto">
                 <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                    <Calendar size={14} className="text-slate-400"/>
                    <span className={new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600 font-bold" : ""}>
                        {ot.dueDate}
                    </span>
                 </div>
                 <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${statusConfig.color}`}>
                    {statusConfig.label}
                 </span>
              </div>

              {/* Assignment Footer */}
              <div className="px-5 py-3 border-t border-slate-100 flex items-center gap-3">
                 <div className={`p-1.5 rounded-full ${ot.assignedTechnicianId ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                    <UserIcon size={16} />
                 </div>

                 <div className="flex-1 min-w-0">
                    {ot.status === WorkOrderStatus.COMPLETED ? (
                         <div className="text-xs font-bold text-slate-700 truncate">
                            {ot.technicianName}
                         </div>
                    ) : (
                        <select 
                            className="w-full bg-transparent text-sm font-medium text-slate-700 focus:outline-none cursor-pointer truncate"
                            value={ot.assignedTechnicianId || ''}
                            onChange={(e) => onAssign(ot.id, e.target.value)}
                        >
                            <option value="">Asignar Técnico...</option>
                            {technicians
                                .filter(t => t.specialty === ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name}</option>
                            ))}
                            <option disabled className="bg-slate-100 text-xs">--- Otros ---</option>
                            {technicians
                                .filter(t => t.specialty !== ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name} (Otr)</option>
                            ))}
                        </select>
                    )}
                    {ot.assignedTechnicianId && ot.status !== WorkOrderStatus.COMPLETED && (
                        <p className="text-[10px] text-indigo-600 font-medium truncate">Asignado</p>
                    )}
                 </div>
              </div>
            </div>
          );
        })}

        {filteredOrders.length === 0 && viewMode === 'grid' && (
             <div className="col-span-full py-16 flex flex-col items-center justify-center text-center bg-white rounded-xl border border-dashed border-slate-300">
                <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                    <Filter size={32} />
                </div>
                <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
             </div>
        )}
      </div>

       {/* CREATE MODAL */}
       {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-lg shadow-2xl animate-in fade-in zoom-in-95 duration-200">
            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-2xl">
              <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                <Activity className="text-blue-600" size={20}/>
                Nueva Orden de Trabajo
              </h3>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 hover:bg-slate-200 p-1 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            <form onSubmit={handleCreateSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Título del Problema</label>
                <input 
                  autoFocus
                  required
                  type="text" 
                  className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="Ej. Falla en motor de cinta"
                  value={newOrderTitle}
                  onChange={e => setNewOrderTitle(e.target.value)}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Activo / Equipo</label>
                    <select 
                      required
                      className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                      value={newOrderAsset}
                      onChange={e => setNewOrderAsset(e.target.value)}
                    >
                      <option value="">-- Seleccionar --</option>
                      {assets.map(a => (
                        <option key={a.id} value={a.id}>{a.name}</option>
                      ))}
                    </select>
                 </div>
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Prioridad</label>
                    <select 
                      className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                      value={newOrderPriority}
                      onChange={e => setNewOrderPriority(e.target.value as Priority)}
                    >
                      <option value={Priority.LOW}>Baja</option>
                      <option value={Priority.MEDIUM}>Media</option>
                      <option value={Priority.HIGH}>Alta</option>
                      <option value={Priority.CRITICAL}>Crítica</option>
                    </select>
                 </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Especialidad</label>
                    <select 
                      className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                      value={newOrderSpecialty}
                      onChange={e => setNewOrderSpecialty(e.target.value)}
                    >
                      <option value="Mecánica">Mecánica</option>
                      <option value="Electricidad">Electricidad</option>
                      <option value="Hidráulica">Hidráulica</option>
                      <option value="Instrumentación">Instrumentación</option>
                      <option value="General">General</option>
                    </select>
                 </div>
                 <div>
                    <label className="block text-sm font-semibold text-slate-700 mb-1">Vencimiento</label>
                    <input 
                      required
                      type="date"
                      className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none bg-white"
                      value={newOrderDate}
                      onChange={e => setNewOrderDate(e.target.value)}
                    />
                 </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-1">Descripción Detallada</label>
                <textarea 
                  className="w-full border border-slate-300 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-blue-500 outline-none h-24 resize-none"
                  placeholder="Detalles adicionales sobre la falla o tarea..."
                  value={newOrderDesc}
                  onChange={e => setNewOrderDesc(e.target.value)}
                />
              </div>

              <div className="pt-2 flex gap-3">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-lg transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  type="submit"
                  className="flex-1 bg-slate-900 text-white py-2.5 rounded-lg font-bold hover:bg-slate-800 transition-colors shadow-lg flex items-center justify-center gap-2"
                >
                  <Save size={18} /> Crear Orden
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, User, UserRole, WorkOrderType, Asset } from '../types';
import { Calendar, User as UserIcon, AlertTriangle, Clock, Filter, Plus, CalendarClock, Wrench, MoreHorizontal, ArrowRight, Activity, LayoutList, LayoutGrid, X, Save, FileText, ChevronDown } from 'lucide-react';

interface WorkOrderListProps {
  orders: WorkOrder[];
  users: User[];
  assets: Asset[];
  onAssign: (orderId: string, technicianId: string) => void;
  onCreate: (order: WorkOrder) => void;
}

export const WorkOrderList: React.FC<WorkOrderListProps> = ({ orders, users, assets, onAssign, onCreate }) => {
  const [filterSpecialty, setFilterSpecialty] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('table'); 
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Create Form State
  const [newOrderTitle, setNewOrderTitle] = useState('');
  const [newOrderDesc, setNewOrderDesc] = useState('');
  const [newOrderAsset, setNewOrderAsset] = useState('');
  const [newOrderPriority, setNewOrderPriority] = useState<Priority>(Priority.MEDIUM);
  const [newOrderSpecialty, setNewOrderSpecialty] = useState('Mecánica');
  const [newOrderDate, setNewOrderDate] = useState('');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);
  const specialties = Array.from(new Set(technicians.map(t => t.specialty).filter(Boolean)));

  const filteredOrders = orders.filter(order => {
    const matchesSpecialty = filterSpecialty === 'ALL' || order.specialtyRequired === filterSpecialty;
    const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
    return matchesSpecialty && matchesStatus;
  });

  const getPriorityConfig = (p: Priority) => {
    switch (p) {
      case Priority.CRITICAL: return { color: 'text-red-700 bg-red-50 border-red-100', label: 'Crítica', dot: 'bg-red-500' };
      case Priority.HIGH: return { color: 'text-orange-700 bg-orange-50 border-orange-100', label: 'Alta', dot: 'bg-orange-500' };
      case Priority.MEDIUM: return { color: 'text-yellow-700 bg-yellow-50 border-yellow-100', label: 'Media', dot: 'bg-yellow-500' };
      default: return { color: 'text-blue-700 bg-blue-50 border-blue-100', label: 'Baja', dot: 'bg-blue-500' };
    }
  };

  const getStatusConfig = (s: WorkOrderStatus) => {
    switch (s) {
      case WorkOrderStatus.COMPLETED: return { color: 'bg-emerald-100 text-emerald-800', label: 'Completada' };
      case WorkOrderStatus.IN_PROGRESS: return { color: 'bg-blue-100 text-blue-800', label: 'En Progreso' };
      default: return { color: 'bg-slate-100 text-slate-600', label: 'Pendiente' };
    }
  };

  const getTypeConfig = (type: WorkOrderType) => {
    if (type === WorkOrderType.PREVENTIVE) {
      return { 
        icon: CalendarClock, 
        text: 'Preventivo', 
        style: 'text-indigo-600 bg-indigo-50 border-indigo-100' 
      };
    }
    return { 
      icon: Activity, 
      text: 'Correctivo', 
      style: 'text-amber-600 bg-amber-50 border-amber-100' 
    };
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newOrderTitle || !newOrderAsset || !newOrderDate) {
      alert("Por favor completa los campos requeridos.");
      return;
    }

    const selectedAsset = assets.find(a => a.id === newOrderAsset);

    const newOrder: WorkOrder = {
      id: `ot-${Date.now()}`,
      title: newOrderTitle,
      description: newOrderDesc,
      assetId: newOrderAsset,
      assetName: selectedAsset?.name || 'Desconocido',
      type: WorkOrderType.CORRECTIVE, // Default for manual creation
      priority: newOrderPriority,
      status: WorkOrderStatus.PENDING,
      dueDate: newOrderDate,
      specialtyRequired: newOrderSpecialty,
    };

    onCreate(newOrder);
    setIsModalOpen(false);

    // Reset form
    setNewOrderTitle('');
    setNewOrderDesc('');
    setNewOrderAsset('');
    setNewOrderPriority(Priority.MEDIUM);
    setNewOrderDate('');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Órdenes (OT)</h2>
          <p className="text-slate-500">Supervisión y asignación de tareas de mantenimiento.</p>
        </div>
        <div className="flex items-center gap-3">
            {/* View Toggle (Desktop Only) */}
            <div className="hidden md:flex bg-white rounded-lg border border-slate-200 p-1 shadow-sm">
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2 rounded transition-colors ${viewMode === 'table' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tabla"
                >
                    <LayoutList size={18} />
                </button>
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2 rounded transition-colors ${viewMode === 'grid' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tarjetas"
                >
                    <LayoutGrid size={18} />
                </button>
            </div>

            <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg font-medium transition-all shadow-lg shadow-slate-200 active:scale-95"
            >
            <Plus size={18} />
            Nueva OT
            </button>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-3 items-center sticky top-0 z-10 backdrop-blur-xl bg-white/90">
        <div className="flex items-center gap-2 text-slate-500 px-2">
          <Filter size={18} />
          <span className="text-sm font-bold uppercase tracking-wide">Filtros</span>
        </div>

        <div className="h-6 w-px bg-slate-200 hidden md:block"></div>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterSpecialty}
          onChange={(e) => setFilterSpecialty(e.target.value)}
        >
          <option value="ALL">Todas las Especialidades</option>
          {specialties.map(s => <option key={s} value={s as string}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="ALL">Todos los Estados</option>
          <option value={WorkOrderStatus.PENDING}>Pendientes</option>
          <option value={WorkOrderStatus.IN_PROGRESS}>En Progreso</option>
          <option value={WorkOrderStatus.COMPLETED}>Completadas</option>
        </select>

        <div className="ml-auto text-xs text-slate-400 font-medium hidden md:block">
            Mostrando {filteredOrders.length} órdenes
        </div>
      </div>

      {/* TABLE VIEW (Desktop Default) */}
      <div className={`hidden md:block ${viewMode === 'grid' ? '!hidden' : ''}`}>
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider font-semibold">
                    <tr>
                        <th className="px-6 py-4 w-16">Tipo</th>
                        <th className="px-6 py-4">ID / Asunto</th>
                        <th className="px-6 py-4">Activo</th>
                        <th className="px-6 py-4">Prioridad</th>
                        <th className="px-6 py-4">Estado</th>
                        <th className="px-6 py-4">Asignación</th>
                        <th className="px-6 py-4 text-right">Vencimiento</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredOrders.map(ot => {
                        const typeConfig = getTypeConfig(ot.type);
                        const priorityConfig = getPriorityConfig(ot.priority);
                        const statusConfig = getStatusConfig(ot.status);
                        const TypeIcon = typeConfig.icon;

                        return (
                            <tr key={ot.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4">
                                     <div className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${typeConfig.style}`} title={typeConfig.text}>
                                        <TypeIcon size={16} />
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="text-xs font-mono text-slate-400 mb-0.5">{ot.id}</span>
                                        <span className="font-bold text-slate-900 group-hover:text-indigo-600 transition-colors truncate max-w-[200px]" title={ot.title}>{ot.title}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">
                                    <div className="flex items-center gap-2">
                                        <Wrench size={14} className="text-slate-400"/>
                                        <span className="truncate max-w-[150px]" title={ot.assetName}>{ot.assetName}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                                        <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                                        {priorityConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${statusConfig.color}`}>
                                        {statusConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    {ot.status === WorkOrderStatus.COMPLETED ? (
                                        <div className="flex items-center gap-2 text-xs font-medium text-slate-700">
                                            <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-slate-500"><UserIcon size={12}/></div>
                                            {ot.technicianName}
                                        </div>
                                    ) : (
                                        <div className="relative group/select">
                                            <select 
                                                className="w-full bg-slate-50 border border-slate-200 text-xs font-medium text-slate-700 rounded-md py-1.5 pl-2 pr-6 focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer appearance-none hover:bg-slate-100 transition-colors"
                                                value={ot.assignedTechnicianId || ''}
                                                onChange={(e) => onAssign(ot.id, e.target.value)}
                                            >
                                                <option value="">-- Sin Asignar --</option>
                                                {technicians
                                                    .filter(t => t.specialty === ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                                <option disabled>--- Otros ---</option>
                                                {technicians
                                                    .filter(t => t.specialty !== ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                            </select>
                                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-400">
                                                <UserIcon size={12} />
                                            </div>
                                        </div>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <span className={`text-xs font-medium ${new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600" : "text-slate-500"}`}>
                                        {ot.dueDate}
                                    </span>
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
             {filteredOrders.length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-center">
                    <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                        <Filter size={32} />
                    </div>
                    <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
                </div>
            )}
        </div>
      </div>

      {/* GRID VIEW (Mobile Default, Desktop Optional) */}
      <div className={`grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 ${viewMode === 'table' ? 'md:hidden' : ''}`}>
        {filteredOrders.map(ot => {
          const typeConfig = getTypeConfig(ot.type);
          const priorityConfig = getPriorityConfig(ot.priority);
          const statusConfig = getStatusConfig(ot.status);
          const TypeIcon = typeConfig.icon;

          return (
            <div key={ot.id} className="group bg-white rounded-xl shadow-sm border border-slate-200 hover:shadow-lg hover:border-indigo-200 transition-all duration-300 flex flex-col">

              {/* Card Header */}
              <div className="p-5 pb-3">
                <div className="flex justify-between items-start mb-3">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-bold border ${typeConfig.style}`}>
                        <TypeIcon size={14} />
                        {typeConfig.text}
                    </div>
                    <div className="flex items-center gap-2">
                         {ot.planId && (
                            <span className="text-[10px] font-mono text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100" title="Plan Maestro Vinculado">
                                PLAN
                            </span>
                        )}
                        <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                            <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                            {priorityConfig.label}
                        </span>
                    </div>
                </div>

                <h3 className="text-base font-bold text-slate-900 leading-tight mb-1 group-hover:text-indigo-600 transition-colors line-clamp-1" title={ot.title}>
                    {ot.title}
                </h3>

                <div className="flex items-center gap-1.5 text-slate-500 text-xs mb-3 font-medium">
                    <Wrench size={12} />
                    {ot.assetName}
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 h-10 leading-relaxed">
                    {ot.description}
                </p>
              </div>

              {/* Card Meta & Status */}
              <div className="px-5 py-3 border-t border-slate-50 bg-slate-50/50 flex items-center justify-between mt-auto">
                 <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                    <Calendar size={14} className="text-slate-400"/>
                    <span className={new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600 font-bold" : ""}>
                        {ot.dueDate}
                    </span>
                 </div>
                 <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${statusConfig.color}`}>
                    {statusConfig.label}
                 </span>
              </div>

              {/* Assignment Footer */}
              <div className="px-5 py-3 border-t border-slate-100 flex items-center gap-3">
                 <div className={`p-1.5 rounded-full ${ot.assignedTechnicianId ? 'bg-indigo-100 text-indigo-600' : 'bg-slate-100 text-slate-400'}`}>
                    <UserIcon size={16} />
                 </div>

                 <div className="flex-1 min-w-0">
                    {ot.status === WorkOrderStatus.COMPLETED ? (
                         <div className="text-xs font-bold text-slate-700 truncate">
                            {ot.technicianName}
                         </div>
                    ) : (
                        <select 
                            className="w-full bg-transparent text-sm font-medium text-slate-700 focus:outline-none cursor-pointer truncate"
                            value={ot.assignedTechnicianId || ''}
                            onChange={(e) => onAssign(ot.id, e.target.value)}
                        >
                            <option value="">Asignar Técnico...</option>
                            {technicians
                                .filter(t => t.specialty === ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name}</option>
                            ))}
                            <option disabled className="bg-slate-100 text-xs">--- Otros ---</option>
                            {technicians
                                .filter(t => t.specialty !== ot.specialtyRequired)
                                .map(t => (
                                <option key={t.id} value={t.id}>{t.name} (Otr)</option>
                            ))}
                        </select>
                    )}
                    {ot.assignedTechnicianId && ot.status !== WorkOrderStatus.COMPLETED && (
                        <p className="text-[10px] text-indigo-600 font-medium truncate">Asignado</p>
                    )}
                 </div>
              </div>
            </div>
          );
        })}

        {filteredOrders.length === 0 && viewMode === 'grid' && (
             <div className="col-span-full py-16 flex flex-col items-center justify-center text-center bg-white rounded-xl border border-dashed border-slate-300">
                <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                    <Filter size={32} />
                </div>
                <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
             </div>
        )}
      </div>

       {/* CREATE MODAL */}
       {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm transition-opacity">
          <div className="bg-white rounded-2xl w-full max-w-2xl shadow-2xl transform transition-all animate-in fade-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">

            {/* Header */}
            <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-white rounded-t-2xl sticky top-0 z-10">
              <div>
                <h3 className="text-xl font-bold text-slate-900">Nueva Orden de Trabajo</h3>
                <p className="text-sm text-slate-500">Generar ticket de mantenimiento correctivo o solicitud.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="text-slate-400 hover:text-slate-600 hover:bg-slate-100 p-2 rounded-full transition-colors">
                <X size={20} />
              </button>
            </div>

            {/* Scrollable Content */}
            <div className="p-6 overflow-y-auto">
                <form id="create-ot-form" onSubmit={handleCreateSubmit} className="space-y-6">

                    {/* Title Section */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                            Título del Incidente <span className="text-red-500">*</span>
                        </label>
                        <input 
                            autoFocus
                            required
                            type="text" 
                            className="w-full border border-slate-200 rounded-lg px-4 py-3 text-slate-900 font-medium placeholder:text-slate-400 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all bg-slate-50 focus:bg-white"
                            placeholder="Ej. Ruido excesivo en bomba de agua"
                            value={newOrderTitle}
                            onChange={e => setNewOrderTitle(e.target.value)}
                        />
                    </div>

                    {/* Grid Section */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

                        {/* Asset Selection */}
                        <div className="col-span-1 md:col-span-2">
                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                                Activo Afectado <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <Wrench className="absolute left-3 top-3 text-slate-400" size={18} />
                                <select 
                                    required
                                    className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-lg text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none bg-slate-50 focus:bg-white appearance-none transition-all cursor-pointer"
                                    value={newOrderAsset}
                                    onChange={e => setNewOrderAsset(e.target.value)}
                                >
                                    <option value="">Seleccionar Equipo...</option>
                                    {assets.map(a => (
                                        <option key={a.id} value={a.id}>{a.name} ({a.location})</option>
                                    ))}
                                </select>
                                <div className="absolute right-3 top-3 pointer-events-none">
                                    <ChevronDown className="text-slate-400" size={16} />
                                </div>
                            </div>
                        </div>

                        {/* Priority */}
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Prioridad</label>
                            <div className="relative">
                                 <AlertTriangle className="absolute left-3 top-3 text-slate-400" size={18} />
                                <select 
                                    className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-lg text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none bg-slate-50 focus:bg-white appearance-none transition-all cursor-pointer"
                                    value={newOrderPriority}
                                    onChange={e => setNewOrderPriority(e.target.value as Priority)}
                                >
                                    <option value={Priority.LOW}>🟢 Baja</option>
                                    <option value={Priority.MEDIUM}>🟡 Media</option>
                                    <option value={Priority.HIGH}>🟠 Alta</option>
                                    <option value={Priority.CRITICAL}>🔴 Crítica</option>
                                </select>
                                <div className="absolute right-3 top-3 pointer-events-none">
                                    <ChevronDown className="text-slate-400" size={16} />
                                </div>
                            </div>
                        </div>

                        {/* Specialty */}
                        <div>
                             <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Especialidad Sugerida</label>
                             <div className="relative">
                                <Activity className="absolute left-3 top-3 text-slate-400" size={18} />
                                <select 
                                    className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-lg text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none bg-slate-50 focus:bg-white appearance-none transition-all cursor-pointer"
                                    value={newOrderSpecialty}
                                    onChange={e => setNewOrderSpecialty(e.target.value)}
                                >
                                    <option value="Mecánica">Mecánica</option>
                                    <option value="Electricidad">Electricidad</option>
                                    <option value="Hidráulica">Hidráulica</option>
                                    <option value="Instrumentación">Instrumentación</option>
                                    <option value="General">General</option>
                                </select>
                                <div className="absolute right-3 top-3 pointer-events-none">
                                    <ChevronDown className="text-slate-400" size={16} />
                                </div>
                             </div>
                        </div>

                        {/* Due Date */}
                         <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">
                                Fecha Límite <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <Calendar className="absolute left-3 top-3 text-slate-400" size={18} />
                                <input 
                                    required
                                    type="date"
                                    className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-lg text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                                    value={newOrderDate}
                                    onChange={e => setNewOrderDate(e.target.value)}
                                />
                            </div>
                        </div>
                    </div>

                    {/* Description */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Descripción Detallada</label>
                        <textarea 
                            className="w-full border border-slate-200 rounded-lg p-4 text-slate-700 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none h-32 resize-none bg-slate-50 focus:bg-white transition-all placeholder:text-slate-400"
                            placeholder="Describa los síntomas, ruidos extraños, códigos de error, etc..."
                            value={newOrderDesc}
                            onChange={e => setNewOrderDesc(e.target.value)}
                        />
                    </div>
                </form>
            </div>

            {/* Footer */}
            <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex items-center justify-end gap-3 rounded-b-2xl sticky bottom-0">
                <button 
                    type="button"
                    onClick={() => setIsModalOpen(false)}
                    className="px-6 py-2.5 text-slate-600 font-semibold hover:bg-slate-200 hover:text-slate-800 rounded-lg transition-colors"
                >
                    Cancelar
                </button>
                <button 
                    type="submit"
                    form="create-ot-form"
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-8 py-2.5 rounded-lg font-bold shadow-lg shadow-indigo-200 hover:shadow-indigo-300 transition-all transform active:scale-95 flex items-center gap-2"
                >
                    <Save size={18} />
                    Crear Orden
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, User, UserRole, WorkOrderType, Asset } from '../types';
import { Calendar, User as UserIcon, AlertTriangle, Clock, Filter, Plus, CalendarClock, Wrench, MoreHorizontal, ArrowRight, Activity, LayoutList, LayoutGrid, X, Save, FileText, ChevronDown, Eye, CheckSquare, Image as ImageIcon, MapPin } from 'lucide-react';

interface WorkOrderListProps {
  orders: WorkOrder[];
  users: User[];
  assets: Asset[];
  onAssign: (orderId: string, technicianId: string) => void;
  onCreate: (order: WorkOrder) => void;
}

export const WorkOrderList: React.FC<WorkOrderListProps> = ({ orders, users, assets, onAssign, onCreate }) => {
  const [filterSpecialty, setFilterSpecialty] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('table'); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<WorkOrder | null>(null);

  // Create Form State
  const [newOrderTitle, setNewOrderTitle] = useState('');
  const [newOrderDesc, setNewOrderDesc] = useState('');
  const [newOrderAsset, setNewOrderAsset] = useState('');
  const [newOrderPriority, setNewOrderPriority] = useState<Priority>(Priority.MEDIUM);
  const [newOrderSpecialty, setNewOrderSpecialty] = useState('Mecánica');
  const [newOrderDate, setNewOrderDate] = useState('');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);
  const specialties = Array.from(new Set(technicians.map(t => t.specialty).filter(Boolean)));

  const filteredOrders = orders.filter(order => {
    const matchesSpecialty = filterSpecialty === 'ALL' || order.specialtyRequired === filterSpecialty;
    const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
    return matchesSpecialty && matchesStatus;
  });

  const getPriorityConfig = (p: Priority) => {
    switch (p) {
      case Priority.CRITICAL: return { color: 'text-red-700 bg-red-50 border-red-100', label: 'Crítica', dot: 'bg-red-500' };
      case Priority.HIGH: return { color: 'text-orange-700 bg-orange-50 border-orange-100', label: 'Alta', dot: 'bg-orange-500' };
      case Priority.MEDIUM: return { color: 'text-yellow-700 bg-yellow-50 border-yellow-100', label: 'Media', dot: 'bg-yellow-500' };
      default: return { color: 'text-blue-700 bg-blue-50 border-blue-100', label: 'Baja', dot: 'bg-blue-500' };
    }
  };

  const getStatusConfig = (s: WorkOrderStatus) => {
    switch (s) {
      case WorkOrderStatus.COMPLETED: return { color: 'bg-emerald-100 text-emerald-800', label: 'Completada' };
      case WorkOrderStatus.IN_PROGRESS: return { color: 'bg-blue-100 text-blue-800', label: 'En Progreso' };
      default: return { color: 'bg-slate-100 text-slate-600', label: 'Pendiente' };
    }
  };

  const getTypeConfig = (type: WorkOrderType) => {
    if (type === WorkOrderType.PREVENTIVE) {
      return { 
        icon: CalendarClock, 
        text: 'Preventivo', 
        style: 'text-indigo-600 bg-indigo-50 border-indigo-100' 
      };
    }
    return { 
      icon: Activity, 
      text: 'Correctivo', 
      style: 'text-amber-600 bg-amber-50 border-amber-100' 
    };
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newOrderTitle || !newOrderAsset || !newOrderDate) {
      alert("Por favor completa los campos requeridos.");
      return;
    }

    const selectedAsset = assets.find(a => a.id === newOrderAsset);

    const newOrder: WorkOrder = {
      id: `ot-${Date.now()}`,
      title: newOrderTitle,
      description: newOrderDesc,
      assetId: newOrderAsset,
      assetName: selectedAsset?.name || 'Desconocido',
      type: WorkOrderType.CORRECTIVE, // Default for manual creation
      priority: newOrderPriority,
      status: WorkOrderStatus.PENDING,
      dueDate: newOrderDate,
      specialtyRequired: newOrderSpecialty,
    };

    onCreate(newOrder);
    setIsModalOpen(false);

    // Reset form
    setNewOrderTitle('');
    setNewOrderDesc('');
    setNewOrderAsset('');
    setNewOrderPriority(Priority.MEDIUM);
    setNewOrderDate('');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Órdenes (OT)</h2>
          <p className="text-slate-500">Supervisión y asignación de tareas de mantenimiento.</p>
        </div>
        <div className="flex items-center gap-3">
            {/* View Toggle (Desktop Only) */}
            <div className="hidden md:flex bg-white rounded-lg border border-slate-200 p-1 shadow-sm">
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2 rounded transition-colors ${viewMode === 'table' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tabla"
                >
                    <LayoutList size={18} />
                </button>
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2 rounded transition-colors ${viewMode === 'grid' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tarjetas"
                >
                    <LayoutGrid size={18} />
                </button>
            </div>

            <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 bg-slate-900 hover:bg-slate-800 text-white px-5 py-2.5 rounded-lg font-medium transition-all shadow-lg shadow-slate-200 active:scale-95"
            >
            <Plus size={18} />
            Nueva OT
            </button>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-3 items-center sticky top-0 z-10 backdrop-blur-xl bg-white/90">
        <div className="flex items-center gap-2 text-slate-500 px-2">
          <Filter size={18} />
          <span className="text-sm font-bold uppercase tracking-wide">Filtros</span>
        </div>

        <div className="h-6 w-px bg-slate-200 hidden md:block"></div>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterSpecialty}
          onChange={(e) => setFilterSpecialty(e.target.value)}
        >
          <option value="ALL">Todas las Especialidades</option>
          {specialties.map(s => <option key={s} value={s as string}>{s}</option>)}
        </select>

        <select 
          className="bg-slate-50 border-none rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 outline-none hover:bg-slate-100 transition-colors cursor-pointer"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="ALL">Todos los Estados</option>
          <option value={WorkOrderStatus.PENDING}>Pendientes</option>
          <option value={WorkOrderStatus.IN_PROGRESS}>En Progreso</option>
          <option value={WorkOrderStatus.COMPLETED}>Completadas</option>
        </select>

        <div className="ml-auto text-xs text-slate-400 font-medium hidden md:block">
            Mostrando {filteredOrders.length} órdenes
        </div>
      </div>

      {/* TABLE VIEW (Desktop Default) */}
      <div className={`hidden md:block ${viewMode === 'grid' ? '!hidden' : ''}`}>
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider font-semibold">
                    <tr>
                        <th className="px-6 py-4 w-16">Tipo</th>
                        <th className="px-6 py-4">ID / Asunto</th>
                        <th className="px-6 py-4">Activo</th>
                        <th className="px-6 py-4">Prioridad</th>
                        <th className="px-6 py-4">Estado</th>
                        <th className="px-6 py-4">Asignación</th>
                        <th className="px-6 py-4 text-right">Vencimiento</th>
                        <th className="px-6 py-4 w-16 text-center">Acciones</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredOrders.map(ot => {
                        const typeConfig = getTypeConfig(ot.type);
                        const priorityConfig = getPriorityConfig(ot.priority);
                        const statusConfig = getStatusConfig(ot.status);
                        const TypeIcon = typeConfig.icon;

                        return (
                            <tr key={ot.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4">
                                     <div className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${typeConfig.style}`} title={typeConfig.text}>
                                        <TypeIcon size={16} />
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="text-xs font-mono text-slate-400 mb-0.5">{ot.id}</span>
                                        <span className="font-bold text-slate-900 group-hover:text-indigo-600 transition-colors truncate max-w-[200px]" title={ot.title}>{ot.title}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">
                                    <div className="flex items-center gap-2">
                                        <Wrench size={14} className="text-slate-400"/>
                                        <span className="truncate max-w-[150px]" title={ot.assetName}>{ot.assetName}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                                        <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                                        {priorityConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${statusConfig.color}`}>
                                        {statusConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    {ot.status === WorkOrderStatus.COMPLETED ? (
                                        <div className="flex items-center gap-2 text-xs font-medium text-slate-700">
                                            <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-slate-500"><UserIcon size={12}/></div>
                                            {ot.technicianName}
                                        </div>
                                    ) : (
                                        <div className="relative group/select">
                                            <select 
                                                className="w-full bg-slate-50 border border-slate-200 text-xs font-medium text-slate-700 rounded-md py-1.5 pl-2 pr-6 focus:outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer appearance-none hover:bg-slate-100 transition-colors"
                                                value={ot.assignedTechnicianId || ''}
                                                onChange={(e) => onAssign(ot.id, e.target.value)}
                                            >
                                                <option value="">-- Sin Asignar --</option>
                                                {technicians
                                                    .filter(t => t.specialty === ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                                <option disabled>--- Otros ---</option>
                                                {technicians
                                                    .filter(t => t.specialty !== ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                            </select>
                                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-400">
                                                <UserIcon size={12} />
                                            </div>
                                        </div>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <span className={`text-xs font-medium ${new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600" : "text-slate-500"}`}>
                                        {ot.dueDate}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <button 
                                        onClick={() => setSelectedOrder(ot)}
                                        className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-indigo-600 hover:border-indigo-200 hover:shadow-sm transition-all"
                                        title="Ver Detalle Completo"
                                    >
                                        <Eye size={16} />
                                    </button>
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
             {filteredOrders.length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-center">
                    <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                        <Filter size={32} />
                    </div>
                    <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
                </div>
            )}
        </div>
      </div>

      {/* GRID VIEW (Mobile Default, Desktop Optional) */}
      <div className={`grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 ${viewMode === 'table' ? 'md:hidden' : ''}`}>
        {filteredOrders.map(ot => {
          const typeConfig = getTypeConfig(ot.type);
          const priorityConfig = getPriorityConfig(ot.priority);
          const statusConfig = getStatusConfig(ot.status);
          const TypeIcon = typeConfig.icon;

          return (
            <div key={ot.id} className="group bg-white rounded-xl shadow-sm border border-slate-200 hover:shadow-lg hover:border-indigo-200 transition-all duration-300 flex flex-col">

              {/* Card Header */}
              <div className="p-5 pb-3">
                <div className="flex justify-between items-start mb-3">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-bold border ${typeConfig.style}`}>
                        <TypeIcon size={14} />
                        {typeConfig.text}
                    </div>
                    <div className="flex items-center gap-2">
                        <button 
                            onClick={() => setSelectedOrder(ot)}
                            className="p-1.5 bg-slate-50 text-slate-400 rounded-md hover:bg-indigo-50 hover:text-indigo-600 transition-colors"
                        >
                            <Eye size={16} />
                        </button>
                    </div>
                </div>

                <h3 className="text-base font-bold text-slate-900 leading-tight mb-1 group-hover:text-indigo-600 transition-colors line-clamp-1" title={ot.title}>
                    {ot.title}
                </h3>

                <div className="flex items-center gap-1.5 text-slate-500 text-xs mb-3 font-medium">
                    <Wrench size={12} />
                    {ot.assetName}
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 h-10 leading-relaxed">
                    {ot.description}
                </p>

                <div className="mt-2 flex gap-2">
                    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                        {priorityConfig.label}
                    </span>
                    {ot.planId && (
                        <span className="text-[10px] font-mono text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100">
                            PLAN
                        </span>
                    )}
                </div>
