  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    // If a Preventive OT is COMPLETED, we must update the Plan's nextDueDate
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          // Calculate new date
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          // Update Plan
          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[]) => {
    const newOrders: WorkOrder[] = [];

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado desde Plan Maestro.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          // Created without assignment
          assignedTechnicianId: undefined,
          technicianName: undefined,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, 
          status: WorkOrderStatus.PENDING,
          dueDate: plan.nextDueDate,
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`✅ Se han generado ${newOrders.length} Órdenes de Trabajo. Ahora puedes asignarlas desde el listado.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleCreateWorkOrder = (newOrder: WorkOrder) => {
    setWorkOrders(prev => [newOrder, ...prev]);
    // No alert needed, UI update is immediate
  };

  // Handlers for Inventory & Purchases
  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      quantity: qty,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING,
      totalCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada correctamente.");
  };

  const handleApprovePurchase = (reqId: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.APPROVED } : pr
    ));
  };

  const handleReceivePurchase = (reqId: string) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // Update Stock
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + request.quantity } 
        : item
    ));

    // Update Request Status
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.RECEIVED } : pr
    ));
  };

  // Role Simulation Handler
  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      // Redirect to appropriate landing view
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      {/* Simulation Banner - FOR DEMO PURPOSES */}
      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-slate-800 text-white text-xs p-2 rounded shadow-lg border border-slate-700 opacity-90 hover:opacity-100 transition-opacity cursor-pointer"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN}>Simular: Admin</option>
          <option value={UserRole.PLANNER}>Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN}>Simular: Técnico</option>
        </select>
      </div>

      {/* Render Views based on route */}
      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS}
          assets={MOCK_ASSETS}
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          assets={MOCK_ASSETS}
          onGenerateOrders={handleGenerateOrders}
          onCreatePlan={handleCreatePlan}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          onRequestPurchase={handleRequestPurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Purchasing 
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onApprovePurchase={handleApprovePurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

    </Layout>
  );
}

export default App;

// Enums
export enum UserRole {
  ADMIN = 'ADMIN',
  PLANNER = 'PLANNER',
  TECHNICIAN = 'TECHNICIAN'
}

export enum WorkOrderStatus {
  PENDING = 'PENDING',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
  BLOCKED = 'BLOCKED'
}

export enum WorkOrderType {
  CORRECTIVE = 'CORRECTIVE',
  PREVENTIVE = 'PREVENTIVE'
}

export enum Priority {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL'
}

export enum PurchaseRequestStatus {
  PENDING_APPROVAL = 'PENDING_APPROVAL', // Creada, espera a Jefatura
  APPROVED = 'APPROVED',         // Aprobada por Jefatura, espera a Compras
  REJECTED = 'REJECTED',         // Rechazada
  PURCHASED = 'PURCHASED',       // Compras asignó proveedor y generó OC
  PARTIALLY_RECEIVED = 'PARTIALLY_RECEIVED', // Llegó parte de la mercadería
  COMPLETED = 'COMPLETED'        // Se recibió el 100% o se cerró manual
}

// Interfaces
export interface User {
  id: string;
  name: string;
  role: UserRole;
  specialty?: string; // For technicians e.g., 'Electricidad', 'Mecánica'
  avatar: string;
}

export interface Asset {
  id: string;
  name: string;
  location: string;
  status: 'OPERATIONAL' | 'DOWN';
}

export interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  quantity: number;
  minStock: number;
  cost: number;
  category: string;
}

export interface ReceptionEntry {
  id: string;
  date: string;
  quantity: number;
  remito: string;
  receivedBy: string;
}

export interface PurchaseRequest {
  id: string;
  itemId: string;
  itemName: string;
  requestedBy: string;
  date: string; // Creation date
  status: PurchaseRequestStatus;

  // Quantities
  originalQuantity: number; // What was asked
  approvedQuantity: number; // What boss approved
  receivedQuantity: number; // Running total of reception

  // Financial & Provider
  estimatedCost: number;
  provider?: string;
  orderDate?: string; // When status changed to PURCHASED

  // History
  receptionLog?: ReceptionEntry[];
}

export interface ChecklistTask {
  id: string;
  description: string;
  completed: boolean;
}

export interface MaintenancePlan {
  id: string;
  title: string;
  assetId: string;
  assetName: string;
  frequencyDays: number;
  nextDueDate: string; // ISO Date
  estimatedHours: number;
  specialtyRequired: string;
  checklistTemplate: string[]; // Simple array of strings for the template
}

export interface WorkOrder {
  id: string;
  title: string;
  description: string;
  assetId: string;
  assetName: string;
  assignedTechnicianId?: string;
  technicianName?: string;
  type: WorkOrderType;
  priority: Priority;
  status: WorkOrderStatus;
  dueDate: string;
  specialtyRequired: string;

  // Link to Plan
  planId?: string; 

  // Execution Data
  checklist?: ChecklistTask[];
  startTime?: string;
  endTime?: string;
  completionComment?: string;
  evidenceImageUrl?: string;
}

import React, { useState } from 'react';
import { PurchaseRequest, PurchaseRequestStatus, User, UserRole } from '../types';
import { Check, X, Clock, PackageCheck, ShoppingCart, User as UserIcon, Calendar, ArrowRight, Truck, FileText, AlertCircle, Save, History, Search } from 'lucide-react';

interface PurchasingProps {
  purchaseRequests: PurchaseRequest[];
  user: User;
  onApprovePurchase: (reqId: string, approvedQty: number) => void;
  onRejectPurchase: (reqId: string) => void;
  onProcessPurchase: (reqId: string, provider: string) => void;
  onReceivePurchase: (reqId: string, qtyReceived: number, remito: string, forceClose: boolean) => void;
}

export const Purchasing: React.FC<PurchasingProps> = ({ 
  purchaseRequests, 
  user, 
  onApprovePurchase,
  onRejectPurchase,
  onProcessPurchase,
  onReceivePurchase
}) => {
  const [activeTab, setActiveTab] = useState<'approvals' | 'purchasing' | 'receiving'>('approvals');

  // State for Approval Stage (Editable Quantity)
  const [approvalQtys, setApprovalQtys] = useState<Record<string, number>>({});

  // State for Purchasing Stage (Provider Input)
  const [providerInputs, setProviderInputs] = useState<Record<string, string>>({});

  // State for Reception Modal
  const [receptionModalOpen, setReceptionModalOpen] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState<PurchaseRequest | null>(null);
  const [receptionQty, setReceptionQty] = useState<number>(0);
  const [remitoNumber, setRemitoNumber] = useState('');
  const [forceClose, setForceClose] = useState(false);

  // Filters
  const pendingRequests = purchaseRequests.filter(pr => pr.status === PurchaseRequestStatus.PENDING_APPROVAL);
  const approvedRequests = purchaseRequests.filter(pr => pr.status === PurchaseRequestStatus.APPROVED);
  const activeOrders = purchaseRequests.filter(pr => 
    pr.status === PurchaseRequestStatus.PURCHASED || 
    pr.status === PurchaseRequestStatus.PARTIALLY_RECEIVED
  );

  // Handlers
  const handleApprovalChange = (id: string, val: string) => {
    setApprovalQtys(prev => ({ ...prev, [id]: Number(val) }));
  };

  const handleProviderChange = (id: string, val: string) => {
    setProviderInputs(prev => ({ ...prev, [id]: val }));
  };

  const openReceptionModal = (req: PurchaseRequest) => {
    setSelectedRequest(req);
    setReceptionQty(req.approvedQuantity - req.receivedQuantity); // Default to remaining
    setRemitoNumber('');
    setForceClose(false);
    setReceptionModalOpen(true);
  };

  const submitReception = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedRequest && receptionQty > 0 && remitoNumber) {
        onReceivePurchase(selectedRequest.id, receptionQty, remitoNumber, forceClose);
        setReceptionModalOpen(false);
    }
  };

  const TabButton = ({ id, label, icon: Icon, count, color }: any) => (
    <button
      onClick={() => setActiveTab(id)}
      className={`flex-1 py-4 border-b-2 transition-all flex items-center justify-center gap-2 ${
        activeTab === id 
          ? `border-${color}-600 text-${color}-600 bg-${color}-50` 
          : 'border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50'
      }`}
    >
      <Icon size={18} />
      <span className="font-bold text-sm">{label}</span>
      {count > 0 && (
        <span className={`ml-1 text-xs px-2 py-0.5 rounded-full bg-${color}-100 text-${color}-700`}>
          {count}
        </span>
      )}
    </button>
  );

  return (
    <div className="space-y-6">
      <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Compras</h2>
          <p className="text-slate-500">Flujo de abastecimiento: Aprobación, Compras y Recepción.</p>
      </div>

      {/* Tabs Navigation */}
      <div className="flex bg-white rounded-t-xl border-b border-slate-200 shadow-sm overflow-hidden">
        <TabButton id="approvals" label="Aprobaciones" icon={Clock} count={pendingRequests.length} color="amber" />
        <TabButton id="purchasing" label="Compras" icon={ShoppingCart} count={approvedRequests.length} color="blue" />
        <TabButton id="receiving" label="Recepciones" icon={Truck} count={activeOrders.length} color="emerald" />
      </div>

      <div className="bg-white rounded-b-xl shadow-sm border border-t-0 border-slate-200 min-h-[400px] p-6">

        {/* === TAB 1: APROBACIONES (Jefatura) === */}
        {activeTab === 'approvals' && (
           <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold text-slate-800">Solicitudes Pendientes</h3>
                    <div className="text-xs text-slate-400 bg-slate-100 px-3 py-1 rounded-full">
                        Jefatura revisa y aprueba cantidades.
                    </div>
                </div>

                {pendingRequests.length === 0 ? (
                    <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-xl">
                        <Check size={40} className="mx-auto mb-3 opacity-50 text-amber-400" />
                        <p>No hay solicitudes pendientes.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 gap-4">
                        {pendingRequests.map(pr => (
                            <div key={pr.id} className="border border-slate-200 rounded-xl p-4 hover:shadow-md transition-shadow flex flex-col md:flex-row gap-4 items-center">
                                <div className="flex-1">
                                    <div className="flex items-center gap-2 mb-1">
                                        <span className="font-bold text-slate-900">{pr.itemName}</span>
                                        <span className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded">
                                            Orig: {pr.originalQuantity} un.
                                        </span>
                                    </div>
                                    <div className="text-sm text-slate-500 flex items-center gap-3">
                                        <span className="flex items-center gap-1"><UserIcon size={12}/> {pr.requestedBy}</span>
                                        <span className="flex items-center gap-1"><Calendar size={12}/> {pr.date}</span>
                                        <span className="font-semibold text-slate-700">${pr.estimatedCost} (Est.)</span>
                                    </div>
                                </div>

                                <div className="flex items-center gap-3 w-full md:w-auto bg-slate-50 p-3 rounded-lg">
                                    <div className="flex flex-col">
                                        <label className="text-[10px] font-bold text-slate-500 uppercase">Aprobar Cant.</label>
                                        <input 
                                            type="number" 
                                            className="w-20 border border-slate-300 rounded px-2 py-1 text-sm font-bold text-center focus:ring-2 focus:ring-amber-500 outline-none"
                                            value={approvalQtys[pr.id] ?? pr.originalQuantity}
                                            onChange={(e) => handleApprovalChange(pr.id, e.target.value)}
                                            min="1"
                                        />
                                    </div>
                                    <div className="h-8 w-px bg-slate-200 mx-2"></div>
                                    <button 
                                        onClick={() => onApprovePurchase(pr.id, approvalQtys[pr.id] ?? pr.originalQuantity)}
                                        className="bg-emerald-600 text-white p-2 rounded-lg hover:bg-emerald-700 transition-colors"
                                        title="Aprobar"
                                    >
                                        <Check size={18} />
                                    </button>
                                    <button 
                                        onClick={() => onRejectPurchase(pr.id)}
                                        className="bg-white border border-slate-200 text-slate-400 p-2 rounded-lg hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition-colors"
                                        title="Rechazar"
                                    >
                                        <X size={18} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
           </div>
        )}

        {/* === TAB 2: COMPRAS (Cotizar y Asignar) === */}
        {activeTab === 'purchasing' && (
             <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold text-slate-800">Órdenes por Procesar</h3>
                    <div className="text-xs text-slate-400 bg-slate-100 px-3 py-1 rounded-full">
                        Compras cotiza y asigna proveedor.
                    </div>
                </div>

                {approvedRequests.length === 0 ? (
                    <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-xl">
                        <ShoppingCart size={40} className="mx-auto mb-3 opacity-50 text-blue-400" />
                        <p>No hay solicitudes aprobadas esperando compra.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 gap-4">
                        {approvedRequests.map(pr => (
                             <div key={pr.id} className="border border-slate-200 rounded-xl p-4 hover:shadow-md transition-shadow">
                                <div className="flex justify-between items-start mb-4">
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <span className="font-bold text-slate-900 text-lg">{pr.itemName}</span>
                                            <span className="bg-emerald-100 text-emerald-700 text-xs font-bold px-2 py-0.5 rounded border border-emerald-200">
                                                Aprobado: {pr.approvedQuantity} un.
                                            </span>
                                        </div>
                                        <p className="text-xs text-slate-400 mt-1">ID: {pr.id}</p>
                                    </div>
                                </div>

                                <div className="bg-blue-50/50 p-4 rounded-lg border border-blue-100 flex flex-col md:flex-row items-end gap-4">
                                    <div className="flex-1 w-full">
                                        <label className="block text-xs font-bold text-blue-700 uppercase mb-1">Proveedor Asignado</label>
                                        <div className="relative">
                                            <Search className="absolute left-3 top-2.5 text-blue-300" size={16}/>
                                            <input 
                                                type="text" 
                                                className="w-full pl-9 pr-4 py-2 border border-blue-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                                placeholder="Nombre del Proveedor..."
                                                value={providerInputs[pr.id] || ''}
                                                onChange={(e) => handleProviderChange(pr.id, e.target.value)}
                                            />
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => {
                                            if(!providerInputs[pr.id]) return alert('Debes asignar un proveedor');
                                            onProcessPurchase(pr.id, providerInputs[pr.id]);
                                        }}
                                        className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold text-sm hover:bg-blue-700 transition-colors shadow-sm flex items-center gap-2 whitespace-nowrap"
                                    >
                                        Generar Orden <ArrowRight size={16} />
                                    </button>
                                </div>
                             </div>
                        ))}
                    </div>
                )}
            </div>
        )}

        {/* === TAB 3: RECEPCIÓN (Almacén) === */}
        {activeTab === 'receiving' && (
             <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h3 className="text-lg font-bold text-slate-800">Mercadería en Tránsito / Recepción</h3>
                    <div className="text-xs text-slate-400 bg-slate-100 px-3 py-1 rounded-full">
                        Ingreso de stock (Total o Parcial).
                    </div>
                </div>

                {activeOrders.length === 0 ? (
                    <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-xl">
                        <Truck size={40} className="mx-auto mb-3 opacity-50 text-emerald-400" />
                        <p>No hay órdenes de compra activas.</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 gap-6">
                        {activeOrders.map(pr => {
                            const progress = (pr.receivedQuantity / pr.approvedQuantity) * 100;
                            const isPartial = pr.receivedQuantity > 0;

                            return (
                                <div key={pr.id} className="border border-slate-200 rounded-xl overflow-hidden hover:shadow-md transition-all">
                                    <div className="bg-slate-50 p-4 border-b border-slate-100 flex justify-between items-center">
                                        <div>
                                            <h4 className="font-bold text-slate-900">{pr.itemName}</h4>
                                            <div className="flex items-center gap-2 text-xs mt-1">
                                                <span className="text-slate-500">Prov: <span className="font-semibold text-slate-700">{pr.provider}</span></span>
                                                <span className="text-slate-300">|</span>
                                                <span className="text-slate-500">Orden: <span className="font-mono text-slate-600">{pr.orderDate}</span></span>
                                            </div>
                                        </div>
                                        <div className="text-right">
                                            {isPartial && (
                                                <span className="text-[10px] font-bold bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full uppercase mb-1 inline-block">
                                                    Parcial
                                                </span>
                                            )}
                                            <div className="text-sm font-bold text-slate-700">
                                                {pr.receivedQuantity} / <span className="text-slate-500">{pr.approvedQuantity}</span> un.
                                            </div>
                                        </div>
                                    </div>

                                    {/* Progress Bar */}
                                    <div className="h-1 w-full bg-slate-100">
                                        <div className="h-1 bg-emerald-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
