                                    <td className="px-5 py-3 text-center">
                                        <span className="text-red-600 font-bold">{item.quantity}</span>
                                    </td>
                                    <td className="px-5 py-3 text-center text-slate-500">
                                        {item.minStock}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                ) : (
                    <div className="p-8 text-center text-slate-400">
                        <CheckCircle2 size={32} className="mx-auto mb-2 text-green-400 opacity-50"/>
                        <p className="text-sm">Todo el inventario está en niveles óptimos.</p>
                    </div>
                )}
            </div>
        </div>

      </div>
    </div>
  );
};

// Enums
export enum UserRole {
  ADMIN = 'ADMIN',
  PLANNER = 'PLANNER',
  TECHNICIAN = 'TECHNICIAN'
}

export enum WorkOrderStatus {
  PENDING = 'PENDING',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
  BLOCKED = 'BLOCKED'
}

export enum WorkOrderType {
  CORRECTIVE = 'CORRECTIVE',
  PREVENTIVE = 'PREVENTIVE'
}

export enum Priority {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL'
}

export enum PurchaseRequestStatus {
  PENDING_APPROVAL = 'PENDING_APPROVAL', // Creada, espera a Jefatura
  APPROVED = 'APPROVED',         // Aprobada por Jefatura, espera a Compras
  REJECTED = 'REJECTED',         // Rechazada
  PURCHASED = 'PURCHASED',       // Compras asignó proveedor y generó OC
  PARTIALLY_RECEIVED = 'PARTIALLY_RECEIVED', // Llegó parte de la mercadería
  COMPLETED = 'COMPLETED'        // Se recibió el 100% o se cerró manual
}

// Interfaces
export interface User {
  id: string;
  name: string;
  role: UserRole;
  specialty?: string; // For technicians e.g., 'Electricidad', 'Mecánica'
  avatar: string;
}

export interface FrequentFailure {
  id: string;
  title: string;
  description: string;
  imageUrl?: string; // URL to photo
}

export interface Asset {
  id: string;
  name: string;
  location: string;
  sector?: string;        // New: Sector/Area
  serialNumber?: string;  // New: S/N
  manualUrl?: string;     // New: Link to PDF
  frequentFailures?: FrequentFailure[]; // New: Knowledge Base
  status: 'OPERATIONAL' | 'DOWN';
}

export interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  quantity: number;
  minStock: number;
  cost: number;
  category: string;
}

export interface ReceptionEntry {
  id: string;
  date: string;
  quantity: number;
  remito: string;
  receivedBy: string;
}

export interface PurchaseRequest {
  id: string;
  itemId: string;
  itemName: string;
  requestedBy: string;
  date: string; // Creation date
  status: PurchaseRequestStatus;

  // Quantities
  originalQuantity: number; // What was asked
  approvedQuantity: number; // What boss approved
  receivedQuantity: number; // Running total of reception

  // Financial & Provider
  estimatedCost: number;
  provider?: string;
  orderDate?: string; // When status changed to PURCHASED

  // History
  receptionLog?: ReceptionEntry[];
}

export interface ChecklistTask {
  id: string;
  description: string;
  completed: boolean;
}

export interface MaintenancePlan {
  id: string;
  title: string;
  assetId: string;
  assetName: string;
  frequencyDays: number;
  nextDueDate: string; // ISO Date
  estimatedHours: number;
  specialtyRequired: string;
  checklistTemplate: string[]; // Simple array of strings for the template
}

export interface WorkOrder {
  id: string;
  title: string;
  description: string;
  assetId: string;
  assetName: string;
  assignedTechnicianId?: string;
  technicianName?: string;
  type: WorkOrderType;
  priority: Priority;
  status: WorkOrderStatus;
  dueDate: string;
  specialtyRequired: string;

  // Link to Plan
  planId?: string; 

  // Execution Data
  checklist?: ChecklistTask[];
  startTime?: string;
  endTime?: string;
  completionComment?: string;
  evidenceImageUrl?: string;
}

