    const [tempTask, setTempTask] = useState('');

    const openCreateModal = () => {
        setCurrentTemplate({
            title: '',
            description: '',
            specialty: 'Mecánica',
            estimatedHours: 1,
            frequencyDays: 30,
            tasks: []
        });
        setIsModalOpen(true);
    };

    const openEditModal = (template: TaskTemplate) => {
        setCurrentTemplate({ ...template });
        setIsModalOpen(true);
    };

    const handleDelete = (id: string) => {
        if(confirm('¿Estás seguro de eliminar este Plan Preventivo Maestro?')) {
            setLocalTemplates(prev => prev.filter(t => t.id !== id));
        }
    };

    const handleSave = () => {
        if (!currentTemplate.title) return alert('El título es obligatorio');

        if (currentTemplate.id) {
            // Edit
            setLocalTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate as TaskTemplate : t));
        } else {
            // Create
            const newTemplate = { ...currentTemplate, id: `tpl-${Date.now()}` } as TaskTemplate;
            setLocalTemplates(prev => [...prev, newTemplate]);
        }
        setIsModalOpen(false);
    };

    const addTask = () => {
        if (tempTask.trim()) {
            setCurrentTemplate(prev => ({
                ...prev,
                tasks: [...(prev.tasks || []), tempTask.trim()]
            }));
            setTempTask('');
        }
    };

    const removeTask = (idx: number) => {
        setCurrentTemplate(prev => ({
            ...prev,
            tasks: prev.tasks?.filter((_, i) => i !== idx)
        }));
