import React, { useState } from 'react';
import { MaintenancePlan, Asset } from '../types';
import { CalendarClock, AlertCircle, Play, CheckSquare, Calendar, ChevronRight, Filter } from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  assets: Asset[];
  // No longer creates plans, only generates orders from occurrences
  onGenerateOrders: (planIds: string[]) => void;
  // onCreatePlan removed
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ plans, onGenerateOrders }) => {
  const [viewMonths, setViewMonths] = useState(3); // Default 3 months view
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());

  // --- LOGIC: GENERATE PROJECTIONS ---
  // We need to project occurrences for each plan for the next N months.
  // Returns a flat list of { planId, date, title, assetName }

  const generateProjections = () => {
    const projections: any[] = [];
    const today = new Date();
    const endDate = new Date();
    endDate.setMonth(today.getMonth() + viewMonths);

    plans.forEach(plan => {
        let currentDate = new Date(plan.nextDueDate);

        // Loop while the projected date is before the end date view
        while (currentDate <= endDate) {
            projections.push({
                uniqueId: `${plan.id}-${currentDate.toISOString()}`, // Unique key for rendering
                planId: plan.id,
                date: currentDate.toISOString().split('T')[0], // YYYY-MM-DD
                rawDate: new Date(currentDate),
                title: plan.title,
                assetName: plan.assetName,
                frequency: plan.frequencyDays,
                specialty: plan.specialtyRequired,
                hours: plan.estimatedHours
            });

            // Increment date by frequency
            currentDate.setDate(currentDate.getDate() + plan.frequencyDays);
        }
    });

    // Sort by Date
    return projections.sort((a, b) => a.rawDate.getTime() - b.rawDate.getTime());
  };

  const projections = generateProjections();

  // --- SELECTION LOGIC ---
  const toggleSelection = (uniqueId: string, planId: string) => {
    const newSet = new Set(selectedPlanIds);
    // Note: In a real app we might select specific Occurrences. 
    // For now, `onGenerateOrders` expects planIds, which implies triggering the *current* next due.
    // To keep it simple with the current Architecture, we will select the PLAN ID.
    if (newSet.has(planId)) newSet.delete(planId);
    else newSet.add(planId);
    setSelectedPlanIds(newSet);
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un mantenimiento.');
    onGenerateOrders(Array.from(selectedPlanIds));
    setSelectedPlanIds(new Set());
  };

  // Group projections by Month for better UI
  const groupByMonth = (items: any[]) => {
    const groups: Record<string, any[]> = {};
    items.forEach(item => {
        const monthKey = item.rawDate.toLocaleString('es-ES', { month: 'long', year: 'numeric' });
        if (!groups[monthKey]) groups[monthKey] = [];
        groups[monthKey].push(item);
    });
    return groups;
  };

  const groupedProjections = groupByMonth(projections);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Calendario Preventivo</h2>
          <p className="text-slate-500">Proyección de mantenimientos programados para los próximos meses.</p>
        </div>

        <div className="flex items-center gap-3">
             <div className="flex items-center gap-2 bg-white border border-slate-200 rounded-lg p-1 pr-3">
                 <div className="bg-slate-100 p-1.5 rounded text-slate-500"><Calendar size={16}/></div>
                 <select 
                    className="bg-transparent text-sm font-medium text-slate-700 outline-none cursor-pointer"
                    value={viewMonths}
                    onChange={(e) => setViewMonths(Number(e.target.value))}
                 >
                     <option value={1}>Ver 1 Mes</option>
                     <option value={3}>Ver 3 Meses</option>
                     <option value={6}>Ver 6 Meses</option>
                     <option value={12}>Ver 1 Año</option>
                 </select>
             </div>

             {selectedPlanIds.size > 0 && (
                <button 
                    onClick={handleBulkGenerate}
                    className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-lg font-medium shadow-sm hover:bg-slate-800 transition-all animate-in fade-in"
                >
                    <Play size={16} fill="currentColor" />
                    Generar {selectedPlanIds.size} OTs
                </button>
            )}
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
         <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center gap-2 text-sm text-slate-500">
             <Filter size={16}/>
             <span>Mostrando {projections.length} ocurrencias preventivas.</span>
         </div>

         <div className="divide-y divide-slate-100">
            {Object.entries(groupedProjections).map(([month, items]) => (
                <div key={month}>
                    <div className="bg-slate-50/50 px-6 py-3 border-b border-slate-100">
                        <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider">{month}</h3>
                    </div>
                    {items.map((proj) => {
                        const isSelected = selectedPlanIds.has(proj.planId);
                        const isOverdue = new Date(proj.date) < new Date();

                        return (
                            <div 
                                key={proj.uniqueId} 
                                className={`flex items-center gap-4 px-6 py-4 hover:bg-slate-50 transition-colors cursor-pointer group ${isSelected ? 'bg-blue-50/40' : ''}`}
                                onClick={() => toggleSelection(proj.uniqueId, proj.planId)}
                            >
                                <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${isSelected ? 'bg-blue-600 border-blue-600' : 'border-slate-300 bg-white'}`}>
                                    {isSelected && <CheckSquare size={14} className="text-white"/>}
                                </div>

