                                        {proj.specialty}
                                    </span>
                                </div>

                                <ChevronRight size={16} className="text-slate-300 group-hover:text-slate-500"/>
                            </div>
                        );
                    })}
                </div>
            ))}
         </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { Purchasing } from './features/Purchasing';
import { TechnicianView } from './features/TechnicianView';
import { PreventiveMaintenance } from './features/PreventiveMaintenance';
import { Configuration } from './features/Configuration';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS,
  MOCK_TASK_TEMPLATES
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask,
  ReceptionEntry,
  TaskTemplate
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);
  const [taskTemplates, setTaskTemplates] = useState<TaskTemplate[]>(MOCK_TASK_TEMPLATES);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[]) => {
    const newOrders: WorkOrder[] = [];

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado desde Plan Maestro.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          assignedTechnicianId: undefined,
          technicianName: undefined,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, 
          status: WorkOrderStatus.PENDING,
          dueDate: plan.nextDueDate,
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`✅ Se han generado ${newOrders.length} Órdenes de Trabajo.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleDeletePlan = (planId: string) => {
    setMaintenancePlans(prev => prev.filter(p => p.id !== planId));
  };

  const handleCreateWorkOrder = (newOrder: WorkOrder) => {
    setWorkOrders(prev => [newOrder, ...prev]);
  };

  // --- NEW PURCHASING LOGIC HANDLERS ---

  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      originalQuantity: qty,
      approvedQuantity: 0,
      receivedQuantity: 0,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING_APPROVAL,
      estimatedCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada. Pendiente de aprobación.");
  };

  // Stage 1: Approval (Manager)
  const handleApprovePurchase = (reqId: string, approvedQty: number) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { 
        ...pr, 
        status: PurchaseRequestStatus.APPROVED, 
        approvedQuantity: approvedQty // Manager can edit qty
      } : pr
    ));
  };

  const handleRejectPurchase = (reqId: string) => {
     setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.REJECTED } : pr
    ));
  };

  // Stage 2: Purchasing (Buyer)
  const handleProcessPurchase = (reqId: string, provider: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
        pr.id === reqId ? { 
            ...pr, 
            status: PurchaseRequestStatus.PURCHASED, 
            provider: provider,
            orderDate: new Date().toISOString().split('T')[0]
        } : pr
      ));
  };

  // Stage 3: Receiving (Warehouse)
  const handleReceivePurchase = (reqId: string, qtyReceived: number, remito: string, forceClose: boolean) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // 1. Update Inventory
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + qtyReceived } 
        : item
    ));

    // 2. Update Request Status & Log
    setPurchaseRequests(prev => prev.map(pr => {
      if (pr.id === reqId) {
        const newReceivedTotal = pr.receivedQuantity + qtyReceived;
        const isFullyReceived = newReceivedTotal >= pr.approvedQuantity;

        // Log Entry
        const newEntry: ReceptionEntry = {
            id: `rec-${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            quantity: qtyReceived,
            remito: remito,
            receivedBy: currentUser.name
        };

        return { 
            ...pr, 
            receivedQuantity: newReceivedTotal,
            receptionLog: [...(pr.receptionLog || []), newEntry],
            status: (isFullyReceived || forceClose) 
                ? PurchaseRequestStatus.COMPLETED 
                : PurchaseRequestStatus.PARTIALLY_RECEIVED
        };
      }
      return pr;
    }));

    alert(`✅ Stock actualizado (+${qtyReceived} un).`);
  };

  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-slate-800 text-white text-xs p-2 rounded shadow-lg border border-slate-700 opacity-90 hover:opacity-100 transition-opacity cursor-pointer"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN}>Simular: Admin</option>
          <option value={UserRole.PLANNER}>Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN}>Simular: Técnico</option>
        </select>
      </div>

      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS}
          assets={MOCK_ASSETS}
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          assets={MOCK_ASSETS}
          taskTemplates={taskTemplates}
          onGenerateOrders={handleGenerateOrders}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          onRequestPurchase={handleRequestPurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Purchasing 
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onApprovePurchase={handleApprovePurchase}
          onRejectPurchase={handleRejectPurchase}
          onProcessPurchase={handleProcessPurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView.startsWith('config-') && (
        <Configuration 
            currentView={currentView}
            users={MOCK_USERS}
            assets={MOCK_ASSETS}
            inventory={inventory}
            taskTemplates={taskTemplates}
            maintenancePlans={maintenancePlans}
            onCreatePlan={handleCreatePlan}
            onDeletePlan={handleDeletePlan}
        />
      )}

    </Layout>
  );
}

export default App;

