        <KpiCard 
          title="Resolución" 
          value={`${completionRate}%`} 
          trend="up" 
          trendValue="+5%"
          footer="vs. mes anterior"
          icon={CheckCircle2}
          colorClass="bg-emerald-100 text-emerald-600"
        />
        <KpiCard 
