          footer="Pendientes de cierre"
          icon={Briefcase}
          colorClass="bg-orange-100 text-orange-600"
        />
        <KpiCard 
          title="Gasto Ejecutado" 
          value={`$${monthlySpend.toLocaleString()}`} 
