  );
};

import React, { useState, useMemo } from 'react';
import { MaintenancePlan, User, WorkOrder, WorkOrderType, WorkOrderStatus, UserRole, InventoryItem } from '../types';
import { 
    CalendarClock, AlertCircle, Play, CheckSquare, Calendar, ChevronRight, Filter, 
    Search, User as UserIcon, History, BarChart3, TrendingUp, CheckCircle2, AlertTriangle, ArrowRight, Ban, Package, X, Save, ShoppingCart
} from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  workOrders: WorkOrder[];
  users: User[];
  inventory: InventoryItem[];
  onGenerateOrders: (planIds: string[], technicianId?: string, specificDate?: string) => void;
  onRequestPurchase: (itemId: string, qty: number) => void;
}

interface MissingStockItem {
    itemId: string;
    itemName: string;
    sku: string;
    required: number;
    available: number;
    missing: number;
    affectedPlans: string[]; // Plan Titles
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ 
    plans, workOrders, users, inventory, onGenerateOrders, onRequestPurchase 
}) => {
  const [viewDays, setViewDays] = useState(1); // Default to Today
  const [activeTab, setActiveTab] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState('');

  // Selection States
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [bulkTechnicianId, setBulkTechnicianId] = useState<string>('');

  // Schedule Modal State
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
  const [itemToSchedule, setItemToSchedule] = useState<{planId: string, title: string, originalDate: string} | null>(null);
  const [newScheduleDate, setNewScheduleDate] = useState('');

  // Stock Alert Modal State
  const [stockAlertOpen, setStockAlertOpen] = useState(false);
  const [missingStockItems, setMissingStockItems] = useState<MissingStockItem[]>([]);

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // --- LOGIC: KPI CALCULATION ---
  const kpis = useMemo(() => {
    let theoreticalCount = 0;
    let realizedCount = 0;
    const machineCompliance: Record<string, { total: number, completed: number, name: string }> = {};

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);
    today.setHours(23,59,59,999);

    if (viewDays === 1) {
        plans.forEach(p => {
            const nextDue = new Date(p.nextDueDate);
            if (nextDue <= today) {
                theoreticalCount++;
                if (!machineCompliance[p.assetId]) {
                    machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
                }
                machineCompliance[p.assetId].total += 1;
            }
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.endTime || wo.dueDate); 
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });

    } else {
        plans.forEach(p => {
            const occurrences = Math.ceil(viewDays / p.frequencyDays);
            theoreticalCount += occurrences;

            if (!machineCompliance[p.assetId]) {
                machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
            }
            machineCompliance[p.assetId].total += occurrences;
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.dueDate);
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });
    }

    const complianceRate = theoreticalCount > 0 ? Math.round((realizedCount / theoreticalCount) * 100) : 100;

    const machineList = Object.values(machineCompliance)
        .map(m => ({ 
            ...m, 
            rate: m.total > 0 ? Math.round((m.completed / m.total) * 100) : 100 
        }))
        .sort((a, b) => a.rate - b.rate)
        .slice(0, 5); 

    return { theoreticalCount, realizedCount, complianceRate, machineList };
  }, [plans, workOrders, viewDays]);

  // --- LOGIC: STOCK VALIDATION ---

  // 1. Simple check for UI display (list view)
  const checkStockAvailability = (plan: MaintenancePlan) => {
      if (!plan.requiredParts || plan.requiredParts.length === 0) return { status: 'none', details: [] };

      const missingParts: string[] = [];
      let hasEnough = true;

      plan.requiredParts.forEach(part => {
          const invItem = inventory.find(i => i.id === part.itemId);
          if (!invItem || invItem.quantity < part.quantity) {
              hasEnough = false;
              missingParts.push(`${part.itemName} (Faltan ${part.quantity - (invItem?.quantity || 0)})`);
          }
      });

      return { 
          status: hasEnough ? 'ok' : 'missing', 
          details: missingParts 
      };
  };

  // 2. Strict Batch Validation (When Clicking Generate)
  const validateBatchStock = (planIds: string[]) => {
      const consolidatedReqs: Record<string, { required: number, affectedPlans: string[] }> = {};

      // Aggregate requirements
      planIds.forEach(id => {
          const plan = plans.find(p => p.id === id);
          if (plan && plan.requiredParts) {
              plan.requiredParts.forEach(part => {
                  if (!consolidatedReqs[part.itemId]) {
                      consolidatedReqs[part.itemId] = { required: 0, affectedPlans: [] };
                  }
                  consolidatedReqs[part.itemId].required += part.quantity;
                  consolidatedReqs[part.itemId].affectedPlans.push(plan.title);
              });
          }
      });

      const missingItems: MissingStockItem[] = [];

      // Check against inventory
      Object.entries(consolidatedReqs).forEach(([itemId, reqData]) => {
          const invItem = inventory.find(i => i.id === itemId);
          const available = invItem ? invItem.quantity : 0;

          if (available < reqData.required) {
              missingItems.push({
                  itemId,
                  itemName: invItem?.name || 'Desconocido',
                  sku: invItem?.sku || 'N/A',
                  required: reqData.required,
                  available: available,
                  missing: reqData.required - available,
                  affectedPlans: reqData.affectedPlans
              });
          }
      });

      return missingItems;
  };

  // --- LOGIC: GENERATE PROJECTIONS (UPCOMING) ---
  const projections = useMemo(() => {
    if (activeTab !== 'upcoming') return [];

    const items: any[] = [];
    const today = new Date();
    today.setHours(0,0,0,0);
    const endDate = new Date();
    endDate.setDate(today.getDate() + (viewDays === 1 ? 0 : viewDays)); 
    endDate.setHours(23,59,59,999);

    plans.forEach(plan => {
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            if (!plan.title.toLowerCase().includes(query) && !plan.assetName.toLowerCase().includes(query)) {
                return;
            }
        }

        let currentDate = new Date(plan.nextDueDate);
        currentDate.setHours(12,0,0,0); 

        while (currentDate <= endDate) {
            const stockCheck = checkStockAvailability(plan);

            items.push({
                uniqueId: `${plan.id}-${currentDate.toISOString()}`, 
                planId: plan.id,
                date: currentDate.toISOString().split('T')[0],
                rawDate: new Date(currentDate),
                title: plan.title,
                assetName: plan.assetName,
                frequency: plan.frequencyDays,
                specialty: plan.specialtyRequired,
                hours: plan.estimatedHours,
                requiresDowntime: plan.requiresDowntime,
                stockStatus: stockCheck.status,
                missingParts: stockCheck.details
            });

            currentDate.setDate(currentDate.getDate() + plan.frequencyDays);
            if (currentDate > endDate) break;
        }
    });

    return items.sort((a, b) => a.rawDate.getTime() - b.rawDate.getTime());
  }, [plans, viewDays, searchQuery, activeTab, inventory]);

  // --- LOGIC: HISTORY (REALIZED) ---
  const historyItems = useMemo(() => {
    if (activeTab !== 'history') return [];

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);

    return workOrders.filter(wo => {
        const woDate = new Date(wo.dueDate); 
        const matchesDate = woDate >= startDate && woDate <= today;
        const matchesType = wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED;

        let matchesSearch = true;
        if (searchQuery) {
             const query = searchQuery.toLowerCase();
             matchesSearch = wo.title.toLowerCase().includes(query) || wo.assetName.toLowerCase().includes(query);
        }

        return matchesDate && matchesType && matchesSearch;
    }).sort((a, b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()); 

  }, [workOrders, viewDays, searchQuery, activeTab]);

  // --- HANDLERS ---
  const toggleSelection = (uniqueId: string, planId: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(planId)) newSet.delete(planId);
    else newSet.add(planId);
    setSelectedPlanIds(newSet);
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un mantenimiento.');

    // Validate Stock
    const planIds = Array.from(selectedPlanIds) as string[];
    const missing = validateBatchStock(planIds);

    if (missing.length > 0) {
        setMissingStockItems(missing);
        setStockAlertOpen(true);
        return;
    }

    onGenerateOrders(planIds, bulkTechnicianId || undefined);
    setSelectedPlanIds(new Set());
    setBulkTechnicianId('');
  };

  const openScheduleModal = (e: React.MouseEvent, item: any) => {
      e.stopPropagation();
      setItemToSchedule({
          planId: item.planId,
          title: item.title,
          originalDate: item.date
      });
      setNewScheduleDate(item.date);
      setScheduleModalOpen(true);
  };

  const confirmSchedule = () => {
      if (itemToSchedule && newScheduleDate) {
          // Validate Stock for Single Item
          const missing = validateBatchStock([itemToSchedule.planId]);

          if (missing.length > 0) {
              setMissingStockItems(missing);
              setStockAlertOpen(true);
              // Close schedule modal because we are blocked
              setScheduleModalOpen(false); 
              return;
          }

          onGenerateOrders([itemToSchedule.planId], undefined, newScheduleDate);
          setScheduleModalOpen(false);
          setItemToSchedule(null);
      }
  };

  const handleQuickPurchase = (itemId: string, qty: number) => {
      onRequestPurchase(itemId, qty);
      // Optional: Close modal or keep it open to show progress?
      // Keeping it open allows user to request other items.
  };

  // Group projections by Date for better UI
  const groupByDate = (items: any[]) => {
    const groups: Record<string, any[]> = {};
    items.forEach(item => {
        const dateKey = activeTab === 'upcoming' 
            ? item.rawDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })
            : new Date(item.dueDate).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

        if (!groups[dateKey]) groups[dateKey] = [];
        groups[dateKey].push(item);
    });
    return groups;
  };

  const groupedItems = groupByDate(activeTab === 'upcoming' ? projections : historyItems);

  return (
    <div className="space-y-6">

      {/* --- SECTION 1: KPIS & STATS --- */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-2 bg-slate-900 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
              <div className="relative z-10 flex justify-between items-end">
                  <div>
                      <h2 className="text-2xl font-bold mb-1">Cumplimiento Global</h2>
                      {/* FIXED: Lighter text for description */}
                      <p className="text-slate-300 text-sm mb-4">
                          {viewDays === 1 
                            ? 'Ejecución en tiempo real (Hoy)' 
                            : `Promedio histórico (Últimos ${viewDays} días)`}
                      </p>
                      <div className="flex items-end gap-3">
                          <span className="text-5xl font-bold text-orange-500">{kpis.complianceRate}%</span>
                          {/* FIXED: Lighter text label */}
                          <span className="text-sm text-slate-300 mb-2">Tasa de Ejecución</span>
                      </div>
                  </div>
                  <div className="hidden md:block">
                       <div className="flex gap-8 text-right">
                           <div>
                               <div className="text-2xl font-bold">{kpis.theoreticalCount}</div>
                               {/* FIXED: Lighter text label */}
                               <div className="text-xs text-slate-400 uppercase">Programados</div>
                           </div>
                           <div>
                               <div className="text-2xl font-bold text-orange-500">{kpis.realizedCount}</div>
                               {/* FIXED: Lighter text label */}
                               <div className="text-xs text-slate-400 uppercase">Realizados</div>
                           </div>
                       </div>
                  </div>
              </div>
              <BarChart3 className="absolute right-[-20px] bottom-[-20px] text-slate-800 opacity-50" size={180} />
          </div>

          <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
               <h3 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
                   <AlertTriangle size={18} className="text-amber-500"/> Alertas por Equipo
               </h3>
               <div className="space-y-3">
                   {kpis.machineList.map((m, idx) => (
                       <div key={idx} className="flex justify-between items-center text-sm">
                           <span className="text-slate-600 truncate max-w-[150px]" title={m.name}>{m.name}</span>
                           <div className="flex items-center gap-2">
                               <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                   <div 
                                        className={`h-full rounded-full ${m.rate < 50 ? 'bg-red-500' : m.rate < 80 ? 'bg-amber-500' : 'bg-emerald-500'}`} 
                                        style={{width: `${m.rate}%`}}
                                    ></div>
                               </div>
                               <span className="text-xs font-bold text-slate-700 w-8 text-right">{m.rate}%</span>
                           </div>
                       </div>
                   ))}
                   {kpis.machineList.length === 0 && <p className="text-xs text-slate-400 italic">Datos insuficientes para análisis.</p>}
               </div>
          </div>
      </div>

      {/* --- SECTION 2: TOOLBAR --- */}
      <div className="flex flex-col gap-4">
           {/* Tabs */}
           <div className="flex bg-slate-100 p-1 rounded-lg w-fit">
                <button 
                    onClick={() => setActiveTab('upcoming')}
                    className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'upcoming' ? 'bg-white text-orange-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <CalendarClock size={16}/> Proyección
                </button>
                <button 
                    onClick={() => setActiveTab('history')}
                    className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <History size={16}/> Histórico
                </button>
           </div>

           {/* Actions Bar */}
           <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 rounded-xl border border-slate-200 shadow-sm">

                {/* Search & Filters */}
                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-4 py-2 bg-slate-50 border-none rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                            placeholder="Buscar plan o máquina..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    <div className="flex items-center gap-2 bg-slate-50 rounded-lg p-1 pr-3">
                         <div className="bg-white p-1.5 rounded shadow-sm text-slate-500"><Calendar size={16}/></div>
                         <select 
                            className="bg-transparent text-sm font-medium text-slate-700 outline-none cursor-pointer"
                            value={viewDays}
                            onChange={(e) => setViewDays(Number(e.target.value))}
                         >
                             <option value={1}>Hoy</option>
                             <option value={7}>Esta Semana</option>
                             <option value={15}>15 Días</option>
                             <option value={30}>30 Días</option>
                             <option value={90}>3 Meses</option>
                         </select>
                     </div>
                </div>

                {/* Bulk Actions (Only for Upcoming) */}
                {activeTab === 'upcoming' && (
                    <div className="flex items-center gap-3 w-full md:w-auto justify-end">
                         {selectedPlanIds.size > 0 && (
                             <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4">
                                <div className="relative">
                                    <select 
                                        className="appearance-none bg-slate-100 border border-slate-200 text-slate-700 text-sm rounded-lg pl-3 pr-8 py-2 focus:ring-2 focus:ring-orange-500 outline-none cursor-pointer font-medium"
                                        value={bulkTechnicianId}
                                        onChange={(e) => setBulkTechnicianId(e.target.value)}
                                    >
                                        <option value="">Asignar Técnico (Opcional)</option>
                                        {technicians.map(t => (
                                            <option key={t.id} value={t.id}>{t.name}</option>
                                        ))}
                                    </select>
                                    <UserIcon size={14} className="absolute right-2.5 top-2.5 text-slate-400 pointer-events-none"/>
                                </div>
                                <button 
                                    onClick={handleBulkGenerate}
                                    className="flex items-center gap-2 bg-orange-600 text-white px-4 py-2 rounded-lg font-bold text-sm shadow-md shadow-orange-200 hover:bg-orange-700 transition-all"
                                >
                                    <Play size={16} fill="currentColor" />
                                    Generar {selectedPlanIds.size} OTs
                                </button>
                             </div>
                         )}
                    </div>
                )}
           </div>
      </div>

      {/* --- SECTION 3: LIST VIEW --- */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden min-h-[400px]">
         <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between text-xs font-bold text-slate-500 uppercase tracking-wider">
             <div className="flex items-center gap-2">
                <Filter size={14}/>
                <span>{Object.values(groupedItems).flat().length} Registros encontrados</span>
             </div>
             {activeTab === 'upcoming' && <span>Selección Múltiple Activa</span>}
         </div>

         <div className="divide-y divide-slate-100">
            {Object.keys(groupedItems).length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-slate-400">
                    <CalendarClock size={48} className="mb-3 opacity-20"/>
                    <p>No hay mantenimientos en este rango.</p>
                </div>
            )}

            {Object.entries(groupedItems).map(([dateLabel, items]) => (
                <div key={dateLabel}>
                    <div className="bg-slate-50/80 px-6 py-2 border-b border-slate-100 sticky top-0 backdrop-blur-sm z-0">
                        <h3 className="text-xs font-bold text-slate-600 uppercase flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${activeTab === 'upcoming' ? 'bg-orange-400' : 'bg-slate-400'}`}></div>
                            {dateLabel.toUpperCase()}
                        </h3>
                    </div>
                    {items.map((item) => {
                        const isSelected = activeTab === 'upcoming' && selectedPlanIds.has(item.planId);
                        const isOverdue = activeTab === 'upcoming' && new Date(item.date) < new Date(new Date().setHours(0,0,0,0));

                        // New Logic: Only show program button if downtime required AND parts required (stock status not none)
                        const canSchedule = item.requiresDowntime && item.stockStatus !== 'none';

                        return (
                            <div 
                                key={activeTab === 'upcoming' ? item.uniqueId : item.id} 
                                className={`flex items-center gap-4 px-6 py-4 hover:bg-slate-50 transition-colors group ${isSelected ? 'bg-orange-50/40' : ''}`}
                            >
                                {/* Checkbox / Icon */}
                                {activeTab === 'upcoming' ? (
                                    <div 
                                        className={`w-5 h-5 shrink-0 rounded border flex items-center justify-center transition-colors cursor-pointer ${isSelected ? 'bg-orange-600 border-orange-600' : 'border-slate-300 bg-white'}`}
                                        onClick={() => toggleSelection(item.uniqueId, item.planId)}
                                    >
                                        {isSelected && <CheckSquare size={14} className="text-white"/>}
                                    </div>
                                ) : (
                                    <div className="w-5 shrink-0 flex justify-center">
                                        <CheckCircle2 size={18} className="text-emerald-500"/>
                                    </div>
                                )}

                                {/* Main Info */}
                                <div className="flex-1 min-w-0" onClick={() => activeTab === 'upcoming' && toggleSelection(item.uniqueId, item.planId)}>
                                    <div className="flex items-center gap-2 mb-1">
                                        <h4 className={`font-bold truncate ${isSelected ? 'text-orange-700' : 'text-slate-900'}`}>{item.title}</h4>
                                        {isOverdue && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded border border-red-200">VENCIDO</span>}
                                        {activeTab === 'history' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-600 px-1.5 py-0.5 rounded border border-emerald-200">COMPLETADO</span>}

                                        {/* Tags for Upcoming */}
                                        {activeTab === 'upcoming' && item.requiresDowntime && (
                                            <span className="text-[10px] font-bold bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100 flex items-center gap-1" title="Requiere Parada de Máquina">
                                                <Ban size={10} /> PARADA
                                            </span>
                                        )}
                                        {activeTab === 'upcoming' && item.stockStatus !== 'none' && (
                                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border flex items-center gap-1 ${item.stockStatus === 'ok' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-orange-50 text-orange-600 border-orange-100'}`} title={item.stockStatus === 'ok' ? 'Stock Disponible' : item.missingParts.join(', ')}>
                                                <Package size={10} /> {item.stockStatus === 'ok' ? 'STOCK OK' : 'FALTA STOCK'}
                                            </span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-3 text-xs text-slate-500">
                                        <span className="font-medium text-slate-600 flex items-center gap-1"><ChevronRight size={12}/> {item.assetName}</span>
                                        {activeTab === 'upcoming' && (
                                            <>
                                                <span>•</span>
                                                <span>Cada {item.frequency} días</span>
                                                <span>•</span>
                                                <span>{item.hours}h est.</span>
                                            </>
                                        )}
                                        {activeTab === 'history' && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-1">
                                                    <UserIcon size={12}/> 
                                                    {item.technicianName}
                                                </span>
                                            </>
                                        )}
                                    </div>
                                </div>

                                {/* Actions / Labels */}
                                <div className="text-right shrink-0 flex items-center gap-3">
                                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">
                                        {activeTab === 'upcoming' ? item.specialty : item.specialtyRequired}
                                    </span>

                                    {/* Programar Button: Only for Downtime + Parts Required */}
                                    {activeTab === 'upcoming' && canSchedule && (
                                        <button 
                                            onClick={(e) => openScheduleModal(e, item)}
                                            className="hidden group-hover:flex items-center gap-1 bg-white border border-slate-300 text-slate-700 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-slate-50 hover:text-orange-600 transition-all shadow-sm"
                                        >
                                            <Calendar size={14} /> Programar
                                        </button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            ))}
         </div>
      </div>

      {/* SCHEDULE MODAL */}
      {scheduleModalOpen && itemToSchedule && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
            <div className="bg-white rounded-xl w-full max-w-md shadow-2xl p-6">
                <div className="flex justify-between items-start mb-4">
                    <div>
                        <h3 className="font-bold text-slate-800 text-lg">Programar Mantenimiento</h3>
                        <p className="text-xs text-slate-500">{itemToSchedule.title}</p>
                    </div>
                    <button onClick={() => setScheduleModalOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600"/></button>
                </div>

                <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 text-sm text-blue-800 mb-4">
                    <p className="font-bold mb-1">Nota:</p>
                    <p className="text-xs">Al confirmar la fecha acordada, se generará la Orden de Trabajo automáticamente, pisando la fecha teórica proyectada.</p>
                </div>

                <div className="mb-6">
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Fecha Acordada de Ejecución</label>
                    <input 
                        type="date" 
                        className="w-full border border-slate-300 rounded-lg px-4 py-3 text-slate-900 font-bold focus:ring-2 focus:ring-orange-500 outline-none"
                        value={newScheduleDate}
                        onChange={(e) => setNewScheduleDate(e.target.value)}
                    />
                </div>

                <div className="flex gap-3">
                    <button 
                        onClick={() => setScheduleModalOpen(false)}
                        className="flex-1 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg"
                    >
                        Cancelar
                    </button>
                    <button 
                        onClick={confirmSchedule}
                        className="flex-1 bg-orange-600 text-white py-2 rounded-lg font-bold hover:bg-orange-700 flex items-center justify-center gap-2"
                    >
                        <Save size={16}/> Confirmar
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* STOCK ALERT MODAL (BLOCKING) */}
      {stockAlertOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl flex flex-col max-h-[90vh]">
                  <div className="p-5 border-b border-red-100 bg-red-50 rounded-t-xl flex items-center gap-3">
                      <div className="bg-red-100 p-2 rounded-full text-red-600">
                          <AlertCircle size={24} />
                      </div>
                      <div>
                          <h3 className="text-lg font-bold text-red-700">Stock Insuficiente</h3>
                          <p className="text-xs text-red-500">No se pueden generar las órdenes de trabajo.</p>
                      </div>
                  </div>

                  <div className="p-6 overflow-y-auto">
                      <p className="text-sm text-slate-600 mb-4">
                          Los siguientes repuestos no tienen existencias suficientes para cubrir los mantenimientos seleccionados:
                      </p>

                      <div className="space-y-3">
                          {missingStockItems.map((item, idx) => (
                              <div key={idx} className="border border-slate-200 rounded-lg p-3 bg-slate-50">
                                  <div className="flex justify-between items-start mb-2">
                                      <div>
                                          <p className="font-bold text-slate-800">{item.itemName}</p>
                                          <p className="text-xs text-slate-400 font-mono">{item.sku}</p>
                                      </div>
                                      <div className="text-right">
                                          <span className="block text-xs text-slate-500">Faltante</span>
                                          <span className="font-bold text-red-600 text-lg">-{item.missing}</span>
                                      </div>
                                  </div>

                                  {/* Quick Actions */}
                                  <div className="mt-3 pt-3 border-t border-slate-200 flex items-center justify-between">
                                      <div className="text-xs text-slate-500">
                                          Req: <strong>{item.required}</strong> | Disp: <strong>{item.available}</strong>
                                      </div>
                                      <button 
                                          onClick={() => handleQuickPurchase(item.itemId, item.missing)}
                                          className="flex items-center gap-1 text-xs font-bold bg-blue-600 text-white px-3 py-1.5 rounded hover:bg-blue-700 transition-colors"
                                      >
                                          <ShoppingCart size={12} /> Solicitar Compra
                                      </button>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>

                  <div className="p-4 bg-slate-50 border-t border-slate-100 rounded-b-xl text-right">
                      <button 
                          onClick={() => setStockAlertOpen(false)}
                          className="bg-slate-800 text-white px-6 py-2 rounded-lg font-bold text-sm hover:bg-slate-900"
                      >
                          Entendido, cerrar
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { Purchasing } from './features/Purchasing';
import { TechnicianView } from './features/TechnicianView';
import { PreventiveMaintenance } from './features/PreventiveMaintenance';
import { Configuration } from './features/Configuration';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS,
  MOCK_TASK_TEMPLATES
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask,
  ReceptionEntry,
  TaskTemplate
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);
  const [taskTemplates, setTaskTemplates] = useState<TaskTemplate[]>(MOCK_TASK_TEMPLATES);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[], technicianId?: string, specificDate?: string) => {
    const newOrders: WorkOrder[] = [];

    let techName = undefined;
    if (technicianId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        techName = tech?.name;
    }

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado desde Plan Maestro.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          assignedTechnicianId: technicianId, // Assign if provided
          technicianName: techName,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, 
          status: WorkOrderStatus.PENDING,
          dueDate: specificDate || plan.nextDueDate, // Use agreed date if provided
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`✅ Se han generado ${newOrders.length} Órdenes de Trabajo${techName ? ` asignadas a ${techName}` : ''}${specificDate ? ` para el día ${specificDate}` : ''}.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleDeletePlan = (planId: string) => {
    setMaintenancePlans(prev => prev.filter(p => p.id !== planId));
  };

  const handleCreateWorkOrder = (newOrder: WorkOrder) => {
    setWorkOrders(prev => [newOrder, ...prev]);
  };

  // --- NEW PURCHASING LOGIC HANDLERS ---

  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      originalQuantity: qty,
      approvedQuantity: 0,
      receivedQuantity: 0,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING_APPROVAL,
      estimatedCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert("Solicitud de compra generada. Pendiente de aprobación.");
  };

  // Stage 1: Approval (Manager)
  const handleApprovePurchase = (reqId: string, approvedQty: number) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { 
        ...pr, 
        status: PurchaseRequestStatus.APPROVED, 
        approvedQuantity: approvedQty // Manager can edit qty
      } : pr
    ));
  };

  const handleRejectPurchase = (reqId: string) => {
     setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.REJECTED } : pr
    ));
  };

  // Stage 2: Purchasing (Buyer)
  const handleProcessPurchase = (reqId: string, provider: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
        pr.id === reqId ? { 
            ...pr, 
            status: PurchaseRequestStatus.PURCHASED, 
            provider: provider,
            orderDate: new Date().toISOString().split('T')[0]
        } : pr
      ));
  };

  // Stage 3: Receiving (Warehouse)
  const handleReceivePurchase = (reqId: string, qtyReceived: number, remito: string, forceClose: boolean) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // 1. Update Inventory
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + qtyReceived } 
        : item
    ));

    // 2. Update Request Status & Log
    setPurchaseRequests(prev => prev.map(pr => {
      if (pr.id === reqId) {
        const newReceivedTotal = pr.receivedQuantity + qtyReceived;
        const isFullyReceived = newReceivedTotal >= pr.approvedQuantity;

        // Log Entry
        const newEntry: ReceptionEntry = {
            id: `rec-${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            quantity: qtyReceived,
            remito: remito,
            receivedBy: currentUser.name
        };

        return { 
            ...pr, 
            receivedQuantity: newReceivedTotal,
            receptionLog: [...(pr.receptionLog || []), newEntry],
            status: (isFullyReceived || forceClose) 
                ? PurchaseRequestStatus.COMPLETED 
                : PurchaseRequestStatus.PARTIALLY_RECEIVED
        };
      }
      return pr;
    }));

    alert(`✅ Stock actualizado (+${qtyReceived} un).`);
  };

  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-orange-600 text-white text-xs font-bold p-2 rounded-lg shadow-lg border border-orange-500 opacity-90 hover:opacity-100 transition-opacity cursor-pointer focus:ring-2 focus:ring-white outline-none"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN} className="text-slate-900 bg-white">Simular: Admin</option>
          <option value={UserRole.PLANNER} className="text-slate-900 bg-white">Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN} className="text-slate-900 bg-white">Simular: Técnico</option>
        </select>
      </div>

      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS}
          assets={MOCK_ASSETS}
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          workOrders={workOrders}
          users={MOCK_USERS}
          inventory={inventory}
          onGenerateOrders={handleGenerateOrders}
          onRequestPurchase={handleRequestPurchase}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          onRequestPurchase={handleRequestPurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Purchasing 
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onApprovePurchase={handleApprovePurchase}
          onRejectPurchase={handleRejectPurchase}
          onProcessPurchase={handleProcessPurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView.startsWith('config-') && (
        <Configuration 
            currentView={currentView}
            users={MOCK_USERS}
            assets={MOCK_ASSETS}
            inventory={inventory}
            taskTemplates={taskTemplates}
            maintenancePlans={maintenancePlans}
            onCreatePlan={handleCreatePlan}
            onDeletePlan={handleDeletePlan}
        />
      )}

    </Layout>
  );
