                )}
             </div>

             {/* Footer Actions */}
             <div className="px-6 py-4 bg-slate-50 border-t border-slate-100 flex justify-end rounded-b-2xl">
                <button 
                  onClick={() => setSelectedOrder(null)}
                  className="px-6 py-2.5 bg-white border border-slate-200 text-slate-700 font-medium hover:bg-slate-50 hover:text-slate-900 rounded-lg transition-colors shadow-sm"
                >
                  Cerrar
                </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { InventoryItem } from '../types';
import { Package, AlertTriangle, ShoppingCart, Search, Filter } from 'lucide-react';

interface InventoryProps {
  inventory: InventoryItem[];
  onRequestPurchase: (itemId: string, qty: number) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ 
  inventory, 
  onRequestPurchase, 
}) => {
  const [qtyInputs, setQtyInputs] = useState<Record<string, number>>({});
  const [searchTerm, setSearchTerm] = useState('');

  const handleQtyChange = (id: string, val: string) => {
    setQtyInputs(prev => ({ ...prev, [id]: parseInt(val) || 0 }));
  };

  const filteredInventory = inventory.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    item.sku.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Almacén y Stock</h2>
          <p className="text-slate-500">Consulta de disponibilidad y solicitud de reposición.</p>
        </div>

        {/* Search Bar */}
        <div className="relative w-full md:w-64">
            <Search className="absolute left-3 top-2.5 text-slate-400" size={18} />
            <input 
                type="text" 
                placeholder="Buscar SKU o Nombre..." 
                className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
            />
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left text-sm">
        <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
            <tr>
            <th className="px-6 py-4 font-semibold">SKU / Ítem</th>
            <th className="px-6 py-4 font-semibold">Categoría</th>
            <th className="px-6 py-4 font-semibold">Stock Actual</th>
            <th className="px-6 py-4 font-semibold text-right">Reposición</th>
            </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
            {filteredInventory.map(item => {
            const isLowStock = item.quantity <= item.minStock;
            return (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-4">
                    <div className="flex items-start gap-3">
                    <div className={`p-2.5 rounded-lg ${isLowStock ? 'bg-red-50 text-red-500' : 'bg-slate-100 text-slate-500'}`}>
                        <Package size={20} />
                    </div>
                    <div>
                        <p className="font-bold text-slate-900">{item.name}</p>
                        <p className="text-xs font-mono text-slate-400 mt-0.5">{item.sku}</p>
                    </div>
                    </div>
                </td>
                <td className="px-6 py-4 text-slate-600">
                    <span className="inline-flex items-center px-2.5 py-1 rounded-md bg-slate-100 text-slate-600 text-xs font-medium border border-slate-200">
                        {item.category}
                    </span>
                </td>
                <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                    <span className={`text-lg font-bold ${isLowStock ? 'text-red-600' : 'text-slate-700'}`}>
                        {item.quantity} <span className="text-xs font-normal text-slate-400">un.</span>
                    </span>
                    {isLowStock && (
                        <div className="flex items-center gap-1 text-[10px] font-bold uppercase text-red-600 bg-red-50 px-2 py-1 rounded border border-red-100">
                        <AlertTriangle size={10} /> Crítico (Min: {item.minStock})
                        </div>
                    )}
                    </div>
                </td>
                <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                        <div className="relative">
                            <input 
                                type="number" 
                                min="1"
                                placeholder="10"
                                className="w-20 border border-slate-200 rounded-lg pl-3 pr-2 py-1.5 text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                                onChange={(e) => handleQtyChange(item.id, e.target.value)}
                            />
                        </div>
                        <button 
                        onClick={() => onRequestPurchase(item.id, qtyInputs[item.id] || 10)}
                        className="bg-white border border-slate-200 text-primary-600 hover:bg-primary-50 hover:border-primary-200 px-3 py-1.5 rounded-lg transition-all flex items-center gap-2 text-xs font-bold shadow-sm"
                        >
                        <ShoppingCart size={14} /> Solicitar
                        </button>
                    </div>
                </td>
                </tr>
            );
            })}
            {filteredInventory.length === 0 && (
                <tr>
                    <td colSpan={4} className="px-6 py-12 text-center text-slate-400">
                        No se encontraron artículos.
                    </td>
                </tr>
            )}
        </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, ChecklistTask } from '../types';
import { Calendar, MapPin, Play, CheckCircle, Camera, AlertCircle, X, CheckSquare, Square } from 'lucide-react';

interface TechnicianViewProps {
  orders: WorkOrder[];
  technicianId: string;
  onStatusChange: (id: string, status: WorkOrderStatus, data?: { comment?: string; evidence?: string; checklist?: ChecklistTask[] }) => void;
}

export const TechnicianView: React.FC<TechnicianViewProps> = ({ orders, technicianId, onStatusChange }) => {
  const [selectedOrder, setSelectedOrder] = useState<WorkOrder | null>(null);
  const [completeModalOpen, setCompleteModalOpen] = useState(false);

  // Form State for Completion
  const [comment, setComment] = useState('');
  const [evidenceFile, setEvidenceFile] = useState<string | null>(null);
  const [checklistState, setChecklistState] = useState<ChecklistTask[]>([]);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const myOrders = orders.filter(o => o.assignedTechnicianId === technicianId);
  const todayOrders = myOrders.filter(o => o.status !== WorkOrderStatus.COMPLETED);

  const handleStart = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onStatusChange(id, WorkOrderStatus.IN_PROGRESS);
  };

  const openCompleteModal = (e: React.MouseEvent, order: WorkOrder) => {
    e.stopPropagation();
    setSelectedOrder(order);
    setChecklistState(order.checklist ? [...order.checklist] : []);
    setCompleteModalOpen(true);
    setComment('');
    setEvidenceFile(null);
    setError('');
  };

  const toggleChecklistTask = (taskId: string) => {
    setChecklistState(prev => prev.map(t => 
      t.id === taskId ? { ...t, completed: !t.completed } : t
    ));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setEvidenceFile(url);
    }
  };

  const submitCompletion = () => {
    if (!comment.trim()) {
      setError('Debes ingresar un comentario técnico.');
      return;
    }
    if (!evidenceFile) {
      setError('Es obligatorio adjuntar una foto de evidencia.');
      return;
    }

    // Validate Checklist
    const allTasksCompleted = checklistState.every(t => t.completed);
    if (checklistState.length > 0 && !allTasksCompleted) {
       setError('Debes completar todas las tareas del check-list.');
       return;
    }

    if (selectedOrder) {
      onStatusChange(selectedOrder.id, WorkOrderStatus.COMPLETED, { 
        comment, 
        evidence: evidenceFile,
        checklist: checklistState
      });
      setCompleteModalOpen(false);
      setSelectedOrder(null);
    }
  };

  // Calculate progress for UI
  const checklistProgress = checklistState.length > 0 
    ? Math.round((checklistState.filter(t => t.completed).length / checklistState.length) * 100) 
    : 100;

  return (
    <div className="space-y-4 max-w-2xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-xl font-bold text-slate-900">Mi Agenda</h2>
          <p className="text-sm text-slate-500">Tareas asignadas para hoy.</p>
        </div>
        <div className="bg-primary-50 text-primary-700 px-3 py-1 rounded-full text-sm font-bold">
          {todayOrders.length} Pendientes
        </div>
      </div>

      {todayOrders.length === 0 ? (
         <div className="text-center py-12 bg-white rounded-xl shadow-sm">
           <div className="inline-flex p-4 rounded-full bg-green-50 text-green-500 mb-4">
             <CheckCircle size={32} />
           </div>
           <p className="text-slate-600 font-medium">¡Todo al día!</p>
           <p className="text-slate-400 text-sm">No tienes órdenes pendientes.</p>
         </div>
      ) : (
        <div className="space-y-4">
          {todayOrders.map(ot => (
            <div 
              key={ot.id} 
              className={`bg-white rounded-xl shadow-sm border-l-4 p-5 transition-all ${
                ot.priority === Priority.CRITICAL ? 'border-l-red-500' : 
                ot.priority === Priority.HIGH ? 'border-l-orange-500' : 'border-l-primary-500'
              }`}
            >
              <div className="flex justify-between items-start mb-2">
                <span className="text-xs font-mono text-slate-400">#{ot.id}</span>
                <span className={`text-xs font-bold px-2 py-1 rounded uppercase ${
                  ot.status === WorkOrderStatus.IN_PROGRESS ? 'bg-primary-100 text-primary-700' : 'bg-slate-100 text-slate-600'
                }`}>
                  {ot.status.replace('_', ' ')}
                </span>
              </div>

              <h3 className="text-lg font-bold text-slate-900 mb-1">{ot.title}</h3>
              <div className="flex items-center gap-2 text-sm text-slate-600 mb-4">
                <MapPin size={14} className="text-slate-400"/>
                {ot.assetName}
              </div>

              <p className="text-sm text-slate-500 mb-6 bg-slate-50 p-3 rounded-lg border border-slate-100">
                {ot.description}
              </p>

              {ot.checklist && ot.checklist.length > 0 && (
                <div className="mb-4">
                   <div className="text-xs font-semibold text-slate-500 mb-1">Tareas (Check-list)</div>
                   <div className="w-full bg-slate-100 rounded-full h-1.5">
                     <div className="bg-primary-500 h-1.5 rounded-full" style={{ width: '0%' }}></div> {/* Static for preview */}
                   </div>
                   <div className="text-xs text-slate-400 mt-1">{ot.checklist.length} puntos de inspección</div>
                </div>
              )}

              <div className="flex gap-3">
                {ot.status === WorkOrderStatus.PENDING && (
                  <button 
                    onClick={(e) => handleStart(e, ot.id)}
                    className="flex-1 bg-primary-600 text-white py-3 rounded-lg font-medium flex justify-center items-center gap-2 active:bg-primary-700"
                  >
                    <Play size={18} /> Iniciar
                  </button>
                )}

                {ot.status === WorkOrderStatus.IN_PROGRESS && (
                  <button 
                    onClick={(e) => openCompleteModal(e, ot)}
                    className="flex-1 bg-green-600 text-white py-3 rounded-lg font-medium flex justify-center items-center gap-2 active:bg-green-700"
                  >
                    <CheckCircle size={18} /> Finalizar
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Completion Modal */}
      {completeModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <h3 className="font-bold text-slate-800">Finalizar Orden</h3>
              <button onClick={() => setCompleteModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <div className="p-6 space-y-6 overflow-y-auto">
              {error && (
                <div className="bg-red-50 text-red-600 text-sm p-3 rounded-lg flex items-center gap-2">
                  <AlertCircle size={16} /> {error}
                </div>
              )}

              {/* Checklist Section */}
              {checklistState.length > 0 && (
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                  <div className="flex justify-between items-center mb-3">
                    <h4 className="font-bold text-slate-700 text-sm">Lista de Verificación</h4>
                    <span className={`text-xs font-bold px-2 py-1 rounded ${checklistProgress === 100 ? 'bg-green-100 text-green-700' : 'bg-slate-200 text-slate-600'}`}>
                      {checklistProgress}% Completo
                    </span>
                  </div>
                  <div className="space-y-2">
                    {checklistState.map(task => (
                      <div 
                        key={task.id} 
                        className={`flex items-start gap-3 p-2 rounded cursor-pointer transition-colors ${task.completed ? 'bg-green-50' : 'hover:bg-slate-100'}`}
                        onClick={() => toggleChecklistTask(task.id)}
                      >
                        <div className={`mt-0.5 ${task.completed ? 'text-green-600' : 'text-slate-400'}`}>
                          {task.completed ? <CheckSquare size={18} /> : <Square size={18} />}
                        </div>
                        <span className={`text-sm ${task.completed ? 'text-slate-600 line-through' : 'text-slate-800'}`}>
                          {task.description}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Comentario Técnico</label>
                <textarea 
                  className="w-full border border-slate-300 rounded-lg p-3 text-sm focus:ring-2 focus:ring-primary-500 outline-none h-24 resize-none"
                  placeholder="Describe el trabajo realizado..."
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Evidencia Fotográfica</label>
                <div 
                  className="border-2 border-dashed border-slate-300 rounded-lg p-6 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-50 transition-colors"
                  onClick={() => fileInputRef.current?.click()}
                >
                  {evidenceFile ? (
                    <div className="relative w-full h-32 bg-slate-100 rounded overflow-hidden">
                       <img src={evidenceFile} className="w-full h-full object-cover" alt="Preview" />
                       <div className="absolute inset-0 flex items-center justify-center bg-black/30 text-white text-xs font-bold opacity-0 hover:opacity-100 transition-opacity">Cambiar Foto</div>
                    </div>
                  ) : (
                    <>
                      <Camera className="text-slate-400 mb-2" size={32} />
                      <p className="text-xs text-slate-500">Toca para tomar foto</p>
                    </>
                  )}
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
                </div>
              </div>
            </div>

            <div className="p-4 border-t border-slate-100 bg-slate-50 flex gap-3 shrink-0">
              <button 
                onClick={() => setCompleteModalOpen(false)}
                className="flex-1 py-3 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={submitCompletion}
                className="flex-1 bg-primary-600 text-white py-3 rounded-lg font-medium hover:bg-primary-700 transition-colors shadow-lg shadow-primary-200 disabled:opacity-50 disabled:cursor-not-allowed"
                disabled={checklistState.length > 0 && checklistProgress < 100}
              >
                Completar OT
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './features/Dashboard';
import { WorkOrderList } from './features/WorkOrderList';
import { Inventory } from './features/Inventory';
import { Purchasing } from './features/Purchasing';
import { TechnicianView } from './features/TechnicianView';
import { PreventiveMaintenance } from './features/PreventiveMaintenance';
import { Configuration } from './features/Configuration';
import { 
  MOCK_USERS, 
  MOCK_WORK_ORDERS, 
  MOCK_INVENTORY, 
  MOCK_PURCHASE_REQUESTS,
  MOCK_MAINTENANCE_PLANS,
  MOCK_ASSETS,
  MOCK_TASK_TEMPLATES
} from './constants';
import { 
  User, 
  UserRole, 
  WorkOrder, 
  InventoryItem, 
  PurchaseRequest, 
  WorkOrderStatus, 
  PurchaseRequestStatus,
  MaintenancePlan,
  WorkOrderType,
  Priority,
  ChecklistTask,
  ReceptionEntry,
  TaskTemplate
} from './types';

function App() {
  // Global Application State
  const [currentUser, setCurrentUser] = useState<User>(MOCK_USERS[0]); // Default Admin
  const [currentView, setCurrentView] = useState('dashboard');

  // Domain State
  const [workOrders, setWorkOrders] = useState<WorkOrder[]>(MOCK_WORK_ORDERS);
  const [inventory, setInventory] = useState<InventoryItem[]>(MOCK_INVENTORY);
  const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>(MOCK_PURCHASE_REQUESTS);
  const [maintenancePlans, setMaintenancePlans] = useState<MaintenancePlan[]>(MOCK_MAINTENANCE_PLANS);
  const [taskTemplates, setTaskTemplates] = useState<TaskTemplate[]>(MOCK_TASK_TEMPLATES);

  // Handlers for Work Orders
  const handleAssignTechnician = (orderId: string, technicianId: string) => {
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        return {
          ...order,
          assignedTechnicianId: technicianId,
          technicianName: tech?.name
        };
      }
      return order;
    }));
  };

  const handleTechStatusChange = (orderId: string, newStatus: WorkOrderStatus, data?: { comment?: string, evidence?: string, checklist?: ChecklistTask[] }) => {

    // 1. Update the Work Order
    setWorkOrders(prev => prev.map(order => {
      if (order.id === orderId) {
        return {
          ...order,
          status: newStatus,
          completionComment: data?.comment,
          evidenceImageUrl: data?.evidence,
          checklist: data?.checklist || order.checklist,
          endTime: newStatus === WorkOrderStatus.COMPLETED ? new Date().toISOString() : undefined
        };
      }
      return order;
    }));

    // 2. LOGIC FOR PREVENTIVE ENGINE (The Trigger)
    if (newStatus === WorkOrderStatus.COMPLETED) {
      const order = workOrders.find(o => o.id === orderId);
      if (order && order.type === WorkOrderType.PREVENTIVE && order.planId) {
        const plan = maintenancePlans.find(p => p.id === order.planId);
        if (plan) {
          const today = new Date();
          today.setDate(today.getDate() + plan.frequencyDays);
          const nextDateISO = today.toISOString().split('T')[0];

          setMaintenancePlans(prev => prev.map(p => 
            p.id === plan.id ? { ...p, nextDueDate: nextDateISO } : p
          ));

          alert(`✅ Preventivo completado. Próximo mantenimiento reprogramado para: ${nextDateISO}`);
        }
      }
    }
  };

  const handleGenerateOrders = (planIds: string[], technicianId?: string, specificDate?: string) => {
    const newOrders: WorkOrder[] = [];

    let techName = undefined;
    if (technicianId) {
        const tech = MOCK_USERS.find(u => u.id === technicianId);
        techName = tech?.name;
    }

    planIds.forEach(id => {
      const plan = maintenancePlans.find(p => p.id === id);
      if (plan) {
        const newOrder: WorkOrder = {
          id: `ot-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
          title: plan.title,
          description: 'Mantenimiento preventivo generado desde Plan Maestro.',
          assetId: plan.assetId,
          assetName: plan.assetName,
          assignedTechnicianId: technicianId, // Assign if provided
          technicianName: techName,
          type: WorkOrderType.PREVENTIVE,
          priority: Priority.MEDIUM, 
          status: WorkOrderStatus.PENDING,
          dueDate: specificDate || plan.nextDueDate, // Use agreed date if provided
          specialtyRequired: plan.specialtyRequired,
          planId: plan.id,
          checklist: plan.checklistTemplate.map((desc, idx) => ({
             id: `chk-${Date.now()}-${idx}`,
             description: desc,
             completed: false
          }))
        };
        newOrders.push(newOrder);
      }
    });

    setWorkOrders(prev => [...prev, ...newOrders]);
    alert(`✅ Se han generado ${newOrders.length} Órdenes de Trabajo${techName ? ` asignadas a ${techName}` : ''}${specificDate ? ` para el día ${specificDate}` : ''}.`);
  };

  const handleCreatePlan = (newPlan: MaintenancePlan) => {
    setMaintenancePlans(prev => [...prev, newPlan]);
    alert("✅ Nuevo plan maestro creado exitosamente.");
  };

  const handleDeletePlan = (planId: string) => {
    setMaintenancePlans(prev => prev.filter(p => p.id !== planId));
  };

  const handleCreateWorkOrder = (newOrder: WorkOrder) => {
    setWorkOrders(prev => [newOrder, ...prev]);
  };

  // --- NEW PURCHASING LOGIC HANDLERS ---

  const handleRequestPurchase = (itemId: string, qty: number) => {
    const item = inventory.find(i => i.id === itemId);
    if (!item) return;

    const newRequest: PurchaseRequest = {
      id: `pr-${Date.now()}`,
      itemId,
      itemName: item.name,
      originalQuantity: qty,
      approvedQuantity: 0,
      receivedQuantity: 0,
      requestedBy: currentUser.name,
      date: new Date().toISOString().split('T')[0],
      status: PurchaseRequestStatus.PENDING_APPROVAL,
      estimatedCost: item.cost * qty
    };

    setPurchaseRequests(prev => [...prev, newRequest]);
    alert(`Solicitud de compra generada para ${qty} x ${item.name}. Pendiente de aprobación.`);
  };

  // Stage 1: Approval (Manager)
  const handleApprovePurchase = (reqId: string, approvedQty: number) => {
    setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { 
        ...pr, 
        status: PurchaseRequestStatus.APPROVED, 
        approvedQuantity: approvedQty // Manager can edit qty
      } : pr
    ));
  };

  const handleRejectPurchase = (reqId: string) => {
     setPurchaseRequests(prev => prev.map(pr => 
      pr.id === reqId ? { ...pr, status: PurchaseRequestStatus.REJECTED } : pr
    ));
  };

  // Stage 2: Purchasing (Buyer)
  const handleProcessPurchase = (reqId: string, provider: string) => {
    setPurchaseRequests(prev => prev.map(pr => 
        pr.id === reqId ? { 
            ...pr, 
            status: PurchaseRequestStatus.PURCHASED, 
            provider: provider,
            orderDate: new Date().toISOString().split('T')[0]
        } : pr
      ));
  };

  // Stage 3: Receiving (Warehouse)
  const handleReceivePurchase = (reqId: string, qtyReceived: number, remito: string, forceClose: boolean) => {
    const request = purchaseRequests.find(pr => pr.id === reqId);
    if (!request) return;

    // 1. Update Inventory
    setInventory(prev => prev.map(item => 
      item.id === request.itemId 
        ? { ...item, quantity: item.quantity + qtyReceived } 
        : item
    ));

    // 2. Update Request Status & Log
    setPurchaseRequests(prev => prev.map(pr => {
      if (pr.id === reqId) {
        const newReceivedTotal = pr.receivedQuantity + qtyReceived;
        const isFullyReceived = newReceivedTotal >= pr.approvedQuantity;

        // Log Entry
        const newEntry: ReceptionEntry = {
            id: `rec-${Date.now()}`,
            date: new Date().toISOString().split('T')[0],
            quantity: qtyReceived,
            remito: remito,
            receivedBy: currentUser.name
        };

        return { 
            ...pr, 
            receivedQuantity: newReceivedTotal,
            receptionLog: [...(pr.receptionLog || []), newEntry],
            status: (isFullyReceived || forceClose) 
                ? PurchaseRequestStatus.COMPLETED 
                : PurchaseRequestStatus.PARTIALLY_RECEIVED
        };
      }
      return pr;
    }));

    alert(`✅ Stock actualizado (+${qtyReceived} un).`);
  };

  const switchRole = (role: UserRole) => {
    const user = MOCK_USERS.find(u => u.role === role);
    if (user) {
      setCurrentUser(user);
      if (role === UserRole.TECHNICIAN) {
        setCurrentView('technician');
      } else {
        setCurrentView('dashboard');
      }
    }
  };

  return (
    <Layout 
      currentUser={currentUser} 
      currentView={currentView} 
      onNavigate={setCurrentView}
      onLogout={() => {
        alert("Sesión finalizada. (Recargando demo...)");
        window.location.reload();
      }}
    >

      <div className="absolute top-4 right-4 z-50 md:right-8">
        <select 
          className="bg-primary-600 text-white text-xs p-2 rounded shadow-lg border border-primary-500 opacity-90 hover:opacity-100 transition-opacity cursor-pointer font-bold focus:ring-2 focus:ring-white outline-none"
          onChange={(e) => switchRole(e.target.value as UserRole)}
          value={currentUser.role}
        >
          <option value={UserRole.ADMIN} className="text-slate-900 bg-white">Simular: Admin</option>
          <option value={UserRole.PLANNER} className="text-slate-900 bg-white">Simular: Jefe Técnicos</option>
          <option value={UserRole.TECHNICIAN} className="text-slate-900 bg-white">Simular: Técnico</option>
        </select>
      </div>

      {currentView === 'dashboard' && (
        <Dashboard 
          workOrders={workOrders} 
          inventory={inventory} 
          purchaseRequests={purchaseRequests}
        />
      )}

      {currentView === 'work-orders' && (
        <WorkOrderList 
          orders={workOrders} 
          users={MOCK_USERS}
          assets={MOCK_ASSETS}
          onAssign={handleAssignTechnician}
          onCreate={handleCreateWorkOrder}
        />
      )}

      {currentView === 'preventive' && (
        <PreventiveMaintenance 
          plans={maintenancePlans}
          workOrders={workOrders}
          users={MOCK_USERS}
          inventory={inventory}
          onGenerateOrders={handleGenerateOrders}
          onRequestPurchase={handleRequestPurchase}
        />
      )}

      {currentView === 'technician' && (
        <TechnicianView 
          orders={workOrders}
          technicianId={currentUser.id}
          onStatusChange={handleTechStatusChange}
        />
      )}

      {currentView === 'inventory' && (
        <Inventory 
          inventory={inventory}
          onRequestPurchase={handleRequestPurchase}
        />
      )}

      {currentView === 'purchasing' && (
        <Purchasing 
          purchaseRequests={purchaseRequests}
          user={currentUser}
          onApprovePurchase={handleApprovePurchase}
          onRejectPurchase={handleRejectPurchase}
          onProcessPurchase={handleProcessPurchase}
          onReceivePurchase={handleReceivePurchase}
        />
      )}

      {currentView.startsWith('config-') && (
        <Configuration 
            currentView={currentView}
            users={MOCK_USERS}
            assets={MOCK_ASSETS}
            inventory={inventory}
            taskTemplates={taskTemplates}
            maintenancePlans={maintenancePlans}
            onCreatePlan={handleCreatePlan}
            onDeletePlan={handleDeletePlan}
        />
      )}

    </Layout>
  );
}

export default App;

import React, { useState, useMemo } from 'react';
import { MaintenancePlan, User, WorkOrder, WorkOrderType, WorkOrderStatus, UserRole, InventoryItem } from '../types';
import { 
    CalendarClock, AlertCircle, Play, CheckSquare, Calendar, ChevronRight, Filter, 
    Search, User as UserIcon, History, BarChart3, TrendingUp, CheckCircle2, AlertTriangle, ArrowRight, Ban, Package, X, Save, ShoppingCart
} from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  workOrders: WorkOrder[];
  users: User[];
  inventory: InventoryItem[];
  onGenerateOrders: (planIds: string[], technicianId?: string, specificDate?: string) => void;
  onRequestPurchase: (itemId: string, qty: number) => void;
}

interface MissingStockItem {
    itemId: string;
    itemName: string;
    sku: string;
    required: number;
    available: number;
    missing: number;
    affectedPlans: string[]; // Plan Titles
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ 
    plans, workOrders, users, inventory, onGenerateOrders, onRequestPurchase 
}) => {
  const [viewDays, setViewDays] = useState(1); // Default to Today
  const [activeTab, setActiveTab] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState('');

  // Selection States
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [bulkTechnicianId, setBulkTechnicianId] = useState<string>('');

  // Schedule Modal State
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
  const [itemToSchedule, setItemToSchedule] = useState<{planId: string, title: string, originalDate: string} | null>(null);
  const [newScheduleDate, setNewScheduleDate] = useState('');

  // Stock Alert Modal State
  const [stockAlertOpen, setStockAlertOpen] = useState(false);
  const [missingStockItems, setMissingStockItems] = useState<MissingStockItem[]>([]);

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // --- LOGIC: KPI CALCULATION ---
  const kpis = useMemo(() => {
    let theoreticalCount = 0;
    let realizedCount = 0;
    const machineCompliance: Record<string, { total: number, completed: number, name: string }> = {};

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);
    today.setHours(23,59,59,999);

    if (viewDays === 1) {
        plans.forEach(p => {
            const nextDue = new Date(p.nextDueDate);
            if (nextDue <= today) {
                theoreticalCount++;
                if (!machineCompliance[p.assetId]) {
                    machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
                }
                machineCompliance[p.assetId].total += 1;
            }
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.endTime || wo.dueDate); 
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });

    } else {
        plans.forEach(p => {
            const occurrences = Math.ceil(viewDays / p.frequencyDays);
            theoreticalCount += occurrences;

            if (!machineCompliance[p.assetId]) {
                machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
            }
            machineCompliance[p.assetId].total += occurrences;
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.dueDate);
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });
    }

    const complianceRate = theoreticalCount > 0 ? Math.round((realizedCount / theoreticalCount) * 100) : 100;

    const machineList = Object.values(machineCompliance)
        .map(m => ({ 
            ...m, 
            rate: m.total > 0 ? Math.round((m.completed / m.total) * 100) : 100 
        }))
        .sort((a, b) => a.rate - b.rate)
        .slice(0, 5); 

    return { theoreticalCount, realizedCount, complianceRate, machineList };
  }, [plans, workOrders, viewDays]);

  // --- LOGIC: STOCK VALIDATION ---

  // 1. Simple check for UI display (list view)
  const checkStockAvailability = (plan: MaintenancePlan) => {
      if (!plan.requiredParts || plan.requiredParts.length === 0) return { status: 'none', details: [] };

      const missingParts: string[] = [];
      let hasEnough = true;

      plan.requiredParts.forEach(part => {
          const invItem = inventory.find(i => i.id === part.itemId);
          if (!invItem || invItem.quantity < part.quantity) {
              hasEnough = false;
              missingParts.push(`${part.itemName} (Faltan ${part.quantity - (invItem?.quantity || 0)})`);
          }
      });

      return { 
          status: hasEnough ? 'ok' : 'missing', 
          details: missingParts 
      };
  };

  // 2. Strict Batch Validation (When Clicking Generate)
  const validateBatchStock = (planIds: string[]) => {
      const consolidatedReqs: Record<string, { required: number, affectedPlans: string[] }> = {};

      // Aggregate requirements
      planIds.forEach(id => {
          const plan = plans.find(p => p.id === id);
          if (plan && plan.requiredParts) {
              plan.requiredParts.forEach(part => {
                  if (!consolidatedReqs[part.itemId]) {
                      consolidatedReqs[part.itemId] = { required: 0, affectedPlans: [] };
                  }
                  consolidatedReqs[part.itemId].required += part.quantity;
                  consolidatedReqs[part.itemId].affectedPlans.push(plan.title);
              });
          }
      });

      const missingItems: MissingStockItem[] = [];

      // Check against inventory
      Object.entries(consolidatedReqs).forEach(([itemId, reqData]) => {
          const invItem = inventory.find(i => i.id === itemId);
          const available = invItem ? invItem.quantity : 0;

          if (available < reqData.required) {
              missingItems.push({
                  itemId,
                  itemName: invItem?.name || 'Desconocido',
                  sku: invItem?.sku || 'N/A',
                  required: reqData.required,
                  available: available,
                  missing: reqData.required - available,
                  affectedPlans: reqData.affectedPlans
              });
          }
      });

      return missingItems;
  };

  // --- LOGIC: GENERATE PROJECTIONS (UPCOMING) ---
  const projections = useMemo(() => {
    if (activeTab !== 'upcoming') return [];

    const items: any[] = [];
    const today = new Date();
    today.setHours(0,0,0,0);
    const endDate = new Date();
    endDate.setDate(today.getDate() + (viewDays === 1 ? 0 : viewDays)); 
    endDate.setHours(23,59,59,999);

    plans.forEach(plan => {
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            if (!plan.title.toLowerCase().includes(query) && !plan.assetName.toLowerCase().includes(query)) {
                return;
            }
        }

        let currentDate = new Date(plan.nextDueDate);
        currentDate.setHours(12,0,0,0); 

        while (currentDate <= endDate) {
            const stockCheck = checkStockAvailability(plan);

            items.push({
                uniqueId: `${plan.id}-${currentDate.toISOString()}`, 
                planId: plan.id,
                date: currentDate.toISOString().split('T')[0],
                rawDate: new Date(currentDate),
                title: plan.title,
                assetName: plan.assetName,
                frequency: plan.frequencyDays,
                specialty: plan.specialtyRequired,
                hours: plan.estimatedHours,
                requiresDowntime: plan.requiresDowntime,
                stockStatus: stockCheck.status,
                missingParts: stockCheck.details
            });

            currentDate.setDate(currentDate.getDate() + plan.frequencyDays);
            if (currentDate > endDate) break;
        }
    });

    return items.sort((a, b) => a.rawDate.getTime() - b.rawDate.getTime());
  }, [plans, viewDays, searchQuery, activeTab, inventory]);

  // --- LOGIC: HISTORY (REALIZED) ---
  const historyItems = useMemo(() => {
    if (activeTab !== 'history') return [];

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);

    return workOrders.filter(wo => {
        const woDate = new Date(wo.dueDate); 
        const matchesDate = woDate >= startDate && woDate <= today;
        const matchesType = wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED;

        let matchesSearch = true;
        if (searchQuery) {
             const query = searchQuery.toLowerCase();
             matchesSearch = wo.title.toLowerCase().includes(query) || wo.assetName.toLowerCase().includes(query);
        }

        return matchesDate && matchesType && matchesSearch;
    }).sort((a, b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()); 

  }, [workOrders, viewDays, searchQuery, activeTab]);

  // --- HANDLERS ---
  const toggleSelection = (uniqueId: string, planId: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(planId)) newSet.delete(planId);
    else newSet.add(planId);
    setSelectedPlanIds(newSet);
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un mantenimiento.');

    // Validate Stock
    const planIds = Array.from(selectedPlanIds) as string[];
    const missing = validateBatchStock(planIds);

    if (missing.length > 0) {
        setMissingStockItems(missing);
        setStockAlertOpen(true);
        return;
    }

    onGenerateOrders(planIds, bulkTechnicianId || undefined);
    setSelectedPlanIds(new Set());
    setBulkTechnicianId('');
  };

  const openScheduleModal = (e: React.MouseEvent, item: any) => {
      e.stopPropagation();
      setItemToSchedule({
          planId: item.planId,
          title: item.title,
          originalDate: item.date
      });
      setNewScheduleDate(item.date);
      setScheduleModalOpen(true);
  };

  const confirmSchedule = () => {
      if (itemToSchedule && newScheduleDate) {
          // Validate Stock for Single Item
          const missing = validateBatchStock([itemToSchedule.planId]);

          if (missing.length > 0) {
              setMissingStockItems(missing);
              setStockAlertOpen(true);
              // Close schedule modal because we are blocked
              setScheduleModalOpen(false); 
              return;
          }

          onGenerateOrders([itemToSchedule.planId], undefined, newScheduleDate);
          setScheduleModalOpen(false);
          setItemToSchedule(null);
      }
  };

  const handleQuickPurchase = (itemId: string, qty: number) => {
      onRequestPurchase(itemId, qty);
      // Optional: Close modal or keep it open to show progress?
      // Keeping it open allows user to request other items.
  };

  // Group projections by Date for better UI
  const groupByDate = (items: any[]) => {
    const groups: Record<string, any[]> = {};
    items.forEach(item => {
        const dateKey = activeTab === 'upcoming' 
            ? item.rawDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })
            : new Date(item.dueDate).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

        if (!groups[dateKey]) groups[dateKey] = [];
        groups[dateKey].push(item);
    });
    return groups;
  };

  const groupedItems = groupByDate(activeTab === 'upcoming' ? projections : historyItems);

  return (
    <div className="space-y-6">

      {/* --- SECTION 1: KPIS & STATS --- */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-2 bg-slate-900 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
              <div className="relative z-10 flex justify-between items-end">
                  <div>
                      <h2 className="text-2xl font-bold mb-1">Cumplimiento Global</h2>
                      <p className="text-slate-400 text-sm mb-4">
                          {viewDays === 1 
                            ? 'Ejecución en tiempo real (Hoy)' 
                            : `Promedio histórico (Últimos ${viewDays} días)`}
                      </p>
                      <div className="flex items-end gap-3">
                          <span className="text-5xl font-bold text-emerald-400">{kpis.complianceRate}%</span>
                          <span className="text-sm text-slate-400 mb-2">Tasa de Ejecución</span>
                      </div>
                  </div>
                  <div className="hidden md:block">
                       <div className="flex gap-8 text-right">
                           <div>
                               <div className="text-2xl font-bold">{kpis.theoreticalCount}</div>
                               <div className="text-xs text-slate-500 uppercase">Programados</div>
                           </div>
                           <div>
