  const [evidenceFile, setEvidenceFile] = useState<string | null>(null);
  const [checklistState, setChecklistState] = useState<ChecklistTask[]>([]);
  const [error, setError] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const myOrders = orders.filter(o => o.assignedTechnicianId === technicianId);
  const activeOrder = myOrders.find(o => o.status === WorkOrderStatus.IN_PROGRESS);
  const pendingOrders = myOrders.filter(o => o.status === WorkOrderStatus.PENDING);
  const completedToday = myOrders.filter(o => o.status === WorkOrderStatus.COMPLETED && new Date(o.endTime || '').toDateString() === new Date().toDateString());

  const handleStart = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onStatusChange(id, WorkOrderStatus.IN_PROGRESS);
  };

  const openCompleteModal = (e: React.MouseEvent, order: WorkOrder) => {
    e.stopPropagation();
    setSelectedOrder(order);
    setChecklistState(order.checklist ? [...order.checklist] : []);
    setCompleteModalOpen(true);
    setComment('');
    setEvidenceFile(null);
    setError('');
  };

  const toggleChecklistTask = (taskId: string) => {
    setChecklistState(prev => prev.map(t => 
      t.id === taskId ? { ...t, completed: !t.completed } : t
    ));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const url = URL.createObjectURL(e.target.files[0]);
      setEvidenceFile(url);
    }
  };

  const submitCompletion = () => {
    if (!comment.trim()) {
      setError('Debes ingresar un comentario técnico.');
      return;
    }
    if (!evidenceFile) {
      setError('Es obligatorio adjuntar una foto de evidencia.');
      return;
    }

    // Validate Checklist
    const allTasksCompleted = checklistState.every(t => t.completed);
    if (checklistState.length > 0 && !allTasksCompleted) {
       setError('Debes completar todas las tareas del check-list.');
       return;
    }

    if (selectedOrder) {
      onStatusChange(selectedOrder.id, WorkOrderStatus.COMPLETED, { 
        comment, 
        evidence: evidenceFile,
        checklist: checklistState
      });
      setCompleteModalOpen(false);
      setSelectedOrder(null);
    }
  };

  // Calculate progress for UI
  const checklistProgress = checklistState.length > 0 
    ? Math.round((checklistState.filter(t => t.completed).length / checklistState.length) * 100) 
    : 100;

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 h-full pb-8">

      {/* --- COLUMN 1: SIDEBAR SUMMARY --- */}
      <aside className="lg:col-span-1 space-y-6">
          {/* Profile Card */}
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col items-center text-center">
              <div className="w-20 h-20 rounded-full bg-slate-100 flex items-center justify-center text-primary-200 mb-4 ring-4 ring-primary-50">
                  <UserCircle size={64} className="text-primary-600"/>
              </div>
              <h2 className="text-lg font-bold text-slate-900">Panel Técnico</h2>
              <p className="text-sm text-slate-500 mb-4">Agenda del día</p>

              <div className="w-full grid grid-cols-2 gap-3 mt-2">
                  <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                      <div className="text-2xl font-bold text-blue-700">{pendingOrders.length}</div>
                      <div className="text-xs text-blue-600 font-medium uppercase">Pendientes</div>
                  </div>
                  <div className="bg-emerald-50 p-3 rounded-lg border border-emerald-100">
                      <div className="text-2xl font-bold text-emerald-700">{completedToday.length}</div>
                      <div className="text-xs text-emerald-600 font-medium uppercase">Completadas</div>
                  </div>
              </div>
          </div>

          {/* Quick Stats / Info */}
          <div className="bg-slate-900 text-white rounded-xl shadow-md p-5 relative overflow-hidden">
              <div className="relative z-10">
                  <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Estado del Turno</h3>
                  {activeOrder ? (
                      <div>
                          <div className="flex items-center gap-2 text-emerald-400 mb-1">
                              <Activity size={20} />
                              <span className="font-bold">En Actividad</span>
                          </div>
                          <p className="text-xs text-slate-400">Orden #{activeOrder.id} en curso.</p>
                      </div>
                  ) : (
                      <div>
                          <div className="flex items-center gap-2 text-slate-400 mb-1">
                              <Clock size={20} />
                              <span className="font-bold">Esperando Tarea</span>
                          </div>
                          <p className="text-xs text-slate-500">Inicia una orden para comenzar.</p>
                      </div>
                  )}
              </div>
              <Activity className="absolute -right-4 -bottom-4 text-white opacity-5 w-32 h-32" />
          </div>
      </aside>

      {/* --- COLUMN 2: MAIN CONTENT --- */}
      <main className="lg:col-span-3 space-y-6">

          {/* 1. HERO CARD: ACTIVE ORDER */}
          {activeOrder ? (
              <div className="bg-white rounded-xl shadow-lg border-l-8 border-l-primary-600 overflow-hidden animate-in slide-in-from-top-4 duration-300">
                  <div className="bg-primary-50 px-6 py-4 border-b border-primary-100 flex justify-between items-center">
                      <div className="flex items-center gap-3">
                          <div className="bg-primary-600 text-white p-2 rounded-lg shadow-sm">
                              <Activity size={24} className="animate-pulse" />
                          </div>
                          <div>
                              <span className="text-xs font-bold text-primary-700 uppercase tracking-wide">Tarea en Curso</span>
                              <h3 className="text-xl font-bold text-primary-900">{activeOrder.title}</h3>
                          </div>
                      </div>
                      <span className="bg-white text-primary-700 font-mono text-xs px-3 py-1 rounded border border-primary-200 shadow-sm">
                          #{activeOrder.id}
                      </span>
                  </div>

                  <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-4">
                          <div className="flex items-start gap-3">
                              <MapPin className="text-slate-400 mt-1" size={20}/>
                              <div>
                                  <p className="text-sm font-bold text-slate-700">Ubicación / Activo</p>
                                  <p className="text-base text-slate-900">{activeOrder.assetName}</p>
                              </div>
                          </div>
                          <div className="bg-slate-50 p-4 rounded-lg border border-slate-100 text-slate-700 text-sm leading-relaxed">
                              {activeOrder.description}
                          </div>
                      </div>

                      <div className="flex flex-col justify-between">
                          {activeOrder.checklist && activeOrder.checklist.length > 0 && (
                              <div className="mb-4">
                                  <div className="flex justify-between items-end mb-2">
                                      <span className="text-xs font-bold text-slate-500 uppercase">Progreso del Checklist</span>
                                      <span className="text-xs font-medium text-primary-600">{activeOrder.checklist.length} items</span>
                                  </div>
                                  <div className="w-full bg-slate-200 rounded-full h-2">
                                      <div className="bg-primary-500 h-2 rounded-full w-1/3"></div> {/* Visual placeholder */}
                                  </div>
                              </div>
                          )}
                          <button 
                              onClick={(e) => openCompleteModal(e, activeOrder)}
                              className="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-4 rounded-xl font-bold shadow-lg shadow-emerald-100 flex items-center justify-center gap-2 transition-all transform active:scale-95"
                          >
                              <CheckCircle size={20} /> Finalizar Orden
                          </button>
                      </div>
                  </div>
              </div>
          ) : (
              <div className="bg-gradient-to-r from-slate-800 to-slate-900 rounded-xl p-8 text-white flex flex-col md:flex-row items-center justify-between shadow-lg">
                  <div className="mb-4 md:mb-0">
                      <h3 className="text-xl font-bold mb-2">No hay tareas activas</h3>
                      <p className="text-slate-400 text-sm">Selecciona una orden de la lista "Pendientes" para comenzar a trabajar.</p>
                  </div>
                  <div className="bg-white/10 p-3 rounded-full">
                      <Play size={32} className="text-white opacity-50" />
                  </div>
              </div>
          )}

          {/* 2. PENDING ORDERS LIST */}
          <div>
              <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
                  <Briefcase size={20} className="text-slate-400"/> Cola de Trabajo ({pendingOrders.length})
              </h3>

              {pendingOrders.length === 0 ? (
                  <div className="text-center py-16 bg-white rounded-xl border-2 border-dashed border-slate-200">
                      <CheckCircle size={48} className="mx-auto mb-4 text-emerald-200" />
                      <p className="text-slate-500 font-medium">¡Todo al día! No tienes órdenes pendientes.</p>
                  </div>
              ) : (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {pendingOrders.map(ot => (
                          <div 
                              key={ot.id} 
                              className={`bg-white rounded-xl p-5 shadow-sm border border-slate-200 hover:shadow-md hover:border-primary-300 transition-all group relative overflow-hidden`}
                          >
                              {/* Priority Stripe */}
                              <div className={`absolute top-0 left-0 w-1.5 h-full ${
                                  ot.priority === Priority.CRITICAL ? 'bg-red-500' : 
                                  ot.priority === Priority.HIGH ? 'bg-orange-500' : 'bg-blue-500'
                              }`}></div>

                              <div className="pl-3">
                                  <div className="flex justify-between items-start mb-2">
                                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${
                                          ot.priority === Priority.CRITICAL ? 'bg-red-100 text-red-700' : 
                                          ot.priority === Priority.HIGH ? 'bg-orange-100 text-orange-700' : 'bg-blue-50 text-blue-700'
                                      }`}>
                                          {ot.priority}
                                      </span>
                                      <span className="text-xs text-slate-400 font-mono">#{ot.id}</span>
                                  </div>

                                  <h4 className="font-bold text-slate-900 mb-1 truncate" title={ot.title}>{ot.title}</h4>
                                  <p className="text-xs text-slate-500 mb-3 flex items-center gap-1">
                                      <MapPin size={12}/> {ot.assetName}
                                  </p>

                                  <div className="flex items-center justify-between mt-4">
                                       <div className="flex items-center gap-2 text-xs text-slate-400">
                                           {ot.checklist && ot.checklist.length > 0 && (
                                               <span className="flex items-center gap-1"><CheckSquare size={12}/> {ot.checklist.length}</span>
                                           )}
                                       </div>
                                       <button 
                                          onClick={(e) => handleStart(e, ot.id)}
                                          disabled={!!activeOrder}
                                          className={`flex items-center gap-1 px-4 py-2 rounded-lg text-xs font-bold transition-colors ${
                                              activeOrder 
                                              ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
                                              : 'bg-primary-600 text-white hover:bg-primary-700 shadow-sm'
                                          }`}
                                       >
                                           {activeOrder ? 'Ocupado' : <><Play size={12}/> Iniciar</>}
                                       </button>
                                  </div>
                              </div>
                          </div>
                      ))}
                  </div>
              )}
          </div>
      </main>

      {/* Completion Modal */}
      {completeModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl max-h-[90vh] flex flex-col">
            <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
              <h3 className="font-bold text-slate-800">Finalizar Orden</h3>
              <button onClick={() => setCompleteModalOpen(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>

            <div className="p-6 space-y-6 overflow-y-auto">
              {error && (
                <div className="bg-red-50 text-red-600 text-sm p-3 rounded-lg flex items-center gap-2">
                  <AlertCircle size={16} /> {error}
                </div>
              )}

              {/* Checklist Section */}
              {checklistState.length > 0 && (
                <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                  <div className="flex justify-between items-center mb-3">
                    <h4 className="font-bold text-slate-700 text-sm">Lista de Verificación</h4>
                    <span className={`text-xs font-bold px-2 py-1 rounded ${checklistProgress === 100 ? 'bg-green-100 text-green-700' : 'bg-slate-200 text-slate-600'}`}>
                      {checklistProgress}% Completo
                    </span>
                  </div>
                  <div className="space-y-2">
                    {checklistState.map(task => (
                      <div 
                        key={task.id} 
                        className={`flex items-start gap-3 p-2 rounded cursor-pointer transition-colors ${task.completed ? 'bg-green-50' : 'hover:bg-slate-100'}`}
                        onClick={() => toggleChecklistTask(task.id)}
                      >
                        <div className={`mt-0.5 ${task.completed ? 'text-green-600' : 'text-slate-400'}`}>
                          {task.completed ? <CheckSquare size={18} /> : <Square size={18} />}
                        </div>
                        <span className={`text-sm ${task.completed ? 'text-slate-600 line-through' : 'text-slate-800'}`}>
                          {task.description}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Comentario Técnico</label>
                <textarea 
                  className="w-full border border-slate-300 rounded-lg p-3 text-sm focus:ring-2 focus:ring-primary-500 outline-none h-24 resize-none bg-white"
                  placeholder="Describe el trabajo realizado..."
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Evidencia Fotográfica</label>
                <div 
                  className="border-2 border-dashed border-slate-300 rounded-lg p-6 flex flex-col items-center justify-center cursor-pointer hover:bg-slate-50 transition-colors bg-white"
                  onClick={() => fileInputRef.current?.click()}
                >
                  {evidenceFile ? (
                    <div className="relative w-full h-32 bg-slate-100 rounded overflow-hidden">
                       <img src={evidenceFile} className="w-full h-full object-cover" alt="Preview" />
                       <div className="absolute inset-0 flex items-center justify-center bg-black/30 text-white text-xs font-bold opacity-0 hover:opacity-100 transition-opacity">Cambiar Foto</div>
                    </div>
                  ) : (
                    <>
                      <Camera className="text-slate-400 mb-2" size={32} />
                      <p className="text-xs text-slate-500">Toca para tomar foto</p>
                    </>
                  )}
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleFileChange}
                  />
                </div>
              </div>
            </div>

            <div className="p-4 border-t border-slate-100 bg-slate-50 flex gap-3 shrink-0">
              <button 
                onClick={() => setCompleteModalOpen(false)}
                className="flex-1 py-3 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={submitCompletion}
                className="flex-1 bg-primary-600 text-white py-3 rounded-lg font-medium hover:bg-primary-700 transition-colors shadow-lg shadow-primary-200 disabled:opacity-50 disabled:cursor-not-allowed"
                disabled={checklistState.length > 0 && checklistProgress < 100}
              >
                Completar OT
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { User, UserRole } from '../types';
import { 
  LayoutDashboard, 
  Wrench, 
  Package, 
  ShoppingCart, 
  LogOut, 
  Menu,
  HardHat,
  CalendarClock,
  Settings,
  Users,
  Shield,
  Cpu,
  Box,
  ChevronDown,
  ClipboardList
} from 'lucide-react';

interface LayoutProps {
  currentUser: User;
  currentView: string;
  onNavigate: (view: string) => void;
  onLogout: () => void;
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ currentUser, currentView, onNavigate, onLogout, children }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isConfigOpen, setIsConfigOpen] = useState(false);

  // Helper to determine if user can see config
  const canSeeConfig = [UserRole.ADMIN, UserRole.PLANNER].includes(currentUser.role);

  const NavItem = ({ view, label, icon: Icon, restrictedTo, onClick, isSubItem }: any) => {
    if (restrictedTo && !restrictedTo.includes(currentUser.role)) return null;

    const isActive = currentView === view;

    return (
      <button
        onClick={() => {
          if(onClick) onClick();
          else {
            onNavigate(view);
            setIsMobileMenuOpen(false);
          }
        }}
        className={`w-full flex items-center gap-3 px-4 py-3 text-sm font-medium transition-colors rounded-lg mb-1
          ${isActive 
            ? 'bg-primary-600 text-white shadow-lg shadow-primary-900/20' 
            : 'text-slate-400 hover:bg-slate-800 hover:text-white'
          } ${isSubItem ? 'pl-11 text-xs' : ''}`}
      >
        {Icon && <Icon size={isSubItem ? 16 : 20} />}
        <span className="flex-1 text-left">{label}</span>
      </button>
    );
  };

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar for Desktop */}
      <aside className="hidden md:flex flex-col w-64 bg-slate-900 text-white h-full shadow-xl z-30">
        <div className="p-6 border-b border-slate-800 flex items-center gap-3">
          <div className="bg-primary-600 p-2 rounded-lg shadow-lg shadow-primary-500/20">
            <Wrench className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-lg font-bold tracking-tight text-white">Nexus GMAO</h1>
            <p className="text-xs text-slate-400">v2.4.0 Enterprise</p>
          </div>
        </div>

        <nav className="flex-1 p-4 overflow-y-auto scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
          <div className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-4 px-4">
            Módulos
          </div>

          <NavItem 
            view="dashboard" 
            label="Dashboard KPI" 
            icon={LayoutDashboard} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="work-orders" 
            label="Órdenes de Trabajo" 
            icon={Wrench} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="preventive" 
            label="Plan Preventivo" 
            icon={CalendarClock} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="technician" 
            label="Mi Agenda" 
            icon={HardHat} 
            restrictedTo={[UserRole.TECHNICIAN]} 
          />
          <NavItem 
            view="inventory" 
            label="Almacén & Stock" 
            icon={Package} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />
          <NavItem 
            view="purchasing" 
            label="Compras" 
            icon={ShoppingCart} 
            restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
          />

          {/* Configuración Dropdown - Only for Admins/Planners */}
          {canSeeConfig && (
            <div className="mt-2">
                <button
                    onClick={() => setIsConfigOpen(!isConfigOpen)}
                    className={`w-full flex items-center justify-between px-4 py-3 text-sm font-medium transition-all duration-200 rounded-lg mb-1 group
                        ${isConfigOpen ? 'bg-slate-800 text-white' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}
                    `}
                >
                    <div className="flex items-center gap-3">
                        <Settings size={20} className={`transition-transform duration-300 ${isConfigOpen ? 'rotate-90' : ''}`}/>
                        <span>Configuración</span>
                    </div>
                    <ChevronDown 
                        size={16} 
                        className={`transition-transform duration-300 ${isConfigOpen ? 'rotate-180' : ''}`}
                    />
                </button>

                <div 
                    className={`grid transition-all duration-300 ease-[cubic-bezier(0.4,0,0.2,1)] ${
                        isConfigOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0'
                    }`}
                >
                    <div className="overflow-hidden">
                        <div className="pt-1 pb-2">
                            <NavItem 
                                view="config-users" 
                                label="Usuarios" 
                                icon={Users} 
                                isSubItem={true}
                                restrictedTo={[UserRole.ADMIN]} 
                            />
                            <NavItem 
                                view="config-roles" 
                                label="Roles" 
                                icon={Shield} 
                                isSubItem={true}
                                restrictedTo={[UserRole.ADMIN]} 
                            />
                            <NavItem 
                                view="config-machines" 
                                label="Máquinas" 
                                icon={Cpu} 
                                isSubItem={true}
                                restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
                            />
                            <NavItem 
                                view="config-articles" 
                                label="Artículos" 
                                icon={Box} 
                                isSubItem={true}
                                restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} 
                            />
                        </div>
                    </div>
                </div>
            </div>
          )}
        </nav>

        <div className="p-4 border-t border-slate-800 bg-slate-900">
          <div className="flex items-center gap-3 mb-4 px-2">
            <img src={currentUser.avatar} alt="User" className="w-8 h-8 rounded-full ring-2 ring-primary-500" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">{currentUser.name}</p>
              <p className="text-xs text-slate-500 truncate capitalize">{currentUser.role.toLowerCase()}</p>
            </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center gap-2 px-4 py-2 text-sm text-slate-400 hover:bg-slate-800 hover:text-white rounded-lg transition-colors"
          >
            <LogOut size={16} />
            Cerrar Sesión
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Mobile Header */}
        <header className="md:hidden bg-slate-900 text-white p-4 flex justify-between items-center shadow-md z-20">
          <div className="flex items-center gap-2">
             <div className="bg-primary-600 p-1.5 rounded-lg">
                <Wrench className="text-white" size={20} />
             </div>
             <span className="font-bold">Nexus GMAO</span>
          </div>
          <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
            <Menu size={24} />
          </button>
        </header>

        {/* Mobile Menu Overlay */}
        {isMobileMenuOpen && (
          <div className="md:hidden absolute inset-0 bg-slate-900 z-10 p-4 pt-20">
            <nav className="flex flex-col gap-2">
              <NavItem view="dashboard" label="Dashboard" icon={LayoutDashboard} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="work-orders" label="Órdenes de Trabajo" icon={Wrench} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="preventive" label="Plan Preventivo" icon={CalendarClock} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="technician" label="Mi Agenda" icon={HardHat} restrictedTo={[UserRole.TECHNICIAN]} />
              <NavItem view="inventory" label="Inventario" icon={Package} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />
              <NavItem view="purchasing" label="Compras" icon={ShoppingCart} restrictedTo={[UserRole.ADMIN, UserRole.PLANNER]} />

              {canSeeConfig && (
                <div className="mt-2 pt-2 border-t border-slate-800">
                    <p className="text-xs text-slate-500 uppercase font-bold mb-2 px-2">Configuración</p>
                    <NavItem view="config-users" label="Usuarios" icon={Users} restrictedTo={[UserRole.ADMIN]} />
                    <NavItem view="config-roles" label="Roles" icon={Shield} restrictedTo={[UserRole.ADMIN]} />
                    <NavItem view="config-machines" label="Máquinas" icon={Cpu} restrictedTo={[UserRole.ADMIN]} />
                    <NavItem view="config-articles" label="Artículos" icon={Box} restrictedTo={[UserRole.ADMIN]} />
                </div>
              )}

              <hr className="border-slate-800 my-2" />
              <button onClick={onLogout} className="flex items-center gap-3 px-4 py-3 text-slate-400">
                <LogOut size={20} /> Cerrar Sesión
              </button>
            </nav>
          </div>
        )}

        <main className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50 relative">
          {children}
        </main>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { MaintenancePlan, User, WorkOrder, WorkOrderType, WorkOrderStatus, UserRole, InventoryItem } from '../types';
import { 
    CalendarClock, AlertCircle, Play, CheckSquare, Calendar, ChevronRight, Filter, 
    Search, User as UserIcon, History, BarChart3, TrendingUp, CheckCircle2, AlertTriangle, ArrowRight, Ban, Package, X, Save, ShoppingCart
} from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  workOrders: WorkOrder[];
  users: User[];
  inventory: InventoryItem[];
  onGenerateOrders: (planIds: string[], technicianId?: string, specificDate?: string) => void;
  onRequestPurchase: (itemId: string, qty: number) => void;
}

interface MissingStockItem {
    itemId: string;
    itemName: string;
    sku: string;
    required: number;
    available: number;
    missing: number;
    affectedPlans: string[]; // Plan Titles
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ 
    plans, workOrders, users, inventory, onGenerateOrders, onRequestPurchase 
}) => {
  const [viewDays, setViewDays] = useState(1); // Default to Today
  const [activeTab, setActiveTab] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState('');

  // Selection States
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [bulkTechnicianId, setBulkTechnicianId] = useState<string>('');

  // Schedule Modal State
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
  const [itemToSchedule, setItemToSchedule] = useState<{planId: string, title: string, originalDate: string} | null>(null);
  const [newScheduleDate, setNewScheduleDate] = useState('');

  // Stock Alert Modal State
  const [stockAlertOpen, setStockAlertOpen] = useState(false);
  const [missingStockItems, setMissingStockItems] = useState<MissingStockItem[]>([]);

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // --- LOGIC: KPI CALCULATION ---
  const kpis = useMemo(() => {
    let theoreticalCount = 0;
    let realizedCount = 0;
    const machineCompliance: Record<string, { total: number, completed: number, name: string }> = {};

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);
    today.setHours(23,59,59,999);

    if (viewDays === 1) {
        plans.forEach(p => {
            const nextDue = new Date(p.nextDueDate);
            if (nextDue <= today) {
                theoreticalCount++;
                if (!machineCompliance[p.assetId]) {
                    machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
                }
                machineCompliance[p.assetId].total += 1;
            }
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.endTime || wo.dueDate); 
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });

    } else {
        plans.forEach(p => {
            const occurrences = Math.ceil(viewDays / p.frequencyDays);
            theoreticalCount += occurrences;

            if (!machineCompliance[p.assetId]) {
                machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
            }
            machineCompliance[p.assetId].total += occurrences;
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.dueDate);
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });
    }

    const complianceRate = theoreticalCount > 0 ? Math.round((realizedCount / theoreticalCount) * 100) : 100;

    const machineList = Object.values(machineCompliance)
        .map(m => ({ 
            ...m, 
            rate: m.total > 0 ? Math.round((m.completed / m.total) * 100) : 100 
        }))
        .sort((a, b) => a.rate - b.rate)
        .slice(0, 5); 

    return { theoreticalCount, realizedCount, complianceRate, machineList };
  }, [plans, workOrders, viewDays]);

  // --- LOGIC: STOCK VALIDATION ---

  // 1. Simple check for UI display (list view)
  const checkStockAvailability = (plan: MaintenancePlan) => {
      if (!plan.requiredParts || plan.requiredParts.length === 0) return { status: 'none', details: [] };

      const missingParts: string[] = [];
      let hasEnough = true;

      plan.requiredParts.forEach(part => {
          const invItem = inventory.find(i => i.id === part.itemId);
          if (!invItem || invItem.quantity < part.quantity) {
              hasEnough = false;
              missingParts.push(`${part.itemName} (Faltan ${part.quantity - (invItem?.quantity || 0)})`);
          }
      });

      return { 
          status: hasEnough ? 'ok' : 'missing', 
          details: missingParts 
      };
  };

  // 2. Strict Batch Validation (When Clicking Generate)
  const validateBatchStock = (planIds: string[]) => {
      const consolidatedReqs: Record<string, { required: number, affectedPlans: string[] }> = {};

      // Aggregate requirements
      planIds.forEach(id => {
          const plan = plans.find(p => p.id === id);
          if (plan && plan.requiredParts) {
              plan.requiredParts.forEach(part => {
                  if (!consolidatedReqs[part.itemId]) {
                      consolidatedReqs[part.itemId] = { required: 0, affectedPlans: [] };
                  }
                  consolidatedReqs[part.itemId].required += part.quantity;
                  consolidatedReqs[part.itemId].affectedPlans.push(plan.title);
              });
          }
      });

      const missingItems: MissingStockItem[] = [];

      // Check against inventory
      Object.entries(consolidatedReqs).forEach(([itemId, reqData]) => {
          const invItem = inventory.find(i => i.id === itemId);
          const available = invItem ? invItem.quantity : 0;

          if (available < reqData.required) {
              missingItems.push({
                  itemId,
                  itemName: invItem?.name || 'Desconocido',
                  sku: invItem?.sku || 'N/A',
                  required: reqData.required,
                  available: available,
                  missing: reqData.required - available,
                  affectedPlans: reqData.affectedPlans
              });
          }
      });

      return missingItems;
  };

  // --- LOGIC: GENERATE PROJECTIONS (UPCOMING) ---
  const projections = useMemo(() => {
    if (activeTab !== 'upcoming') return [];

    const items: any[] = [];
    const today = new Date();
    today.setHours(0,0,0,0);
    const endDate = new Date();
    endDate.setDate(today.getDate() + (viewDays === 1 ? 0 : viewDays)); 
    endDate.setHours(23,59,59,999);

    plans.forEach(plan => {
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            if (!plan.title.toLowerCase().includes(query) && !plan.assetName.toLowerCase().includes(query)) {
                return;
            }
        }

        let currentDate = new Date(plan.nextDueDate);
        currentDate.setHours(12,0,0,0); 

        while (currentDate <= endDate) {
            const stockCheck = checkStockAvailability(plan);

            items.push({
                uniqueId: `${plan.id}-${currentDate.toISOString()}`, 
                planId: plan.id,
                date: currentDate.toISOString().split('T')[0],
                rawDate: new Date(currentDate),
                title: plan.title,
                assetName: plan.assetName,
                frequency: plan.frequencyDays,
                specialty: plan.specialtyRequired,
                hours: plan.estimatedHours,
                requiresDowntime: plan.requiresDowntime,
                stockStatus: stockCheck.status,
                missingParts: stockCheck.details
            });

            currentDate.setDate(currentDate.getDate() + plan.frequencyDays);
            if (currentDate > endDate) break;
        }
    });

    return items.sort((a, b) => a.rawDate.getTime() - b.rawDate.getTime());
  }, [plans, viewDays, searchQuery, activeTab, inventory]);

  // --- LOGIC: HISTORY (REALIZED) ---
  const historyItems = useMemo(() => {
    if (activeTab !== 'history') return [];

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);

    return workOrders.filter(wo => {
        const woDate = new Date(wo.dueDate); 
        const matchesDate = woDate >= startDate && woDate <= today;
        const matchesType = wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED;

        let matchesSearch = true;
        if (searchQuery) {
             const query = searchQuery.toLowerCase();
             matchesSearch = wo.title.toLowerCase().includes(query) || wo.assetName.toLowerCase().includes(query);
        }

        return matchesDate && matchesType && matchesSearch;
    }).sort((a, b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()); 

  }, [workOrders, viewDays, searchQuery, activeTab]);

  // --- HANDLERS ---
  const toggleSelection = (uniqueId: string, planId: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(planId)) newSet.delete(planId);
    else newSet.add(planId);
    setSelectedPlanIds(newSet);
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un mantenimiento.');

    // Validate Stock
    const planIds = Array.from(selectedPlanIds) as string[];
    const missing = validateBatchStock(planIds);

    if (missing.length > 0) {
        setMissingStockItems(missing);
        setStockAlertOpen(true);
        return;
    }

    onGenerateOrders(planIds, bulkTechnicianId || undefined);
    setSelectedPlanIds(new Set());
    setBulkTechnicianId('');
  };

  const openScheduleModal = (e: React.MouseEvent, item: any) => {
      e.stopPropagation();
      setItemToSchedule({
          planId: item.planId,
          title: item.title,
          originalDate: item.date
      });
      setNewScheduleDate(item.date);
      setScheduleModalOpen(true);
  };

  const confirmSchedule = () => {
      if (itemToSchedule && newScheduleDate) {
          // Validate Stock for Single Item
          const missing = validateBatchStock([itemToSchedule.planId]);

          if (missing.length > 0) {
              setMissingStockItems(missing);
              setStockAlertOpen(true);
              // Close schedule modal because we are blocked
              setScheduleModalOpen(false); 
              return;
          }

          onGenerateOrders([itemToSchedule.planId], undefined, newScheduleDate);
          setScheduleModalOpen(false);
          setItemToSchedule(null);
      }
  };

  const handleQuickPurchase = (itemId: string, qty: number) => {
      onRequestPurchase(itemId, qty);
      // Optional: Close modal or keep it open to show progress?
      // Keeping it open allows user to request other items.
  };

  // Group projections by Date for better UI
  const groupByDate = (items: any[]) => {
    const groups: Record<string, any[]> = {};
    items.forEach(item => {
        const dateKey = activeTab === 'upcoming' 
            ? item.rawDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })
            : new Date(item.dueDate).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

        if (!groups[dateKey]) groups[dateKey] = [];
        groups[dateKey].push(item);
    });
    return groups;
  };

  const groupedItems = groupByDate(activeTab === 'upcoming' ? projections : historyItems);

  return (
    <div className="space-y-6">

      {/* --- SECTION 1: KPIS & STATS --- */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-2 bg-slate-900 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
              <div className="relative z-10 flex justify-between items-end">
                  <div>
                      <h2 className="text-2xl font-bold mb-1">Cumplimiento Global</h2>
                      <p className="text-slate-400 text-sm mb-4">
                          {viewDays === 1 
                            ? 'Ejecución en tiempo real (Hoy)' 
                            : `Promedio histórico (Últimos ${viewDays} días)`}
                      </p>
                      <div className="flex items-end gap-3">
                          <span className="text-5xl font-bold text-emerald-400">{kpis.complianceRate}%</span>
                          <span className="text-sm text-slate-400 mb-2">Tasa de Ejecución</span>
                      </div>
                  </div>
                  <div className="hidden md:block">
                       <div className="flex gap-8 text-right">
                           <div>
                               <div className="text-2xl font-bold">{kpis.theoreticalCount}</div>
                               <div className="text-xs text-slate-500 uppercase">Programados</div>
                           </div>
                           <div>
                               <div className="text-2xl font-bold text-emerald-400">{kpis.realizedCount}</div>
                               <div className="text-xs text-slate-500 uppercase">Realizados</div>
                           </div>
                       </div>
                  </div>
              </div>
              <BarChart3 className="absolute right-[-20px] bottom-[-20px] text-slate-800 opacity-50" size={180} />
          </div>

          <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
               <h3 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
                   <AlertTriangle size={18} className="text-amber-500"/> Alertas por Equipo
               </h3>
               <div className="space-y-3">
                   {kpis.machineList.map((m, idx) => (
                       <div key={idx} className="flex justify-between items-center text-sm">
                           <span className="text-slate-600 truncate max-w-[150px]" title={m.name}>{m.name}</span>
                           <div className="flex items-center gap-2">
                               <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                   <div 
                                        className={`h-full rounded-full ${m.rate < 50 ? 'bg-red-500' : m.rate < 80 ? 'bg-amber-500' : 'bg-emerald-500'}`} 
                                        style={{width: `${m.rate}%`}}
                                    ></div>
                               </div>
                               <span className="text-xs font-bold text-slate-700 w-8 text-right">{m.rate}%</span>
                           </div>
                       </div>
                   ))}
                   {kpis.machineList.length === 0 && <p className="text-xs text-slate-400 italic">Datos insuficientes para análisis.</p>}
               </div>
          </div>
      </div>

      {/* --- SECTION 2: TOOLBAR --- */}
      <div className="flex flex-col gap-4">
           {/* Tabs */}
           <div className="flex bg-slate-100 p-1 rounded-lg w-fit">
                <button 
                    onClick={() => setActiveTab('upcoming')}
                    className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'upcoming' ? 'bg-white text-primary-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <CalendarClock size={16}/> Proyección
                </button>
                <button 
                    onClick={() => setActiveTab('history')}
                    className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white text-purple-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <History size={16}/> Histórico
                </button>
           </div>

           {/* Actions Bar */}
           <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 rounded-xl border border-slate-200 shadow-sm">

                {/* Search & Filters */}
                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-4 py-2 bg-slate-50 border-none rounded-lg text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                            placeholder="Buscar plan o máquina..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    <div className="flex items-center gap-2 bg-slate-50 rounded-lg p-1 pr-3">
                         <div className="bg-white p-1.5 rounded shadow-sm text-slate-500"><Calendar size={16}/></div>
                         <select 
                            className="bg-transparent text-sm font-medium text-slate-700 outline-none cursor-pointer"
                            value={viewDays}
                            onChange={(e) => setViewDays(Number(e.target.value))}
                         >
                             <option value={1}>Hoy</option>
                             <option value={7}>Esta Semana</option>
                             <option value={15}>15 Días</option>
                             <option value={30}>30 Días</option>
                             <option value={90}>3 Meses</option>
                         </select>
                     </div>
                </div>

                {/* Bulk Actions (Only for Upcoming) */}
                {activeTab === 'upcoming' && (
                    <div className="flex items-center gap-3 w-full md:w-auto justify-end">
                         {selectedPlanIds.size > 0 && (
                             <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4">
                                <div className="relative">
                                    <select 
                                        className="appearance-none bg-slate-100 border border-slate-200 text-slate-700 text-sm rounded-lg pl-3 pr-8 py-2 focus:ring-2 focus:ring-primary-500 outline-none cursor-pointer font-medium"
                                        value={bulkTechnicianId}
                                        onChange={(e) => setBulkTechnicianId(e.target.value)}
                                    >
                                        <option value="">Asignar Técnico (Opcional)</option>
                                        {technicians.map(t => (
                                            <option key={t.id} value={t.id}>{t.name}</option>
                                        ))}
                                    </select>
                                    <UserIcon size={14} className="absolute right-2.5 top-2.5 text-slate-400 pointer-events-none"/>
                                </div>
                                <button 
                                    onClick={handleBulkGenerate}
                                    className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2 rounded-lg font-bold text-sm shadow-md shadow-primary-200 hover:bg-primary-700 transition-all"
                                >
                                    <Play size={16} fill="currentColor" />
                                    Generar {selectedPlanIds.size} OTs
                                </button>
                             </div>
                         )}
                    </div>
                )}
           </div>
      </div>

      {/* --- SECTION 3: LIST VIEW --- */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden min-h-[400px]">
         <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between text-xs font-bold text-slate-500 uppercase tracking-wider">
             <div className="flex items-center gap-2">
                <Filter size={14}/>
                <span>{Object.values(groupedItems).flat().length} Registros encontrados</span>
             </div>
             {activeTab === 'upcoming' && <span>Selección Múltiple Activa</span>}
         </div>

         <div className="divide-y divide-slate-100">
            {Object.keys(groupedItems).length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-slate-400">
                    <CalendarClock size={48} className="mb-3 opacity-20"/>
                    <p>No hay mantenimientos en este rango.</p>
                </div>
            )}

            {Object.entries(groupedItems).map(([dateLabel, items]) => (
                <div key={dateLabel}>
                    <div className="bg-slate-50/80 px-6 py-2 border-b border-slate-100 sticky top-0 backdrop-blur-sm z-0">
                        <h3 className="text-xs font-bold text-slate-600 uppercase flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${activeTab === 'upcoming' ? 'bg-primary-400' : 'bg-purple-400'}`}></div>
                            {dateLabel.toUpperCase()}
                        </h3>
                    </div>
                    {items.map((item) => {
                        const isSelected = activeTab === 'upcoming' && selectedPlanIds.has(item.planId);
                        const isOverdue = activeTab === 'upcoming' && new Date(item.date) < new Date(new Date().setHours(0,0,0,0));

                        // New Logic: Only show program button if downtime required AND parts required (stock status not none)
                        const canSchedule = item.requiresDowntime && item.stockStatus !== 'none';

                        return (
                            <div 
                                key={activeTab === 'upcoming' ? item.uniqueId : item.id} 
                                className={`flex items-center gap-4 px-6 py-4 hover:bg-slate-50 transition-colors group ${isSelected ? 'bg-primary-50/40' : ''}`}
                            >
                                {/* Checkbox / Icon */}
                                {activeTab === 'upcoming' ? (
                                    <div 
                                        className={`w-5 h-5 shrink-0 rounded border flex items-center justify-center transition-colors cursor-pointer ${isSelected ? 'bg-primary-600 border-primary-600' : 'border-slate-300 bg-white'}`}
                                        onClick={() => toggleSelection(item.uniqueId, item.planId)}
                                    >
                                        {isSelected && <CheckSquare size={14} className="text-white"/>}
                                    </div>
                                ) : (
                                    <div className="w-5 shrink-0 flex justify-center">
                                        <CheckCircle2 size={18} className="text-emerald-500"/>
                                    </div>
                                )}

                                {/* Main Info */}
                                <div className="flex-1 min-w-0" onClick={() => activeTab === 'upcoming' && toggleSelection(item.uniqueId, item.planId)}>
                                    <div className="flex items-center gap-2 mb-1">
                                        <h4 className={`font-bold truncate ${isSelected ? 'text-primary-700' : 'text-slate-900'}`}>{item.title}</h4>
                                        {isOverdue && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded border border-red-200">VENCIDO</span>}
                                        {activeTab === 'history' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-600 px-1.5 py-0.5 rounded border border-emerald-200">COMPLETADO</span>}

                                        {/* Tags for Upcoming */}
                                        {activeTab === 'upcoming' && item.requiresDowntime && (
                                            <span className="text-[10px] font-bold bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100 flex items-center gap-1" title="Requiere Parada de Máquina">
                                                <Ban size={10} /> PARADA
                                            </span>
                                        )}
                                        {activeTab === 'upcoming' && item.stockStatus !== 'none' && (
                                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border flex items-center gap-1 ${item.stockStatus === 'ok' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-primary-50 text-primary-600 border-primary-100'}`} title={item.stockStatus === 'ok' ? 'Stock Disponible' : item.missingParts.join(', ')}>
                                                <Package size={10} /> {item.stockStatus === 'ok' ? 'STOCK OK' : 'FALTA STOCK'}
                                            </span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-3 text-xs text-slate-500">
                                        <span className="font-medium text-slate-600 flex items-center gap-1"><ChevronRight size={12}/> {item.assetName}</span>
                                        {activeTab === 'upcoming' && (
                                            <>
                                                <span>•</span>
                                                <span>Cada {item.frequency} días</span>
                                                <span>•</span>
                                                <span>{item.hours}h est.</span>
                                            </>
                                        )}
                                        {activeTab === 'history' && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-1">
                                                    <UserIcon size={12}/> 
                                                    {item.technicianName}
                                                </span>
                                            </>
                                        )}
                                    </div>
                                </div>

                                {/* Actions / Labels */}
                                <div className="text-right shrink-0 flex items-center gap-3">
                                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">
                                        {activeTab === 'upcoming' ? item.specialty : item.specialtyRequired}
                                    </span>

                                    {/* Programar Button: Only for Downtime + Parts Required */}
                                    {activeTab === 'upcoming' && canSchedule && (
                                        <button 
                                            onClick={(e) => openScheduleModal(e, item)}
