                        const isOverdue = activeTab === 'upcoming' && new Date(item.date) < new Date(new Date().setHours(0,0,0,0));

                        // New Logic: Only show program button if downtime required AND parts required (stock status not none)
                        const canSchedule = item.requiresDowntime && item.stockStatus !== 'none';

                        return (
                            <div 
                                key={activeTab === 'upcoming' ? item.uniqueId : item.id} 
                                className={`flex items-center gap-4 px-6 py-4 hover:bg-slate-50 transition-colors group ${isSelected ? 'bg-primary-50/40' : ''}`}
                            >
                                {/* Checkbox / Icon */}
                                {activeTab === 'upcoming' ? (
                                    <div 
                                        className={`w-5 h-5 shrink-0 rounded border flex items-center justify-center transition-colors cursor-pointer ${isSelected ? 'bg-primary-600 border-primary-600' : 'border-slate-300 bg-white'}`}
