                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
                    <tr>
                        <th className="px-6 py-4">SKU</th>
                        <th className="px-6 py-4">Descripción</th>
                        <th className="px-6 py-4">Categoría</th>
                        <th className="px-6 py-4 text-right">Costo Ref.</th>
                        <th className="px-6 py-4 text-center">Acciones</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {inventory.map(item => (
                        <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-4 font-mono text-xs font-bold text-slate-600">{item.sku}</td>
                            <td className="px-6 py-4 font-medium text-slate-900">{item.name}</td>
                             <td className="px-6 py-4">
                                <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-slate-100 text-slate-600 border border-slate-200">
                                    {item.category}
                                </span>
                            </td>
                            <td className="px-6 py-4 text-right font-mono text-slate-700">${item.cost.toFixed(2)}</td>
                            <td className="px-6 py-4 text-center">
                                <button className="text-slate-400 hover:text-primary-600 p-1"><Edit2 size={16}/></button>
                            </td>
                        </tr>
                    ))}
                </tbody>
             </table>
        </div>
    </div>
  );

  // --- SUB-COMPONENT: USERS GRID (Unchanged) ---
  const UsersGrid = () => (
    <div className="space-y-4">
         <div className="flex justify-between items-center">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Users size={20} className="text-indigo-600"/> Gestión de Usuarios
            </h3>
            <button className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-indigo-700">
                <Plus size={16}/> Nuevo Usuario
            </button>
        </div>
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
                    <tr>
                        <th className="px-6 py-4">Usuario</th>
                        <th className="px-6 py-4">Rol Asignado</th>
                        <th className="px-6 py-4">Especialidad</th>
                        <th className="px-6 py-4 text-center">Acciones</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {users.map(u => (
                        <tr key={u.id} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-4">
                                <div className="flex items-center gap-3">
                                    <img src={u.avatar} className="w-8 h-8 rounded-full bg-slate-200" alt=""/>
                                    <span className="font-medium text-slate-900">{u.name}</span>
                                </div>
                            </td>
                            <td className="px-6 py-4">
                                 <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-bold uppercase bg-slate-100 text-slate-600 border border-slate-200">
                                    {u.role}
                                </span>
                            </td>
                            <td className="px-6 py-4 text-slate-600">{u.specialty || '-'}</td>
                             <td className="px-6 py-4 text-center">
                                <div className="flex items-center justify-center gap-2">
                                    <button className="text-slate-400 hover:text-primary-600"><Edit2 size={16}/></button>
                                    <button className="text-slate-400 hover:text-red-600"><Trash2 size={16}/></button>
                                </div>
                            </td>
                        </tr>
                    ))}
                </tbody>
             </table>
        </div>
    </div>
  );

  // --- SUB-COMPONENT: ROLES GRID (Unchanged) ---
  const RolesGrid = () => (
     <div className="space-y-4">
         <div className="flex justify-between items-center">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <Shield size={20} className="text-emerald-600"/> Roles y Permisos
            </h3>
        </div>
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
                    <tr>
                        <th className="px-6 py-4">Nombre del Rol</th>
                        <th className="px-6 py-4">Nivel de Acceso</th>
                        <th className="px-6 py-4">Permisos Clave</th>
                        <th className="px-6 py-4 text-center">Usuarios</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {[UserRole.ADMIN, UserRole.PLANNER, UserRole.TECHNICIAN].map(role => (
                        <tr key={role} className="hover:bg-slate-50 transition-colors">
                            <td className="px-6 py-4 font-bold text-slate-900">{role}</td>
                            <td className="px-6 py-4 text-slate-600">
                                {role === 'ADMIN' ? 'Acceso Total' : role === 'PLANNER' ? 'Gestión Operativa' : 'Ejecución Limitada'}
                            </td>
                            <td className="px-6 py-4 text-xs text-slate-500">
                                {role === 'ADMIN' && "Configuración, Usuarios, Compras, Reportes"}
                                {role === 'PLANNER' && "Crear OTs, Planificar, Solicitar Compras"}
                                {role === 'TECHNICIAN' && "Ver Agenda, Completar OTs"}
                            </td>
                            <td className="px-6 py-4 text-center">
                                <span className="bg-slate-100 text-slate-600 px-2 py-1 rounded-full text-xs font-bold">
                                    {users.filter(u => u.role === role).length}
                                </span>
                            </td>
                        </tr>
                    ))}
                </tbody>
             </table>
        </div>
    </div>
  );

  return (
    <div className="max-w-6xl mx-auto pb-10">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-slate-900">Configuración</h2>
        <p className="text-slate-500">Administración de datos maestros del sistema.</p>
      </div>

      {subView === 'machines' && <MachinesGrid />}
      {subView === 'articles' && <ArticlesGrid />}
      {subView === 'users' && <UsersGrid />}
      {subView === 'roles' && <RolesGrid />}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { MaintenancePlan, User, WorkOrder, WorkOrderType, WorkOrderStatus, UserRole, InventoryItem } from '../types';
import { 
    CalendarClock, AlertCircle, Play, CheckSquare, Calendar, ChevronRight, Filter, 
    Search, User as UserIcon, History, BarChart3, TrendingUp, CheckCircle2, AlertTriangle, ArrowRight, Ban, Package, X, Save, ShoppingCart
} from 'lucide-react';

interface PreventiveMaintenanceProps {
  plans: MaintenancePlan[];
  workOrders: WorkOrder[];
  users: User[];
  inventory: InventoryItem[];
  onGenerateOrders: (planIds: string[], technicianId?: string, specificDate?: string) => void;
  onRequestPurchase: (itemId: string, qty: number) => void;
}

interface MissingStockItem {
    itemId: string;
    itemName: string;
    sku: string;
    required: number;
    available: number;
    missing: number;
    affectedPlans: string[]; // Plan Titles
}

export const PreventiveMaintenance: React.FC<PreventiveMaintenanceProps> = ({ 
    plans, workOrders, users, inventory, onGenerateOrders, onRequestPurchase 
}) => {
  const [viewDays, setViewDays] = useState(1); // Default to Today
  const [activeTab, setActiveTab] = useState<'upcoming' | 'history'>('upcoming');
  const [searchQuery, setSearchQuery] = useState('');

  // Selection States
  const [selectedPlanIds, setSelectedPlanIds] = useState<Set<string>>(new Set());
  const [bulkTechnicianId, setBulkTechnicianId] = useState<string>('');

  // Schedule Modal State
  const [scheduleModalOpen, setScheduleModalOpen] = useState(false);
  const [itemToSchedule, setItemToSchedule] = useState<{planId: string, title: string, originalDate: string} | null>(null);
  const [newScheduleDate, setNewScheduleDate] = useState('');

  // Stock Alert Modal State
  const [stockAlertOpen, setStockAlertOpen] = useState(false);
  const [missingStockItems, setMissingStockItems] = useState<MissingStockItem[]>([]);

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);

  // --- LOGIC: KPI CALCULATIONS ---
  const kpis = useMemo(() => {
    let theoreticalCount = 0;
    let realizedCount = 0;
    const machineCompliance: Record<string, { total: number, completed: number, name: string }> = {};

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);
    today.setHours(23,59,59,999);

    if (viewDays === 1) {
        plans.forEach(p => {
            const nextDue = new Date(p.nextDueDate);
            if (nextDue <= today) {
                theoreticalCount++;
                if (!machineCompliance[p.assetId]) {
                    machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
                }
                machineCompliance[p.assetId].total += 1;
            }
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.endTime || wo.dueDate); 
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });

    } else {
        plans.forEach(p => {
            const occurrences = Math.ceil(viewDays / p.frequencyDays);
            theoreticalCount += occurrences;

            if (!machineCompliance[p.assetId]) {
                machineCompliance[p.assetId] = { total: 0, completed: 0, name: p.assetName };
            }
            machineCompliance[p.assetId].total += occurrences;
        });

        workOrders.forEach(wo => {
             const woDate = new Date(wo.dueDate);
             if (wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED && 
                 woDate >= startDate && woDate <= today) {
                 realizedCount++;
                 if (machineCompliance[wo.assetId]) {
                    machineCompliance[wo.assetId].completed += 1;
                 }
             }
        });
    }

    const complianceRate = theoreticalCount > 0 ? Math.round((realizedCount / theoreticalCount) * 100) : 100;

    const machineList = Object.values(machineCompliance)
        .map(m => ({ 
            ...m, 
            rate: m.total > 0 ? Math.round((m.completed / m.total) * 100) : 100 
        }))
        .sort((a, b) => a.rate - b.rate)
        .slice(0, 5); 

    return { theoreticalCount, realizedCount, complianceRate, machineList };
  }, [plans, workOrders, viewDays]);

  // --- LOGIC: STOCK VALIDATION ---

  // 1. Simple check for UI display (list view)
  const checkStockAvailability = (plan: MaintenancePlan) => {
      if (!plan.requiredParts || plan.requiredParts.length === 0) return { status: 'none', details: [] };

      const missingParts: string[] = [];
      let hasEnough = true;

      plan.requiredParts.forEach(part => {
          const invItem = inventory.find(i => i.id === part.itemId);
          if (!invItem || invItem.quantity < part.quantity) {
              hasEnough = false;
              missingParts.push(`${part.itemName} (Faltan ${part.quantity - (invItem?.quantity || 0)})`);
          }
      });

      return { 
          status: hasEnough ? 'ok' : 'missing', 
          details: missingParts 
      };
  };

  // 2. Strict Batch Validation (When Clicking Generate)
  const validateBatchStock = (planIds: string[]) => {
      const consolidatedReqs: Record<string, { required: number, affectedPlans: string[] }> = {};

      // Aggregate requirements
      planIds.forEach(id => {
          const plan = plans.find(p => p.id === id);
          if (plan && plan.requiredParts) {
              plan.requiredParts.forEach(part => {
                  if (!consolidatedReqs[part.itemId]) {
                      consolidatedReqs[part.itemId] = { required: 0, affectedPlans: [] };
                  }
                  consolidatedReqs[part.itemId].required += part.quantity;
                  consolidatedReqs[part.itemId].affectedPlans.push(plan.title);
              });
          }
      });

      const missingItems: MissingStockItem[] = [];

      // Check against inventory
      Object.entries(consolidatedReqs).forEach(([itemId, reqData]) => {
          const invItem = inventory.find(i => i.id === itemId);
          const available = invItem ? invItem.quantity : 0;

          if (available < reqData.required) {
              missingItems.push({
                  itemId,
                  itemName: invItem?.name || 'Desconocido',
                  sku: invItem?.sku || 'N/A',
                  required: reqData.required,
                  available: available,
                  missing: reqData.required - available,
                  affectedPlans: reqData.affectedPlans
              });
          }
      });

      return missingItems;
  };

  // --- LOGIC: GENERATE PROJECTIONS (UPCOMING) ---
  const projections = useMemo(() => {
    if (activeTab !== 'upcoming') return [];

    const items: any[] = [];
    const today = new Date();
    today.setHours(0,0,0,0);
    const endDate = new Date();
    endDate.setDate(today.getDate() + (viewDays === 1 ? 0 : viewDays)); 
    endDate.setHours(23,59,59,999);

    plans.forEach(plan => {
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            if (!plan.title.toLowerCase().includes(query) && !plan.assetName.toLowerCase().includes(query)) {
                return;
            }
        }

        let currentDate = new Date(plan.nextDueDate);
        currentDate.setHours(12,0,0,0); 

        while (currentDate <= endDate) {
            const stockCheck = checkStockAvailability(plan);

            items.push({
                uniqueId: `${plan.id}-${currentDate.toISOString()}`, 
                planId: plan.id,
                date: currentDate.toISOString().split('T')[0],
                rawDate: new Date(currentDate),
                title: plan.title,
                assetName: plan.assetName,
                frequency: plan.frequencyDays,
                specialty: plan.specialtyRequired,
                hours: plan.estimatedHours,
                requiresDowntime: plan.requiresDowntime,
                stockStatus: stockCheck.status,
                missingParts: stockCheck.details
            });

            currentDate.setDate(currentDate.getDate() + plan.frequencyDays);
            if (currentDate > endDate) break;
        }
    });

    return items.sort((a, b) => a.rawDate.getTime() - b.rawDate.getTime());
  }, [plans, viewDays, searchQuery, activeTab, inventory]);

  // --- LOGIC: HISTORY (REALIZED) ---
  const historyItems = useMemo(() => {
    if (activeTab !== 'history') return [];

    const today = new Date();
    const startDate = new Date();
    startDate.setDate(today.getDate() - (viewDays === 1 ? 0 : viewDays));
    startDate.setHours(0,0,0,0);

    return workOrders.filter(wo => {
        const woDate = new Date(wo.dueDate); 
        const matchesDate = woDate >= startDate && woDate <= today;
        const matchesType = wo.type === WorkOrderType.PREVENTIVE && wo.status === WorkOrderStatus.COMPLETED;

        let matchesSearch = true;
        if (searchQuery) {
             const query = searchQuery.toLowerCase();
             matchesSearch = wo.title.toLowerCase().includes(query) || wo.assetName.toLowerCase().includes(query);
        }

        return matchesDate && matchesType && matchesSearch;
    }).sort((a, b) => new Date(b.dueDate).getTime() - new Date(a.dueDate).getTime()); 

  }, [workOrders, viewDays, searchQuery, activeTab]);

  // --- HANDLERS ---
  const toggleSelection = (uniqueId: string, planId: string) => {
    const newSet = new Set(selectedPlanIds);
    if (newSet.has(planId)) newSet.delete(planId);
    else newSet.add(planId);
    setSelectedPlanIds(newSet);
  };

  const handleBulkGenerate = () => {
    if (selectedPlanIds.size === 0) return alert('Selecciona al menos un mantenimiento.');

    // Validate Stock
    const planIds = Array.from(selectedPlanIds) as string[];
    const missing = validateBatchStock(planIds);

    if (missing.length > 0) {
        setMissingStockItems(missing);
        setStockAlertOpen(true);
        return;
    }

    onGenerateOrders(planIds, bulkTechnicianId || undefined);
    setSelectedPlanIds(new Set());
    setBulkTechnicianId('');
  };

  const openScheduleModal = (e: React.MouseEvent, item: any) => {
      e.stopPropagation();
      setItemToSchedule({
          planId: item.planId,
          title: item.title,
          originalDate: item.date
      });
      setNewScheduleDate(item.date);
      setScheduleModalOpen(true);
  };

  const confirmSchedule = () => {
      if (itemToSchedule && newScheduleDate) {
          // Validate Stock for Single Item
          const missing = validateBatchStock([itemToSchedule.planId]);

          if (missing.length > 0) {
              setMissingStockItems(missing);
              setStockAlertOpen(true);
              // Close schedule modal because we are blocked
              setScheduleModalOpen(false); 
              return;
          }

          onGenerateOrders([itemToSchedule.planId], undefined, newScheduleDate);
          setScheduleModalOpen(false);
          setItemToSchedule(null);
      }
  };

  const handleQuickPurchase = (itemId: string, qty: number) => {
      onRequestPurchase(itemId, qty);
      // Optional: Close modal or keep it open to show progress?
      // Keeping it open allows user to request other items.
  };

  // Group projections by Date for better UI
  const groupByDate = (items: any[]) => {
    const groups: Record<string, any[]> = {};
    items.forEach(item => {
        const dateKey = activeTab === 'upcoming' 
            ? item.rawDate.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })
            : new Date(item.dueDate).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' });

        if (!groups[dateKey]) groups[dateKey] = [];
        groups[dateKey].push(item);
    });
    return groups;
  };

  const groupedItems = groupByDate(activeTab === 'upcoming' ? projections : historyItems);

  return (
    <div className="space-y-6">

      {/* --- SECTION 1: KPIS & STATS --- */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="md:col-span-2 bg-slate-900 text-white p-6 rounded-xl shadow-lg relative overflow-hidden">
              <div className="relative z-10 flex justify-between items-end">
                  <div>
                      <h2 className="text-2xl font-bold mb-1">Cumplimiento Global</h2>
                      <p className="text-slate-300 text-sm mb-4">
                          {viewDays === 1 
                            ? 'Ejecución en tiempo real (Hoy)' 
                            : `Promedio histórico (Últimos ${viewDays} días)`}
                      </p>
                      <div className="flex items-end gap-3">
                          <span className="text-5xl font-bold text-emerald-400">{kpis.complianceRate}%</span>
                          <span className="text-sm text-slate-400 mb-2">Tasa de Ejecución</span>
                      </div>
                  </div>
                  <div className="hidden md:block">
                       <div className="flex gap-8 text-right">
                           <div>
                               <div className="text-2xl font-bold">{kpis.theoreticalCount}</div>
                               <div className="text-xs text-slate-400 uppercase">Programados</div>
                           </div>
                           <div>
                               <div className="text-2xl font-bold text-emerald-400">{kpis.realizedCount}</div>
                               <div className="text-xs text-slate-400 uppercase">Realizados</div>
                           </div>
                       </div>
                  </div>
              </div>
              <BarChart3 className="absolute right-[-20px] bottom-[-20px] text-slate-800 opacity-50" size={180} />
          </div>

          <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
               <h3 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
                   <AlertTriangle size={18} className="text-amber-500"/> Alertas por Equipo
               </h3>
               <div className="space-y-3">
                   {kpis.machineList.map((m, idx) => (
                       <div key={idx} className="flex justify-between items-center text-sm">
                           <span className="text-slate-600 truncate max-w-[150px]" title={m.name}>{m.name}</span>
                           <div className="flex items-center gap-2">
                               <div className="w-16 h-1.5 bg-slate-100 rounded-full overflow-hidden">
                                   <div 
                                        className={`h-full rounded-full ${m.rate < 50 ? 'bg-red-500' : m.rate < 80 ? 'bg-amber-500' : 'bg-emerald-500'}`} 
                                        style={{width: `${m.rate}%`}}
                                    ></div>
                               </div>
                               <span className="text-xs font-bold text-slate-700 w-8 text-right">{m.rate}%</span>
                           </div>
                       </div>
                   ))}
                   {kpis.machineList.length === 0 && <p className="text-xs text-slate-400 italic">Datos insuficientes para análisis.</p>}
               </div>
          </div>
      </div>

      {/* --- SECTION 2: TOOLBAR --- */}
      <div className="flex flex-col gap-4">
           {/* Tabs */}
           <div className="flex bg-slate-100 p-1 rounded-lg w-fit">
                <button 
                    onClick={() => setActiveTab('upcoming')}
                    className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'upcoming' ? 'bg-white text-primary-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <CalendarClock size={16}/> Proyección
                </button>
                <button 
                    onClick={() => setActiveTab('history')}
                    className={`px-4 py-2 rounded-md text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'history' ? 'bg-white text-purple-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                    <History size={16}/> Histórico
                </button>
           </div>

           {/* Actions Bar */}
           <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 rounded-xl border border-slate-200 shadow-sm">

                {/* Search & Filters */}
                <div className="flex items-center gap-3 w-full md:w-auto">
                    <div className="relative flex-1 md:w-64">
                        <Search className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                        <input 
                            type="text" 
                            className="w-full pl-9 pr-4 py-2 bg-slate-50 border-none rounded-lg text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                            placeholder="Buscar plan o máquina..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    <div className="flex items-center gap-2 bg-slate-50 rounded-lg p-1 pr-3">
                         <div className="bg-white p-1.5 rounded shadow-sm text-slate-500"><Calendar size={16}/></div>
                         <select 
                            className="bg-transparent text-sm font-medium text-slate-700 outline-none cursor-pointer"
                            value={viewDays}
                            onChange={(e) => setViewDays(Number(e.target.value))}
                         >
                             <option value={1}>Hoy</option>
                             <option value={7}>Esta Semana</option>
                             <option value={15}>15 Días</option>
                             <option value={30}>30 Días</option>
                             <option value={90}>3 Meses</option>
                         </select>
                     </div>
                </div>

                {/* Bulk Actions (Only for Upcoming) */}
                {activeTab === 'upcoming' && (
                    <div className="flex items-center gap-3 w-full md:w-auto justify-end">
                         {selectedPlanIds.size > 0 && (
                             <div className="flex items-center gap-2 animate-in fade-in slide-in-from-right-4">
                                <div className="relative">
                                    <select 
                                        className="appearance-none bg-slate-100 border border-slate-200 text-slate-700 text-sm rounded-lg pl-3 pr-8 py-2 focus:ring-2 focus:ring-primary-500 outline-none cursor-pointer font-medium bg-white"
                                        value={bulkTechnicianId}
                                        onChange={(e) => setBulkTechnicianId(e.target.value)}
                                    >
                                        <option value="">Asignar Técnico (Opcional)</option>
                                        {technicians.map(t => (
                                            <option key={t.id} value={t.id}>{t.name}</option>
                                        ))}
                                    </select>
                                    <UserIcon size={14} className="absolute right-2.5 top-2.5 text-slate-400 pointer-events-none"/>
                                </div>
                                <button 
                                    onClick={handleBulkGenerate}
                                    className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2 rounded-lg font-bold text-sm shadow-md shadow-primary-200 hover:bg-primary-700 transition-all"
                                >
                                    <Play size={16} fill="currentColor" />
                                    Generar {selectedPlanIds.size} OTs
                                </button>
                             </div>
                         )}
                    </div>
                )}
           </div>
      </div>

      {/* --- SECTION 3: LIST VIEW --- */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden min-h-[400px]">
         <div className="p-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between text-xs font-bold text-slate-500 uppercase tracking-wider">
             <div className="flex items-center gap-2">
                <Filter size={14}/>
                <span>{Object.values(groupedItems).flat().length} Registros encontrados</span>
             </div>
             {activeTab === 'upcoming' && <span>Selección Múltiple Activa</span>}
         </div>

         <div className="divide-y divide-slate-100">
            {Object.keys(groupedItems).length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-slate-400">
                    <CalendarClock size={48} className="mb-3 opacity-20"/>
                    <p>No hay mantenimientos en este rango.</p>
                </div>
            )}

            {Object.entries(groupedItems).map(([dateLabel, items]) => (
                <div key={dateLabel}>
                    <div className="bg-slate-50/80 px-6 py-2 border-b border-slate-100 sticky top-0 backdrop-blur-sm z-0">
                        <h3 className="text-xs font-bold text-slate-600 uppercase flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${activeTab === 'upcoming' ? 'bg-primary-400' : 'bg-purple-400'}`}></div>
                            {dateLabel.toUpperCase()}
                        </h3>
                    </div>
                    {items.map((item) => {
                        const isSelected = activeTab === 'upcoming' && selectedPlanIds.has(item.planId);
                        const isOverdue = activeTab === 'upcoming' && new Date(item.date) < new Date(new Date().setHours(0,0,0,0));

                        // New Logic: Only show program button if downtime required AND parts required (stock status not none)
                        const canSchedule = item.requiresDowntime && item.stockStatus !== 'none';

                        return (
                            <div 
                                key={activeTab === 'upcoming' ? item.uniqueId : item.id} 
                                className={`flex items-center gap-4 px-6 py-4 hover:bg-slate-50 transition-colors group ${isSelected ? 'bg-primary-50/40' : ''}`}
                            >
                                {/* Checkbox / Icon */}
                                {activeTab === 'upcoming' ? (
                                    <div 
                                        className={`w-5 h-5 shrink-0 rounded border flex items-center justify-center transition-colors cursor-pointer ${isSelected ? 'bg-primary-600 border-primary-600' : 'border-slate-300 bg-white'}`}
                                        onClick={() => toggleSelection(item.uniqueId, item.planId)}
                                    >
                                        {isSelected && <CheckSquare size={14} className="text-white"/>}
                                    </div>
                                ) : (
                                    <div className="w-5 shrink-0 flex justify-center">
                                        <CheckCircle2 size={18} className="text-emerald-500"/>
                                    </div>
                                )}

                                {/* Main Info */}
                                <div className="flex-1 min-w-0" onClick={() => activeTab === 'upcoming' && toggleSelection(item.uniqueId, item.planId)}>
                                    <div className="flex items-center gap-2 mb-1">
                                        <h4 className={`font-bold truncate ${isSelected ? 'text-primary-700' : 'text-slate-900'}`}>{item.title}</h4>
                                        {isOverdue && <span className="text-[10px] font-bold bg-red-100 text-red-600 px-1.5 py-0.5 rounded border border-red-200">VENCIDO</span>}
                                        {activeTab === 'history' && <span className="text-[10px] font-bold bg-emerald-100 text-emerald-600 px-1.5 py-0.5 rounded border border-emerald-200">COMPLETADO</span>}

                                        {/* Tags for Upcoming */}
                                        {activeTab === 'upcoming' && item.requiresDowntime && (
                                            <span className="text-[10px] font-bold bg-red-50 text-red-600 px-1.5 py-0.5 rounded border border-red-100 flex items-center gap-1" title="Requiere Parada de Máquina">
                                                <Ban size={10} /> PARADA
                                            </span>
                                        )}
                                        {activeTab === 'upcoming' && item.stockStatus !== 'none' && (
                                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded border flex items-center gap-1 ${item.stockStatus === 'ok' ? 'bg-green-50 text-green-600 border-green-100' : 'bg-primary-50 text-primary-600 border-primary-100'}`} title={item.stockStatus === 'ok' ? 'Stock Disponible' : item.missingParts.join(', ')}>
                                                <Package size={10} /> {item.stockStatus === 'ok' ? 'STOCK OK' : 'FALTA STOCK'}
                                            </span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-3 text-xs text-slate-500">
                                        <span className="font-medium text-slate-600 flex items-center gap-1"><ChevronRight size={12}/> {item.assetName}</span>
                                        {activeTab === 'upcoming' && (
                                            <>
                                                <span>•</span>
                                                <span>Cada {item.frequency} días</span>
                                                <span>•</span>
                                                <span>{item.hours}h est.</span>
                                            </>
                                        )}
                                        {activeTab === 'history' && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-1">
                                                    <UserIcon size={12}/> 
                                                    {item.technicianName}
                                                </span>
                                            </>
                                        )}
                                    </div>
                                </div>

                                {/* Actions / Labels */}
                                <div className="text-right shrink-0 flex items-center gap-3">
                                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-slate-100 text-slate-600 border border-slate-200">
                                        {activeTab === 'upcoming' ? item.specialty : item.specialtyRequired}
                                    </span>

                                    {/* Programar Button: Only for Downtime + Parts Required */}
                                    {activeTab === 'upcoming' && canSchedule && (
                                        <button 
                                            onClick={(e) => openScheduleModal(e, item)}
                                            className="hidden group-hover:flex items-center gap-1 bg-white border border-slate-300 text-slate-700 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-slate-50 hover:text-primary-600 transition-all shadow-sm"
                                        >
                                            <Calendar size={14} /> Programar
                                        </button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </tbody>
            </table>
         </div>
      </div>

      {/* SCHEDULE MODAL */}
      {scheduleModalOpen && itemToSchedule && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
            <div className="bg-white rounded-xl w-full max-w-md shadow-2xl p-6">
                <div className="flex justify-between items-start mb-4">
                    <div>
                        <h3 className="font-bold text-slate-800 text-lg">Programar Mantenimiento</h3>
                        <p className="text-xs text-slate-500">{itemToSchedule.title}</p>
                    </div>
                    <button onClick={() => setScheduleModalOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600"/></button>
                </div>

                <div className="bg-blue-50 p-3 rounded-lg border border-blue-100 text-sm text-blue-800 mb-4">
                    <p className="font-bold mb-1">Nota:</p>
                    <p className="text-xs">Al confirmar la fecha acordada, se generará la Orden de Trabajo automáticamente, pisando la fecha teórica proyectada.</p>
                </div>

                <div className="mb-6">
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Fecha Acordada de Ejecución</label>
                    <input 
                        type="date" 
                        className="w-full border border-slate-300 rounded-lg px-4 py-3 text-slate-900 font-bold focus:ring-2 focus:ring-primary-500 outline-none bg-white"
                        value={newScheduleDate}
                        onChange={(e) => setNewScheduleDate(e.target.value)}
                    />
                </div>

                <div className="flex gap-3">
                    <button 
                        onClick={() => setScheduleModalOpen(false)}
                        className="flex-1 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg"
                    >
                        Cancelar
                    </button>
                    <button 
                        onClick={confirmSchedule}
                        className="flex-1 bg-primary-600 text-white py-2 rounded-lg font-bold hover:bg-primary-700 flex items-center justify-center gap-2"
                    >
                        <Save size={16}/> Confirmar
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* STOCK ALERT MODAL (BLOCKING) */}
      {stockAlertOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm animate-in fade-in zoom-in-95 duration-200">
              <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl flex flex-col max-h-[90vh]">
                  <div className="p-5 border-b border-red-100 bg-red-50 rounded-t-xl flex items-center gap-3">
                      <div className="bg-red-100 p-2 rounded-full text-red-600">
                          <AlertCircle size={24} />
                      </div>
                      <div>
                          <h3 className="text-lg font-bold text-red-700">Stock Insuficiente</h3>
                          <p className="text-xs text-red-500">No se pueden generar las órdenes de trabajo.</p>
                      </div>
                  </div>

                  <div className="p-6 overflow-y-auto">
                      <p className="text-sm text-slate-600 mb-4">
                          Los siguientes repuestos no tienen existencias suficientes para cubrir los mantenimientos seleccionados:
                      </p>

                      <div className="space-y-3">
                          {missingStockItems.map((item, idx) => (
                              <div key={idx} className="border border-slate-200 rounded-lg p-3 bg-slate-50">
                                  <div className="flex justify-between items-start mb-2">
                                      <div>
                                          <p className="font-bold text-slate-800">{item.itemName}</p>
                                          <p className="text-xs text-slate-400 font-mono">{item.sku}</p>
                                      </div>
                                      <div className="text-right">
                                          <span className="block text-xs text-slate-500">Faltante</span>
                                          <span className="font-bold text-red-600 text-lg">-{item.missing}</span>
                                      </div>
                                  </div>

                                  {/* Quick Actions */}
                                  <div className="mt-3 pt-3 border-t border-slate-200 flex items-center justify-between">
                                      <div className="text-xs text-slate-500">
                                          Req: <strong>{item.required}</strong> | Disp: <strong>{item.available}</strong>
                                      </div>
                                      <button 
                                          onClick={() => handleQuickPurchase(item.itemId, item.missing)}
                                          className="flex items-center gap-1 text-xs font-bold bg-blue-600 text-white px-3 py-1.5 rounded hover:bg-blue-700 transition-colors"
                                      >
                                          <ShoppingCart size={12} /> Solicitar Compra
                                      </button>
                                  </div>
                              </div>
                          ))}
                      </div>
                  </div>

                  <div className="p-4 bg-slate-50 border-t border-slate-100 rounded-b-xl text-right">
                      <button 
                          onClick={() => setStockAlertOpen(false)}
                          className="bg-slate-800 text-white px-6 py-2 rounded-lg font-bold text-sm hover:bg-slate-900"
                      >
                          Entendido, cerrar
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { User, UserRole, Asset, InventoryItem, TaskTemplate, MaintenancePlan, PlanPart } from '../types';
import { 
  Users, Shield, Cpu, Box, Plus, Edit2, Trash2, Search, FileText, AlertTriangle, X, Image as ImageIcon, BookOpen, Download, ClipboardList, CheckSquare, Save, Clock, Calendar, ArrowRight, Eye, MoreHorizontal, ChevronDown, CalendarClock, Ban, Package
} from 'lucide-react';

interface ConfigurationProps {
  currentView: string;
  users: User[];
  assets: Asset[];
  inventory: InventoryItem[];
  taskTemplates: TaskTemplate[];
  // Props for Preventive Management inside Asset
  maintenancePlans: MaintenancePlan[];
  onCreatePlan: (plan: MaintenancePlan) => void;
  onDeletePlan: (planId: string) => void;
}

export const Configuration: React.FC<ConfigurationProps> = ({ 
    currentView, users, assets, inventory, taskTemplates, maintenancePlans, onCreatePlan, onDeletePlan 
}) => {
  const subView = currentView.replace('config-', '');

  // --- SUB-COMPONENT: MACHINES GRID & DETAIL VIEW ---
  const MachinesGrid = () => {
    const [selectedAsset, setSelectedAsset] = useState<Asset | null>(null);
    const [viewMode, setViewMode] = useState<'list' | 'detail'>('list');

    // States for "Create Plan" inside Detail View
    const [isPlanModalOpen, setIsPlanModalOpen] = useState(false);
    const [newPlan, setNewPlan] = useState<Partial<MaintenancePlan>>({
        frequencyDays: 30,
        estimatedHours: 1,
        specialtyRequired: 'Mecánica',
        checklistTemplate: [],
        requiresDowntime: false,
        requiredParts: []
    });
    const [tempTask, setTempTask] = useState('');

    // States for Parts Selector inside Modal
    const [selectedPartId, setSelectedPartId] = useState('');
    const [partQty, setPartQty] = useState(1);

    const openDetail = (asset: Asset) => {
        setSelectedAsset(asset);
        setViewMode('detail');
    };

    const closeDetail = () => {
        setSelectedAsset(null);
        setViewMode('list');
    };

    // Plan Management Logic
    const handleAddPlan = () => {
        if (!selectedAsset || !newPlan.title || !newPlan.frequencyDays) return alert("Faltan datos obligatorios.");

        const plan: MaintenancePlan = {
            id: `mp-${Date.now()}`,
            assetId: selectedAsset.id,
            assetName: selectedAsset.name,
            title: newPlan.title,
            frequencyDays: Number(newPlan.frequencyDays),
            nextDueDate: new Date(Date.now() + 86400000).toISOString().split('T')[0], // Default tomorrow
            estimatedHours: Number(newPlan.estimatedHours),
            specialtyRequired: newPlan.specialtyRequired || 'Mecánica',
            checklistTemplate: newPlan.checklistTemplate || [],
            requiresDowntime: newPlan.requiresDowntime,
            requiredParts: newPlan.requiredParts
        };

        onCreatePlan(plan);
        setIsPlanModalOpen(false);
        setNewPlan({ frequencyDays: 30, estimatedHours: 1, specialtyRequired: 'Mecánica', checklistTemplate: [], requiresDowntime: false, requiredParts: [] });
    };

    const handleLoadTemplate = (tplId: string) => {
        const tpl = taskTemplates.find(t => t.id === tplId);
        if (tpl) {
            setNewPlan(prev => ({
                ...prev,
                title: prev.title || tpl.title,
                checklistTemplate: tpl.tasks,
                estimatedHours: tpl.estimatedHours,
                specialtyRequired: tpl.specialty,
                frequencyDays: tpl.frequencyDays
            }));
        }
    };

    const addTask = () => {
        if (tempTask.trim()) {
            setNewPlan(prev => ({ ...prev, checklistTemplate: [...(prev.checklistTemplate || []), tempTask.trim()] }));
            setTempTask('');
        }
    };

    const addPart = () => {
        if (selectedPartId && partQty > 0) {
            const item = inventory.find(i => i.id === selectedPartId);
            if (item) {
                const newPart: PlanPart = {
                    itemId: item.id,
                    itemName: item.name,
                    quantity: partQty
                };
                setNewPlan(prev => ({
                    ...prev,
                    requiredParts: [...(prev.requiredParts || []), newPart]
                }));
                setSelectedPartId('');
                setPartQty(1);
            }
        }
    };

    const removePart = (idx: number) => {
        setNewPlan(prev => ({
            ...prev,
            requiredParts: prev.requiredParts?.filter((_, i) => i !== idx)
        }));
    };

    // Render List Mode
    if (viewMode === 'list') {
        return (
            <div className="space-y-4">
                <div className="flex justify-between items-center">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                        <Cpu size={20} className="text-primary-600"/> Gestión de Máquinas (Activos)
                    </h3>
                    <button className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-primary-700">
                        <Plus size={16}/> Nuevo Máquina
                    </button>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
                            <tr>
                                <th className="px-6 py-4">Máquina</th>
                                <th className="px-6 py-4">Sector / Ubicación</th>
                                <th className="px-6 py-4">N° Serie</th>
                                <th className="px-6 py-4 text-center">Planes Prev.</th>
                                <th className="px-6 py-4 text-center">Estado</th>
                                <th className="px-6 py-4 text-center">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {assets.map(asset => {
                                const assetPlans = maintenancePlans.filter(p => p.assetId === asset.id);
                                return (
                                    <tr key={asset.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => openDetail(asset)}>
                                        <td className="px-6 py-4 font-medium text-slate-900 flex items-center gap-2">
                                            <div className="p-2 bg-slate-100 rounded-lg text-slate-500 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                                                <Cpu size={18} />
                                            </div>
                                            {asset.name}
                                        </td>
                                        <td className="px-6 py-4 text-slate-600">
                                            <div className="font-medium text-slate-800">{asset.sector || 'N/A'}</div>
                                            <div className="text-xs text-slate-400">{asset.location}</div>
                                        </td>
                                        <td className="px-6 py-4 font-mono text-xs text-slate-500">{asset.serialNumber || '-'}</td>
                                        <td className="px-6 py-4 text-center">
                                            {assetPlans.length > 0 ? (
                                                <span className="inline-flex items-center gap-1 bg-teal-50 text-teal-700 px-2 py-1 rounded-full text-xs font-bold border border-teal-100">
                                                    <ClipboardList size={12}/> {assetPlans.length} Activos
                                                </span>
                                            ) : (
                                                <span className="text-slate-400 text-xs">-</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${asset.status === 'OPERATIONAL' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {asset.status === 'OPERATIONAL' ? 'OPERATIVO' : 'PARADA'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); openDetail(asset); }}
                                                className="text-primary-600 hover:text-primary-800 font-medium text-xs flex items-center justify-center gap-1 bg-primary-50 px-3 py-1.5 rounded-lg hover:bg-primary-100 transition-colors"
                                            >
                                                <Eye size={14}/> Ficha Técnica
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    }

    // Render Detail Mode
    if (viewMode === 'detail' && selectedAsset) {
        const assetPlans = maintenancePlans.filter(p => p.assetId === selectedAsset.id);

        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                {/* Breadcrumb / Header */}
                <div className="flex items-center gap-4 border-b border-slate-200 pb-4">
                    <button onClick={closeDetail} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-500">
                        <ArrowRight size={20} className="rotate-180" />
                    </button>
                    <div>
                        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                            {selectedAsset.name}
                            <span className={`text-xs px-2 py-0.5 rounded-full border ${selectedAsset.status === 'OPERATIONAL' ? 'bg-green-50 border-green-200 text-green-700' : 'bg-red-50 border-red-200 text-red-700'}`}>
                                {selectedAsset.status}
                            </span>
                        </h2>
                        <p className="text-sm text-slate-500 flex items-center gap-2">
                            <span className="font-mono">{selectedAsset.serialNumber}</span> • {selectedAsset.sector} • {selectedAsset.location}
                        </p>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column: General Info & Docs */}
                    <div className="space-y-6">
                        <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                            <h4 className="text-sm font-bold text-slate-800 uppercase mb-4 flex items-center gap-2">
                                <BookOpen size={16} className="text-primary-500"/> Documentación
                            </h4>
                            <div className="space-y-3">
                                <div className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-white rounded border border-slate-200 text-red-500"><FileText size={20}/></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">Manual de Usuario</p>
                                            <p className="text-xs text-slate-400">PDF • 2.4 MB</p>
                                        </div>
                                    </div>
                                    <button className="text-primary-600 hover:text-primary-800"><Download size={18}/></button>
                                </div>
                                <div className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-white rounded border border-slate-200 text-primary-500"><FileText size={20}/></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">Diagrama Eléctrico</p>
                                            <p className="text-xs text-slate-400">PDF • 5.1 MB</p>
                                        </div>
                                    </div>
                                    <button className="text-primary-600 hover:text-primary-800"><Download size={18}/></button>
                                </div>
                            </div>
                        </div>

                        <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                             <h4 className="text-sm font-bold text-slate-800 uppercase mb-4 flex items-center gap-2">
                                <AlertTriangle size={16} className="text-orange-500"/> Historial de Fallas
                            </h4>
                            {(!selectedAsset.frequentFailures || selectedAsset.frequentFailures.length === 0) ? (
                                <p className="text-sm text-slate-400 italic">No hay fallas reportadas.</p>
                            ) : (
                                <ul className="space-y-3">
                                    {selectedAsset.frequentFailures.map(fail => (
                                        <li key={fail.id} className="text-sm text-slate-600 border-l-2 border-orange-300 pl-3">
                                            <span className="font-bold text-slate-800 block">{fail.title}</span>
                                            {fail.description}
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    </div>

                    {/* Right Column: Maintenance Strategy (Preventive Plans) */}
                    <div className="lg:col-span-2">
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
                            <div className="p-5 border-b border-slate-200 flex justify-between items-center bg-slate-50/50">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                        <CalendarClock size={20} className="text-teal-600"/> Estrategia de Mantenimiento
                                    </h3>
                                    <p className="text-sm text-slate-500">Planes preventivos recurrentes asignados a este equipo.</p>
                                </div>
                                <button 
                                    onClick={() => setIsPlanModalOpen(true)}
                                    className="bg-teal-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-teal-700 transition-colors flex items-center gap-2 shadow-sm"
                                >
                                    <Plus size={16}/> Agregar Plan
                                </button>
                            </div>

                            <div className="p-5 flex-1 overflow-y-auto bg-slate-50">
                                {assetPlans.length === 0 ? (
                                    <div className="h-40 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-white">
