           {/* Actions Bar */}
           <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white p-3 rounded-xl border border-slate-200 shadow-sm">

                {/* Search & Filters */}
                <div className="flex items-center gap-3 w-full md:w-auto">
