                                        <p className="text-sm font-bold text-indigo-900">¿Usar una plantilla estándar?</p>
                                        <p className="text-xs text-indigo-600">Carga tareas y frecuencias predefinidas.</p>
                                    </div>
                                    <div className="relative">
                                         <select 
                                            className="pl-3 pr-8 py-2 bg-white border border-indigo-200 text-indigo-700 text-xs font-bold rounded-lg cursor-pointer focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm hover:border-indigo-300 appearance-none"
                                            onChange={(e) => handleLoadTemplate(e.target.value)}
                                            defaultValue=""
                                         >
                                            <option value="" disabled>📥 Importar Plantilla</option>
                                            {taskTemplates.map(t => (
                                                <option key={t.id} value={t.id}>{t.title}</option>
