    // Derived States for "Smart Catalog" Logic
    const availableModels = newMachine.category ? ASSET_MODEL_CATALOG[newMachine.category] : [];
    const selectedModelData = availableModels?.find(m => m.name === newMachine.model);

    const openDetail = (asset: Asset) => {
