    const addTask = () => {
        if (tempTask.trim()) {
            setNewPlan(prev => ({ ...prev, checklistTemplate: [...(prev.checklistTemplate || []), tempTask.trim()] }));
            setTempTask('');
        }
    };

    const addPart = () => {
        if (selectedPartId && partQty > 0) {
            const item = inventory.find(i => i.id === selectedPartId);
            if (item) {
                const newPart: PlanPart = {
                    itemId: item.id,
                    itemName: item.name,
                    quantity: partQty
                };
                setNewPlan(prev => ({
                    ...prev,
                    requiredParts: [...(prev.requiredParts || []), newPart]
                }));
                setSelectedPartId('');
                setPartQty(1);
            }
        }
    };

    const removePart = (idx: number) => {
        setNewPlan(prev => ({
            ...prev,
            requiredParts: prev.requiredParts?.filter((_, i) => i !== idx)
        }));
    };

    // Render List Mode
    if (viewMode === 'list') {
        return (
            <div className="space-y-4">
                <div className="flex justify-between items-center">
                    <div>
                        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                            <Cpu size={24} className="text-primary-600"/> Gestión de Activos
                        </h2>
                        <p className="text-slate-500 text-sm">Inventario de maquinaria y equipos.</p>
                    </div>
                    <button 
                        onClick={() => setIsAddMachineOpen(true)}
                        className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-primary-700"
                    >
                        <Plus size={16}/> Nuevo Máquina
                    </button>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
                            <tr>
                                <th className="px-6 py-4">Máquina</th>
                                <th className="px-6 py-4">Modelo / Tipo</th>
                                <th className="px-6 py-4">Sector / Ubicación</th>
                                <th className="px-6 py-4">N° Serie</th>
                                <th className="px-6 py-4 text-center">Planes Prev.</th>
                                <th className="px-6 py-4 text-center">Estado</th>
                                <th className="px-6 py-4 text-center">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {assets.map(asset => {
                                const assetPlans = maintenancePlans.filter(p => p.assetId === asset.id);
                                return (
                                    <tr key={asset.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => openDetail(asset)}>
                                        <td className="px-6 py-4 font-medium text-slate-900 flex items-center gap-2">
                                            <div className="p-2 bg-slate-100 rounded-lg text-slate-500 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                                                <Cpu size={18} />
                                            </div>
                                            {asset.name}
                                        </td>
                                        <td className="px-6 py-4">
                                            {asset.model ? (
                                                <div>
                                                    <div className="font-bold text-slate-700">{asset.model}</div>
                                                    <div className="text-xs text-slate-400">{asset.category}</div>
                                                </div>
                                            ) : (
                                                <span className="text-slate-400 text-xs italic">Genérico</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-slate-600">
                                            <div className="font-medium text-slate-800">{asset.sector || 'N/A'}</div>
                                            <div className="text-xs text-slate-400">{asset.location}</div>
                                        </td>
                                        <td className="px-6 py-4 font-mono text-xs text-slate-500">{asset.serialNumber || '-'}</td>
                                        <td className="px-6 py-4 text-center">
                                            {assetPlans.length > 0 ? (
                                                <span className="inline-flex items-center gap-1 bg-teal-50 text-teal-700 px-2 py-1 rounded-full text-xs font-bold border border-teal-100">
                                                    <ClipboardList size={12}/> {assetPlans.length} Activos
                                                </span>
                                            ) : (
                                                <span className="text-slate-400 text-xs">-</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${asset.status === 'OPERATIONAL' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {asset.status === 'OPERATIONAL' ? 'OPERATIVO' : 'PARADA'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); openDetail(asset); }}
                                                className="text-primary-600 hover:text-primary-800 font-medium text-xs flex items-center justify-center gap-1 bg-primary-50 px-3 py-1.5 rounded-lg hover:bg-primary-100 transition-colors"
                                            >
                                                <Eye size={14}/> Ficha Técnica
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                {/* MODAL: NEW MACHINE */}
                {isAddMachineOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in zoom-in-95 duration-200">
                        <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl flex flex-col max-h-[90vh]">
                            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                                <div>
                                    <h3 className="font-bold text-slate-800">Alta de Nueva Máquina</h3>
                                    <p className="text-xs text-slate-500">Registrar un nuevo activo en el sistema.</p>
                                </div>
                                <button onClick={() => setIsAddMachineOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600"/></button>
                            </div>

                            <div className="p-6 space-y-4 overflow-y-auto">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nombre del Equipo <span className="text-red-500">*</span></label>
                                    <input 
                                        type="text" 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                                        placeholder="Ej. Compresor de Tornillo #2"
                                        value={newMachine.name || ''}
                                        onChange={e => setNewMachine({...newMachine, name: e.target.value})}
                                    />
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoría (Tipo)</label>
                                        <select 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white"
                                            value={newMachine.category || ''}
                                            onChange={e => setNewMachine({...newMachine, category: e.target.value, model: ''})}
                                        >
                                            <option value="">Seleccionar Tipo...</option>
                                            {categories.map(cat => (
                                                <option key={cat} value={cat}>{cat}</option>
                                            ))}
                                        </select>
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Modelo Específico</label>
                                        <select 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white disabled:bg-slate-100 disabled:text-slate-400"
                                            value={newMachine.model || ''}
                                            onChange={e => setNewMachine({...newMachine, model: e.target.value})}
                                            disabled={!newMachine.category}
                                        >
                                            <option value="">Seleccionar Modelo...</option>
                                            {availableModels?.map(m => (
                                                <option key={m.id} value={m.name}>{m.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                {/* SMART PREVIEW */}
                                {selectedModelData && (
                                    <div className="bg-indigo-50 border border-indigo-100 rounded-lg p-3 flex items-start gap-3 animate-in fade-in zoom-in-95 duration-200">
                                        <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg shrink-0">
                                            <Sparkles size={20} />
                                        </div>
                                        <div>
                                            <h4 className="text-sm font-bold text-indigo-900 flex items-center gap-2">
                                                Configuración Automática Detectada
                                            </h4>
                                            <p className="text-xs text-indigo-700 mt-1">
                                                Al crear este equipo, se importarán automáticamente:
                                            </p>
                                            <ul className="mt-2 space-y-1 text-xs text-indigo-800">
                                                <li className="flex items-center gap-1"><CheckSquare size={12}/> {selectedModelData.standardPlans.length} Planes Preventivos Recomendados</li>
                                                <li className="flex items-center gap-1"><BookOpen size={12}/> Manual de Usuario Oficial</li>
                                                <li className="flex items-center gap-1"><AlertTriangle size={12}/> Base de Fallas Comunes</li>
                                            </ul>
                                        </div>
                                    </div>
                                )}

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Sector / Área</label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                                            placeholder="Ej. Sala de Máquinas"
                                            value={newMachine.sector || ''}
                                            onChange={e => setNewMachine({...newMachine, sector: e.target.value})}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Ubicación Física <span className="text-red-500">*</span></label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none"
                                            placeholder="Ej. Nave Industrial B"
                                            value={newMachine.location || ''}
                                            onChange={e => setNewMachine({...newMachine, location: e.target.value})}
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Número de Serie</label>
                                    <input 
                                        type="text" 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none font-mono"
                                        placeholder="S/N-12345-XYZ"
                                        value={newMachine.serialNumber || ''}
                                        onChange={e => setNewMachine({...newMachine, serialNumber: e.target.value})}
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Estado Inicial</label>
                                    <select 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white"
                                        value={newMachine.status}
                                        onChange={e => setNewMachine({...newMachine, status: e.target.value as any})}
                                    >
                                        <option value="OPERATIONAL">OPERATIVO</option>
                                        <option value="DOWN">PARADA (Fuera de Servicio)</option>
                                    </select>
                                </div>
                            </div>

                            <div className="p-5 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 rounded-b-xl">
                                <button onClick={() => setIsAddMachineOpen(false)} className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-200 rounded-lg">Cancelar</button>
                                <button 
                                    onClick={handleCreateMachine}
                                    className="bg-primary-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-primary-700 shadow-sm flex items-center gap-2"
                                >
                                    <Save size={18}/> Crear Máquina
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    // Render Detail Mode
    if (viewMode === 'detail' && selectedAsset) {
        const assetPlans = maintenancePlans.filter(p => p.assetId === selectedAsset.id);

        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                {/* Breadcrumb / Header */}
                <div className="flex items-center gap-4 border-b border-slate-200 pb-4">
                    <button onClick={closeDetail} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-500">
                        <ArrowRight size={20} className="rotate-180" />
                    </button>
                    <div>
                        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                            {selectedAsset.name}
                            <span className={`text-xs px-2 py-0.5 rounded-full border ${selectedAsset.status === 'OPERATIONAL' ? 'bg-green-50 border-green-200 text-green-700' : 'bg-red-50 border-red-200 text-red-700'}`}>
                                {selectedAsset.status}
                            </span>
                        </h2>
                        <div className="flex items-center gap-3 text-sm text-slate-500 mt-1">
                            <span className="font-mono bg-slate-100 px-1.5 rounded">{selectedAsset.serialNumber}</span>
                            <span>•</span>
                            <span>{selectedAsset.category}</span>
                            <span>•</span>
                            <span className="font-bold text-slate-700">{selectedAsset.model || 'Modelo Genérico'}</span>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column: General Info & Docs */}
                    <div className="space-y-6">
                        {selectedAsset.imageUrl && (
                            <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-200">
                                <img src={selectedAsset.imageUrl} alt={selectedAsset.name} className="w-full h-48 object-cover rounded-lg" />
                            </div>
                        )}

                        <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                            <h4 className="text-sm font-bold text-slate-800 uppercase mb-4 flex items-center gap-2">
                                <BookOpen size={16} className="text-primary-500"/> Documentación
                            </h4>
                            <div className="space-y-3">
                                {selectedAsset.manualUrl && selectedAsset.manualUrl !== '#' && (
                                    <div className="flex items-center justify-between p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                                        <div className="flex items-center gap-3">
                                            <div className="p-2 bg-white rounded border border-indigo-200 text-indigo-500"><FileText size={20}/></div>
                                            <div>
                                                <p className="text-sm font-bold text-indigo-900">Manual de Fabricante</p>
                                                <p className="text-xs text-indigo-600">Oficial • PDF</p>
                                            </div>
                                        </div>
                                        <button className="text-indigo-600 hover:text-indigo-800"><Download size={18}/></button>
                                    </div>
                                )}
                                <div className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-white rounded border border-slate-200 text-slate-500"><FileText size={20}/></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">Diagrama Eléctrico</p>
                                            <p className="text-xs text-slate-400">PDF • 5.1 MB</p>
                                        </div>
                                    </div>
                                    <button className="text-slate-600 hover:text-slate-800"><Download size={18}/></button>
                                </div>
                            </div>
                        </div>

                        <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                             <h4 className="text-sm font-bold text-slate-800 uppercase mb-4 flex items-center gap-2">
                                <AlertTriangle size={16} className="text-orange-500"/> Historial de Fallas
                            </h4>
                            {(!selectedAsset.frequentFailures || selectedAsset.frequentFailures.length === 0) ? (
                                <p className="text-sm text-slate-400 italic">No hay fallas reportadas.</p>
                            ) : (
                                <ul className="space-y-3">
                                    {selectedAsset.frequentFailures.map(fail => (
                                        <li key={fail.id} className="text-sm text-slate-600 border-l-2 border-orange-300 pl-3">
                                            <span className="font-bold text-slate-800 block">{fail.title}</span>
                                            {fail.description}
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    </div>

                    {/* Right Column: Maintenance Strategy (Preventive Plans) */}
                    <div className="lg:col-span-2">
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
                            <div className="p-5 border-b border-slate-200 flex justify-between items-center bg-slate-50/50">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                        <CalendarClock size={20} className="text-teal-600"/> Estrategia de Mantenimiento
                                    </h3>
                                    <p className="text-sm text-slate-500">Planes preventivos recurrentes asignados a este equipo.</p>
                                </div>
                                <button 
                                    onClick={() => setIsPlanModalOpen(true)}
                                    className="bg-teal-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-teal-700 transition-colors flex items-center gap-2 shadow-sm"
                                >
                                    <Plus size={16}/> Agregar Plan
                                </button>
                            </div>

                            <div className="p-5 flex-1 overflow-y-auto bg-slate-50">
                                {assetPlans.length === 0 ? (
                                    <div className="h-40 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-white">
                                        <ClipboardList size={32} className="mb-2 opacity-50"/>
                                        <p className="text-sm font-medium">Este equipo no tiene planes preventivos.</p>
                                        <p className="text-xs">Agrega uno para automatizar la generación de OTs.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {assetPlans.map(plan => (
                                            <div key={plan.id} className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm hover:shadow-md transition-shadow">
                                                <div className="flex justify-between items-start mb-3">
                                                    <div>
                                                        <div className="flex items-center gap-2 mb-1">
                                                             <h4 className="text-base font-bold text-slate-900">{plan.title}</h4>
                                                             {plan.requiresDowntime && (
                                                                 <span className="bg-red-100 text-red-600 text-[10px] font-bold px-1.5 py-0.5 rounded border border-red-200 flex items-center gap-1">
                                                                     <Ban size={10} /> PARADA
                                                                 </span>
                                                             )}
                                                             {plan.requiredParts && plan.requiredParts.length > 0 && (
                                                                 <span className="bg-primary-100 text-primary-600 text-[10px] font-bold px-1.5 py-0.5 rounded border border-primary-200 flex items-center gap-1">
                                                                     <Package size={10} /> REPUESTOS
                                                                 </span>
                                                             )}
                                                        </div>
                                                        <div className="flex items-center gap-3 mt-1 text-sm text-slate-500">
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Calendar size={12}/> Cada {plan.frequencyDays} días</span>
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Clock size={12}/> {plan.estimatedHours}h Est.</span>
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Cpu size={12}/> {plan.specialtyRequired}</span>
                                                        </div>
                                                    </div>
                                                    <button 
                                                        onClick={() => {
                                                            if(confirm('¿Eliminar este plan?')) onDeletePlan(plan.id);
                                                        }}
                                                        className="text-slate-400 hover:text-red-500 p-2 hover:bg-red-50 rounded transition-colors"
                                                    >
                                                        <Trash2 size={16}/>
                                                    </button>
                                                </div>

                                                <div className="bg-slate-50 rounded-lg p-3 border border-slate-100">
                                                    <p className="text-xs font-bold text-slate-400 uppercase mb-2">Tareas ({plan.checklistTemplate.length})</p>
                                                    <div className="space-y-1">
                                                        {plan.checklistTemplate.slice(0, 3).map((task, i) => (
                                                            <div key={i} className="flex items-start gap-2 text-sm text-slate-600">
                                                                <CheckSquare size={14} className="mt-0.5 text-teal-500 shrink-0"/>
                                                                <span className="truncate">{task}</span>
                                                            </div>
                                                        ))}
                                                        {plan.checklistTemplate.length > 3 && (
                                                            <p className="text-xs text-slate-400 pl-6 italic">+ {plan.checklistTemplate.length - 3} tareas más...</p>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }
    return null;
}

// Enums
export enum UserRole {
  ADMIN = 'ADMIN',
  PLANNER = 'PLANNER',
  TECHNICIAN = 'TECHNICIAN'
}

export enum WorkOrderStatus {
  PENDING = 'PENDING',
  IN_PROGRESS = 'IN_PROGRESS',
  COMPLETED = 'COMPLETED',
  BLOCKED = 'BLOCKED'
}

export enum WorkOrderType {
  CORRECTIVE = 'CORRECTIVE',
  PREVENTIVE = 'PREVENTIVE'
}

export enum Priority {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL'
}

export enum PurchaseRequestStatus {
  PENDING_APPROVAL = 'PENDING_APPROVAL', // Creada, espera a Jefatura
  APPROVED = 'APPROVED',         // Aprobada por Jefatura, espera a Compras
  REJECTED = 'REJECTED',         // Rechazada
  PURCHASED = 'PURCHASED',       // Compras asignó proveedor y generó OC
  PARTIALLY_RECEIVED = 'PARTIALLY_RECEIVED', // Llegó parte de la mercadería
  COMPLETED = 'COMPLETED'        // Se recibió el 100% o se cerró manual
}

// Interfaces
export interface User {
  id: string;
  name: string;
  role: UserRole;
  specialty?: string; // For technicians e.g., 'Electricidad', 'Mecánica'
  avatar: string;
}

export interface FrequentFailure {
  id: string;
  title: string;
  description: string;
  imageUrl?: string; // URL to photo
}

export interface Asset {
  id: string;
  name: string;
  location: string;
  sector?: string;        // New: Sector/Area
  brand?: string;         // New: Brand (e.g., 'Girbau')
  category?: string;      // New: Machine Type (e.g., 'Túnel de Lavado')
  model?: string;         // New: Specific Model (e.g., 'PowerTrans 50kg')
  serialNumber?: string;  // New: S/N
  manualUrl?: string;     // New: Link to PDF
  imageUrl?: string;      // New: Photo of the machine
  frequentFailures?: FrequentFailure[]; // New: Knowledge Base
  status: 'OPERATIONAL' | 'DOWN';
}

export interface InventoryItem {
  id: string;
  name: string;
  sku: string;
  quantity: number;
  minStock: number;
  cost: number;
  category: string;
}

export interface ReceptionEntry {
  id: string;
  date: string;
  quantity: number;
  remito: string;
  receivedBy: string;
}

export interface PurchaseRequest {
  id: string;
  itemId: string;
  itemName: string;
  requestedBy: string;
  date: string; // Creation date
  status: PurchaseRequestStatus;

  // Quantities
  originalQuantity: number; // What was asked
  approvedQuantity: number; // What boss approved
  receivedQuantity: number; // Running total of reception

  // Financial & Provider
  estimatedCost: number;
  provider?: string;
  orderDate?: string; // When status changed to PURCHASED

  // History
  receptionLog?: ReceptionEntry[];
}

export interface ChecklistTask {
  id: string;
  description: string;
  completed: boolean;
}

// Nueva Interfaz para Plantillas de Protocolos
export interface TaskTemplate {
  id: string;
  title: string;
  description: string; // Breve descripción para el planner
  specialty: string;
  estimatedHours: number;
  frequencyDays: number; // Frecuencia sugerida por defecto
  tasks: string[];
}

// Plan Parts Requirement
export interface PlanPart {
  itemId: string;
  itemName: string; // Denormalized for display
  quantity: number;
}

export interface MaintenancePlan {
  id: string;
  title: string;
  assetId: string;
  assetName: string;
  frequencyDays: number;
  nextDueDate: string; // ISO Date
  estimatedHours: number;
  specialtyRequired: string;
  checklistTemplate: string[]; // Simple array of strings for the template

  // New Fields for Advanced Planning
  requiresDowntime?: boolean;
  requiredParts?: PlanPart[];
}

export interface WorkOrder {
  id: string;
  title: string;
  description: string;
  assetId: string;
  assetName: string;
  assignedTechnicianId?: string;
  technicianName?: string;
  type: WorkOrderType;
  priority: Priority;
  status: WorkOrderStatus;
  dueDate: string;
  specialtyRequired: string;

  // Link to Plan
  planId?: string; 

  // Execution Data
  checklist?: ChecklistTask[];
  startTime?: string;
  endTime?: string;
  completionComment?: string;
  evidenceImageUrl?: string;
}

// Smart Catalog Interface
export interface CatalogModel {
    id: string;
    brand: string; // Brand (e.g., Girbau)
    category: string; // Category (e.g., Tunnel Washer)
    name: string; // Model Name
    description: string;
    manualUrl: string;
    imageUrl: string; 
    standardPlans: Partial<MaintenancePlan>[];
    commonFailures: FrequentFailure[];
}

import React, { useState, useEffect } from 'react';
import { User, Asset, InventoryItem, TaskTemplate, MaintenancePlan, PlanPart, CatalogModel } from '../types';
import { 
  Cpu, Plus, Search, FileText, AlertTriangle, X, BookOpen, Download, ClipboardList, CheckSquare, Save, Clock, Calendar, ArrowRight, Eye, ChevronDown, Ban, Package, Sparkles, Trash2, CalendarClock, Tags
} from 'lucide-react';

interface AssetsProps {
  assets: Asset[];
  inventory: InventoryItem[];
  taskTemplates: TaskTemplate[];
  maintenancePlans: MaintenancePlan[];
  modelCatalog: CatalogModel[];
  onCreatePlan: (plan: MaintenancePlan) => void;
  onDeletePlan: (planId: string) => void;
  onCreateAsset: (asset: Asset) => void;
}

export const Assets: React.FC<AssetsProps> = ({ 
    assets, inventory, taskTemplates, maintenancePlans, modelCatalog, onCreatePlan, onDeletePlan, onCreateAsset 
}) => {
    const [selectedAsset, setSelectedAsset] = useState<Asset | null>(null);
    const [viewMode, setViewMode] = useState<'list' | 'detail'>('list');

    // State for Add Machine Modal
    const [isAddMachineOpen, setIsAddMachineOpen] = useState(false);
    const [newMachine, setNewMachine] = useState<Partial<Asset>>({
        status: 'OPERATIONAL',
        brand: '',
        category: '',
        model: ''
    });

    // States for "Create Plan" inside Detail View
    const [isPlanModalOpen, setIsPlanModalOpen] = useState(false);
    const [newPlan, setNewPlan] = useState<Partial<MaintenancePlan>>({
        frequencyDays: 30,
        estimatedHours: 1,
        specialtyRequired: 'Mecánica',
        checklistTemplate: [],
        requiresDowntime: false,
        requiredParts: []
    });
    const [tempTask, setTempTask] = useState('');

    // States for Parts Selector inside Modal
    const [selectedPartId, setSelectedPartId] = useState('');
    const [partQty, setPartQty] = useState(1);

    // Derived Lists for Cascading Dropdowns
    const availableBrands = Array.from(new Set(modelCatalog.map(m => m.brand))).sort();

    const availableCategories = newMachine.brand 
        ? Array.from(new Set(modelCatalog.filter(m => m.brand === newMachine.brand).map(m => m.category))).sort()
        : [];

    const availableModels = newMachine.brand && newMachine.category
        ? modelCatalog.filter(m => m.brand === newMachine.brand && m.category === newMachine.category).sort((a,b) => a.name.localeCompare(b.name))
        : [];

    const selectedModelData = availableModels.find(m => m.name === newMachine.model);

    const openDetail = (asset: Asset) => {
        setSelectedAsset(asset);
        setViewMode('detail');
    };

    const closeDetail = () => {
        setSelectedAsset(null);
        setViewMode('list');
    };

    // Machine Creation Logic
    const handleCreateMachine = () => {
        if (!newMachine.name || !newMachine.location) return alert("Nombre y Ubicación son obligatorios.");

        const asset: Asset = {
            id: `a-${Date.now()}`,
            name: newMachine.name,
            location: newMachine.location,
            sector: newMachine.sector || 'General',
            brand: newMachine.brand,
            category: newMachine.category,
            model: newMachine.model,
            serialNumber: newMachine.serialNumber || 'S/N',
            status: newMachine.status as 'OPERATIONAL' | 'DOWN' || 'OPERATIONAL',
            frequentFailures: []
        };

        onCreateAsset(asset);
        setIsAddMachineOpen(false);
        setNewMachine({ status: 'OPERATIONAL', brand: '', category: '', model: '' });
    };

    // Plan Management Logic
    const handleAddPlan = () => {
        if (!selectedAsset || !newPlan.title || !newPlan.frequencyDays) return alert("Faltan datos obligatorios.");

        const plan: MaintenancePlan = {
            id: `mp-${Date.now()}`,
            assetId: selectedAsset.id,
            assetName: selectedAsset.name,
            title: newPlan.title,
            frequencyDays: Number(newPlan.frequencyDays),
            nextDueDate: new Date(Date.now() + 86400000).toISOString().split('T')[0], // Default tomorrow
            estimatedHours: Number(newPlan.estimatedHours),
            specialtyRequired: newPlan.specialtyRequired || 'Mecánica',
            checklistTemplate: newPlan.checklistTemplate || [],
            requiresDowntime: newPlan.requiresDowntime,
            requiredParts: newPlan.requiredParts
        };

        onCreatePlan(plan);
        setIsPlanModalOpen(false);
        setNewPlan({ frequencyDays: 30, estimatedHours: 1, specialtyRequired: 'Mecánica', checklistTemplate: [], requiresDowntime: false, requiredParts: [] });
    };

    const handleLoadTemplate = (tplId: string) => {
        const tpl = taskTemplates.find(t => t.id === tplId);
        if (tpl) {
            setNewPlan(prev => ({
                ...prev,
                title: prev.title || tpl.title,
                checklistTemplate: tpl.tasks,
                estimatedHours: tpl.estimatedHours,
                specialtyRequired: tpl.specialty,
                frequencyDays: tpl.frequencyDays
            }));
        }
    };

    const addTask = () => {
        if (tempTask.trim()) {
            setNewPlan(prev => ({ ...prev, checklistTemplate: [...(prev.checklistTemplate || []), tempTask.trim()] }));
            setTempTask('');
        }
    };

    const addPart = () => {
        if (selectedPartId && partQty > 0) {
            const item = inventory.find(i => i.id === selectedPartId);
            if (item) {
                const newPart: PlanPart = {
                    itemId: item.id,
                    itemName: item.name,
                    quantity: partQty
                };
                setNewPlan(prev => ({
                    ...prev,
                    requiredParts: [...(prev.requiredParts || []), newPart]
                }));
                setSelectedPartId('');
                setPartQty(1);
            }
        }
    };

    const removePart = (idx: number) => {
        setNewPlan(prev => ({
            ...prev,
            requiredParts: prev.requiredParts?.filter((_, i) => i !== idx)
        }));
    };

    // Render List Mode
    if (viewMode === 'list') {
        return (
            <div className="space-y-4">
                <div className="flex justify-between items-center">
                    <div>
                        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                            <Cpu size={24} className="text-primary-600"/> Gestión de Activos
                        </h2>
                        <p className="text-slate-500 text-sm">Inventario de maquinaria y equipos.</p>
                    </div>
                    <button 
                        onClick={() => setIsAddMachineOpen(true)}
                        className="flex items-center gap-2 bg-primary-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-primary-700"
                    >
                        <Plus size={16}/> Nuevo Máquina
                    </button>
                </div>

                <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider">
                            <tr>
                                <th className="px-6 py-4">Máquina</th>
                                <th className="px-6 py-4">Marca / Modelo</th>
                                <th className="px-6 py-4">Sector / Ubicación</th>
                                <th className="px-6 py-4">N° Serie</th>
                                <th className="px-6 py-4 text-center">Planes Prev.</th>
                                <th className="px-6 py-4 text-center">Estado</th>
                                <th className="px-6 py-4 text-center">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {assets.map(asset => {
                                const assetPlans = maintenancePlans.filter(p => p.assetId === asset.id);
                                return (
                                    <tr key={asset.id} className="hover:bg-slate-50 transition-colors group cursor-pointer" onClick={() => openDetail(asset)}>
                                        <td className="px-6 py-4 font-medium text-slate-900 flex items-center gap-2">
                                            <div className="p-2 bg-slate-100 rounded-lg text-slate-500 group-hover:bg-primary-100 group-hover:text-primary-600 transition-colors">
                                                <Cpu size={18} />
                                            </div>
                                            {asset.name}
                                        </td>
                                        <td className="px-6 py-4">
                                            {asset.model ? (
                                                <div>
                                                    <div className="font-bold text-slate-700">{asset.model}</div>
                                                    <div className="text-xs text-slate-400 flex items-center gap-1">
                                                        <Tags size={10}/> {asset.brand} • {asset.category}
                                                    </div>
                                                </div>
                                            ) : (
                                                <span className="text-slate-400 text-xs italic">Genérico</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-slate-600">
                                            <div className="font-medium text-slate-800">{asset.sector || 'N/A'}</div>
                                            <div className="text-xs text-slate-400">{asset.location}</div>
                                        </td>
                                        <td className="px-6 py-4 font-mono text-xs text-slate-500">{asset.serialNumber || '-'}</td>
                                        <td className="px-6 py-4 text-center">
                                            {assetPlans.length > 0 ? (
                                                <span className="inline-flex items-center gap-1 bg-teal-50 text-teal-700 px-2 py-1 rounded-full text-xs font-bold border border-teal-100">
                                                    <ClipboardList size={12}/> {assetPlans.length} Activos
                                                </span>
                                            ) : (
                                                <span className="text-slate-400 text-xs">-</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <span className={`px-2 py-1 rounded-full text-xs font-bold ${asset.status === 'OPERATIONAL' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {asset.status === 'OPERATIONAL' ? 'OPERATIVO' : 'PARADA'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-center">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); openDetail(asset); }}
                                                className="text-primary-600 hover:text-primary-800 font-medium text-xs flex items-center justify-center gap-1 bg-primary-50 px-3 py-1.5 rounded-lg hover:bg-primary-100 transition-colors"
                                            >
                                                <Eye size={14}/> Ficha Técnica
                                            </button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                {/* MODAL: NEW MACHINE */}
                {isAddMachineOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in zoom-in-95 duration-200">
                        <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl flex flex-col max-h-[90vh]">
                            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                                <div>
                                    <h3 className="font-bold text-slate-800">Alta de Nueva Máquina</h3>
                                    <p className="text-xs text-slate-500">Registrar un nuevo activo en el sistema.</p>
                                </div>
                                <button onClick={() => setIsAddMachineOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600"/></button>
                            </div>

                            <div className="p-6 space-y-4 overflow-y-auto">
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nombre del Equipo <span className="text-red-500">*</span></label>
                                    <input 
                                        type="text" 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900"
                                        placeholder="Ej. Compresor de Tornillo #2"
                                        value={newMachine.name || ''}
                                        onChange={e => setNewMachine({...newMachine, name: e.target.value})}
                                    />
                                </div>

                                {/* CASCADING DROPDOWNS: BRAND -> CATEGORY -> MODEL */}
                                <div className="space-y-4">
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Marca (Fabricante)</label>
                                            <select 
                                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900"
                                                value={newMachine.brand || ''}
                                                onChange={e => setNewMachine({...newMachine, brand: e.target.value, category: '', model: ''})}
                                            >
                                                <option value="">Seleccionar Marca...</option>
                                                {availableBrands.map(brand => (
                                                    <option key={brand} value={brand}>{brand}</option>
                                                ))}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoría (Tipo)</label>
                                            <select 
                                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900 disabled:bg-slate-50 disabled:text-slate-400"
                                                value={newMachine.category || ''}
                                                onChange={e => setNewMachine({...newMachine, category: e.target.value, model: ''})}
                                                disabled={!newMachine.brand}
                                            >
                                                <option value="">Seleccionar Tipo...</option>
                                                {availableCategories.map(cat => (
                                                    <option key={cat} value={cat}>{cat}</option>
                                                ))}
                                            </select>
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Modelo Específico</label>
                                        <select 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900 disabled:bg-slate-50 disabled:text-slate-400"
                                            value={newMachine.model || ''}
                                            onChange={e => setNewMachine({...newMachine, model: e.target.value})}
                                            disabled={!newMachine.category}
                                        >
                                            <option value="">Seleccionar Modelo...</option>
                                            {availableModels.map(m => (
                                                <option key={m.id} value={m.name}>{m.name}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                {/* SMART PREVIEW */}
                                {selectedModelData && (
                                    <div className="bg-indigo-50 border border-indigo-100 rounded-lg p-3 flex items-start gap-3 animate-in fade-in zoom-in-95 duration-200">
                                        <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg shrink-0">
                                            <Sparkles size={20} />
                                        </div>
                                        <div>
                                            <h4 className="text-sm font-bold text-indigo-900 flex items-center gap-2">
                                                Configuración Automática Detectada
                                            </h4>
                                            <p className="text-xs text-indigo-700 mt-1">
                                                Al crear este equipo, se importarán automáticamente:
                                            </p>
                                            <ul className="mt-2 space-y-1 text-xs text-indigo-800">
                                                <li className="flex items-center gap-1"><CheckSquare size={12}/> {selectedModelData.standardPlans.length} Planes Preventivos Recomendados</li>
                                                <li className="flex items-center gap-1"><BookOpen size={12}/> Manual de Usuario Oficial</li>
                                                <li className="flex items-center gap-1"><AlertTriangle size={12}/> Base de Fallas Comunes</li>
                                            </ul>
                                        </div>
                                    </div>
                                )}

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Sector / Área</label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900"
                                            placeholder="Ej. Sala de Máquinas"
                                            value={newMachine.sector || ''}
                                            onChange={e => setNewMachine({...newMachine, sector: e.target.value})}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Ubicación Física <span className="text-red-500">*</span></label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900"
                                            placeholder="Ej. Nave Industrial B"
                                            value={newMachine.location || ''}
                                            onChange={e => setNewMachine({...newMachine, location: e.target.value})}
                                        />
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Número de Serie</label>
                                    <input 
                                        type="text" 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900 font-mono"
                                        placeholder="S/N-12345-XYZ"
                                        value={newMachine.serialNumber || ''}
                                        onChange={e => setNewMachine({...newMachine, serialNumber: e.target.value})}
                                    />
                                </div>

                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Estado Inicial</label>
                                    <select 
                                        className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-primary-500 outline-none bg-white text-slate-900"
                                        value={newMachine.status}
                                        onChange={e => setNewMachine({...newMachine, status: e.target.value as any})}
                                    >
                                        <option value="OPERATIONAL">OPERATIVO</option>
                                        <option value="DOWN">PARADA (Fuera de Servicio)</option>
                                    </select>
                                </div>
                            </div>

                            <div className="p-5 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 rounded-b-xl">
                                <button onClick={() => setIsAddMachineOpen(false)} className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-200 rounded-lg">Cancelar</button>
                                <button 
                                    onClick={handleCreateMachine}
                                    className="bg-primary-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-primary-700 shadow-sm flex items-center gap-2"
                                >
                                    <Save size={18}/> Crear Máquina
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    }

    // Render Detail Mode
    if (viewMode === 'detail' && selectedAsset) {
        const assetPlans = maintenancePlans.filter(p => p.assetId === selectedAsset.id);

        return (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                {/* Breadcrumb / Header */}
                <div className="flex items-center gap-4 border-b border-slate-200 pb-4">
                    <button onClick={closeDetail} className="p-2 hover:bg-slate-100 rounded-full transition-colors text-slate-500">
                        <ArrowRight size={20} className="rotate-180" />
                    </button>
                    <div>
                        <h2 className="text-2xl font-bold text-slate-900 flex items-center gap-2">
                            {selectedAsset.name}
                            <span className={`text-xs px-2 py-0.5 rounded-full border ${selectedAsset.status === 'OPERATIONAL' ? 'bg-green-50 border-green-200 text-green-700' : 'bg-red-50 border-red-200 text-red-700'}`}>
                                {selectedAsset.status}
                            </span>
                        </h2>
                        <div className="flex items-center gap-3 text-sm text-slate-500 mt-1">
                            <span className="font-mono bg-slate-100 px-1.5 rounded">{selectedAsset.serialNumber}</span>
                            <span>•</span>
                            <span className="font-semibold text-slate-700">{selectedAsset.brand}</span>
                            <span>•</span>
                            <span className="text-slate-600">{selectedAsset.category}</span>
                            <span>•</span>
                            <span className="font-bold text-slate-700">{selectedAsset.model || 'Modelo Genérico'}</span>
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column: General Info & Docs */}
                    <div className="space-y-6">
                        {selectedAsset.imageUrl && (
                            <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-200">
                                <img src={selectedAsset.imageUrl} alt={selectedAsset.name} className="w-full h-48 object-cover rounded-lg" />
                            </div>
                        )}

                        <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                            <h4 className="text-sm font-bold text-slate-800 uppercase mb-4 flex items-center gap-2">
                                <BookOpen size={16} className="text-primary-500"/> Documentación
                            </h4>
                            <div className="space-y-3">
                                {selectedAsset.manualUrl && selectedAsset.manualUrl !== '#' && (
                                    <div className="flex items-center justify-between p-3 bg-indigo-50 rounded-lg border border-indigo-100">
                                        <div className="flex items-center gap-3">
                                            <div className="p-2 bg-white rounded border border-indigo-200 text-indigo-500"><FileText size={20}/></div>
                                            <div>
                                                <p className="text-sm font-bold text-indigo-900">Manual de Fabricante</p>
                                                <p className="text-xs text-indigo-600">Oficial • PDF</p>
                                            </div>
                                        </div>
                                        <button className="text-indigo-600 hover:text-indigo-800"><Download size={18}/></button>
                                    </div>
                                )}
                                <div className="flex items-center justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                                    <div className="flex items-center gap-3">
                                        <div className="p-2 bg-white rounded border border-slate-200 text-slate-500"><FileText size={20}/></div>
                                        <div>
                                            <p className="text-sm font-bold text-slate-700">Diagrama Eléctrico</p>
                                            <p className="text-xs text-slate-400">PDF • 5.1 MB</p>
                                        </div>
                                    </div>
                                    <button className="text-slate-600 hover:text-slate-800"><Download size={18}/></button>
                                </div>
                            </div>
                        </div>

                        <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                             <h4 className="text-sm font-bold text-slate-800 uppercase mb-4 flex items-center gap-2">
                                <AlertTriangle size={16} className="text-orange-500"/> Historial de Fallas
                            </h4>
                            {(!selectedAsset.frequentFailures || selectedAsset.frequentFailures.length === 0) ? (
                                <p className="text-sm text-slate-400 italic">No hay fallas reportadas.</p>
                            ) : (
                                <ul className="space-y-3">
                                    {selectedAsset.frequentFailures.map(fail => (
                                        <li key={fail.id} className="text-sm text-slate-600 border-l-2 border-orange-300 pl-3">
                                            <span className="font-bold text-slate-800 block">{fail.title}</span>
                                            {fail.description}
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    </div>

                    {/* Right Column: Maintenance Strategy (Preventive Plans) */}
                    <div className="lg:col-span-2">
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 h-full flex flex-col">
                            <div className="p-5 border-b border-slate-200 flex justify-between items-center bg-slate-50/50">
                                <div>
                                    <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                                        <CalendarClock size={20} className="text-teal-600"/> Estrategia de Mantenimiento
                                    </h3>
                                    <p className="text-sm text-slate-500">Planes preventivos recurrentes asignados a este equipo.</p>
                                </div>
                                <button 
                                    onClick={() => setIsPlanModalOpen(true)}
                                    className="bg-teal-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-teal-700 transition-colors flex items-center gap-2 shadow-sm"
                                >
                                    <Plus size={16}/> Agregar Plan
                                </button>
                            </div>

                            <div className="p-5 flex-1 overflow-y-auto bg-slate-50">
                                {assetPlans.length === 0 ? (
                                    <div className="h-40 flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-white">
                                        <ClipboardList size={32} className="mb-2 opacity-50"/>
                                        <p className="text-sm font-medium">Este equipo no tiene planes preventivos.</p>
                                        <p className="text-xs">Agrega uno para automatizar la generación de OTs.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {assetPlans.map(plan => (
                                            <div key={plan.id} className="bg-white border border-slate-200 rounded-xl p-4 shadow-sm hover:shadow-md transition-shadow">
                                                <div className="flex justify-between items-start mb-3">
                                                    <div>
                                                        <div className="flex items-center gap-2 mb-1">
                                                             <h4 className="text-base font-bold text-slate-900">{plan.title}</h4>
                                                             {plan.requiresDowntime && (
                                                                 <span className="bg-red-100 text-red-600 text-[10px] font-bold px-1.5 py-0.5 rounded border border-red-200 flex items-center gap-1">
                                                                     <Ban size={10} /> PARADA
                                                                 </span>
                                                             )}
                                                             {plan.requiredParts && plan.requiredParts.length > 0 && (
                                                                 <span className="bg-primary-100 text-primary-600 text-[10px] font-bold px-1.5 py-0.5 rounded border border-primary-200 flex items-center gap-1">
                                                                     <Package size={10} /> REPUESTOS
                                                                 </span>
                                                             )}
                                                        </div>
                                                        <div className="flex items-center gap-3 mt-1 text-sm text-slate-500">
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Calendar size={12}/> Cada {plan.frequencyDays} días</span>
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Clock size={12}/> {plan.estimatedHours}h Est.</span>
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Cpu size={12}/> {plan.specialtyRequired}</span>
                                                        </div>
                                                    </div>
                                                    <button 
                                                        onClick={() => {
                                                            if(confirm('¿Eliminar este plan?')) onDeletePlan(plan.id);
                                                        }}
                                                        className="text-slate-400 hover:text-red-500 p-2 hover:bg-red-50 rounded transition-colors"
                                                    >
                                                        <Trash2 size={16}/>
                                                    </button>
                                                </div>

                                                <div className="bg-slate-50 rounded-lg p-3 border border-slate-100">
                                                    <p className="text-xs font-bold text-slate-400 uppercase mb-2">Tareas ({plan.checklistTemplate.length})</p>
                                                    <div className="space-y-1">
                                                        {plan.checklistTemplate.slice(0, 3).map((task, i) => (
                                                            <div key={i} className="flex items-start gap-2 text-sm text-slate-600">
                                                                <CheckSquare size={14} className="mt-0.5 text-teal-500 shrink-0"/>
                                                                <span className="truncate">{task}</span>
                                                            </div>
                                                        ))}
                                                        {plan.checklistTemplate.length > 3 && (
                                                            <p className="text-xs text-slate-400 pl-6 italic">+ {plan.checklistTemplate.length - 3} tareas más...</p>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }
    return null;
}

import React, { useState } from 'react';
import { WorkOrder, WorkOrderStatus, Priority, User, UserRole, WorkOrderType, Asset } from '../types';
import { Calendar, User as UserIcon, AlertTriangle, Clock, Filter, Plus, CalendarClock, Wrench, MoreHorizontal, ArrowRight, Activity, LayoutList, LayoutGrid, X, Save, FileText, ChevronDown, Eye, CheckSquare, Image as ImageIcon, MapPin } from 'lucide-react';

interface WorkOrderListProps {
  orders: WorkOrder[];
  users: User[];
  assets: Asset[];
  onAssign: (orderId: string, technicianId: string) => void;
  onCreate: (order: WorkOrder) => void;
}

export const WorkOrderList: React.FC<WorkOrderListProps> = ({ orders, users, assets, onAssign, onCreate }) => {
  const [filterSpecialty, setFilterSpecialty] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [viewMode, setViewMode] = useState<'table' | 'grid'>('table'); 
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedOrder, setSelectedOrder] = useState<WorkOrder | null>(null);

  // Create Form State
  const [newOrderTitle, setNewOrderTitle] = useState('');
  const [newOrderDesc, setNewOrderDesc] = useState('');
  const [newOrderAsset, setNewOrderAsset] = useState('');
  const [newOrderPriority, setNewOrderPriority] = useState<Priority>(Priority.MEDIUM);
  const [newOrderSpecialty, setNewOrderSpecialty] = useState('Mecánica');
  const [newOrderDate, setNewOrderDate] = useState('');

  const technicians = users.filter(u => u.role === UserRole.TECHNICIAN);
  const specialties = Array.from(new Set(technicians.map(t => t.specialty).filter(Boolean)));

  const filteredOrders = orders.filter(order => {
    const matchesSpecialty = filterSpecialty === 'ALL' || order.specialtyRequired === filterSpecialty;
    const matchesStatus = filterStatus === 'ALL' || order.status === filterStatus;
    return matchesSpecialty && matchesStatus;
  });

  const getPriorityConfig = (p: Priority) => {
    switch (p) {
      case Priority.CRITICAL: return { color: 'text-red-700 bg-red-50 border-red-100', label: 'Crítica', dot: 'bg-red-500' };
      case Priority.HIGH: return { color: 'text-orange-700 bg-orange-50 border-orange-100', label: 'Alta', dot: 'bg-orange-500' };
      case Priority.MEDIUM: return { color: 'text-yellow-700 bg-yellow-50 border-yellow-100', label: 'Media', dot: 'bg-yellow-500' };
      default: return { color: 'text-primary-700 bg-primary-50 border-primary-100', label: 'Baja', dot: 'bg-primary-500' };
    }
  };

  const getStatusConfig = (s: WorkOrderStatus) => {
    switch (s) {
      case WorkOrderStatus.COMPLETED: return { color: 'bg-emerald-100 text-emerald-800', label: 'Completada' };
      case WorkOrderStatus.IN_PROGRESS: return { color: 'bg-primary-100 text-primary-800', label: 'En Progreso' };
      default: return { color: 'bg-slate-100 text-slate-600', label: 'Pendiente' };
    }
  };

  const getTypeConfig = (type: WorkOrderType) => {
    if (type === WorkOrderType.PREVENTIVE) {
      return { 
        icon: CalendarClock, 
        text: 'Preventivo', 
        style: 'text-primary-600 bg-primary-50 border-primary-100' 
      };
    }
    return { 
      icon: Activity, 
      text: 'Correctivo', 
      style: 'text-amber-600 bg-amber-50 border-amber-100' 
    };
  };

  const handleCreateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newOrderTitle || !newOrderAsset || !newOrderDate) {
      alert("Por favor completa los campos requeridos.");
      return;
    }

    const selectedAsset = assets.find(a => a.id === newOrderAsset);

    const newOrder: WorkOrder = {
      id: `ot-${Date.now()}`,
      title: newOrderTitle,
      description: newOrderDesc,
      assetId: newOrderAsset,
      assetName: selectedAsset?.name || 'Desconocido',
      type: WorkOrderType.CORRECTIVE, // Default for manual creation
      priority: newOrderPriority,
      status: WorkOrderStatus.PENDING,
      dueDate: newOrderDate,
      specialtyRequired: newOrderSpecialty,
    };

    onCreate(newOrder);
    setIsModalOpen(false);

    // Reset form
    setNewOrderTitle('');
    setNewOrderDesc('');
    setNewOrderAsset('');
    setNewOrderPriority(Priority.MEDIUM);
    setNewOrderDate('');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Gestión de Órdenes (OT)</h2>
          <p className="text-slate-500">Supervisión y asignación de tareas de mantenimiento.</p>
        </div>
        <div className="flex items-center gap-3">
            {/* View Toggle (Desktop Only) */}
            <div className="hidden md:flex bg-white rounded-lg border border-slate-200 p-1 shadow-sm">
                <button 
                    onClick={() => setViewMode('table')}
                    className={`p-2 rounded transition-colors ${viewMode === 'table' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tabla"
                >
                    <LayoutList size={18} />
                </button>
                <button 
                    onClick={() => setViewMode('grid')}
                    className={`p-2 rounded transition-colors ${viewMode === 'grid' ? 'bg-slate-100 text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                    title="Vista de Tarjetas"
                >
                    <LayoutGrid size={18} />
                </button>
            </div>

            <button 
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-2 bg-primary-600 hover:bg-primary-700 text-white px-5 py-2.5 rounded-lg font-medium transition-all shadow-lg shadow-primary-200 active:scale-95"
            >
            <Plus size={18} />
            Nueva OT
            </button>
        </div>
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-3 rounded-xl shadow-sm border border-slate-200 flex flex-wrap gap-3 items-center sticky top-0 z-10 backdrop-blur-xl bg-white/90">
        <div className="flex items-center gap-2 text-slate-500 px-2">
          <Filter size={18} />
          <span className="text-sm font-bold uppercase tracking-wide">Filtros</span>
        </div>

        <div className="h-6 w-px bg-slate-200 hidden md:block"></div>

        <select 
          className="bg-white border border-slate-200 rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-primary-500 outline-none hover:bg-slate-50 transition-colors cursor-pointer"
          value={filterSpecialty}
          onChange={(e) => setFilterSpecialty(e.target.value)}
        >
          <option value="ALL">Todas las Especialidades</option>
          {specialties.map(s => <option key={s} value={s as string}>{s}</option>)}
        </select>

        <select 
          className="bg-white border border-slate-200 rounded-lg text-sm px-4 py-2 text-slate-700 font-medium focus:ring-2 focus:ring-primary-500 outline-none hover:bg-slate-50 transition-colors cursor-pointer"
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
        >
          <option value="ALL">Todos los Estados</option>
          <option value={WorkOrderStatus.PENDING}>Pendientes</option>
          <option value={WorkOrderStatus.IN_PROGRESS}>En Progreso</option>
          <option value={WorkOrderStatus.COMPLETED}>Completadas</option>
        </select>

        <div className="ml-auto text-xs text-slate-400 font-medium hidden md:block">
            Mostrando {filteredOrders.length} órdenes
        </div>
      </div>

      {/* TABLE VIEW (Desktop Default) */}
      <div className={`hidden md:block ${viewMode === 'grid' ? '!hidden' : ''}`}>
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 text-slate-500 border-b border-slate-200 uppercase text-xs tracking-wider font-semibold">
                    <tr>
                        <th className="px-6 py-4 w-16">Tipo</th>
                        <th className="px-6 py-4">ID / Asunto</th>
                        <th className="px-6 py-4">Activo</th>
                        <th className="px-6 py-4">Prioridad</th>
                        <th className="px-6 py-4">Estado</th>
                        <th className="px-6 py-4">Asignación</th>
                        <th className="px-6 py-4 text-right">Vencimiento</th>
                        <th className="px-6 py-4 w-16 text-center">Acciones</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                    {filteredOrders.map(ot => {
                        const typeConfig = getTypeConfig(ot.type);
                        const priorityConfig = getPriorityConfig(ot.priority);
                        const statusConfig = getStatusConfig(ot.status);
                        const TypeIcon = typeConfig.icon;

                        return (
                            <tr key={ot.id} className="hover:bg-slate-50 transition-colors group">
                                <td className="px-6 py-4">
                                     <div className={`inline-flex items-center justify-center w-8 h-8 rounded-lg ${typeConfig.style}`} title={typeConfig.text}>
                                        <TypeIcon size={16} />
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex flex-col">
                                        <span className="text-xs font-mono text-slate-400 mb-0.5">{ot.id}</span>
                                        <span className="font-bold text-slate-900 group-hover:text-primary-600 transition-colors truncate max-w-[200px]" title={ot.title}>{ot.title}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-slate-600">
                                    <div className="flex items-center gap-2">
                                        <Wrench size={14} className="text-slate-400"/>
                                        <span className="truncate max-w-[150px]" title={ot.assetName}>{ot.assetName}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                                        <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                                        {priorityConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                     <span className={`text-[10px] font-bold px-2 py-1 rounded-full uppercase ${statusConfig.color}`}>
                                        {statusConfig.label}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    {ot.status === WorkOrderStatus.COMPLETED ? (
                                        <div className="flex items-center gap-2 text-xs font-medium text-slate-700">
                                            <div className="w-6 h-6 rounded-full bg-slate-200 flex items-center justify-center text-slate-500"><UserIcon size={12}/></div>
                                            {ot.technicianName}
                                        </div>
                                    ) : (
                                        <div className="relative group/select">
                                            <select 
                                                className="w-full bg-white border border-slate-200 text-xs font-medium text-slate-700 rounded-md py-1.5 pl-2 pr-6 focus:outline-none focus:ring-2 focus:ring-primary-500 cursor-pointer appearance-none hover:bg-slate-50 transition-colors"
                                                value={ot.assignedTechnicianId || ''}
                                                onChange={(e) => onAssign(ot.id, e.target.value)}
                                            >
                                                <option value="">-- Sin Asignar --</option>
                                                {technicians
                                                    .filter(t => t.specialty === ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                                <option disabled>--- Otros ---</option>
                                                {technicians
                                                    .filter(t => t.specialty !== ot.specialtyRequired)
                                                    .map(t => (
                                                    <option key={t.id} value={t.id}>{t.name}</option>
                                                ))}
                                            </select>
                                            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none text-slate-400">
                                                <UserIcon size={12} />
                                            </div>
                                        </div>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <span className={`text-xs font-medium ${new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600" : "text-slate-500"}`}>
                                        {ot.dueDate}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <button 
                                        onClick={() => setSelectedOrder(ot)}
                                        className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-primary-600 hover:border-primary-200 hover:shadow-sm transition-all"
                                        title="Ver Detalle Completo"
                                    >
                                        <Eye size={16} />
                                    </button>
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
             {filteredOrders.length === 0 && (
                <div className="py-12 flex flex-col items-center justify-center text-center">
                    <div className="p-4 bg-slate-50 rounded-full text-slate-300 mb-3">
                        <Filter size={32} />
                    </div>
                    <p className="text-slate-900 font-medium">No se encontraron órdenes</p>
                </div>
            )}
        </div>
      </div>

      {/* GRID VIEW (Mobile Default, Desktop Optional) */}
      <div className={`grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 ${viewMode === 'table' ? 'md:hidden' : ''}`}>
        {filteredOrders.map(ot => {
          const typeConfig = getTypeConfig(ot.type);
          const priorityConfig = getPriorityConfig(ot.priority);
          const statusConfig = getStatusConfig(ot.status);
          const TypeIcon = typeConfig.icon;

          return (
            <div key={ot.id} className="group bg-white rounded-xl shadow-sm border border-slate-200 hover:shadow-lg hover:border-primary-200 transition-all duration-300 flex flex-col">

              {/* Card Header */}
              <div className="p-5 pb-3">
                <div className="flex justify-between items-start mb-3">
                    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md text-xs font-bold border ${typeConfig.style}`}>
                        <TypeIcon size={14} />
                        {typeConfig.text}
                    </div>
                    <div className="flex items-center gap-2">
                        <button 
                            onClick={() => setSelectedOrder(ot)}
                            className="p-1.5 bg-slate-50 text-slate-400 rounded-md hover:bg-primary-50 hover:text-primary-600 transition-colors"
                        >
                            <Eye size={16} />
                        </button>
                    </div>
                </div>

                <h3 className="text-base font-bold text-slate-900 leading-tight mb-1 group-hover:text-primary-600 transition-colors line-clamp-1" title={ot.title}>
                    {ot.title}
                </h3>

                <div className="flex items-center gap-1.5 text-slate-500 text-xs mb-3 font-medium">
                    <Wrench size={12} />
                    {ot.assetName}
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 h-10 leading-relaxed">
                    {ot.description}
                </p>

                <div className="mt-2 flex gap-2">
                    <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[10px] font-bold border uppercase tracking-wide ${priorityConfig.color}`}>
                        <span className={`w-1.5 h-1.5 rounded-full ${priorityConfig.dot}`}></span>
                        {priorityConfig.label}
                    </span>
                    {ot.planId && (
                        <span className="text-[10px] font-mono text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded border border-slate-100">
                            PLAN
                        </span>
                    )}
                </div>
              </div>

              {/* Card Meta & Status */}
              <div className="px-5 py-3 border-t border-slate-50 bg-slate-50/50 flex items-center justify-between mt-auto">
                 <div className="flex items-center gap-2 text-xs text-slate-500 font-medium">
                    <Calendar size={14} className="text-slate-400"/>
                    <span className={new Date(ot.dueDate) < new Date() && ot.status !== WorkOrderStatus.COMPLETED ? "text-red-600 font-bold" : ""}>
                        {ot.dueDate}
                    </span>
                 </div>
                 <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase ${statusConfig.color}`}>
                    {statusConfig.label}
                 </span>
              </div>

              {/* Assignment Footer */}
              <div className="px-5 py-3 border-t border-slate-100 flex items-center gap-3">
                 <div className={`p-1.5 rounded-full ${ot.assignedTechnicianId ? 'bg-primary-100 text-primary-600' : 'bg-slate-100 text-slate-400'}`}>
                    <UserIcon size={16} />
                 </div>

                 <div className="flex-1 min-w-0">
                    {ot.status === WorkOrderStatus.COMPLETED ? (
                         <div className="text-xs font-bold text-slate-700 truncate">
                            {ot.technicianName}
                         </div>
                    ) : (
                        <select 
                            className="w-full bg-transparent text-sm font-medium text-slate-700 focus:outline-none cursor-pointer truncate"
