                {/* Checklist (Read Only) */}
                {selectedOrder.checklist && selectedOrder.checklist.length > 0 && (
                     <div>
                        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Checklist de Tareas</h4>
