                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Clock size={12}/> {plan.estimatedHours}h Est.</span>
                                                            <span className="flex items-center gap-1 bg-slate-100 px-2 py-0.5 rounded text-xs font-medium"><Cpu size={12}/> {plan.specialtyRequired}</span>
                                                        </div>
                                                    </div>
                                                    <button 
                                                        onClick={() => {
                                                            if(confirm('¿Eliminar este plan?')) onDeletePlan(plan.id);
                                                        }}
                                                        className="text-slate-400 hover:text-red-500 p-2 hover:bg-red-50 rounded transition-colors"
                                                    >
                                                        <Trash2 size={16}/>
                                                    </button>
                                                </div>

                                                <div className="bg-slate-50 rounded-lg p-3 border border-slate-100">
                                                    <p className="text-xs font-bold text-slate-400 uppercase mb-2">Tareas ({plan.checklistTemplate.length})</p>
                                                    <div className="space-y-1">
                                                        {plan.checklistTemplate.slice(0, 3).map((task, i) => (
                                                            <div key={i} className="flex items-start gap-2 text-sm text-slate-600">
                                                                <CheckSquare size={14} className="mt-0.5 text-teal-500 shrink-0"/>
                                                                <span className="truncate">{task}</span>
                                                            </div>
                                                        ))}
                                                        {plan.checklistTemplate.length > 3 && (
                                                            <p className="text-xs text-slate-400 pl-6 italic">+ {plan.checklistTemplate.length - 3} tareas más...</p>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {/* MODAL: ADD MAINTENANCE PLAN */}
                {isPlanModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in zoom-in-95 duration-200">
                        <div className="bg-white rounded-xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[90vh]">
                            <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50 rounded-t-xl">
                                <div>
                                    <h3 className="font-bold text-slate-800">Nuevo Plan Preventivo</h3>
                                    <p className="text-xs text-slate-500">Asignar rutina de mantenimiento a: <span className="font-bold">{selectedAsset.name}</span></p>
                                </div>
                                <button onClick={() => setIsPlanModalOpen(false)}><X size={20} className="text-slate-400 hover:text-slate-600"/></button>
                            </div>

                            <div className="p-6 space-y-6 overflow-y-auto">
                                {/* Basic Info */}
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Título del Plan <span className="text-red-500">*</span></label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                                            placeholder="Ej. Lubricación Semanal de Rodamientos"
                                            value={newPlan.title || ''}
                                            onChange={e => setNewPlan({...newPlan, title: e.target.value})}
                                        />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Frecuencia (Días)</label>
                                            <div className="relative">
                                                <Calendar className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                                                <input 
                                                    type="number" 
                                                    className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                                                    value={newPlan.frequencyDays}
                                                    onChange={e => setNewPlan({...newPlan, frequencyDays: Number(e.target.value)})}
                                                />
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Duración Estimada (Horas)</label>
                                            <div className="relative">
                                                <Clock className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                                                <input 
                                                    type="number" 
                                                    className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                                                    value={newPlan.estimatedHours}
                                                    onChange={e => setNewPlan({...newPlan, estimatedHours: Number(e.target.value)})}
                                                />
                                            </div>
                                        </div>
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Especialidad</label>
                                            <div className="relative">
                                                <Cpu className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                                                <select 
                                                    className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white"
                                                    value={newPlan.specialtyRequired}
                                                    onChange={e => setNewPlan({...newPlan, specialtyRequired: e.target.value})}
                                                >
                                                    <option value="Mecánica">Mecánica</option>
                                                    <option value="Electricidad">Electricidad</option>
                                                    <option value="Hidráulica">Hidráulica</option>
                                                    <option value="General">General</option>
                                                </select>
                                            </div>
                                        </div>
                                        <div className="flex items-center mt-6">
                                            <label className="flex items-center gap-2 cursor-pointer">
                                                <input 
                                                    type="checkbox" 
                                                    className="w-4 h-4 text-teal-600 rounded focus:ring-teal-500"
                                                    checked={newPlan.requiresDowntime}
                                                    onChange={e => setNewPlan({...newPlan, requiresDowntime: e.target.checked})}
                                                />
                                                <span className="text-sm font-medium text-slate-700">Requiere Parada de Máquina</span>
                                            </label>
                                        </div>
                                    </div>
                                </div>

                                <hr className="border-slate-100"/>

                                {/* Checklist Builder */}
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Checklist de Tareas</label>
                                    <div className="flex gap-2 mb-3">
                                        <input 
                                            type="text" 
                                            className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                                            placeholder="Describir tarea..."
                                            value={tempTask}
                                            onChange={e => setTempTask(e.target.value)}
                                            onKeyDown={e => e.key === 'Enter' && addTask()}
                                        />
                                        <button 
                                            onClick={addTask}
                                            className="bg-slate-100 text-slate-600 px-3 py-2 rounded-lg hover:bg-slate-200 font-bold text-sm"
                                        >
                                            <Plus size={18}/>
                                        </button>
                                    </div>

                                    <div className="bg-slate-50 rounded-lg border border-slate-200 p-2 min-h-[100px] max-h-[200px] overflow-y-auto space-y-1">
                                        {newPlan.checklistTemplate && newPlan.checklistTemplate.length > 0 ? (
                                            newPlan.checklistTemplate.map((task, idx) => (
                                                <div key={idx} className="flex items-start gap-2 bg-white p-2 rounded border border-slate-100 text-sm">
                                                    <span className="text-teal-500 font-bold">{idx + 1}.</span>
                                                    <span className="flex-1 text-slate-700">{task}</span>
                                                    <button 
                                                        onClick={() => setNewPlan(prev => ({...prev, checklistTemplate: prev.checklistTemplate?.filter((_, i) => i !== idx)}))}
                                                        className="text-slate-400 hover:text-red-500"
                                                    >
                                                        <Trash2 size={14}/>
                                                    </button>
                                                </div>
                                            ))
                                        ) : (
                                            <div className="h-full flex flex-col items-center justify-center text-slate-400 py-4">
                                                <CheckSquare size={24} className="mb-1 opacity-50"/>
                                                <span className="text-xs">Agrega tareas al checklist</span>
                                            </div>
                                        )}
                                    </div>
                                </div>

                                <hr className="border-slate-100"/>

                                {/* Parts Requirement */}
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Repuestos Necesarios</label>
                                    <div className="flex gap-2 mb-3">
                                        <select 
                                            className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white"
                                            value={selectedPartId}
                                            onChange={e => setSelectedPartId(e.target.value)}
                                        >
                                            <option value="">Seleccionar Repuesto...</option>
                                            {inventory.map(item => (
                                                <option key={item.id} value={item.id}>{item.name} (Stock: {item.quantity})</option>
                                            ))}
                                        </select>
                                        <input 
                                            type="number" 
                                            className="w-20 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                                            min="1"
                                            value={partQty}
                                            onChange={e => setPartQty(Number(e.target.value))}
                                        />
                                        <button 
                                            onClick={addPart}
                                            className="bg-slate-100 text-slate-600 px-3 py-2 rounded-lg hover:bg-slate-200 font-bold text-sm"
                                        >
                                            <Plus size={18}/>
                                        </button>
                                    </div>

                                    {newPlan.requiredParts && newPlan.requiredParts.length > 0 && (
                                        <div className="space-y-1">
                                            {newPlan.requiredParts.map((part, idx) => (
                                                <div key={idx} className="flex items-center justify-between bg-blue-50 p-2 rounded border border-blue-100 text-sm">
                                                    <div className="flex items-center gap-2">
                                                        <Wrench size={14} className="text-blue-500"/>
                                                        <span className="text-blue-900 font-medium">{part.itemName}</span>
                                                    </div>
                                                    <div className="flex items-center gap-3">
                                                        <span className="bg-white px-2 py-0.5 rounded text-xs font-bold border border-blue-200">x{part.quantity}</span>
                                                        <button 
                                                            onClick={() => removePart(idx)}
                                                            className="text-blue-400 hover:text-red-500"
                                                        >
                                                            <Trash2 size={14}/>
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="p-5 border-t border-slate-100 bg-slate-50 flex justify-end gap-3 rounded-b-xl">
                                <button onClick={() => setIsPlanModalOpen(false)} className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-200 rounded-lg">Cancelar</button>
                                <button 
                                    onClick={handleAddPlan}
                                    className="bg-teal-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-teal-700 shadow-sm flex items-center gap-2"
                                >
                                    <Save size={18}/> Guardar Plan
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* MODAL: FAULT MANUAL */}
                {isFaultModalOpen && (
                    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in zoom-in-95 duration-200">
                        <div className="bg-white rounded-xl w-full max-w-4xl shadow-2xl flex flex-col max-h-[85vh]">
                            <div className="p-5 border-b border-slate-100 bg-orange-50 rounded-t-xl flex justify-between items-center">
                                <div>
                                    <h3 className="font-bold text-orange-900 text-lg flex items-center gap-2">
                                        <BookOpen size={20} className="text-orange-600"/> Manual de Fallas
                                    </h3>
                                    <p className="text-xs text-orange-700">Base de conocimiento para: <span className="font-bold">{selectedAsset.model || selectedAsset.name}</span></p>
                                </div>
                                <button onClick={() => setIsFaultModalOpen(false)}><X size={20} className="text-orange-400 hover:text-orange-600"/></button>
                            </div>

                            <div className="p-4 bg-white border-b border-slate-100">
                                <div className="relative">
                                    <Search className="absolute left-3 top-2.5 text-slate-400" size={18}/>
                                    <input 
                                        type="text" 
                                        className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none bg-slate-50"
                                        placeholder="Buscar por código, descripción o causa..."
                                        value={faultSearch}
                                        onChange={e => setFaultSearch(e.target.value)}
                                        autoFocus
                                    />
                                </div>
                            </div>

                            <div className="p-6 overflow-y-auto bg-slate-50">
                                {filteredFailures.length === 0 ? (
                                    <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                                        <HelpCircle size={48} className="mb-2 opacity-50"/>
                                        <p>No se encontraron fallas registradas para este modelo.</p>
                                    </div>
                                ) : (
                                    <div className="space-y-4">
                                        {filteredFailures.map((fail, idx) => (
                                            <div key={idx} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                                                <div className="p-4 border-b border-slate-50 bg-slate-50/50 flex justify-between items-start">
                                                    <div>
                                                        <span className="inline-block bg-slate-800 text-white text-xs font-bold px-2 py-0.5 rounded mb-1">
                                                            {fail.code}
                                                        </span>
                                                        <h4 className="font-bold text-slate-900 text-sm">{fail.title}</h4>
                                                    </div>
                                                </div>
                                                <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
                                                    <div className="bg-red-50 p-3 rounded-lg border border-red-100">
                                                        <p className="text-xs font-bold text-red-800 uppercase mb-1">Causa Probable</p>
                                                        <p className="text-sm text-red-900">{fail.cause || 'No especificada'}</p>
                                                    </div>
                                                    <div className="bg-green-50 p-3 rounded-lg border border-green-100">
                                                        <p className="text-xs font-bold text-green-800 uppercase mb-1">Solución Recomendada</p>
                                                        <p className="text-sm text-green-900">{fail.solution || 'Contactar servicio técnico'}</p>
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>

                            <div className="p-4 border-t border-slate-100 bg-white rounded-b-xl flex justify-end">
                                <button onClick={() => setIsFaultModalOpen(false)} className="px-4 py-2 bg-slate-100 text-slate-600 rounded-lg hover:bg-slate-200 font-medium">
                                    Cerrar Manual
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        );
    }
    return null;
}

import React, { useState } from 'react';
import { Asset, MaintenancePlan, InventoryItem, TaskTemplate, CatalogModel } from '../types';
import { 
  Cpu, Plus, Search, MapPin, Activity, Calendar, Clock, AlertTriangle, 
  FileText, CheckSquare, Trash2, Save, X, ChevronRight, Box, Wrench
} from 'lucide-react';

interface AssetsProps {
  assets: Asset[];
  inventory: InventoryItem[];
  taskTemplates: TaskTemplate[];
  maintenancePlans: MaintenancePlan[];
  modelCatalog: CatalogModel[];
  onCreateAsset: (asset: Asset) => void;
  onCreatePlan: (plan: MaintenancePlan) => void;
  onDeletePlan: (planId: string) => void;
}

export const Assets: React.FC<AssetsProps> = ({
  assets,
  inventory,
  maintenancePlans,
  modelCatalog,
  onCreateAsset,
  onCreatePlan,
  onDeletePlan
}) => {
  // State
  const [selectedAssetId, setSelectedAssetId] = useState<string | null>(null);
  const [isAssetModalOpen, setIsAssetModalOpen] = useState(false);
  const [isPlanModalOpen, setIsPlanModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // New Asset Form State
  const [newAsset, setNewAsset] = useState<Partial<Asset>>({
    name: '',
    location: '',
    category: '',
    model: '',
    serialNumber: '',
    status: 'OPERATIONAL'
  });

  // New Plan Form State
  const [newPlan, setNewPlan] = useState<Partial<MaintenancePlan>>({
    title: '',
    frequencyDays: 30,
    estimatedHours: 1,
    specialtyRequired: 'Mecánica',
    requiresDowntime: false,
    checklistTemplate: [],
    requiredParts: []
  });
  const [tempTask, setTempTask] = useState('');
  const [selectedPartId, setSelectedPartId] = useState('');
  const [partQty, setPartQty] = useState(1);

  // Filtered Assets
  const filteredAssets = assets.filter(a => 
    a.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    a.location.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (a.model && a.model.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const selectedAsset = assets.find(a => a.id === selectedAssetId);
  const assetPlans = maintenancePlans.filter(p => p.assetId === selectedAssetId);

  // Handlers
  const handleCreateAsset = () => {
    if (!newAsset.name || !newAsset.location) return alert('Nombre y Ubicación son requeridos');

    const asset: Asset = {
      id: `a-${Date.now()}`,
      name: newAsset.name || 'Sin Nombre',
      location: newAsset.location || 'Sin Ubicación',
      sector: newAsset.sector || 'General',
      category: newAsset.category || 'Maquinaria',
      brand: newAsset.brand || '',
      model: newAsset.model || '',
      serialNumber: newAsset.serialNumber || '',
      status: 'OPERATIONAL',
      frequentFailures: []
    };

    onCreateAsset(asset);
    setIsAssetModalOpen(false);
    setNewAsset({ name: '', location: '', category: '', model: '', serialNumber: '', status: 'OPERATIONAL' });
  };

  const handleCreatePlan = () => {
    if (!newPlan.title || !selectedAsset) return alert('Título es requerido');

    const plan: MaintenancePlan = {
      id: `mp-${Date.now()}`,
      title: newPlan.title || 'Mantenimiento',
      assetId: selectedAsset.id,
      assetName: selectedAsset.name,
      frequencyDays: newPlan.frequencyDays || 30,
      nextDueDate: new Date().toISOString().split('T')[0],
      estimatedHours: newPlan.estimatedHours || 1,
      specialtyRequired: newPlan.specialtyRequired || 'Mecánica',
      checklistTemplate: newPlan.checklistTemplate || [],
      requiresDowntime: newPlan.requiresDowntime || false,
      requiredParts: newPlan.requiredParts || []
    };

    onCreatePlan(plan);
    setIsPlanModalOpen(false);
    setNewPlan({ 
        title: '', frequencyDays: 30, estimatedHours: 1, specialtyRequired: 'Mecánica', 
        requiresDowntime: false, checklistTemplate: [], requiredParts: [] 
    });
  };

  const addTask = () => {
    if (tempTask.trim()) {
      setNewPlan(prev => ({
        ...prev,
        checklistTemplate: [...(prev.checklistTemplate || []), tempTask]
      }));
      setTempTask('');
    }
  };

  const addPart = () => {
    if (selectedPartId && partQty > 0) {
      const item = inventory.find(i => i.id === selectedPartId);
      if (item) {
        setNewPlan(prev => ({
          ...prev,
          requiredParts: [
            ...(prev.requiredParts || []),
            { itemId: item.id, itemName: item.name, quantity: partQty }
          ]
        }));
        setSelectedPartId('');
        setPartQty(1);
      }
    }
  };

  const removePart = (idx: number) => {
      setNewPlan(prev => ({
          ...prev,
          requiredParts: prev.requiredParts?.filter((_, i) => i !== idx)
      }));
  };

  return (
    <div className="flex h-full gap-6">
      {/* List Sidebar */}
      <div className={`flex flex-col w-full md:w-1/3 bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden ${selectedAssetId ? 'hidden md:flex' : 'flex'}`}>
        {/* Header */}
        <div className="p-4 border-b border-slate-100">
            <div className="flex justify-between items-center mb-4">
                <h2 className="font-bold text-slate-800 text-lg">Activos</h2>
                <button 
                    onClick={() => setIsAssetModalOpen(true)}
                    className="bg-slate-900 text-white p-2 rounded-lg hover:bg-slate-700 transition-colors"
                >
                    <Plus size={18} />
                </button>
            </div>
            <div className="relative">
                <Search className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                <input 
                    type="text" 
                    placeholder="Buscar máquina..."
                    className="w-full pl-9 pr-4 py-2 bg-slate-50 border-none rounded-lg text-sm focus:ring-2 focus:ring-slate-200 outline-none"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
        </div>

        {/* List */}
        <div className="flex-1 overflow-y-auto divide-y divide-slate-50">
            {filteredAssets.map(asset => (
                <div 
                    key={asset.id}
                    onClick={() => setSelectedAssetId(asset.id)}
                    className={`p-4 cursor-pointer hover:bg-slate-50 transition-colors flex items-center justify-between group ${selectedAssetId === asset.id ? 'bg-primary-50 border-l-4 border-primary-600' : 'border-l-4 border-transparent'}`}
                >
                    <div className="flex items-center gap-3">
                        <div className={`p-2 rounded-lg ${asset.status === 'OPERATIONAL' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
                            <Cpu size={20} />
                        </div>
                        <div>
                            <h3 className={`font-bold text-sm ${selectedAssetId === asset.id ? 'text-primary-900' : 'text-slate-800'}`}>{asset.name}</h3>
                            <p className="text-xs text-slate-500 flex items-center gap-1">
                                <MapPin size={10}/> {asset.location}
                            </p>
                        </div>
                    </div>
                    <ChevronRight size={16} className={`text-slate-300 ${selectedAssetId === asset.id ? 'text-primary-400' : 'group-hover:text-slate-500'}`}/>
                </div>
            ))}
        </div>
      </div>

      {/* Details Panel */}
      <div className={`flex-1 bg-white rounded-xl shadow-sm border border-slate-200 flex-col overflow-hidden ${selectedAssetId ? 'flex' : 'hidden md:flex'}`}>
        {selectedAsset ? (
            <>
                {/* Asset Header */}
                <div className="p-6 border-b border-slate-100 flex justify-between items-start bg-slate-50/50">
                    <div className="flex items-start gap-4">
                        <div className="w-16 h-16 bg-white rounded-xl border border-slate-200 p-1 shadow-sm">
                            <img 
                                src={selectedAsset.imageUrl || "https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=200&q=80"} 
                                alt={selectedAsset.name}
                                className="w-full h-full object-cover rounded-lg"
                            />
                        </div>
                        <div>
                            <div className="flex items-center gap-2 mb-1">
                                <h2 className="text-2xl font-bold text-slate-900">{selectedAsset.name}</h2>
                                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border uppercase ${selectedAsset.status === 'OPERATIONAL' ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-red-50 text-red-600 border-red-200'}`}>
                                    {selectedAsset.status === 'OPERATIONAL' ? 'Operativo' : 'Parado'}
                                </span>
                            </div>
                            <div className="flex flex-wrap gap-4 text-sm text-slate-500">
                                <span className="flex items-center gap-1"><Box size={14}/> {selectedAsset.model || 'S/Modelo'}</span>
                                <span className="flex items-center gap-1"><MapPin size={14}/> {selectedAsset.location}</span>
                                {selectedAsset.manualUrl && (
                                    <a href={selectedAsset.manualUrl} target="_blank" rel="noreferrer" className="text-blue-600 hover:underline flex items-center gap-1">
                                        <FileText size={14}/> Manual PDF
                                    </a>
                                )}
                            </div>
                        </div>
                    </div>
                    <button 
                        onClick={() => setSelectedAssetId(null)}
                        className="md:hidden text-slate-400 hover:text-slate-600"
                    >
                        <X size={24}/>
                    </button>
                </div>

                {/* Content Tabs/Sections */}
                <div className="flex-1 overflow-y-auto p-6 space-y-8">

                    {/* Maintenance Plans Section */}
                    <div>
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                <Calendar size={20} className="text-primary-600"/> Planes de Mantenimiento
                            </h3>
                            <button 
                                onClick={() => setIsPlanModalOpen(true)}
                                className="text-xs bg-primary-50 text-primary-700 px-3 py-1.5 rounded-lg font-bold hover:bg-primary-100 transition-colors flex items-center gap-1 border border-primary-200"
                            >
                                <Plus size={14}/> Agregar Plan
                            </button>
                        </div>

                        {assetPlans.length === 0 ? (
                            <div className="text-center py-8 border-2 border-dashed border-slate-100 rounded-xl">
                                <p className="text-slate-400 text-sm">No hay planes preventivos configurados.</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 gap-3">
                                {assetPlans.map(plan => (
                                    <div key={plan.id} className="border border-slate-200 rounded-xl p-4 hover:shadow-md transition-shadow bg-white group relative">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <h4 className="font-bold text-slate-800">{plan.title}</h4>
                                                <div className="flex items-center gap-3 text-xs text-slate-500 mt-1">
                                                    <span className="flex items-center gap-1"><Clock size={12}/> Cada {plan.frequencyDays} días</span>
                                                    <span className="flex items-center gap-1"><Activity size={12}/> {plan.specialtyRequired}</span>
                                                    {plan.requiresDowntime && <span className="text-red-500 font-bold flex items-center gap-1"><AlertTriangle size={10}/> Parada Req.</span>}
                                                </div>
                                            </div>
                                            <button 
                                                onClick={() => onDeletePlan(plan.id)}
                                                className="opacity-0 group-hover:opacity-100 text-slate-300 hover:text-red-500 transition-opacity"
                                            >
                                                <Trash2 size={16}/>
                                            </button>
                                        </div>

                                        {/* Preview Checklist */}
                                        <div className="mt-3 pt-3 border-t border-slate-50">
                                            <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Tareas ({plan.checklistTemplate.length})</p>
                                            <div className="flex flex-wrap gap-1">
                                                {plan.checklistTemplate.slice(0, 3).map((t, i) => (
                                                    <span key={i} className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded truncate max-w-[150px]">
                                                        {t}
                                                    </span>
                                                ))}
                                                {plan.checklistTemplate.length > 3 && (
                                                    <span className="text-[10px] text-slate-400 px-1">+{plan.checklistTemplate.length - 3} más</span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Spare Parts History */}
                    <div>
                         <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                <Box size={20} className="text-indigo-600"/> Historial de Fallas
                        </h3>
                        {selectedAsset.frequentFailures && selectedAsset.frequentFailures.length > 0 ? (
                            <div className="space-y-3">
                                {selectedAsset.frequentFailures.map((fail, i) => (
                                    <div key={i} className="bg-red-50 border border-red-100 rounded-lg p-3">
                                        <div className="flex gap-2 items-start">
                                            <AlertTriangle size={16} className="text-red-500 shrink-0 mt-0.5"/>
                                            <div>
                                                <p className="text-sm font-bold text-red-800">{fail.title} <span className="text-xs font-normal opacity-70">({fail.code})</span></p>
                                                <p className="text-xs text-red-600 mt-1">{fail.solution}</p>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <p className="text-sm text-slate-400 italic">No hay registros de fallas comunes.</p>
                        )}
                    </div>

                </div>
            </>
        ) : (
            <div className="flex-1 flex flex-col items-center justify-center text-slate-300">
                <Wrench size={64} className="mb-4 opacity-20"/>
                <p className="text-lg font-medium">Selecciona una máquina para ver detalles</p>
            </div>
        )}
      </div>

      {/* CREATE ASSET MODAL */}
      {isAssetModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
            <div className="bg-white rounded-xl w-full max-w-lg shadow-2xl p-6">
                <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-slate-800 text-lg">Nueva Máquina</h3>
                    <button onClick={() => setIsAssetModalOpen(false)}><X size={20} className="text-slate-400"/></button>
                </div>

                <div className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nombre / Código</label>
                        <input 
                            type="text" 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-primary-500"
                            value={newAsset.name}
                            onChange={e => setNewAsset({...newAsset, name: e.target.value})}
                            placeholder="Ej. Lavadora Industrial L-01"
                        />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                             <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Modelo (Catálogo)</label>
                             <select 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-primary-500 bg-white"
                                value={newAsset.model}
                                onChange={e => {
                                    const model = modelCatalog.find(m => m.name === e.target.value);
                                    setNewAsset({
                                        ...newAsset, 
                                        model: e.target.value,
                                        category: model?.category || newAsset.category,
                                        brand: model?.brand || newAsset.brand
                                    });
                                }}
                             >
                                 <option value="">-- Personalizado --</option>
                                 {modelCatalog.map(m => <option key={m.id} value={m.name}>{m.name}</option>)}
                             </select>
                        </div>
                        <div>
                             <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Ubicación</label>
                             <input 
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-primary-500"
                                value={newAsset.location}
                                onChange={e => setNewAsset({...newAsset, location: e.target.value})}
                                placeholder="Ej. Planta Baja"
                            />
                        </div>
                    </div>
                    <div>
                         <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Categoría</label>
                         <input 
                            type="text" 
                            className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-primary-500"
                            value={newAsset.category}
                            onChange={e => setNewAsset({...newAsset, category: e.target.value})}
                            placeholder="Ej. Lavado"
                        />
                    </div>
                </div>

                <div className="mt-6 flex justify-end gap-2">
                    <button onClick={() => setIsAssetModalOpen(false)} className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancelar</button>
                    <button onClick={handleCreateAsset} className="bg-slate-900 text-white px-4 py-2 rounded-lg font-bold hover:bg-slate-800">Crear Activo</button>
                </div>
            </div>
        </div>
      )}

      {/* CREATE PLAN MODAL */}
      {isPlanModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
            <div className="bg-white rounded-xl w-full max-w-2xl shadow-2xl flex flex-col max-h-[90vh]">
                <div className="p-6 border-b border-slate-100 flex justify-between items-center">
                    <h3 className="font-bold text-slate-800 text-lg">Nuevo Plan Preventivo</h3>
                    <button onClick={() => setIsPlanModalOpen(false)}><X size={20} className="text-slate-400"/></button>
                </div>

                <div className="p-6 overflow-y-auto space-y-6">
                    {/* Basic Info */}
                    <div className="space-y-4">
                        <div>
                            <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Título del Plan <span className="text-red-500">*</span></label>
                            <input 
                                type="text" 
                                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                placeholder="Ej. Lubricación Semanal de Rodamientos"
                                value={newPlan.title || ''}
                                onChange={e => setNewPlan({...newPlan, title: e.target.value})}
                            />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Frecuencia (Días)</label>
                                <div className="relative">
                                    <Calendar className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                                    <input 
                                        type="number" 
                                        className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                        value={newPlan.frequencyDays}
                                        onChange={e => setNewPlan({...newPlan, frequencyDays: Number(e.target.value)})}
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Duración Estimada (Horas)</label>
                                <div className="relative">
                                    <Clock className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                                    <input 
                                        type="number" 
                                        className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                        value={newPlan.estimatedHours}
                                        onChange={e => setNewPlan({...newPlan, estimatedHours: Number(e.target.value)})}
                                    />
                                </div>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Especialidad</label>
                                <div className="relative">
                                    <Activity className="absolute left-3 top-2.5 text-slate-400" size={16}/>
                                    <select 
                                        className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                        value={newPlan.specialtyRequired}
                                        onChange={e => setNewPlan({...newPlan, specialtyRequired: e.target.value})}
                                    >
                                        <option value="Mecánica">Mecánica</option>
                                        <option value="Electricidad">Electricidad</option>
                                        <option value="Hidráulica">Hidráulica</option>
                                        <option value="General">General</option>
                                    </select>
                                </div>
                            </div>
                            <div className="flex items-center mt-6">
                                <label className="flex items-center gap-2 cursor-pointer">
                                    <input 
                                        type="checkbox" 
                                        className="w-4 h-4 text-teal-600 rounded focus:ring-teal-500"
                                        checked={newPlan.requiresDowntime}
                                        onChange={e => setNewPlan({...newPlan, requiresDowntime: e.target.checked})}
                                    />
                                    <span className="text-sm font-medium text-slate-700">Requiere Parada de Máquina</span>
                                </label>
                            </div>
                        </div>
                    </div>

                    <hr className="border-slate-100"/>

                    {/* Checklist Builder */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Checklist de Tareas</label>
                        <div className="flex gap-2 mb-3">
                            <input 
                                type="text" 
                                className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                placeholder="Describir tarea..."
                                value={tempTask}
                                onChange={e => setTempTask(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && addTask()}
                            />
                            <button 
                                onClick={addTask}
                                className="bg-slate-100 text-slate-600 px-3 py-2 rounded-lg hover:bg-slate-200 font-bold text-sm"
                            >
                                <Plus size={18}/>
                            </button>
                        </div>

                        <div className="bg-slate-50 rounded-lg border border-slate-200 p-2 min-h-[100px] max-h-[200px] overflow-y-auto space-y-1">
                            {newPlan.checklistTemplate && newPlan.checklistTemplate.length > 0 ? (
                                newPlan.checklistTemplate.map((task, idx) => (
                                    <div key={idx} className="flex items-start gap-2 bg-white p-2 rounded border border-slate-100 text-sm">
                                        <span className="text-teal-500 font-bold">{idx + 1}.</span>
                                        <span className="flex-1 text-slate-700">{task}</span>
                                        <button 
                                            onClick={() => setNewPlan(prev => ({...prev, checklistTemplate: prev.checklistTemplate?.filter((_, i) => i !== idx)}))}
                                            className="text-slate-400 hover:text-red-500"
                                        >
                                            <Trash2 size={14}/>
                                        </button>
                                    </div>
                                ))
                            ) : (
                                <div className="h-full flex flex-col items-center justify-center text-slate-400 py-4">
                                    <CheckSquare size={24} className="mb-1 opacity-50"/>
                                    <span className="text-xs">Agrega tareas al checklist</span>
                                </div>
                            )}
                        </div>
                    </div>

                    <hr className="border-slate-100"/>

                    {/* Parts Requirement */}
                    <div>
                        <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Repuestos Necesarios</label>
                        <div className="flex gap-2 mb-3">
                            <select 
                                className="flex-1 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                value={selectedPartId}
                                onChange={e => setSelectedPartId(e.target.value)}
                            >
                                <option value="">Seleccionar Repuesto...</option>
                                {inventory.map(item => (
                                    <option key={item.id} value={item.id}>{item.name} (Stock: {item.quantity})</option>
                                ))}
                            </select>
                            <input 
                                type="number" 
                                className="w-20 border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-teal-500 outline-none bg-white text-slate-900"
                                min="1"
                                value={partQty}
                                onChange={e => setPartQty(Number(e.target.value))}
                            />
                            <button 
                                onClick={addPart}
                                className="bg-slate-100 text-slate-600 px-3 py-2 rounded-lg hover:bg-slate-200 font-bold text-sm"
                            >
                                <Plus size={18}/>
                            </button>
                        </div>

                         <div className="space-y-1">
                            {newPlan.requiredParts && newPlan.requiredParts.length > 0 ? (
                                newPlan.requiredParts.map((part, idx) => (
                                    <div key={idx} className="flex justify-between items-center bg-white p-2 border border-slate-100 rounded text-sm">
                                        <span className="text-slate-700">{part.itemName}</span>
                                        <div className="flex items-center gap-3">
                                            <span className="font-bold text-slate-900">x{part.quantity}</span>
                                            <button onClick={() => removePart(idx)} className="text-slate-300 hover:text-red-500"><Trash2 size={14}/></button>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <p className="text-xs text-slate-400 italic">No requiere repuestos.</p>
                            )}
                        </div>
                    </div>
                </div>

                <div className="p-6 border-t border-slate-100 bg-slate-50 flex justify-end gap-2 rounded-b-xl">
                    <button onClick={() => setIsPlanModalOpen(false)} className="px-4 py-2 text-slate-600 font-medium hover:bg-slate-200 rounded-lg">Cancelar</button>
                    <button onClick={handleCreatePlan} className="bg-teal-600 text-white px-4 py-2 rounded-lg font-bold hover:bg-teal-700 flex items-center gap-2">
                        <Save size={18}/> Guardar Plan
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

