             <div className="flex items-center gap-2">
                <Filter size={14}/>
                <span>{Object.values(groupedItems).flat().length} Registros encontrados</span>
             </div>
             {activeTab === 'upcoming' && (
                 <div className="flex items-center gap-2">
                    <span>Seleccionar Todos</span>
                    <button 
                        onClick={toggleSelectAll}
