// --- PARSER LOGIC ---
const parseCSV = () => {
    const assetsMap = new Map<string, Asset>();
    const plansMap = new Map<string, MaintenancePlan>(); // Key: AssetID-Freq-Specialty
    const failuresMap = new Map<string, FrequentFailure[]>(); // Key: ModelName (or simplified name)

    // --- 1. PARSE FAULTS CSV ---
    // Logic: Split by newline, then split by semicolon.
    // Columns: [0]Equipo afectado, [1]CODIGO, [2]Desc, [3]Causa, [4]Solucion

    const faultRows = RAW_FAULT_CSV.split('\n').slice(1); // Skip header
    faultRows.forEach((row, index) => {
        if (!row.trim()) return;

        // Simple semicolon split (handling basic quoted content if necessary, but this CSV looks clean-ish with ;)
        // Using a regex to handle quoted semicolons if they exist
        const cols: string[] = [];
        let inQuote = false;
        let current = '';
        for (let i = 0; i < row.length; i++) {
            const char = row[i];
            if (char === '"') { inQuote = !inQuote; continue; }
            if (char === ';' && !inQuote) {
                cols.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        cols.push(current.trim());

        if (cols.length < 5) return;

        const [machineName, code, desc, cause, solution] = cols;

        // Use the raw machine name as key for now, we will match loosely later
        const mapKey = machineName.trim(); 

        const failure: FrequentFailure = {
            id: `fail-${index}`,
            code: code || 'GEN',
            title: desc || 'Falla sin título',
            description: desc,
            cause: cause,
            solution: solution,
            imageUrl: ''
        };

        if (!failuresMap.has(mapKey)) {
            failuresMap.set(mapKey, []);
        }
        failuresMap.get(mapKey)?.push(failure);
    });


    // --- 2. PARSE MAINTENANCE CSV ---
    // Regex for CSV parsing (handles quoted fields with commas)
    const regex = /(?:,|\n|^)("(?:(?:"")*[^"]*)*"|[^",\n]*|(?:\n|$))/g;
    const dataStart = RAW_CSV_DATA.indexOf('\n') + 1;
    const rawData = RAW_CSV_DATA.slice(dataStart);
    const rows = rawData.split('\n');

    rows.forEach((row, index) => {
        if (!row.trim()) return;

        const cols: string[] = [];
        let inQuote = false;
        let current = '';
        for (let i = 0; i < row.length; i++) {
            const char = row[i];
            if (char === '"') { inQuote = !inQuote; continue; }
            if (char === ',' && !inQuote) {
                cols.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        cols.push(current.trim());

        if (cols.length < 6) return;

        const [title, specialty, serial, taskDesc, brandRaw, freqStr] = cols;

        const safeSerial = serial || `GEN-${title}-${index}`; // Fallback ID if empty serial
        const assetId = `a-${safeSerial}`;

        // Match Failures to Asset based on 'title' (Model Name)
        // Try exact match or partial match from the Failures Map
        let assetFailures: FrequentFailure[] = [];

        // Simple normalization for matching (e.g. "TBS-50/12" matches "TBS50-12" somewhat)
        const normTitle = title.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();

        for (const [failKey, fails] of failuresMap.entries()) {
            const normFailKey = failKey.replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
            if (normTitle.includes(normFailKey) || normFailKey.includes(normTitle)) {
                assetFailures = [...assetFailures, ...fails];
            }
        }

        // Deduplicate failures by code
        assetFailures = Array.from(new Map(assetFailures.map(f => [f.code + f.title, f])).values());

        // 1. Create or Update Asset
        if (!assetsMap.has(assetId)) {
            assetsMap.set(assetId, {
                id: assetId,
                name: `${title} ${serial ? `#${serial}` : ''}`,
                location: 'Planta Principal',
                sector: 'Producción',
                category: CATEGORY_MAP[title] || 'Maquinaria',
                brand: brandRaw.includes('GIRBAU') ? 'GIRBAU' : (brandRaw.includes('SML') ? 'SML' : 'Generico'),
                model: title,
                serialNumber: serial || 'N/A',
                status: 'OPERATIONAL',
                frequentFailures: assetFailures // Attach found failures
            });
        }

        // 2. Create or Update Plan (Grouping)
        const days = FREQ_MAP[freqStr] || 30;
        const planKey = `${assetId}-${days}-${specialty}`;

        if (!plansMap.has(planKey)) {
            plansMap.set(planKey, {
                id: `mp-${planKey}`,
                title: `Mantenimiento ${freqStr} - ${specialty}`,
                assetId: assetId,
                assetName: assetsMap.get(assetId)!.name,
                frequencyDays: days,
                nextDueDate: addDays(days === 1 ? 0 : Math.floor(Math.random() * 30)), // Stagger dates
                estimatedHours: days > 30 ? 2 : 0.5,
                specialtyRequired: specialty || 'General',
                checklistTemplate: [],
                requiresDowntime: days >= 180, // Assumption: Bi-annual/Annual requires stop
            });
        }

        const plan = plansMap.get(planKey)!;
        plan.checklistTemplate.push(taskDesc.replace(/"/g, ''));
    });

    return {
        assets: Array.from(assetsMap.values()),
        plans: Array.from(plansMap.values())
    };
};

const generatedData = parseCSV();

