                                            <>
                                                <span>•</span>
                                                <span>Cada {item.frequency} días</span>
                                                <span>•</span>
                                                <span>{item.hours}h est.</span>
                                            </>
                                        )}
                                        {activeTab === 'history' && (
                                            <>
                                                <span>•</span>
                                                <span className="flex items-center gap-1">
                                                    <UserIcon size={12}/> 
