import React, { useState } from 'react';
import { User, InventoryItem, CatalogModel, FrequentFailure, UserRole } from '../types';
import { Plus, Trash2, AlertTriangle, Shield, AlertCircle, Search, X } from 'lucide-react';

interface ConfigurationProps {
  currentView: string;
  users: User[];
  inventory: InventoryItem[];
  modelCatalog: CatalogModel[];
  onUpdateCatalog: (catalog: CatalogModel[]) => void;
}

export const Configuration: React.FC<ConfigurationProps> = ({ 
    currentView, 
    users, 
    inventory, 
    modelCatalog, 
    onUpdateCatalog 
}) => {
    // State for Config Models
    const [selectedModelId, setSelectedModelId] = useState<string | null>(null);
    const [tempFault, setTempFault] = useState<Partial<FrequentFailure>>({ 
        code: '', title: '', cause: '', solution: '' 
    });

    // Helper to find selected model
    const selectedModel = modelCatalog.find(m => m.id === selectedModelId);

    const handleAddFault = () => {
        if (!selectedModel || !tempFault.code || !tempFault.title) return;

        const newFault: FrequentFailure = {
            id: `fail-${Date.now()}`,
            code: tempFault.code || 'GEN',
            title: tempFault.title || 'Sin Título',
            description: tempFault.title, // Fallback
            cause: tempFault.cause,
            solution: tempFault.solution,
            imageUrl: ''
        };

        const updatedModel = {
            ...selectedModel,
            commonFailures: [...(selectedModel.commonFailures || []), newFault]
        };

        const updatedCatalog = modelCatalog.map(m => m.id === selectedModel.id ? updatedModel : m);
        onUpdateCatalog(updatedCatalog);

        // Reset form
        setTempFault({ code: '', title: '', cause: '', solution: '' });
    };

    const handleDeleteFault = (faultId: string) => {
        if (!selectedModel) return;
        const updatedModel = {
            ...selectedModel,
            commonFailures: selectedModel.commonFailures.filter(f => f.id !== faultId)
        };
        const updatedCatalog = modelCatalog.map(m => m.id === selectedModel.id ? updatedModel : m);
        onUpdateCatalog(updatedCatalog);
    };

    // View Routing
    if (currentView === 'config-users') {
        return (
            <div className="space-y-6">
                <div className="flex items-center justify-between">
                    <h2 className="text-2xl font-bold text-slate-900">Gestión de Usuarios</h2>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {users.map(u => (
                        <div key={u.id} className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex items-center gap-4">
                            <img src={u.avatar} alt={u.name} className="w-12 h-12 rounded-full bg-slate-100" />
                            <div>
                                <p className="font-bold text-slate-900">{u.name}</p>
                                <p className="text-xs text-slate-500 uppercase font-bold">{u.role}</p>
                                {u.specialty && <p className="text-xs text-slate-400">{u.specialty}</p>}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    if (currentView === 'config-roles') {
        return (
            <div className="space-y-6">
                <h2 className="text-2xl font-bold text-slate-900">Roles y Permisos</h2>
                <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                    <p className="text-slate-500 text-sm mb-4">Configuración de niveles de acceso (Solo lectura en Demo).</p>
                    <div className="space-y-2">
                        {Object.values(UserRole).map(role => (
                            <div key={role} className="flex items-center gap-3 p-3 bg-slate-50 rounded border border-slate-100">
                                <Shield size={18} className="text-slate-400"/>
                                <span className="font-mono font-bold text-slate-700">{role}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    if (currentView === 'config-articles') {
        return (
            <div className="space-y-6">
                <h2 className="text-2xl font-bold text-slate-900">Catálogo de Artículos</h2>
                <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-slate-50 border-b border-slate-200">
                            <tr>
                                <th className="px-6 py-3 font-semibold text-slate-500">Nombre</th>
                                <th className="px-6 py-3 font-semibold text-slate-500">SKU</th>
                                <th className="px-6 py-3 font-semibold text-slate-500">Categoría</th>
                                <th className="px-6 py-3 font-semibold text-slate-500">Stock</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {inventory.map(item => (
                                <tr key={item.id} className="hover:bg-slate-50">
                                    <td className="px-6 py-3">{item.name}</td>
                                    <td className="px-6 py-3 font-mono text-xs">{item.sku}</td>
                                    <td className="px-6 py-3">{item.category}</td>
                                    <td className="px-6 py-3 font-bold">{item.quantity}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    }

    // Default: config-models
    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-slate-900">Modelos y Fallas Comunes</h2>
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* List of Models */}
                <div className="space-y-3">
                    {modelCatalog.map(model => (
                        <div 
                            key={model.id} 
                            onClick={() => setSelectedModelId(model.id)}
                            className={`p-4 rounded-xl border cursor-pointer transition-all ${selectedModelId === model.id ? 'bg-primary-50 border-primary-500 shadow-md ring-1 ring-primary-500' : 'bg-white border-slate-200 hover:border-primary-300'}`}
                        >
                            <div className="flex justify-between items-start">
                                <h4 className="font-bold text-slate-800">{model.name}</h4>
                                <span className="text-[10px] font-bold bg-slate-100 px-2 py-0.5 rounded text-slate-500">{model.brand}</span>
                            </div>
                            <p className="text-xs text-slate-500 mt-1">{model.category}</p>
                        </div>
                    ))}
                </div>

                {/* Detail / Edit View */}
                <div className="lg:col-span-2">
                    {selectedModel ? (
                        <div className="bg-white rounded-xl border border-slate-200 shadow-sm p-6">
                            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
                                {selectedModel.imageUrl && (
                                    <img src={selectedModel.imageUrl} className="w-16 h-16 rounded-lg object-cover bg-slate-100" alt={selectedModel.name} />
                                )}
                                <div>
                                    <h3 className="text-xl font-bold text-slate-900">{selectedModel.name}</h3>
                                    <p className="text-sm text-slate-500">{selectedModel.description}</p>
                                </div>
                            </div>

                            <h4 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
                                <AlertTriangle size={18} className="text-orange-500"/> Base de Conocimiento de Fallas
                            </h4>

                            {/* Existing Faults List */}
                            <div className="space-y-3 mb-6 max-h-60 overflow-y-auto pr-2">
                                {selectedModel.commonFailures?.map(fail => (
                                    <div key={fail.id} className="bg-slate-50 border border-slate-100 rounded-lg p-3 relative group">
                                            <div className="flex items-center gap-2 mb-1">
                                            <span className="font-mono text-xs font-bold bg-slate-800 text-white px-1.5 py-0.5 rounded">{fail.code}</span>
                                            <span className="font-bold text-sm text-slate-700">{fail.title}</span>
                                            </div>
                                            <div className="text-xs text-slate-600 space-y-1">
                                                {fail.cause && <p><span className="font-bold text-slate-500">Causa:</span> {fail.cause}</p>}
                                                {fail.solution && <p><span className="font-bold text-slate-500">Solución:</span> {fail.solution}</p>}
                                            </div>

                                            <button 
                                            onClick={() => handleDeleteFault(fail.id)}
                                            className="absolute top-2 right-2 p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded transition-colors opacity-0 group-hover:opacity-100"
                                            >
                                            <Trash2 size={14} />
                                            </button>
                                    </div>
                                ))}
                                {(!selectedModel.commonFailures || selectedModel.commonFailures.length === 0) && (
                                    <p className="text-sm text-slate-400 italic text-center py-4 bg-slate-50 rounded-lg border border-dashed border-slate-200">
                                        No hay fallas registradas para este modelo.
                                    </p>
                                )}
                            </div>

                            {/* Fault Entry Form */}
                            <div className="bg-slate-50 p-4 rounded-lg border border-slate-200 mb-4 shadow-inner">
                                <p className="text-xs font-bold text-slate-500 uppercase mb-3">Agregar Nueva Falla</p>
                                <div className="grid grid-cols-12 gap-3 mb-3">
                                    <div className="col-span-3">
                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Código</label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded px-2 py-1.5 text-xs outline-none focus:border-orange-500 bg-white text-slate-900"
                                            placeholder="E-001"
                                            value={tempFault.code}
                                            onChange={e => setTempFault({...tempFault, code: e.target.value})}
                                        />
                                    </div>
                                    <div className="col-span-9">
                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Descripción del Fallo</label>
                                        <input 
                                            type="text" 
                                            className="w-full border border-slate-300 rounded px-2 py-1.5 text-xs outline-none focus:border-orange-500 bg-white text-slate-900"
                                            placeholder="Ej. Error de temperatura en cámara"
                                            value={tempFault.title}
                                            onChange={e => setTempFault({...tempFault, title: e.target.value})}
                                        />
                                    </div>
                                    <div className="col-span-6">
                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Causa Probable</label>
                                        <textarea 
                                            className="w-full border border-slate-300 rounded px-2 py-1.5 text-xs outline-none focus:border-orange-500 resize-none h-14 bg-white text-slate-900"
                                            placeholder="Sensor sucio o desconectado..."
                                            value={tempFault.cause}
                                            onChange={e => setTempFault({...tempFault, cause: e.target.value})}
                                        />
                                    </div>
                                    <div className="col-span-6">
                                        <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Solución Recomendada</label>
                                        <textarea 
                                            className="w-full border border-slate-300 rounded px-2 py-1.5 text-xs outline-none focus:border-orange-500 resize-none h-14 bg-white text-slate-900"
                                            placeholder="Limpiar sensor y reiniciar..."
                                            value={tempFault.solution}
                                            onChange={e => setTempFault({...tempFault, solution: e.target.value})}
                                        />
                                    </div>
                                </div>
                                <button 
                                    onClick={handleAddFault}
                                    className="w-full bg-slate-800 text-white py-2 rounded text-xs font-bold hover:bg-slate-900 flex items-center justify-center gap-2"
                                >
                                    <Plus size={14}/> Agregar Falla a la Base de Datos
                                </button>
                            </div>

                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50 p-8">
                            <Search size={48} className="mb-4 opacity-20"/>
                            <p className="font-bold">Selecciona un modelo</p>
                            <p className="text-sm">Para ver y editar sus fallas comunes.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

