      const handleOpenPlanModal = (index?: number) => {
        if (typeof index === 'number') {
            setEditingPlanIndex(index);
            setCurrentPlan({ ...formData.standardPlans![index] });
        } else {
            setEditingPlanIndex(null);
            setCurrentPlan({
                title: '', 
