              { id: 'f-imp-2', code: 'E02', title: 'Sobrecalentamiento', cause: 'Filtro obstruido', solution: 'Limpiar filtro de aire', imageUrl: '' }
          ];
          setFormData({
              ...formData,
              commonFailures: [...(formData.commonFailures || []), ...demoFaults]
